#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define MLX91219_SENSITIVITY 0.040 // 40mV/A
#define MLX91219_OFFSET 0.5 // Mid-supply offset

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int ads1115_configure();
int ads1115_read(int *raw_value);
float calculate_current(int raw_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to configure the ADS1115
int ads1115_configure() {
    // Configuration register settings:
    // MUX = 100 (AIN0 single-ended)
    // PGA = 110 (±4.096V)
    // MODE = 10 (Single-shot)
    // DR = 011 (128 SPS)
    // COMP_MODE = 00 (Traditional comparator)
    // COMP_POL = 0 (Active low)
    // COMP_LAT = 0 (Non-latching)
    // COMP_QUE = 00 (Disable comparator)

    uint16_t config_value = 0x4083; // 0b0100000010000011

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf + 1, 2); // Write only the 2 data bytes
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the ADS1115 conversion register
int ads1115_read(int *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteI2CBlockData(i2c_handle, CONVERSION_REG, buf, 0); // Trigger conversion
    if (result < 0) {
        fprintf(stderr, "Error triggering conversion: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion to complete (adjust as needed)

    char data[2];
    result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Function to calculate current from raw ADC value
float calculate_current(int raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // 16-bit ADC, ±4.096V range
    float current = (voltage - MLX91219_OFFSET) / MLX91219_SENSITIVITY;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (ads1115_configure() != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value;
        if (ads1115_read(&raw_value) == 0) {
            float current = calculate_current(raw_value);
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

