#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GPIO_FAN 18
#define DEFAULT_SENSITIVITY 0.1 // 100 mV/A = 0.1 V/A
#define DEFAULT_THRESHOLD 5.0 // Amperes
#define VREF 3.3 // Reference voltage

// Global variables
int spi_handle;
FILE *log_file;
double sensitivity = DEFAULT_SENSITIVITY;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_current(double voltage, double sensitivity);
void control_fan(double current, double threshold);
void log_data(double current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    double sensitivity;
    double threshold;
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Dummy byte

    spiXfer(spi_handle, tx, rx, 3);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to current
double voltage_to_current(double voltage, double sensitivity) {
    return voltage / sensitivity;
}

// Function to control the cooling fan
void control_fan(double current, double threshold) {
    if (current > threshold) {
        gpioWrite(GPIO_FAN, 1); // Turn fan ON
    } else {
        gpioWrite(GPIO_FAN, 0); // Turn fan OFF
    }
}

// Function to log data to a file
void log_data(double current) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, %.3f\n", buf, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO_FAN as output
    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioWrite(GPIO_FAN, 0); // Initially turn fan OFF

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWrite(GPIO_FAN, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    fprintf(stderr, "Sensitivity: %.3f V/A, Threshold: %.2f A\n", sensitivity, threshold);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: Sensor absent or faulty (ADC value: %d)\n", adc_value);
        }

        // Convert ADC value to voltage
        double voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        double current = voltage_to_current(voltage, sensitivity);

        // Control the fan
        control_fan(current, threshold);

        // Log the data
        log_data(current);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

