// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define SPI_CE0 8
#define SPI_CE1 7

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature range
#define MIN_TEMP 10.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    return MIN_TEMP + (float)(adc_value / 1023.0) * (MAX_TEMP - MIN_TEMP);
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlameDetected,Temperature(C)\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = calculate_temperature(adc_value);

        // Log data
        if (flame_detected != -1 && adc_value != -1 && temperature != -1.0) {
            log_data(flame_detected, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

