#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define CO_REG 0x00
#define NO2_REG 0x02
#define CO_THRESHOLD 25.0
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *co_log_file = NULL;
FILE *alert_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *co_raw, int *no2_raw);
float calculate_co_ppm(int co_raw);
int log_co_level(float co_ppm);
int check_threshold(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int co_raw;
    int no2_raw;
    float co_ppm;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *co_raw, int *no2_raw) {
    char buf[4];
    int result;

    // Read CO data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading CO data: %d\n", result);
        return -1;
    }
    *co_raw = (buf[0] << 8) | buf[1];

    // Read NO2 data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, NO2_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading NO2 data: %d\n", result);
        return -1;
    }
    *no2_raw = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to calculate CO level in PPM
float calculate_co_ppm(int co_raw) {
    // Calibration parameters (example values, replace with actual sensor calibration)
    float co_slope = 0.1;  // PPM per unit ADC
    float co_intercept = 0.0; // PPM offset

    return co_slope * co_raw + co_intercept;
}

// Function to log CO level to file
int log_co_level(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (co_log_file == NULL) {
        fprintf(stderr, "Error: CO log file is not open.\n");
        return -1;
    }

    fprintf(co_log_file, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fflush(co_log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to check if CO level exceeds threshold
int check_threshold(float co_ppm) {
    return (co_ppm > CO_THRESHOLD) ? 1 : 0;
}

// Function to log alert to file
int log_alert(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (alert_log_file == NULL) {
        fprintf(stderr, "Error: Alert log file is not open.\n");
        return -1;
    }

    fprintf(alert_log_file, "%s, ALERT: CO level exceeded %.2f PPM (%.2f PPM)\n", timestamp, CO_THRESHOLD, co_ppm);
    fflush(alert_log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log files
    co_log_file = fopen("co_log.txt", "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Error opening co_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    alert_log_file = fopen("alert_log.txt", "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Error opening alert_log.txt\n");
        fclose(co_log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int co_raw, no2_raw;
    float co_ppm;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&co_raw, &no2_raw) == 0) {
            // Calculate CO level
            co_ppm = calculate_co_ppm(co_raw);

            // Log CO level
            if (log_co_level(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO level\n");
            }

            // Check threshold and log alert
            if (check_threshold(co_ppm)) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up
    fclose(co_log_file);
    fclose(alert_log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

