// Structure for sensor data
typedef struct {
    int co_raw;
    int no2_raw;
    float co_ppm;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *co_raw, int *no2_raw) {
    char buf[4];
    int result;

    // Read CO data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading CO data: %d\n", result);
        return -1;
    }
    *co_raw = (buf[0] << 8) | buf[1];

    // Read NO2 data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, NO2_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading NO2 data: %d\n", result);
        return -1;
    }
    *no2_raw = (buf[0] << 8) | buf[1];

    return 0;
}

