int log_co_level(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (co_log_file == NULL) {
        fprintf(stderr, "Error: CO log file is not open.\n");
        return -1;
    }

    fprintf(co_log_file, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fflush(co_log_file); // Ensure data is written to disk immediately

