#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MICROPHONE1_ADDRESS 0x48
#define MICROPHONE2_ADDRESS 0x49
#define SENSITIVITY -38.0 // dBV/Pa
#define REFERENCE_PRESSURE 20.0e-6 // Pa
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_microphone_data(int i2c_handle);
double convert_to_dbspl(int raw_data);
void log_data(double dbspl1, double dbspl2);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mic1_address;
    int mic2_address;
    double sensitivity;
    double reference_pressure;
    int sample_interval_ms;
} Config;

Config config = {
    I2C_BUS,
    MICROPHONE1_ADDRESS,
    MICROPHONE2_ADDRESS,
    SENSITIVITY,
    REFERENCE_PRESSURE,
    SAMPLE_INTERVAL_MS
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_data1 = read_microphone_data(i2c_handle1);
        int raw_data2 = read_microphone_data(i2c_handle2);

        double dbspl1 = -999.0;
        double dbspl2 = -999.0;

        if (raw_data1 != -1) {
            dbspl1 = convert_to_dbspl(raw_data1);
        }

        if (raw_data2 != -1) {
            dbspl2 = convert_to_dbspl(raw_data2);
        }

        log_data(dbspl1, dbspl2);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    if (i2c_handle1 != -1) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 != -1) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle1 = i2cOpen(config.i2c_bus, config.mic1_address, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for microphone 1: %d\n", i2c_handle1);
        return 1;
    }

    i2c_handle2 = i2cOpen(config.i2c_bus, config.mic2_address, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for microphone 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        return 1;
    }

    return 0;
}

// Read microphone data
int read_microphone_data(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (buf[0] << 8) | buf[1];
    return raw_data;
}

// Convert raw data to dB SPL
double convert_to_dbspl(int raw_data) {
    // Assuming raw_data is a 16-bit signed integer representing voltage
    // Convert voltage to pressure (Pa)
    double voltage = (double)raw_data / 65535.0 * 3.3; // Assuming 16-bit ADC and 3.3V reference
    double pressure = voltage / pow(10, SENSITIVITY / 20.0); // Convert voltage to pressure

    // Calculate dB SPL
    double dbspl = 20.0 * log10(pressure / REFERENCE_PRESSURE);

    return dbspl;
}

// Log data to file
void log_data(double dbspl1, double dbspl2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, dbspl1, dbspl2);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

