#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define MIC1_CE 8
#define MIC2_CE 9
#define LED_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 0.7

// Define sampling window
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_MS 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t samples[SAMPLE_WINDOW_MS];
    double rms;
} MicrophoneData;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
double calculate_rms(int16_t *samples, int num_samples);
void control_led(double mic1_rms, double mic2_rms);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC1_CE, PI_OUTPUT);
    gpioSetMode(MIC2_CE, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MIC1_CE, 0); // Select chip
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MIC1_CE, 1); // Deselect chip

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
        gpioDelay(500);        // Wait 500 ms
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        MicrophoneData mic1_data, mic2_data;
        int adc_value;

        // Sample microphone 1
        for (int i = 0; i < SAMPLE_WINDOW_MS; i++) {
            adc_value = read_mcp3008(0); // Channel 0 for mic1
            if (adc_value < 0) {
                fprintf(stderr, "Error reading mic1, exiting\n");
                break;
            }
            mic1_data.samples[i] = (int16_t)adc_value; // Store ADC value as 16-bit integer
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait for 1 ms
        }

        // Sample microphone 2
        for (int i = 0; i < SAMPLE_WINDOW_MS; i++) {
            adc_value = read_mcp3008(1); // Channel 1 for mic2
            if (adc_value < 0) {
                fprintf(stderr, "Error reading mic2, exiting\n");
                break;
            }
            mic2_data.samples[i] = (int16_t)adc_value; // Store ADC value as 16-bit integer
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait for 1 ms
        }

        // Calculate RMS values
        mic1_data.rms = calculate_rms(mic1_data.samples, SAMPLE_WINDOW_MS);
        mic2_data.rms = calculate_rms(mic2_data.samples, SAMPLE_WINDOW_MS);

        // Control LED
        control_led(mic1_data.rms, mic2_data.rms);

        // Log data
        log_data(mic1_data.rms, mic2_data.rms);

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

