#include <unistd.h>
#include <time.h>

// Constants
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define CURRENT_MAX 100.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int i2c_handle, int16_t *reading);
float convert_to_current(int16_t reading);
void add_to_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_address;
    int led_pin;
    float current_threshold;
} Config;

Config config = {I2C_ADDR, LED_GPIO, CURRENT_THRESHOLD};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Initialize circular buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        current_buffer[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_reading;
        if (read_ads1115(i2c_handle, &raw_reading) == 0) {
            float current = convert_to_current(raw_reading);
            add_to_buffer(current);
            float average_current = calculate_average();
            control_led(average_current);
            printf("Average Current: %.2f A\n", average_current);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 10Hz sampling
    }

    // Cleanup
    gpioWrite(config.led_pin, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, config.i2c_address, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read from ADS1115
int read_ads1115(int i2c_handle, int16_t *reading) {
    char config[3];
    char data[2];

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 128 SPS
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, 4.096V, Continuous, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (Disable comparator, non-latching)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    gpioDelay(1000); // Wait for conversion (adjust as needed)

    // Read the conversion result
    char reg = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Failed to write register address\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    *reading = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw reading to current
float convert_to_current(int16_t reading) {
    float voltage = (float)reading * (VOLTAGE_MAX - VOLTAGE_MIN) / 32767.0 + VOLTAGE_MIN;
    float current = (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * CURRENT_MAX;
    return current;
}

// Add current to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > config.current_threshold) {
        gpioWrite(config.led_pin, 1); // Turn on LED
    } else {
        gpioWrite(config.led_pin, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

