#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_sensor();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the sensor
int verify_sensor() {
    int id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }

    if ((id & 0x44) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    printf("Sensor ID: 0x%02X\n", id);
    return 0;
}

// Function to configure the sensor
int configure_sensor() {
    // Set integration time (ATIME) to 0xFF (2.4ms)
    int result = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error setting integration time: %d\n", result);
        return -1;
    }

    // Set gain (CONTROL) to 0x01 (4x)
    result = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error setting gain: %d\n", result);
        return -1;
    }

    // Power on and enable ADC (ENABLE = 0x01 | 0x02)
    result = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03);
    if (result < 0) {
        fprintf(stderr, "Error enabling sensor: %d\n", result);
        return -1;
    }

    gpioDelay(3); // Wait 3ms after power-on
    return 0;
}

// Function to read color data
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;

    result = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", result);
        return -1;
    }
    *clear = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    *red = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
    }
    *green = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", result);
        return -1;
    }
    *blue = (uint16_t)result;

    return 0;
}

// Function to log data to a CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;
    int read_failures = 0;

    // Main loop
    while (!terminate) {
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
            read_failures = 0; // Reset failure counter
        } else {
            fprintf(stderr, "I2C read failure. Retrying...\n");
            read_failures++;
            if (read_failures >= 3) {
                fprintf(stderr, "Too many I2C read failures. Exiting.\n");
                break;
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

