    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;
    int read_failures = 0;

    // Main loop
    while (!terminate) {
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
            read_failures = 0; // Reset failure counter
        } else {
