#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_SHUTDOWN 17
#define OVERCURRENT_THRESHOLD 10.0
#define OVERCURRENT_DURATION 1
#define ADC_CHANNEL 0
#define VREF 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.05

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *shutdown_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int gpio_init(int gpio_pin);
int gpio_set_value(int gpio_pin, int value);
int log_data(float current);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    unsigned int mode = SPI_MODE_0;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    unsigned int bits = 8;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    unsigned int speed = 1000000; // 1 MHz
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;
    int ret, retries = 3;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    while (retries > 0) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret == 1) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            perror("SPI transaction failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read ADC after multiple retries.\n");
    return -1; // Indicate failure
}

// ADC to Voltage Conversion
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Voltage to Current Conversion
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// GPIO Initialization
int gpio_init(int gpio_pin) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    shutdown_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!shutdown_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(shutdown_line, "motor_shutdown", 1); // Request as output, initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int gpio_pin, int value) {
    int ret;

    ret = gpiod_line_set_value(shutdown_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

// Log Data
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1); // Set HIGH before releasing
        gpiod_line_release(shutdown_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int adc_value;
    float voltage, current;
    time_t last_overcurrent_time = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_SHUTDOWN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    printf("Starting data acquisition...\n");

    while (keep_running) {
        // Read ADC value
        adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        current = voltage_to_current(voltage);

        // Log data
        log_data(current);

        // Overcurrent protection
        if (current > OVERCURRENT_THRESHOLD) {
            time_t now = time(NULL);
            if (now - last_overcurrent_time >= OVERCURRENT_DURATION) {
                printf("Overcurrent detected: %.3f A\n", current);
                if (gpio_set_value(GPIO_SHUTDOWN, 0) < 0) { // Set LOW to disable motor
                    fprintf(stderr, "Failed to set GPIO value.\n");
                }
                last_overcurrent_time = now;
            }
        } else {
            if (gpio_set_value(GPIO_SHUTDOWN, 1) < 0) { // Set HIGH to enable motor
                fprintf(stderr, "Failed to set GPIO value.\n");
            }
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

