#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define PRESSURE_SCALE_FACTOR 500.0
#define PRESSURE_MAX_RAW 65535.0
#define LOG_FILE "pressure_log.csv"
#define READ_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure(int *raw_pressure);
double convert_to_kPa(int raw_pressure);
char *get_iso8601_timestamp();
int log_data(char *timestamp, double pressure_kPa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(int *raw_pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure to kPa
double convert_to_kPa(int raw_pressure) {
    return (raw_pressure / PRESSURE_MAX_RAW) * PRESSURE_SCALE_FACTOR;
}

// Get current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, double pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_pressure;
    double pressure_kPa;
    char *timestamp;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_data(timestamp, pressure_kPa) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading pressure, retrying...\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

