#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_DEFAULT 0x4083 // Single-shot mode, AIN0, +/-6.144V, 128 SPS

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int channel);
float convert_to_pressure(int adc_value);
float convert_to_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold ADC configuration
typedef struct {
    int channel;
    int gain;
    int sps;
} adc_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value from a specific channel
int read_adc(int channel) {
    int config;
    int retries = 3;
    int adc_value;

    // Configure the ADS1115 for single-ended reading on the specified channel
    switch (channel) {
        case 0:
            config = ADS1115_CONFIG_DEFAULT; // AIN0
            break;
        case 1:
            config = 0x4083 | 0x0001; // AIN1
            break;
        default:
            fprintf(stderr, "Invalid ADC channel: %d\n", channel);
            return -1;
    }

    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, ADS1115_CONFIG_REG, config) < 0) {
            fprintf(stderr, "Error writing to config register: %d\n", i2c_handle);
            retries--;
            gpioDelay(10000); // 10ms delay
        } else {
            gpioDelay(10000); // Wait for conversion (at least 10ms)
            adc_value = i2cReadWordData(i2c_handle, ADS1115_CONVERSION_REG);
            if (adc_value >= 0) {
                return adc_value;
            } else {
                fprintf(stderr, "Error reading from conversion register: %d\n", i2c_handle);
                retries--;
                gpioDelay(10000); // 10ms delay
            }
        }
    }

    fprintf(stderr, "Failed to read ADC after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to pressure (kPa)
float convert_to_pressure(int adc_value) {
    // Assuming 16-bit ADC, 0-65535 range
    // 0V = 0 kPa, 5V = 400 kPa
    float voltage = (float)adc_value / 65535.0 * 5.0;
    float pressure = voltage * 80.0; // 400 kPa / 5V
    return pressure;
}

// Function to convert ADC value to temperature (°C)
float convert_to_temperature(int adc_value) {
    // Assuming 16-bit ADC, 0-65535 range
    // 1V = 0°C, 2V = 100°C
    float voltage = (float)adc_value / 65535.0 * 5.0;
    float temperature = (voltage - 1.0) * 100.0; // 100°C / 1V
    return temperature;
}

// Function to control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int pressure_adc = read_adc(0);
        int temperature_adc = read_adc(1);

        if (pressure_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC values to pressure and temperature
        float pressure = convert_to_pressure(pressure_adc);
        float temperature = convert_to_temperature(temperature_adc);

        // Control the LED
        control_led(pressure);

        // Display pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

