#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MLX91209_ZERO_CURRENT_VOLTAGE 1.65
#define MLX91209_SENSITIVITY 0.066 // 66 mV/A
#define OVERCURRENT_THRESHOLD 10.0
#define SHUTDOWN_GPIO 27
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_data(float current);
void handle_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended channel configuration
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - MLX91209_ZERO_CURRENT_VOLTAGE) / MLX91209_SENSITIVITY;
}

// Function to log data to file
void log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.3f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle overcurrent condition
void handle_overcurrent(float current) {
    fprintf(log_file, "OVERCURRENT: Current = %.3f A\n", current);
    fflush(log_file);
    gpioWrite(SHUTDOWN_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000); // Wait for 1 second
    gpioWrite(SHUTDOWN_GPIO, 0); // Set GPIO LOW
    gpioTerminate(); // Terminate pigpio
    exit(1); // Exit the program
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set shutdown GPIO as output
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(SHUTDOWN_GPIO, 0); // Initialize to LOW

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(SHUTDOWN_GPIO, 0); // Ensure GPIO is LOW
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            cleanup();
            return 1;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log the data
        log_data(current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            handle_overcurrent(current);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

