#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define ALARM_GPIO 4
#define VOLTAGE_THRESHOLD 2.5
#define LOG_FILE "co_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_conversion(int adc_value, float vref);
void alarm_control(float voltage);
void log_data(float voltage);
void signal_handler(int signal);

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_conversion(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to control the alarm based on voltage
void alarm_control(float voltage) {
    if (voltage > VOLTAGE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Turn alarm ON
    } else {
        gpioWrite(ALARM_GPIO, 0); // Turn alarm OFF
    }
}

// Function to log data to a file
void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            float voltage = voltage_conversion(adc_value, VREF);
            alarm_control(voltage);
            log_data(voltage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

