#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CLK 11
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_CS 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define sensor parameters
#define ADC_MAX 1023
#define PPM_MAX 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm);
void alarm_check(float ppm);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // Construct SPI command
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode + channel number
    tx_buffer[2] = 0x00;                  // Dummy byte

    // Transfer data
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value
    adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return ((float)adc_value / ADC_MAX) * PPM_MAX;
}

// Function to log data to file
void log_data(float ppm) {
    time_t now;
    struct tm timeinfo;
    char timestamp[30];

    // Get current time
    time(&now);
    localtime_r(&now, &timeinfo);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    // Open log file in append mode
    log_file = fopen("methane_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    // Write data to log file
    fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm);

    // Close log file
    fclose(log_file);
}

// Function to check for alarm condition
void alarm_check(float ppm) {
    if (ppm > 1000.0) {
        fprintf(stderr, "ALARM: Methane concentration exceeds 1000 PPM (%.2f PPM)\n", ppm);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Set CS pin as output (optional, but good practice)
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioWrite(SPI_CS, 1); // Ensure CS is initially high

    return 0;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    int adc_value;
    float ppm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to PPM
        ppm = adc_to_ppm(adc_value);

        // Log data
        log_data(ppm);

        // Check for alarm
        alarm_check(ppm);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

