    float ppm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to PPM
        ppm = adc_to_ppm(adc_value);

        // Log data
        log_data(ppm);

        // Check for alarm
        alarm_check(ppm);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

