#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // V
#define OFFSET_VOLTAGE 0.5 // V
#define SENSITIVITY 0.1 // V/kPa
#define MIN_PRESSURE 0.0 // kPa
#define MAX_PRESSURE 100.0 // kPa
#define SAMPLE_RATE 1 // Hz
#define SAMPLE_PERIOD (60 * 1000000) // microseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_ads1115();
int read_ads1115(int16_t *raw_value);
float convert_to_voltage(int16_t raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float offset_voltage;
    float sensitivity;
    float min_pressure;
    float max_pressure;
} Config;

Config config = {
    I2C_BUS,
    ADS1115_ADDR,
    OFFSET_VOLTAGE,
    SENSITIVITY,
    MIN_PRESSURE,
    MAX_PRESSURE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_value;
    float voltage, pressure;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD;

    while (!terminate) {
        // Read raw ADC value
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Convert to voltage
        voltage = convert_to_voltage(raw_value);

        // Convert to pressure
        pressure = convert_to_pressure(voltage);

        // Validate pressure range
        if (pressure >= config.min_pressure && pressure <= config.max_pressure) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        // Sleep for the sample period
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure ADS1115
int config_ads1115() {
    // Configuration register value:
    // 0b1000001101000000 = Single-shot mode, AIN0, +/-4.096V, 128 SPS, Disable comparator
    uint16_t config_value = 0x8380; //0b1000001110000000

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    // Start a single conversion by writing to the conversion register
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to start conversion\n");
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion register\n");
        return 1;
    }

    // Combine the two bytes into a 16-bit value
    *raw_value = (read_buf[0] << 8) | read_buf[1];

    return 0;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    float voltage = (float)raw_value * REF_VOLTAGE / 32768.0;
    return voltage;
}

// Convert voltage to pressure
float convert_to_pressure(float voltage) {
    float pressure = (voltage - config.offset_voltage) / config.sensitivity;
    return pressure;
}

// Log pressure to file
int log_pressure(float pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

