#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_TEMPERATURE 1
#define V_SUPPLY 5.0
#define R0 10000.0
#define BETA 3950.0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} sensor_data_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12-bit)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * V_SUPPLY;
    float humidity = (voltage - 0.824) / 0.0315;
    return humidity;
}

// Function to calculate temperature using the thermistor equation
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * V_SUPPLY;
    float resistance = (V_SUPPLY * 10000.0) / voltage - 10000.0; // R = (V_SUPPLY * R0) / Vout - R0
    float temperature = (BETA / (log(resistance / R0) + BETA / 298.15)) - 273.15; // Temperature in Celsius
    return temperature;
}

// Function to log data to a file
void log_data(float humidity, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send an email alert
void send_email_alert(float humidity, float temperature) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2f C\" | ssmtp recipient@example.com", humidity, temperature);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Email alert failed\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    while (!terminate) {
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int temperature_adc = read_mcp3208(MCP3208_CHANNEL_TEMPERATURE);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        printf("Humidity: %.2f%%, Temperature: %.2f C\n", humidity, temperature);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

