#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define VREF 3.3
#define SENSITIVITY 0.3
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100 // Hz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_acceleration(int adc_value);
float calculate_magnitude(float x, float y, float z);
void log_data(int x, int y, int z, float magnitude);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to calculate acceleration in g
float calculate_acceleration(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float acceleration = (voltage - VREF / 2.0) / (SENSITIVITY / 1000.0);
    return acceleration;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log data to a file
void log_data(int x, int y, int z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000 / SAMPLE_RATE; // Calculate sleep time for desired sample rate

    while (!terminate) {
        int x_adc = read_adc(ADC_CHANNEL_X);
        int y_adc = read_adc(ADC_CHANNEL_Y);
        int z_adc = read_adc(ADC_CHANNEL_Z);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error reading ADC values, skipping sample\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (x_adc < 0 || x_adc > 1023 || y_adc < 0 || y_adc > 1023 || z_adc < 0 || z_adc > 1023) {
            fprintf(stderr, "ADC value out of range, skipping sample\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        float x_acceleration = calculate_acceleration(x_adc);
        float y_acceleration = calculate_acceleration(y_adc);
        float z_acceleration = calculate_acceleration(z_adc);
        float magnitude = calculate_magnitude(x_acceleration, y_acceleration, z_acceleration);

        log_data(x_adc, y_adc, z_adc, magnitude);

        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

