#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FIFO_REG 0xC1
#define COMMAND_REG 0xC0
#define MEASURE_COMMAND 0x01 // Example command to trigger measurement
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t ir_adc;
    int16_t red_adc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(time_t timestamp, int hr, int spo2, int error_flag);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si1172
int read_sensor_data(sensor_data_t *data) {
    char buf[4]; // Buffer to hold 4 bytes (2 IR, 2 RED)
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, COMMAND_REG, MEASURE_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error writing to command register: %d\n", result);
        return -1;
    }

    // Read FIFO data
    result = i2cReadI2CBlockData(i2c_handle, FIFO_REG, buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    // Parse the data (assuming IR is first 2 bytes, RED is next 2)
    data->ir_adc = (int16_t)((buf[1] << 8) | buf[0]);
    data->red_adc = (int16_t)((buf[3] << 8) | buf[2]);

    return 0;
}

// Log data to CSV file
int log_data(time_t timestamp, int hr, int spo2, int error_flag) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, hr, spo2, error_flag);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    time_t current_time;
    int hr, spo2, error_flag;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

