typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} icp10125_calibration_data_t;

icp10125_calibration_data_t calibration_data;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
int32_t convert_raw_to_pressure(int32_t raw_pressure, int32_t raw_temperature);
int32_t convert_raw_to_temperature(int32_t raw_temperature);
int log_data(int32_t pressure, int32_t temperature);
void display_data(int32_t pressure, int32_t temperature);
void signal_handler(int signal);
int read_calibration_data();
int write_calibration_data_to_file();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    char buf[24];
    if (i2cReadI2CBlockData(i2c_handle, 0x31, buf, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data.c0 = (buf[0] << 8) | buf[1];
    calibration_data.c1 = (buf[2] << 8) | buf[3];
    calibration_data.c00 = (buf[4] << 8) | buf[5];
    calibration_data.c10 = (buf[6] << 8) | buf[7];
    calibration_data.c01 = (buf[8] << 8) | buf[9];
    calibration_data.c11 = (buf[10] << 8) | buf[11];
    calibration_data.c20 = (buf[12] << 8) | buf[13];
    calibration_data.c21 = (buf[14] << 8) | buf[15];
    calibration_data.c30 = (buf[16] << 8) | buf[17];

    return 0;
}

// Write calibration data to file
int write_calibration_data_to_file() {
    FILE *fp = fopen("calibration_data.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration data file\n");
        return -1;
    }

    fprintf(fp, "c0: %d\n", calibration_data.c0);
    fprintf(fp, "c1: %d\n", calibration_data.c1);
    fprintf(fp, "c00: %d\n", calibration_data.c00);
    fprintf(fp, "c10: %d\n", calibration_data.c10);
    fprintf(fp, "c01: %d\n", calibration_data.c01);
    fprintf(fp, "c11: %d\n", calibration_data.c11);
    fprintf(fp, "c20: %d\n", calibration_data.c20);
    fprintf(fp, "c21: %d\n", calibration_data.c21);
    fprintf(fp, "c30: %d\n", calibration_data.c30);

    fclose(fp);
    return 0;
}

// Read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    int32_t raw_pressure, raw_temperature;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    // Wait for conversion to complete (adjust delay as needed)
    gpioDelay(100); // 100 ms delay

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Extract raw pressure and temperature values
    raw_pressure = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | (uint32_t)buf[2];
    raw_temperature = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    *pressure = raw_pressure;
    *temperature = raw_temperature;

    return 0;
}

