    // Placeholder for actual conversion formula from datasheet
    // This is a simplified example and needs to be replaced with the correct formula
    return (int32_t)((double)raw_pressure * 0.1); // Example scaling
}

// Convert raw temperature to Celsius
int32_t convert_raw_to_temperature(int32_t raw_temperature) {
    // Placeholder for actual conversion formula from datasheet
    // This is a simplified example and needs to be replaced with the correct formula
    return (int32_t)((double)raw_temperature * 0.01); // Example scaling
}

// Log data to CSV file
