    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%d,%d\n", timestamp, pressure, temperature);
    fflush(csv_file); // Ensure data is written to file immediately

    return 0;
}

// Display data on console
void display_data(int32_t pressure, int32_t temperature) {
    printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
