// Structure to hold audio data
typedef struct {
    int16_t channel1;
    int16_t channel2;
    int16_t difference;
} AudioData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
int16_t process_audio_data(int raw1, int raw2, float gain);
void output_audio_data(AudioData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
