}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Process audio data (apply gain and calculate difference)
int16_t process_audio_data(int raw1, int raw2, float gain) {
    int16_t channel1 = (int16_t)(raw1 * gain);
    int16_t channel2 = (int16_t)(raw2 * gain);
    int16_t difference = channel1 - channel2;
    return difference;
}

// Output audio data to the terminal in CSV format
void output_audio_data(AudioData data) {
    printf("%d,%d,%d\n", data.channel1, data.channel2, data.difference);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float gain = DEFAULT_GAIN;

    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Invalid gain value. Using default gain: %f\n", DEFAULT_GAIN);
            gain = DEFAULT_GAIN;
        }
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    printf("Audio processing started. Gain: %f\n", gain);

    // Main loop
    while (!terminate) {
        int raw1 = read_mcp3008(MCP3008_CHANNEL_1);
        int raw2 = read_mcp3008(MCP3008_CHANNEL_2);

        if (raw1 == -1 || raw2 == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        AudioData data;
        data.channel1 = (int16_t)(raw1 * gain);
        data.channel2 = (int16_t)(raw2 * gain);
        data.difference = process_audio_data(raw1, raw2, gain);

        output_audio_data(data);

        gpioDelay(1000); // 1ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

