#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE 0  // CE0 (GPIO8)
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define water level thresholds
#define WATER_LEVEL_HIGH 75
#define WATER_LEVEL_LOW 70

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void control_led(float water_level);
void log_to_json(float water_level);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];
    int adc_value;

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", pigpio_error(result));
        return -1; // Indicate error
    }

    // Parse ADC value
    adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_HIGH) {
        gpioWrite(LED_PIN, 1); // Turn LED ON
    } else if (water_level < WATER_LEVEL_LOW) {
        gpioWrite(LED_PIN, 0); // Turn LED OFF
    }
}

// Function to log water level data to JSON file
void log_to_json(float water_level) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
    char timestamp[80];
    snprintf(timestamp, sizeof(timestamp), "%s.%03ld", buf, (long)now % 1000);

    // Create JSON object
    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);

    // Append to JSON file
    if (json_file != NULL) {
        fprintf(json_file, "%s", json_string);
        fflush(json_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: JSON file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open JSON file
    json_file = fopen("water_levels.json", "a+");
    if (json_file == NULL) {
        fprintf(stderr, "Error opening JSON file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket if file is empty
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
        fflush(json_file);
    } else {
        // If not empty, go back one character and overwrite the closing bracket
        fseek(json_file, -1, SEEK_END);
        int c = fgetc(json_file);
        if (c == ']') {
            fseek(json_file, -1, SEEK_END);
            fprintf(json_file, ",");
            fflush(json_file);
        } else {
            fprintf(stderr, "Error: JSON file is not properly formatted.\n");
            fclose(json_file);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
    }

    return 0;
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close JSON file
    if (json_file != NULL) {
        fprintf(json_file, "]");
        fclose(json_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping.\n");
            gpioDelay(5000); // Wait 5 seconds
            continue;
        }

        // Convert to percentage
        float water_level = convert_to_percentage(adc_value);

        // Control LED
        control_led(water_level);

        // Log to JSON
        log_to_json(water_level);

        // Print to console
        printf("Water Level: %.2f%%\n", water_level);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    cleanup();

    return 0;
}

