#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define SENSITIVITY 0.01 // V/LPM
#define OFFSET 0.5 // V
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
float convert_to_lpm(int adc_value);
char* get_iso8601_timestamp();
int log_data(char *timestamp, float lpm);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    float sensitivity;
    float offset;
    char *log_file;
    int sample_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    VREF,
    SENSITIVITY,
    OFFSET,
    LOG_FILE,
    SAMPLE_INTERVAL_MS
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to LPM
        float lpm = convert_to_lpm(adc_value);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, lpm) != 0) {
            fprintf(stderr, "Failed to log data. Retrying.\n");
        }

        free(timestamp); // Free the allocated timestamp memory

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
