#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define MOISTURE_THRESHOLD 30
#define LOGGING_FREQUENCY 60
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
int dry_value = 300;
int wet_value = 700;
int moisture_threshold = MOISTURE_THRESHOLD;
int logging_frequency = LOGGING_FREQUENCY;
char *recipient_email = NULL;
char *msmtp_config = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int raw_value);
void log_data(float moisture_percent);
void send_email_alert(float moisture_percent);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int raw_value) {
    float moisture_percent = 100.0 - ((float)(raw_value - dry_value) / (float)(wet_value - dry_value)) * 100.0;

    // Clamp the value to be within 0-100%
    if (moisture_percent < 0.0) {
        moisture_percent = 0.0;
    } else if (moisture_percent > 100.0) {
        moisture_percent = 100.0;
    }

    return moisture_percent;
}

// Function to log data to file
void log_data(float moisture_percent) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percent) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Plant Moisture Alert\n\nMoisture level is below threshold (%.2f%%).\" | msmtp -t -f \"Plant Monitor\" %s", moisture_percent, recipient_email);

    FILE *email_pipe = popen(command, "r");
    if (email_pipe == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return;
    }

    int status = pclose(email_pipe);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "d:w:t:f:r:c:")) != -1) {
        switch (opt) {
            case 'd':
                dry_value = atoi(optarg);
                break;
            case 'w':
                wet_value = atoi(optarg);
                break;
            case 't':
                moisture_threshold = atoi(optarg);
                break;
            case 'f':
                logging_frequency = atoi(optarg);
                break;
            case 'r':
                recipient_email = optarg;
                break;
            case 'c':
                msmtp_config = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-d dry_value] [-w wet_value] [-t moisture_threshold] [-f logging_frequency] [-r recipient_email] [-c msmtp_config]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (recipient_email == NULL) {
        fprintf(stderr, "Error: Recipient email is required\n");
        fprintf(stderr, "Usage: %s [-d dry_value] [-w wet_value] [-t moisture_threshold] [-f logging_frequency] [-r recipient_email] [-c msmtp_config]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int raw_value = -1;
        int retries = 0;

        // Retry reading ADC value if it fails
        while (raw_value == -1 && retries < MAX_RETRIES) {
            raw_value = read_mcp3008(0); // Read from channel 0
            if (raw_value == -1) {
                fprintf(stderr, "Error: Failed to read ADC value, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value after multiple retries\n");
        } else {
            float moisture_percent = calculate_moisture_percentage(raw_value);
            printf("Moisture: %.2f%%\n", moisture_percent);

            log_data(moisture_percent);

            if (moisture_percent < moisture_threshold) {
                send_email_alert(moisture_percent);
            }
        }

        gpioDelay(logging_frequency * 1000); // Wait for logging_frequency seconds
    }

    return 0;
}

