#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for SPI communication
#define CE0 8
#define MISO 9
#define MOSI 10
#define SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define pressure span
#define MIN_PRESSURE 10.0  // kPa
#define MAX_PRESSURE 150.0 // kPa
#define MIN_VOLTAGE 0.5    // V
#define MAX_VOLTAGE 4.5    // V

// Define sensor absent thresholds
#define SENSOR_STUCK_LOW 0.1 // V
#define SENSOR_STUCK_HIGH 3.2 // V

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_reading(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int ce_pin;
    int miso_pin;
    int mosi_pin;
    int sclk_pin;
    int spi_channel;
    int spi_baud;
    float min_pressure;
    float max_pressure;
    float min_voltage;
    float max_voltage;
    float sensor_stuck_low;
    float sensor_stuck_high;
} config_t;

config_t config = {
    CE0, MISO, MOSI, SCLK, SPI_CHANNEL, SPI_BAUD,
    MIN_PRESSURE, MAX_PRESSURE, MIN_VOLTAGE, MAX_VOLTAGE,
    SENSOR_STUCK_LOW, SENSOR_STUCK_HIGH
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log the reading
        log_reading(pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1023.0;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < config.min_voltage) {
        return config.min_pressure;
    } else if (voltage > config.max_voltage) {
        return config.max_pressure;
    } else {
        return config.min_pressure + (voltage - config.min_voltage) * (config.max_pressure - config.min_pressure) / (config.max_voltage - config.min_voltage);
    }
}

// Log the reading with ISO 8601 timestamp
void log_reading(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

