        return config.max_pressure;
    } else {
        return config.min_pressure + (voltage - config.min_voltage) * (config.max_pressure - config.min_pressure) / (config.max_voltage - config.min_voltage);
    }
}

// Log the reading with ISO 8601 timestamp
void log_reading(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

