static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ce0_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int fd, int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int sig);
int setup_gpio(void);
int setup_spi(void);
void cleanup(void);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    ssize_t bytes_read = read(fd, rx_buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spi_transfer(fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    float moisture_percentage = 0.0;

    if (adc_value < MIN_ADC_VALUE) {
        moisture_percentage = 0.0;
    } else if (adc_value > MAX_ADC_VALUE) {
        moisture_percentage = 100.0;
    } else {
        moisture_percentage = ((float)(adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
    }

    return moisture_percentage;
}

