#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define VREF 3.3
#define NUM_SENSORS 4
#define LOG_FILE "environmental_data.csv"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *cs_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
int log_data(float voltages[NUM_SENSORS]);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    // Assert chip select
    ret = gpiod_line_set_value(cs_line, 0);
    if (ret < 0) {
        perror("Error asserting chip select");
        return -1;
    }

    // Transfer data
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        // De-assert chip select even on error
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    // De-assert chip select
    ret = gpiod_line_set_value(cs_line, 1);
    if (ret < 0) {
        perror("Error de-asserting chip select");
