#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL 5 // seconds
#define BUFFER_SIZE 20

// Structure for log entry
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer structure
typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global variables
int spi_handle;
CircularBuffer log_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void add_log_entry(CircularBuffer *buffer, int moisture_level, int pump_state);
void print_log_buffer(CircularBuffer *buffer);
void timer_callback();
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

// Add log entry to circular buffer
void add_log_entry(CircularBuffer *buffer, int moisture_level, int pump_state) {
    time_t now = time(NULL);
    buffer->entries[buffer->head].timestamp = now;
    buffer->entries[buffer->head].moisture_level = moisture_level;
    buffer->entries[buffer->head].pump_state = pump_state;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Print log buffer
void print_log_buffer(CircularBuffer *buffer) {
    printf("\n--- Log Buffer ---\n");
    int i = buffer->tail;
    for (int j = 0; j < buffer->count; j++) {
        struct tm *timeinfo = localtime(&buffer->entries[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, buffer->entries[i].moisture_level, buffer->entries[i].pump_state ? "ON" : "OFF");
        i = (i + 1) % BUFFER_SIZE;
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Control water pump based on moisture level
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = OFF, 1 = ON

    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        pump_state = 1;
        printf("Pump ON\n");
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        pump_state = 0;
        printf("Pump OFF\n");
    }
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    control_pump(moisture_level);
    add_log_entry(&log_buffer, moisture_level, gpioRead(PUMP_GPIO));
    print_log_buffer(&log_buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFunc(0, SAMPLE_INTERVAL * 1000, timer_callback); // Timer 0, every SAMPLE_INTERVAL ms

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

