#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define PART_ID_VALUE 0x15
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define FIFO_CONFIG_REG 0x05
#define FIFO_CONFIG_VALUE 0x0F // Enable FIFO, Sample Average = 1

#define SAMPLE_RATE 1 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(uint32_t *red, uint32_t *ir);
float calculate_spo2(uint32_t red, uint32_t ir);
int calculate_hr(uint32_t *ir_data, int data_len);
void log_data(float spo2, int hr);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    uint32_t red;
    uint32_t ir;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the MAX30102 sensor
int init_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode\n");
        return -1;
    }

    // Configure SPO2_CONFIG register
    if (i2cWriteByteData(i2c_handle, SPO2_CONFIG_REG, 0x27) < 0) {
        fprintf(stderr, "Error configuring SPO2_CONFIG\n");
        return -1;
    }

    // Set LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, LED1_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error setting LED1_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LED2_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error setting LED2_PA\n");
        return -1;
    }

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, FIFO_CONFIG_REG, FIFO_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error configuring FIFO\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint32_t *red, uint32_t *ir) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *red = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | (uint32_t)buffer[2];
    *ir = ((uint32_t)buffer[3] << 16) | ((uint32_t)buffer[4] << 8) | (uint32_t)buffer[5];

