#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY_MS 50
#define THRESHOLD_PERCENT 80
#define RELAY_DURATION_S 3
#define POLL_DELAY_MS 200

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int i2c_fd);
float calculate_average(int *samples, int count);
float calculate_threshold(float average, float percentage);
int control_relay(int gpio, int state);
int read_reed_sensor(int gpio);
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int i2c_fd) {
    unsigned char config[3];
    unsigned char buffer[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, start single conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-shot mode, AIN0, +/-4.096V, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (Don't care)

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    config[0] = 0x00; // Conversion register address
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to ADS1115 for read");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from ADS1115");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Function to calculate the average of an array
float calculate_average(int *samples, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i];
    }
    return sum / count;
}

// Function to calculate the threshold
float calculate_threshold(float average, float percentage) {
    return average * (1.0 - percentage / 100.0);
}

// Function to control the relay
int control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Function to read the reed sensor
int read_reed_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log events
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int main() {
    int samples[SAMPLE_COUNT];
    float average;
    float threshold;
    int adc_value;
    int reed_state;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("/var/log/door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure GPIOs
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(REED_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(REED_SENSOR_GPIO, PI_PUD_UP);

    // Collect baseline samples
    printf("Collecting baseline samples...\n");
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        adc_value = read_ads1115(i2c_fd);
        if (adc_value < 0) {
            log_event("Error reading ADC during baseline collection");
            samples[i] = 0; // Use a default value to avoid affecting the average
        } else {
            samples[i] = adc_value;
        }
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to us
    }

    // Calculate average and threshold
    average = calculate_average(samples, SAMPLE_COUNT);
    threshold = calculate_threshold(average, THRESHOLD_PERCENT);
    printf("Baseline average: %.2f, Threshold: %.2f\n", average, threshold);

    // Main loop
    while (!terminate) {
        adc_value = read_ads1115(i2c_fd);
        if (adc_value < 0) {
            log_event("Error reading ADC");
        } else {
            printf("ADC Value: %d\n", adc_value);
            if (adc_value < threshold) {
                printf("Threshold breached!\n");
                log_event("Threshold breached");

                // Control relay
                control_relay(RELAY_GPIO, 1); // Energize relay
                log_event("Relay energized");
                gpioDelay(RELAY_DURATION_S * 1000000); // 3 seconds
                control_relay(RELAY_GPIO, 0); // De-energize relay
                log_event("Relay de-energized");

                // Read reed sensor
                reed_state = read_reed_sensor(REED_SENSOR_GPIO);
                if (reed_state == 0) {
                    log_event("Door opened");
                    printf("Door opened\n");
                } else {
                    log_event("Door not opened");
                    printf("Door not opened\n");
                }
            }
        }
        gpioDelay(POLL_DELAY_MS * 1000); // Convert ms to us
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

