#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for chip select lines
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define the number of sensors
#define NUM_SENSORS 3

// Global variables for SPI handles and file pointer
int spi_handle;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int cs_pin, int channel);
int log_data(int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} SensorData;

// Function to read data from MCP3008 ADC
int read_mcp3008(int cs_pin, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Default to -1 in case of error

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Set the chip select pin low to select the chip
    gpioWrite(cs_pin, 0);

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        gpioWrite(cs_pin, 1); // Deselect the chip
        return -1; // Indicate an error
    }

    // Set the chip select pin high to deselect the chip
    gpioWrite(cs_pin, 1);

    // Extract the ADC value from the received data
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to a CSV file
int log_data(int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Get the current time
    time(&current_time);
    time_info = localtime(&current_time);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    // Open the log file in append mode
    if (log_file == NULL) {
        log_file = fopen("soil_moisture_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }

        // Write the CSV header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        }
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close the SPI connection
    spiClose(spi_handle);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins for chip select as outputs
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Initialize the SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_mcp3008(CS0, 0);
        int sensor2_value = read_mcp3008(CS1, 0);
        int sensor3_value = read_mcp3008(CS2, 0);

        // Log the data
        if (log_data(sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

