// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_RAW 200
#define WET_RAW 800
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_moisture(int raw_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], float *threshold, int *duration, int *interval);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        log_message("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map raw ADC value to moisture percentage
float map_moisture(int raw_value) {
    float moisture = (float)(raw_value - DRY_RAW) * 100.0 / (WET_RAW - DRY_RAW);
    if (moisture < 0.0) {
        moisture = 0.0;
    } else if (moisture > 100.0) {
        moisture = 100.0;
    }
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Pump %s", state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

