    float moisture_threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_INTERVAL;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &moisture_threshold, &pump_duration, &sleep_interval) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Starting irrigation system...");

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int raw_value = read_mcp3008(0);
        if (raw_value < 0) {
            log_message("Error reading moisture sensor, skipping irrigation cycle.");
        } else {
            // Map raw value to moisture percentage
            float moisture = map_moisture(raw_value);

            // Log moisture reading
            char message[100];
            snprintf(message, sizeof(message), "Moisture: %.2f%% (Raw: %d)", moisture, raw_value);
            log_message(message);

            // Check if moisture is below threshold
            if (moisture < moisture_threshold) {
                log_message("Moisture below threshold, activating pump.");
                control_pump(1); // Turn pump ON
                gpioDelay(pump_duration * 1000000); // Wait for specified duration
                control_pump(0); // Turn pump OFF
                log_message("Pump deactivated.");
            }
        }

        gpioDelay(sleep_interval * 1000000); // Wait for specified interval
    }

    // Cleanup
    log_message("Shutting down...");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

