#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Control byte for single-ended AIN0, analog output disabled
#define CONTROL_BYTE 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl-C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a single sample from the PCF8591
int read_sample(int fd) {
    unsigned char data[1];
    int result;

    // Write the control byte to start the conversion
    result = write(fd, &CONTROL_BYTE, 1);
    if (result != 1) {
        perror("Error writing control byte");
        return -1;
    }

    // Read the dummy byte
    result = read(fd, data, 1);
    if (result != 1) {
        perror("Error reading dummy byte");
        return -1;
    }

    // Read the actual sample
    result = read(fd, data, 1);
    if (result != 1) {
        perror("Error reading sample");
        return -1;
    }

    return data[0];
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        int sample = read_sample(i2c_fd);
        if (sample >= 0) {
            printf("Sample: %d\n", sample);
        } else {
            fprintf(stderr, "Error reading sample, exiting...\n");
            break;
        }

        usleep(100000); // 100 ms
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

