#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_MOTOR_SHUTDOWN 27
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define THRESHOLD_GAUSS 500
#define CIRCULAR_BUFFER_SIZE 10

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_readings[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
float read_ads1115();
float voltage_to_gauss(float voltage);
void update_circular_buffer(float gauss);
float calculate_rolling_average();
void check_threshold(float average_gauss);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (example)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int gpio_motor_shutdown;
    int sample_rate_hz;
    int threshold_gauss;
} Config;

Config config = {
    I2C_BUS,
    ADS1115_ADDR,
    GPIO_MOTOR_SHUTDOWN,
    SAMPLE_RATE_HZ,
    THRESHOLD_GAUSS
};

int main() {
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (initialize() != 0) {
        syslog(LOG_ERR, "Initialization failed. Exiting.");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float voltage = read_ads1115();
        if (voltage >= 0.0 && voltage <= 3.3) {
            float gauss = voltage_to_gauss(voltage);
            update_circular_buffer(gauss);
            float average_gauss = calculate_rolling_average();
            check_threshold(average_gauss);
            syslog(LOG_INFO, "Magnetic field: %.2f Gauss, Average: %.2f Gauss", gauss, average_gauss);
        } else {
            syslog(LOG_ERR, "Invalid voltage reading: %.2f V", voltage);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    closelog();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Initialize to LOW

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    uint16_t config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to configure ADS1115");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

float read_ads1115() {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115");
        return -1.0;
    }

    gpioDelay(100); // Wait for conversion (adjust as needed)

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from ADS1115");
        return -1.0;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    float voltage = (float)raw_value * 4.096 / 32768.0; // 4.096V range, 16-bit
    return voltage;
}

float voltage_to_gauss(float voltage) {
    // SS49E transfer function: V = 2.5V + (Gauss * 1.4mV/Gauss)
    // Solving for Gauss: Gauss = (V - 2.5V) / 1.4mV/Gauss
    return (voltage - 2.5) / 0.0014;
}

void update_circular_buffer(float gauss) {
    magnetic_field_readings[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        sum += magnetic_field_readings[i];
    }
    return sum / CIRCULAR_BUFFER_SIZE;
}

void check_threshold(float average_gauss) {
    if (average_gauss > config.threshold_gauss) {
        syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", average_gauss);
        gpioWrite(GPIO_MOTOR_SHUTDOWN, 1); // Set GPIO HIGH
    } else {
        gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Set GPIO LOW
    }
}

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Ensure GPIO is LOW
    gpioTerminate();
}

