#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define WATERING_INTERVAL 60 // seconds
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
int log_event(int adc_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and watering system started.\n");

    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read soil moisture\n");
            // Attempt to recover by re-initializing SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Log the event
        log_event(adc_value);

        // Control the pump
        if (adc_value < MOISTURE_THRESHOLD) {
            printf("Moisture level low (%d). Activating pump.\n", adc_value);
            if (control_pump(1) != 0) {
                fprintf(stderr, "Error: Failed to activate pump\n");
                terminate = 1; // Exit loop if pump activation fails
            }
            gpioDelay(WATERING_DURATION * 1000000); // Wait for watering duration
            if (control_pump(0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate pump\n");
                terminate = 1; // Exit loop if pump deactivation fails
            }
            printf("Pump deactivated.\n");
        }

        // Wait before next reading
        gpioDelay(WATERING_INTERVAL * 1000000); // Wait for watering interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Deactivate pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

