#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_ON_TIME 50    // milliseconds
#define BLINK_OFF_TIME 50   // milliseconds

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_ads1115(int i2c_handle, int16_t *value);
double convert_to_gauss(int16_t raw_value);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, continuous conversion mode
    uint16_t config = 0x4083; // 0b0100000010000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int i2c_handle, int16_t *value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "I2C write (conversion reg) failed\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Sensitivity: 1.0 mV/Gauss = 0.001 V/Gauss
    // Zero-gauss output: 1.65V
    // Gain: 4.096V
    // Resolution: 16 bits
    double voltage = (double)raw_value * 4.096 / 32768.0;
    double gauss = (voltage - 1.65) / 0.001;
    return gauss;
}

// Control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Cleanup resources
void cleanup() {
    control_led(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[i + 1]);
            i++;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    int16_t raw_value;
    double gauss;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    printf("Monitoring magnetic field strength. Threshold: %.2f Gauss\n", threshold);

    while (!terminate) {
        if (read_ads1115(i2c_handle, &raw_value) == 0) {
            gauss = convert_to_gauss(raw_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                printf("Threshold exceeded! Blinking LED for %d ms\n", BLINK_DURATION);
                for (int i = 0; i < BLINK_DURATION / (BLINK_ON_TIME + BLINK_OFF_TIME); i++) {
                    control_led(GPIO_LED, 1); // Turn on LED
                    gpioDelay(BLINK_ON_TIME * 1000); // Convert ms to microseconds
                    control_led(GPIO_LED, 0); // Turn off LED
                    gpioDelay(BLINK_OFF_TIME * 1000); // Convert ms to microseconds
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

