        return -1.0; // Indicate error
    }

    // Assuming 0 ADC value = 0% moisture, 1023 ADC value = 100% moisture
    float moisture = (float)adc_value / 1023.0 * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", RELAY_GPIO);
    }
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
}

