#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Define GPIO pins for vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;

// Function prototypes
int read_mcp3008(int channel);
int map_noise_to_duty_cycle(int noise_level);
void control_motor(int gpio_pin, int duty_cycle);
void log_event(int noise_level, int duty_cycle);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map noise level to PWM duty cycle
int map_noise_to_duty_cycle(int noise_level) {
    if (noise_level > NOISE_THRESHOLD) {
        // Linear mapping from 500 to 1023 to 0 to 100
        return (int)(((float)(noise_level - NOISE_THRESHOLD) / (1023.0 - NOISE_THRESHOLD)) * 100.0);
    } else {
        return 0;
    }
}

// Function to control vibration motor
void control_motor(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to log event to file
void log_event(int noise_level, int duty_cycle) {
    FILE *fp = fopen("vibration_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Noise Level: %d, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            noise_level, duty_cycle);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop motors
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpioTerminate();
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level, skipping iteration\n");
            usleep(10000); // 10 ms
            continue;
        }

        // Map noise level to duty cycle
        int duty_cycle = map_noise_to_duty_cycle(noise_level);

        // Control vibration motors
        control_motor(MOTOR1_GPIO, duty_cycle);
        control_motor(MOTOR2_GPIO, duty_cycle);

        // Log event
        log_event(noise_level, duty_cycle);

        // Wait for 10 ms
        usleep(10000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

