#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE2 0x11
#define CSV_FILE "tamper_log.csv"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
float lux_to_db(float lux);
void log_data(float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB
float adc_to_db(int adc_value) {
    // Simple linear conversion (adjust as needed based on MAX9814 characteristics)
    return (float)adc_value * 0.1; // Example: 0.1 dB per ADC unit
}

// Function to read from BH1750 sensor
int read_bh1750() {
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE2) != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 mode\n");
        return -1;
    }
    gpioDelay(180); // Wait for measurement (at least 180ms)

    int lux = i2cReadWordData(i2c_handle, 0x00);
    if (lux < 0) {
        fprintf(stderr, "Error: Failed to read BH1750 data\n");
        return -1;
    }

    return lux;
}

// Function to convert lux to dB (example conversion)
float lux_to_db(float lux) {
    // Example conversion: dB = 10 * log10(lux + 1) - 20
    return 10 * log10(lux + 1) - 20;
}

// Function to log data to CSV file
void log_data(float sound_level_db, float light_level_lux, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Tamper detection system started. Logging to %s\n", CSV_FILE);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level_db = 0.0;
        float light_level_lux = 0.0;
        int error_code = 0;

        if (adc_value >= 0) {
            sound_level_db = adc_to_db(adc_value);
        } else {
            error_code = 1; // ADC read error
        }

        int lux = read_bh1750();
        if (lux >= 0) {
            light_level_lux = (float)lux; // Return value from read_bh1750 is already lux
        } else {
            error_code = 2; // BH1750 read error
        }

        float db_from_lux = lux_to_db(light_level_lux);
        if (db_from_lux < 0) {
            error_code = 3; // Lux to dB conversion error
        }

        log_data(sound_level_db, light_level_lux, error_code);

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    fprintf(stderr, "Tamper detection system stopped.\n");
    return 0;
}

