        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MQ135_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to CO2 ppm
        float co2_ppm = adc_to_co2(adc_value);
        if (co2_ppm < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to CO2 ppm\n");
            continue; // Skip to the next iteration
        }

        // Control the fan
        control_fan(co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);

        // Log the data
        log_data(co2_ppm, fan_state);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 milliseconds = 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Air quality monitoring stopped.\n");
    return 0;
}

