// Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_CLOCK_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *door_sensor_line;
static struct gpiod_line *entry_sensor_line;
static struct gpiod_line *exit_sensor_line;
static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_adc(int channel);
float adc_to_distance(int adc_value);
int read_door_sensor();
int read_entry_sensor();
int read_exit_sensor();
int control_relay(int state);
int log_event(const char *event_type, int sensor_state);
void signal_handler(int sig);
int setup();
void cleanup();

// Function to read from MCP3008 ADC via SPI
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command to read a single channel
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_CLOCK_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to distance (cm) - Linear approximation
float adc_to_distance(int adc_value) {
    // This is a simplified linear approximation.
    // You'll need to calibrate this based on your specific sensor.
    // The GP2Y0A21YK0F has a non-linear response, so a more complex
    // calibration curve would be better for accuracy.
    // This is just for demonstration purposes.
    if (adc_value < 100) return 100.0; // Max range
    return 100.0 - ((float)adc_value - 100.0) * (100.0 / 900.0); // Min range
}

