}

// Setup function to initialize GPIO and SPI
int setup() {
    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    door_sensor_line = gpiod_chip_get_line(chip, 23); // Example GPIO for door sensor
    if (!door_sensor_line) {
        perror("Failed to get door sensor GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    entry_sensor_line = gpiod_chip_get_line(chip, 24); // Example GPIO for entry sensor
    if (!entry_sensor_line) {
        perror("Failed to get entry sensor GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    exit_sensor_line = gpiod_chip_get_line(chip, 25); // Example GPIO for exit sensor
    if (!exit_sensor_line) {
        perror("Failed to get exit sensor GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "door_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT; // Relay
    config.flags = 0;

    if (gpiod_line_request(relay_line, &config, 0) < 0) {
        perror("Failed to request relay GPIO line");
        cleanup();
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "door_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Door sensor
    config.flags = 0;

    if (gpiod_line_request(door_sensor_line, &config, 0) < 0) {
        perror("Failed to request door sensor GPIO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request(entry_sensor_line, &config, 0) < 0) {
        perror("Failed to request entry sensor GPIO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request(exit_sensor_line, &config, 0) < 0) {
        perror("Failed to request exit sensor GPIO line");
        cleanup();
        return -1;
    }

    // Initialize SPI
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.0"); // SPI0, CE0
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return -1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return -1;
    }

    // Configure SPI clock speed
    unsigned int speed = SPI_CLOCK_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI clock speed");
        cleanup();
        return -1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // De-energize relay
        gpiod_line_release(relay_line);
    }
    if (door_sensor_line) gpiod_line_release(door_sensor_line);
    if (entry_sensor_line) gpiod_line_release(entry_sensor_line);
    if (exit_sensor_line) gpiod_line_release(exit_sensor_line);
    if (chip) gpiod_chip_close(chip);

    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() < 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    printf("Door monitoring system started.\n");

    int proximity_detected = 0;
    time_t last_debounce_time = 0;

    while (!terminate) {
        // Read sensor values
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        float distance = adc_to_distance(adc_value);
        int door_state = read_door_sensor();
        int entry_state = read_entry_sensor();
        int exit_state = read_exit_sensor();

        if (distance < PROXIMITY_THRESHOLD) {
            if (!proximity_detected) {
                // Proximity detected
                if (time(NULL) - last_debounce_time >= DEBOUNCE_DELAY) {
                    printf("Proximity detected! Distance: %.2f cm\n", distance);
                    if (control_relay(1) == 0) { // Energize relay
                        log_event("Proximity Detected", 1);
                        proximity_detected = 1;
                        last_debounce_time = time(NULL);
                    }
                }
            }
        } else {
            // Proximity lost
            if (proximity_detected) {
                if (time(NULL) - last_debounce_time >= DEBOUNCE_DELAY) {
                    printf("Proximity lost! Distance: %.2f cm\n", distance);
                    if (control_relay(0) == 0) { // De-energize relay
                        log_event("Proximity Lost", 0);
                        proximity_detected = 0;
                        last_debounce_time = time(NULL);
                    }
                }
            }
        }

        // Log sensor states
        log_event("Door Sensor", door_state);
        log_event("Entry Sensor", entry_state);
        log_event("Exit Sensor", exit_state);

        usleep(POLLING_INTERVAL * 1000); // Polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

