#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_GPIO 17
#define SPI_CE0 8
#define SPI_CE1 7
#define SPI_CE2 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define valve control parameters
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

// Define sensor parameters
#define NUM_SENSORS 3
#define SENSOR_CHANNELS {0, 1, 2}

// Define logging parameters
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_sensor_readings(int sensor_values[], int num_sensors);
int map_moisture_to_valve(float average_moisture);
void set_valve_position(int valve_position);
void log_data(int sensor_values[], float average_moisture, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read command)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to average sensor readings
float average_sensor_readings(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) {
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to map moisture level to valve position
int map_moisture_to_valve(float average_moisture) {
    // Inverse mapping: dry soil (low moisture) -> high valve opening (100)
    // wet soil (high moisture) -> low valve opening (0)
    // Ensure moisture is within 0-1023 range
    if (average_moisture < 0) average_moisture = 0;
    if (average_moisture > 1023) average_moisture = 1023;

    return (int)((1023 - average_moisture) * (PWM_RANGE / 1023.0));
}

// Function to set valve position using PWM
void set_valve_position(int valve_position) {
    gpioPWM(VALVE_GPIO, valve_position);
}

// Function to log data to file
void log_data(int sensor_values[], float average_moisture, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

