    // Inverse mapping: dry soil (low moisture) -> high valve opening (100)
    // wet soil (high moisture) -> low valve opening (0)
    // Ensure moisture is within 0-1023 range
    if (average_moisture < 0) average_moisture = 0;
    if (average_moisture > 1023) average_moisture = 1023;

    return (int)((1023 - average_moisture) * (PWM_RANGE / 1023.0));
