#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration structure
typedef struct {
    float distance_min;
    float distance_max;
    float frequency_min;
    float frequency_max;
    int spi_channel;
    char mqtt_broker_address[100];
    int mqtt_broker_port;
    char mqtt_client_id[50];
    char mqtt_username[50];
    char mqtt_password[50];
    char mqtt_topic_distance[100];
    char mqtt_topic_frequency[100];
    char mqtt_topic_volume[100];
} ThereminConfig;

// Global variables
ThereminConfig config;
int spi_handle;
int pwm_handle;
int trig_pin = 23;
int echo_pin = 24;
int ldr_pin = 18; // MCP3008 channel 0
int spi_channel = 0; // SPI channel for MCP3008
int spi_speed = 1000000; // SPI speed (1 MHz)
int spi_mode = 0; // SPI mode (0 for CPOL=0, CPHA=0)
int spi_flags = 0; // SPI flags
int last_distance = 0;
int last_frequency = 440;
int last_volume = 50;
int last_ldr_value = 512; // Initial LDR value
int last_valid_distance = 0;
int last_valid_frequency = 440;
int last_valid_volume = 50;
int last_valid_ldr_value = 512;
int last_valid_pwm_duty_cycle = 128;
int last_valid_pwm_frequency = 440;
int last_valid_pwm_period = 1000000 / 440; // Period in nanoseconds
int last_valid_pwm_duty_cycle_ns = last_valid_pwm_duty_cycle * last_valid_pwm_period / 100; // Duty cycle in nanoseconds
int last_valid_pwm_duty_cycle_percent = last_valid_pwm_duty_cycle; // Duty cycle as a percentage

// Function prototypes
int read_config(const char *filename, ThereminConfig *config);
int write_config(const char *filename, const ThereminConfig *config);
float read_distance();
int read_ldr();
int map_distance_to_frequency(float distance);
int map_ldr_to_volume(int ldr_value);
int set_pwm_frequency(int frequency);
int set_pwm_duty_cycle(int duty_cycle);
void publish_mqtt_data(float distance, int frequency, int volume);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config(const char *filename, ThereminConfig *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "distance_min") == 0) {
            config->distance_min = atof(value);
        } else if (strcmp(key, "distance_max") == 0) {
            config->distance_max = atof(value);
        } else if (strcmp(key, "frequency_min") == 0) {
            config->frequency_min = atof(value);
        } else if (strcmp(key, "frequency_max") == 0) {
            config->frequency_max = atof(value);
        } else if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "mqtt_broker_address") == 0) {
            strncpy(config->mqtt_broker_address, value, sizeof(config->mqtt_broker_address) - 1);
            config->mqtt_broker_address[sizeof(config->mqtt_broker_address) - 1] = '\0';
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config->mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_client_id") == 0) {
            strncpy(config->mqtt_client_id, value, sizeof(config->mqtt_client_id) - 1);
            config->mqtt_client_id[sizeof(config->mqtt_client_id) - 1] = '\0';
        } else if (strcmp(key, "mqtt_username") == 0) {
            strncpy(config->mqtt_username, value, sizeof(config->mqtt_username) - 1);
            config->mqtt_username[sizeof(config->mqtt_username) - 1] = '\0';
        } else if (strcmp(key, "mqtt_password") == 0) {
            strncpy(config->mqtt_password, value, sizeof(config->mqtt_password) - 1);
            config->mqtt_password[sizeof(config->mqtt_password) - 1] = '\0';
        } else if (strcmp(key, "mqtt_topic_distance") == 0) {
            strncpy(config->mqtt_topic_distance, value, sizeof(config->mqtt_topic_distance) - 1);
            config->mqtt_topic_distance[sizeof(config->mqtt_topic_distance) - 1] = '\0';
        } else if (strcmp(key, "mqtt_topic_frequency") == 0) {
            strncpy(config->mqtt_topic_frequency, value, sizeof(config->mqtt_topic_frequency) - 1);
            config->mqtt_topic_frequency[sizeof(config->mqtt_topic_frequency) - 1] = '\0';
        } else if (strcmp(key, "mqtt_topic_volume") == 0) {
            strncpy(config->mqtt_topic_volume, value, sizeof(config->mqtt_topic_volume) - 1);
            config->mqtt_topic_volume[sizeof(config->mqtt_topic_volume) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to write configuration to file
int write_config(const char *filename, const ThereminConfig *config) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening config file for writing");
        return -1;
    }

    fprintf(fp, "distance_min=%.2f\n", config->distance_min);
    fprintf(fp, "distance_max=%.2f\n", config->distance_max);
    fprintf(fp, "frequency_min=%.2f\n", config->frequency_min);
    fprintf(fp, "frequency_max=%.2f\n", config->frequency_max);
    fprintf(fp, "spi_channel=%d\n", config->spi_channel);
    fprintf(fp, "mqtt_broker_address=%s\n", config->mqtt_broker_address);
    fprintf(fp, "mqtt_broker_port=%d\n", config->mqtt_broker_port);
    fprintf(fp, "mqtt_client_id=%s\n", config->mqtt_client_id);
    fprintf(fp, "mqtt_username=%s\n", config->mqtt_username);
    fprintf(fp, "mqtt_password=%s\n", config->mqtt_password);
    fprintf(fp, "mqtt_topic_distance=%s\n", config->mqtt_topic_distance);
    fprintf(fp, "mqtt_topic_frequency=%s\n", config->mqtt_topic_frequency);
    fprintf(fp, "mqtt_topic_volume=%s\n", config->mqtt_topic_volume);

    fclose(fp);
    return 0;
}

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(trig_pin, 0);
    gpioDelay(2);
    gpioWrite(trig_pin, 1);
    gpioDelay(10);
    gpioWrite(trig_pin, 0);

    int start_tick = gpioTick();
    while (gpioRead(echo_pin) == 0) {
        if (gpioTick() - start_tick > 50000) { // Timeout after 50ms
            fprintf(stderr, "Timeout waiting for echo start\n");
            return last_valid_distance; // Return last valid distance
        }
    }

    int end_tick = gpioTick();
    while (gpioRead(echo_pin) == 1) {
        if (gpioTick() - end_tick > 50000) { // Timeout after 50ms
            fprintf(stderr, "Timeout waiting for echo end\n");
            return last_valid_distance; // Return last valid distance
        }
    }

    int pulse_width = end_tick - start_tick;
    float distance = pulse_width / 58.0; // Speed of sound: 343 m/s, 0.0343 cm/us

    last_valid_distance = (int)distance;
    return (float)last_valid_distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | spi_channel) << 4; // Single-ended mode, channel selection
