#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"
#define ISO8601_FORMAT_WITH_MS "%Y-%m-%dT%H:%M:%S.%03dZ"
#define ISO8601_FORMAT_WITH_US "%Y-%m-%dT%H:%M:%S.%06dZ"
#define ISO8601_FORMAT_WITH_NS "%Y-%m-%dT%H:%M:%S.%09dZ"
#define ISO8601_FORMAT_WITH_TZ "%Y-%m-%dT%H:%M:%S%z"

#define ALCOHOL_THRESHOLD_HIGH 50.0
#define ALCOHOL_THRESHOLD_LOW 20.0

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm, const char *classification);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value = -1;
    int retries = 0;

    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode + channel
    tx[2] = 0x00;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx, rx, 3) == 0) {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read from MCP3008 after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return adc_value;
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to log data to file
void log_data(float ppm, const char *classification) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), ISO8601_FORMAT, tstruct);

    fprintf(log_file, "%s, PPM: %.2f, Classification: %s\n", buf, ppm, classification);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("alcohol_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float ppm = adc_to_ppm(adc_value);

            // Classify the reading
            const char *classification;
            if (ppm > ALCOHOL_THRESHOLD_HIGH) {
                classification = "Alcohol detected! Limit exceeded.";
            } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
                classification = "Sobriety confirmed.";
            } else {
                classification = "Alcohol level within acceptable range.";
            }

            log_data(ppm, classification);
        } else {
            fprintf(stderr, "Failed to read ADC value. Skipping logging.\n");
        }

        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

