#define MOISTURE_THRESHOLD 300

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int sensor_id, int moisture_level, int pump_status);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to file
void log_data(int sensor_id, int moisture_level, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor: %d, Moisture: %d, Pump: %s\n",
            timestamp, sensor_id, moisture_level, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_CE1, PI_OUTPUT);
    gpioSetMode(SPI_CE2, PI_OUTPUT);
    gpioSetMode(SPI_CE3, PI_OUTPUT);

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int moisture_0 = read_mcp3008(CHANNEL_0);
        int moisture_1 = read_mcp3008(CHANNEL_1);
        int moisture_2 = read_mcp3008(CHANNEL_2);
        int moisture_3 = read_mcp3008(CHANNEL_3);

        // Control pump based on moisture levels
        int pump_status = 0;
        if (moisture_0 < MOISTURE_THRESHOLD || moisture_1 < MOISTURE_THRESHOLD ||
            moisture_2 < MOISTURE_THRESHOLD || moisture_3 < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn pump ON
            pump_status = 1;
        } else {
            control_pump(0); // Turn pump OFF
            pump_status = 0;
        }

        // Log data
        log_data(0, moisture_0, pump_status);
        log_data(1, moisture_1, pump_status);
        log_data(2, moisture_2, pump_status);
        log_data(3, moisture_3, pump_status);

        // Wait for 60 seconds
        gpioDelay(60000); // 60 seconds in milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn pump OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

