#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1 GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIOs
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channel Definitions
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Motion Profile Parameters
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCELERATION_DURATION 2 // seconds
#define HOLD_DURATION 2 // seconds
#define DECELERATION_DURATION 2 // seconds
#define PAUSE_DURATION 5 // seconds

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
float map_potentiometer_to_speed(int pot_value);
void motor_forward(int enable_pin, int direction_pin, int speed);
void motor_backward(int enable_pin, int direction_pin, int speed);
void motor_stop(int enable_pin);
void motion_profile(int enable1, int direction1, int enable2, int direction2, int speed1, int speed2);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map potentiometer value to speed factor
float map_potentiometer_to_speed(int pot_value) {
    // Logarithmic mapping
    float speed_factor = log10((float)pot_value / 1023.0 + 1e-9) / log10(10.0) * (MAX_SPEED - MIN_SPEED) + MIN_SPEED;
    return speed_factor;
}

// Function to control motor forward
void motor_forward(int enable_pin, int direction_pin, int speed) {
    gpioWrite(direction_pin, 1); // Set direction forward
    gpioPWM(enable_pin, speed);   // Set speed
}

// Function to control motor backward
void motor_backward(int enable_pin, int direction_pin, int speed) {
    gpioWrite(direction_pin, 0); // Set direction backward
    gpioPWM(enable_pin, speed);   // Set speed
}

// Function to stop the motor
void motor_stop(int enable_pin) {
    gpioPWM(enable_pin, 0); // Stop the motor
}

// Function to execute the motion profile
void motion_profile(int enable1, int direction1, int enable2, int direction2, int speed1, int speed2) {
    // Accelerate
    for (int i = MIN_SPEED; i <= MAX_SPEED; i += (int)((MAX_SPEED - MIN_SPEED) / ACCELERATION_DURATION)) {
        motor_forward(enable1, direction1, i);
        motor_backward(enable2, direction2, i);
        gpioDelay(1000000 / ACCELERATION_DURATION); // Delay for acceleration duration
    }

    // Hold
    gpioDelay(HOLD_DURATION * 1000000); // Delay for hold duration

    // Decelerate
    for (int i = MAX_SPEED; i >= MIN_SPEED; i -= (int)((MAX_SPEED - MIN_SPEED) / DECELERATION_DURATION)) {
        motor_forward(enable1, direction1, i);
        motor_backward(enable2, direction2, i);
        gpioDelay(1000000 / DECELERATION_DURATION); // Delay for deceleration duration
    }

    // Stop
    motor_stop(enable1);
    motor_stop(enable2);
    gpioDelay(1000000); // Short pause after stopping
}

