    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion control program started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            gpioDelay(100000); // Small delay to avoid flooding the console with errors
            continue;
        }

        // Map potentiometer values to speed factors
        float speed_factor1 = map_potentiometer_to_speed(pot1_value);
        float speed_factor2 = map_potentiometer_to_speed(pot2_value);

        // Execute motion profile
        motion_profile(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, (int)speed_factor1, (int)speed_factor2);

        // Pause
        gpioDelay(PAUSE_DURATION * 1000000); // Delay for pause duration
    }

    // Cleanup
    printf("Cleaning up...\n");
    motor_stop(MOTOR1_ENABLE);
    motor_stop(MOTOR2_ENABLE);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
