#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MCP3008_CS 8
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
double ambient_level = 0.0;
int led_state = 0; // 0 = off, 1 = on
unsigned long last_led_change = 0;

// Function prototypes
int read_mcp3008(int channel);
double calibrate_ambient_level(int duration_seconds);
void control_led(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate ambient noise level
double calibrate_ambient_level(int duration_seconds) {
    double sum = 0.0;
    int num_samples = duration_seconds * 100; // 100 samples per second

    printf("Calibrating ambient noise level for %d seconds...\n", duration_seconds);

    for (int i = 0; i < num_samples; i++) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value during calibration\n");
            return -1.0;
        }
        sum += adc_value;
        gpioDelay(10); // 10 ms delay
    }

    return sum / num_samples;
}

// Function to control the LED
void control_led(int state) {
    if (state != led_state) {
        unsigned long now = gpioTick();
        if ((now - last_led_change) > 10000) { // 10 ms debounce
            gpioWrite(LED_PIN, state);
            led_state = state;
            last_led_change = now;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate ambient noise level
    ambient_level = calibrate_ambient_level(5);
    if (ambient_level < 0) {
        fprintf(stderr, "Error: Ambient level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Ambient noise level: %.2f\n", ambient_level);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        double threshold = ambient_level * 1.10; // 10% above ambient level

        if (adc_value > threshold) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

