#define ZERO_SLPM_VOLTAGE 0.5
#define MAX_SLPM_VOLTAGE 4.5
#define MAX_SLPM 200.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float voltage_to_slpm(int adc_value);
void log_data(float airflow);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    float zero_slpm_voltage;
    float max_slpm_voltage;
    float max_slpm;
    int sample_interval_ms;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    VREF,
    ZERO_SLPM_VOLTAGE,
    MAX_SLPM_VOLTAGE,
    MAX_SLPM,
    SAMPLE_INTERVAL_MS,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(config.adc_channel);
        if (adc_value >= 0) {
            float airflow = voltage_to_slpm(adc_value);
            log_data(airflow);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }
        gpioDelay(config.sample_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float voltage_to_slpm(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * config.vref;
    float airflow = (voltage - config.zero_slpm_voltage) / (config.max_slpm_voltage - config.zero_slpm_voltage) * config.max_slpm;
    return airflow;
}

void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

