#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define CS_GPIO 8 // GPIO8 (CE0)
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *cs_line = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t max_speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int mcp3008_read(int fd, int channel);
int gpio_init(int gpio, const char *chipname);
int gpio_set_value(int gpio, int value);
int gpio_get_value(int gpio);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t max_speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 read function
int mcp3008_read(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
        return -1;
    }

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// GPIO initialization function
int gpio_init(int gpio, const char *chipname) {
    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, gpio);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "audio_sampler", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int gpio, int value) {
    if (gpiod_line_set_value(cs_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO get value function
int gpio_get_value(int gpio) {
    int value = gpiod_line_get_value(cs_line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_MS * 1000000; // Convert ms to ns

    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(CS_GPIO, "gpiochip0") < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        // Set CS low
        if (gpio_set_value(CS_GPIO, 0) < 0) {
            fprintf(stderr, "Error setting CS low. Continuing.\n");
        }

        // Read from MCP3008
        int adc_value = mcp3008_read(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading from MCP3008. Continuing.\n");
        } else {
            // Set CS high
            if (gpio_set_value(CS_GPIO, 1) < 0) {
                fprintf(stderr, "Error setting CS high. Continuing.\n");
            }

            // Get timestamp
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC_RAW, &ts);

            // Log data
            fprintf(log_file, "%ld.%09ld|%d\n", ts.tv_sec, ts.tv_nsec, adc_value);
            fflush(log_file);
        }

        // Sleep until next sample
        if (nanosleep(&sleep_time, NULL) < 0) {
            if (errno == EINTR) {
                printf("Nanosleep interrupted by signal.\n");
            } else {
                perror("Nanosleep error");
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

