#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity and zero-g bias
#define SENSITIVITY 0.3 // 300 mV/g
#define ZERO_G_BIAS 1.5 // 1.5V

// Define Kalman filter parameters
#define Q 0.001 // Process noise covariance
#define R 0.1   // Measurement noise covariance

// Global variables for Kalman filter state
double x_state = 0.0;
double x_error = 1.0;
double P = 1.0;
double K = 0.0;

double y_state = 0.0;
double y_error = 1.0;
double Py = 1.0;
double Ky = 0.0;

double z_state = 0.0;
double z_error = 1.0;
double Pz = 1.0;
double Kz = 0.0;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_acceleration(double voltage);
double kalman_filter(double measurement);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008

    // Construct SPI message (MCP3008 datasheet)
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(SPI_CHANNEL, (char *)spi_tx_buf, (char *)spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008
        return -1;
    }

    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC reading to voltage
double adc_to_voltage(int adc_value) {
    return (double)adc_value * (3.3 / 1023.0);
}

// Function to convert voltage to acceleration (g)
double voltage_to_acceleration(double voltage) {
    return (voltage - ZERO_G_BIAS) / SENSITIVITY;
}

// Kalman filter implementation
double kalman_filter(double measurement) {
    // Prediction step
    double x_predict = x_state;
    double P_predict = P + Q;

    // Update step
    K = P_predict / (P_predict + R);
    x_state = x_predict + K * (measurement - x_predict);
    P = (1 - K) * P_predict;

    return x_state;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for SPI communication
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    // Initialize SPI channel
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set CS pin high initially
    gpioWrite(MCP3008_CS, 1);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC values from all three channels
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        double x_voltage = adc_to_voltage(x_adc);
        double y_voltage = adc_to_voltage(y_adc);
        double z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to acceleration values
        double x_acceleration = voltage_to_acceleration(x_voltage);
        double y_acceleration = voltage_to_acceleration(y_voltage);
        double z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter to acceleration values
        double x_filtered = kalman_filter(x_acceleration);
        double y_filtered = kalman_filter(y_acceleration);
        double z_filtered = kalman_filter(z_acceleration);

        // Print the filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay to achieve approximately 10 Hz sampling rate
        gpioDelay(100); // 100 ms delay
    }

    // Close SPI channel and terminate pigpio library (this part will not be reached in the infinite loop)
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

