#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the number of GPIO lines to request
#define NUM_GPIO_LINES 3

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field range (mT)
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define the sampling interval (milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_lines[NUM_GPIO_LINES];
struct gpiod_chip *gpio_chip;

// Function prototypes
int read_sensor(int gpio_pin);
float calculate_magnetic_field(int digital_value);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int signal);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to read the digital value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = -1; // Initialize to an invalid value
    int retries = 3; // Number of retries
    int delay_ms = 1; // Initial delay in milliseconds

    while (retries > 0) {
        value = gpiod_line_get_value(gpio_lines[gpio_pin]); // Get the value of the GPIO line
        if (value >= 0) {
            return value; // Return the digital value if successful
        } else {
            fprintf(stderr, "Error reading GPIO %d: %s. Retrying...\n", gpio_pin, strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Wait before retrying
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read GPIO %d after multiple retries.\n", gpio_pin);
    return -1; // Return -1 to indicate an error
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int digital_value) {
    float magnetic_field;

    // Convert digital value (0 or 1) to voltage (0.0V or 3.3V)
    float voltage = (float)digital_value * 3.3;

    // Calculate the magnetic field strength
    magnetic_field = (voltage - 1.65) / 0.025;

    return magnetic_field;
}

// Function to log the sensor data to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a"); // Open the log file in append mode
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write the data to the log file
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);

    fclose(fp); // Close the log file
    return 0; // Indicate success
}

// Function to setup GPIO lines
int setup_gpio(void) {
    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO lines for each sensor
    int pins[] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO};
    for (int i = 0; i < NUM_GPIO_LINES; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, pins[i]);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        // Request the GPIO line for input
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "magnetic_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(gpio_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    // Release GPIO lines
    for (int i = 0; i < NUM_GPIO_LINES; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
            gpio_lines[i] = NULL; // Set to NULL to avoid double release
        }
    }

    // Close the GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL; // Set to NULL to avoid double close
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Setup GPIO lines
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Calculate magnetic field strengths
