    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buf[2] = 0x00;                  // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int channel0, int channel1, int channel2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "Received SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup function to release resources
void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        int channel0 = read_mcp3008(0);
        int channel1 = read_mcp3008(1);
        int channel2 = read_mcp3008(2);

        if (channel0 == -1 || channel1 == -1 || channel2 == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            sleep(SLEEP_SECONDS);
            continue;
        }

        if (log_data(csv_file, channel0, channel1, channel2) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

