#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_LED 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, shutting down...\n");
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        // Subscribe to the topic
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Connection failed");
    }
}

// Callback function for when a message is received on the subscribed topic
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        cJSON *json = cJSON_Parse(payload);

        if (json == NULL) {
            const char *error_ptr = cJSON_GetErrorPtr();
            if (error_ptr != NULL) {
                log_error("JSON parse error: ");
                log_error(error_ptr);
            }
            return;
        }

        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (cJSON_IsBool(led_state)) {
            gpioWrite(GPIO_LED, led_state->valueint);
        } else {
            log_error("Invalid JSON format: 'led_state' is not a boolean");
        }

        cJSON_Delete(json);
    }
}

// Function to reconnect to the MQTT broker with exponential backoff
void reconnect() {
    int rc;
    int delay = 1;
    while (running && mosq == NULL) {
        printf("Attempting to reconnect in %d seconds...\n", delay);
        rc = mosquitto_reconnect(mosq);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Reconnected to MQTT broker\n");
            return;
        } else {
            log_error("Reconnection failed");
            delay *= 2;
            if (delay > 60) {
                delay = 60;
            }
            sleep(delay);
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Turn off the LED on startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start the MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, 50, 1); // Check for messages every 50ms, max 1 message
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error, attempting to reconnect");
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            mosquitto_lib_init();
            mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
            if (!mosq) {
                log_error("Failed to recreate mosquitto instance");
                running = 0; // Exit if reinitialization fails
                continue;
            }
            mosquitto_connect_callback_set(mosq, on_connect);
            mosquitto_message_callback_set(mosq, on_message);
            rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("Failed to reconnect to MQTT broker");
                running = 0;
                continue;
            }
            mosquitto_loop_start(mosq);
        }
        sleep(1); // Sleep for 1 second
    }

    // Clean up and disconnect
    printf("Cleaning up...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_LED, 0); // Turn off the LED
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

