#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to blink the alarm LED
void blink_alarm_led() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        // Print the sound level
        printf("Sound Level: %d\n", sound_level);

        // Check if sound is detected
        if (sound_level == 0) {
            blink_alarm_led();
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up GPIO resources
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

