#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Wait for falling edge
        if (gpioRead(GPIO_PIN) == 0) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event
            fprintf(log_file, "%s: Vibration detected!\n", timestamp);
            fflush(log_file); // Ensure immediate write to file

            // Print to stdout
            printf("%s: Vibration detected!\n", timestamp);

            // Execute shutdown command
            if (system("sudo shutdown -h now") != 0) {
                fprintf(stderr, "Error executing shutdown command: %s\n", strerror(errno));
            }

            // Exit loop after shutdown is initiated
            break;
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

