#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define I2C_BUS 1
#define MCP4725_ADDRESS 0x62
#define VREF 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
float temperature_to_voltage(float temperature);
int dac_write(int i2c_handle, float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1;
    int retries = 3;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "SPI transfer failed. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read from MCP3008 after multiple retries.\n");
        return -1; // Indicate failure
    }

    return adc_value;
}

// Function to convert ADC reading to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    return (adc_value * VREF / 1024.0) * 100.0;
}

// Function to convert temperature to DAC voltage
float temperature_to_voltage(float temperature) {
    return (temperature / 50.0) * 3.3;
}

// Function to write to MCP4725 DAC
int dac_write(int i2c_handle, float voltage) {
    int dac_value = (int)(voltage / (VREF / 4095.0));
    char buffer[3];
    int retries = 3;

    buffer[0] = 0x40; // Write DAC value command
    buffer[1] = (dac_value >> 4) & 0xFF; // MSB
    buffer[2] = (dac_value << 4) & 0xF0; // LSB

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buffer, 3) == 0) {
            return 0; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C write failed. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to write to MCP4725 after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, Voltage: %.2f V\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s, ADC: %d, Temp: %.2f C, Voltage: %.2f V\n", timestamp, adc_value, temperature, voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
