#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pins connected to the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the number of relays
#define NUM_RELAYS 4

// Structure to hold the GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
} gpio_line_t;

// Global variables for GPIO lines
gpio_line_t relay_lines[NUM_RELAYS];

// Function prototypes
int setup_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to set up the GPIO lines
int setup_gpio(void) {
    struct gpiod_chip *chip;
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request the GPIO lines for each relay
    for (i = 0; i < NUM_RELAYS; i++) {
        int pin = (i == 0) ? RELAY1_PIN :
                  (i == 1) ? RELAY2_PIN :
                  (i == 2) ? RELAY3_PIN :
                  RELAY4_PIN;

        relay_lines[i].pin = pin;

        relay_lines[i].line = gpiod_chip_get_line(chip, pin);
        if (!relay_lines[i].line) {
            perror("Error getting GPIO line");
            gpiod_chip_close(chip);
            return -1;
        }

        // Request the GPIO line as an output
        if (gpiod_line_request_output(relay_lines[i].line, "light_sequencer", 0) < 0) {
            perror("Error requesting GPIO line as output");
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Function to activate a relay
void activate_relay(int pin) {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i].pin == pin) {
            if (gpiod_line_set_value(relay_lines[i].line, 1) < 0) {
                perror("Error setting GPIO line value");
            }
            return;
        }
    }
    fprintf(stderr, "Error: Invalid pin number: %d\n", pin);
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i].pin == pin) {
            if (gpiod_line_set_value(relay_lines[i].line, 0) < 0) {
                perror("Error setting GPIO line value");
            }
            return;
        }
    }
    fprintf(stderr, "Error: Invalid pin number: %d\n", pin);
}

// Function to clean up the GPIO lines
void cleanup_gpio(void) {
    int i;

    // Deactivate all relays
    for (i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(relay_lines[i].pin);
    }

    // Release the GPIO lines
    for (i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i].line) {
            gpiod_line_release(relay_lines[i].line);
        }
    }
}

int main(void) {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the GPIO lines
    if (setup_gpio() < 0) {
        return 1;
    }

    // Main loop to control the relays
    while (1) {
        // Activate and deactivate each relay in sequence
        for (int i = 0; i < NUM_RELAYS; i++) {
            int pin = (i == 0) ? RELAY1_PIN :
                      (i == 1) ? RELAY2_PIN :
                      (i == 2) ? RELAY3_PIN :
                      RELAY4_PIN;

            activate_relay(pin);
            sleep(1);
            deactivate_relay(pin);
            sleep(1);
        }
    }

    return 0;
}

