#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for motor control
#define IN1 17
#define IN2 18
#define ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor control duration
#define MOTOR_DURATION 3 // seconds

// Define PWM range
#define PWM_RANGE 255

// Define PWM duty cycle
#define PWM_DUTY 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor();
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    unsigned char tx[3];
    unsigned char rx[3];

    // MCP3008 single-ended read sequence
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | 0) << 4; // Single-ended channel 0
    tx[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to convert ADC value to rain level
int convert_adc_to_rain_level(int adc_value) {
    // Linear mapping: ADC 0 -> rain level 10, ADC 1023 -> rain level 0
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the motor direction and speed
void control_motor(int direction) {
    if (direction == 1) { // Forward (close window)
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, PWM_DUTY);
    } else if (direction == 0) { // Reverse (open window)
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioPWM(ENA, PWM_DUTY);
    } else { // Stop motor
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, 0);
    }
}

// Function to log rain data to a file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(ENA, PWM_RANGE);

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int rain_level;
    int motor_direction = 0; // 0 = open, 1 = closed

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int adc_value = read_rain_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to rain level
        rain_level = convert_adc_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD && motor_direction == 0) {
            printf("Closing window...\n");
            control_motor(1); // Close window
            gpioDelay(MOTOR_DURATION * 1000000); // Delay for 3 seconds
            control_motor(0); // Stop motor
            motor_direction = 1;
        } else if (rain_level < RAIN_THRESHOLD && motor_direction == 1) {
            printf("Opening window...\n");
            control_motor(0); // Open window
            gpioDelay(MOTOR_DURATION * 1000000); // Delay for 3 seconds
            control_motor(0); // Stop motor
            motor_direction = 0;
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(0); // Stop motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

