#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 26
#define LED_PIN 16

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define ADC sampling rate in Hz
#define ADC_SAMPLING_RATE 1000

// Define ADC resolution
#define ADC_RESOLUTION 1023

// Define clap threshold
#define CLAP_THRESHOLD 700

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
    unsigned long last_trigger_time;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin as output\n");
        return 1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting microphone pin as input\n");
        return 1;
    }

    return 0;
}

// Function to read the analog value from the microphone
int read_adc() {
    // This is a placeholder for the actual ADC reading.
    // In a real application, you would need to implement
    // a proper ADC reading mechanism using bit-banging or an external ADC.
    // For this example, we'll just return a dummy value.
    // The MAX9814 output is assumed to be connected to a voltage divider
    // that scales the voltage to the GPIO pin.

    // Simulate ADC reading (replace with actual ADC reading logic)
    // This example uses a simple delay to simulate ADC conversion
    gpioDelay(1000000 / ADC_SAMPLING_RATE); // Delay to simulate ADC conversion time

    // Generate a pseudo-random value for demonstration purposes
    // Replace this with actual ADC reading logic
    return rand() % ADC_RESOLUTION; // Simulate ADC reading
}

// Function to detect a clap
int detect_clap(int adc_value) {
    return (adc_value > CLAP_THRESHOLD) ? 1 : 0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        program_running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    log_message("Clap detector started");

    // Main loop
    while (program_running) {
        int adc_value = read_adc();
        int clap_detected = detect_clap(adc_value);

        if (clap_detected) {
            // Debounce check
            if (state.led_state == 0 && (gpioTick() - state.last_trigger_time) > DEBOUNCE_TIME * 1000) {
                control_led(1); // Turn on LED
                state.led_state = 1;
                state.last_trigger_time = gpioTick();
                log_message("Clap detected!");
            }
        } else {
            control_led(0); // Turn off LED
            state.led_state = 0;
        }

        gpioDelay(10000); // Delay to avoid excessive CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

