#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to export the GPIO pin
int export_gpio(int gpio) {
    FILE *export_file = fopen(GPIO_EXPORT_PATH, "w");
    if (export_file == NULL) {
        fprintf(stderr, "Error opening GPIO export file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(export_file, "%d", gpio);
    fclose(export_file);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int gpio) {
    FILE *unexport_file = fopen(GPIO_UNEXPORT_PATH, "w");
    if (unexport_file == NULL) {
        fprintf(stderr, "Error opening GPIO unexport file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(unexport_file, "%d", gpio);
    fclose(unexport_file);
    return 0;
}

// Function to set the GPIO direction (in or out)
int set_gpio_direction(int gpio, const char *direction) {
    char direction_path[64];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", gpio);
    FILE *direction_file = fopen(direction_path, "w");
    if (direction_file == NULL) {
        fprintf(stderr, "Error opening GPIO direction file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(direction_file, "%s", direction);
    fclose(direction_file);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int gpio) {
    char value_path[64];
    snprintf(value_path, sizeof(value_path), "/sys/class/gpio/gpio%d/value", gpio);
    FILE *value_file = fopen(value_path, "r");
    if (value_file == NULL) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        return -1;
    }
    int value;
    if (fscanf(value_file, "%d", &value) != 1) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        fclose(value_file);
        return -1;
    }
    fclose(value_file);
    return value;
}

