    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Function to check proximity and activate the feeder
void check_proximity(float distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

