    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (set_gpio_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Monitoring System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int gpio_value = read_gpio_value(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert GPIO value to voltage
        float voltage = gpio_to_voltage(gpio_value);

        // Convert voltage to distance
        float distance = voltage_to_distance(voltage);

        // Log the distance
        if (log_distance(distance) != 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Check proximity and activate feeder
        check_proximity(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (unexport_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    printf("Pet Feeder Monitoring System stopped.\n");

    return 0;
}

