int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode_flags = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_hz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Chip select initialization function
int cs_init(const char *chip, int line) {
    struct gpiod_chip *chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip, strerror(errno));
        return -1;
    }

    struct gpiod_line *line_handle = gpiod_chip_get_line(chip_handle, line);
    if (!line_handle) {
        fprintf(stderr, "Error getting GPIO line %d from chip %s: %s\n", line, chip, strerror(errno));
        gpiod_chip_close(chip_handle);
        return -1;
    }

    if (gpiod_line_request_output(line_handle, "mcp3008_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", line, strerror(errno));
        gpiod_chip_close(chip_handle);
        gpiod_line_release(line_handle);
        return -1;
