// Convert voltage to magnetic field
float voltage_to_magnetic_field(float voltage) {
    int16_t vout_mV = (int16_t)(voltage * 1000.0f);
    int16_t offset = (int16_t)QUIESCENT_OUTPUT;
    int16_t field_raw = vout_mV - offset;
