void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (cs_chip) {
        gpiod_chip_close(cs_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

