        cleanup();
        return 1;
    }

    fprintf(stdout, "Starting magnetic field monitoring...\n");

    while (keep_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample.\n");
            sleep(SAMPLE_INTERVAL_MS / 1000); // Sleep for the sample interval
