#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 21
#define VCC 3.3
#define SENSITIVITY 1.65 // mV/mT
#define THRESHOLD 10.0 // mT
#define LOG_FILE "magnetic_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float voltage_to_magnetic_field(float voltage);
void log_data(float magnetic_field);
void control_led(float magnetic_field);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int led_pin;
    float vcc;
    float sensitivity;
    float threshold;
    char *log_file_name;
} Config;

Config config = {LED_GPIO, VCC, SENSITIVITY, THRESHOLD, LOG_FILE};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        float voltage = (float)adc_value * VCC / 1023.0;
        float magnetic_field = voltage_to_magnetic_field(voltage);
        log_data(magnetic_field);
        control_led(magnetic_field);

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

float voltage_to_magnetic_field(float voltage) {
    float magnetic_field = (voltage - VCC / 2.0) * 1000.0 / SENSITIVITY;
    return magnetic_field;
}

void log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f mT\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to file immediately
}

void control_led(float magnetic_field) {
    if (magnetic_field > config.threshold) {
        gpioWrite(config.led_pin, 1); // Turn on LED
    } else {
        gpioWrite(config.led_pin, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    spiClose(spi_handle);
    gpioWrite(config.led_pin, 0); // Turn off LED
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

