#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define ZERO_CURRENT_VOLTAGE (VREF / 2.0)
#define FULL_SCALE_CURRENT 50.0
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_from_adc(int adc_value);
float current_from_voltage(float voltage);
void log_current(float current);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Dummy byte

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx, rx, 3);

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to current
float current_from_voltage(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        return -1.0; // Indicate error
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (FULL_SCALE_CURRENT / (VREF - ZERO_CURRENT_VOLTAGE));
}

// Function to log current to file
void log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            gpioDelay(100000); // 100ms
            continue; // Skip to the next iteration if there's an error
        }

        // Convert ADC value to voltage
        float voltage = voltage_from_adc(adc_value);

        // Convert voltage to current
        float current = current_from_voltage(voltage);

        if (current >= 0.0) {
            // Log current
            log_current(current);

            // Print current to console
            printf("Current: %.2f A\n", current);
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

