#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
volatile sig_atomic_t terminate = 0;
int spi_handle;

// Function prototypes
int spi_setup(spi_config_t config);
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);

// Structure for SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function to initialize SPI
int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", config.channel, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI command
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00;                  // Dummy byte

    // Transfer data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Extract ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture_level;

    moisture_level = 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;

    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    } else if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }

    return moisture_level;
}

// Function to log data to file
void log_data(double moisture_level) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Write data to file
    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);

    // Close file
    fclose(fp);

    // Print to console
    printf("%s,%.2f\n", timestamp, moisture_level);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    if (spi_setup(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        } else {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
        }

        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

