#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_QUALITY 85
#define IMAGE_FORMAT "jpeg"
#define IMAGE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    program_running = 0;
}

int main() {
    int gpio_status;
    int image_capture_status;
    int child_pid;
    int exit_status;
    char timestamp[32];
    char filename[128];
    char filepath[256];
    struct stat st;

    // Initialize syslog
    openlog("security_camera", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Create image directory if it doesn't exist
    if (stat(IMAGE_DIR, &st) == -1) {
        if (mkdir(IMAGE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create image directory: %s", strerror(errno));
            gpioTerminate();
            closelog();
            return 1;
        }
    }

    syslog(LOG_INFO, "Security camera started");

    while (program_running) {
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read GPIO to confirm state
            if (gpioRead(GPIO_PIN) == 1) {
                // Motion detected
                syslog(LOG_INFO, "Motion detected");

                // Generate timestamp
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                // Construct filename
                snprintf(filename, sizeof(filename), "%s%s.jpg", timestamp, timestamp);

                // Construct filepath
                snprintf(filepath, sizeof(filepath), "%s%s", IMAGE_DIR, filename);

                // Execute libcamera-still command
                child_pid = fork();
                if (child_pid == 0) {
                    // Child process
                    char *args[] = {
                        "libcamera-still",
                        "--width", IMAGE_WIDTH,
                        "--height", IMAGE_HEIGHT,
                        "--quality", IMAGE_QUALITY,
                        "--format", IMAGE_FORMAT,
                        "--output", filepath,
                        NULL
                    };
                    execvp(args[0], args);
                    syslog(LOG_ERR, "execvp failed: %s", strerror(errno));
                    exit(1);
                } else if (child_pid > 0) {
                    // Parent process
                    wait(&exit_status);
                    if (WIFEXITED(exit_status)) {
                        exit_status = WEXITSTATUS(exit_status);
                        if (exit_status == 0) {
                            syslog(LOG_INFO, "Image captured: %s", filepath);
                        } else {
                            syslog(LOG_ERR, "Image capture failed with exit status: %d", exit_status);
                        }
                    } else {
                        syslog(LOG_ERR, "Child process terminated abnormally");
                    }
                } else {
                    syslog(LOG_ERR, "fork failed: %s", strerror(errno));
                }

                // Wait for a short period before checking for motion again
                gpioDelay(1000000); // 1 second
            }
        } else {
            // No motion detected
            gpioDelay(50000); // 50 ms
        }
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera stopped");
    closelog();

    return 0;
}

