#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)
#define NUM_BUFFERS 1

// Structure to hold the buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
static int                  fd                  = -1; // File descriptor of the V4L2 device
static struct buffer        buffers[NUM_BUFFERS]; // Array to store the buffer information
static unsigned int         n_buffers           = 0; // Number of buffers allocated
static int                  buffer_index       = 0; // Index of the current buffer
static volatile int         running             = 1; // Flag to control the main loop
static int                  buffer_fd           = -1; // File descriptor for the buffer

// Signal handler function
void signal_handler(int sig)
{
    (void)(sig);
    running = 0;
    fprintf(stderr, "\nCaught signal, exiting...\n");
}

// Function to open the V4L2 device
int open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the V4L2 device
int init_device(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to allocate and initialize the buffers
int init_mmap(int fd)
{
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    n_buffers = req.count;

    // Allocate memory for the buffers
    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd)
{
    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, unsigned char *image_data)
{
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Copy the image data from the buffer to the image_data array
    memcpy(image_data, buffers[buf.index].start, IMAGE_SIZE);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer_index = (buffer_index + 1) % n_buffers;

    return 0;
}

// Function to save the image to a PGM file
int save_image(const unsigned char *image_data, int image_number)
{
    FILE *fp;
    char filename[50];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", image_number);

    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(image_data, 1, IMAGE_SIZE, fp);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers(int fd)
{
    for (int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to close the device
int close_device(int fd)
{
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device_name = DEVICE_NAME;
    if (argc > 1) {
        device_name = argv[1];
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(device_name);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffers(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    unsigned char image_data[IMAGE_SIZE];
    int image_number = 1;

    // Capture and save images until a signal is received
    while (running) {
        if (capture_frame(fd, image_data) == -1) {
            break;
        }

        if (save_image(image_data, image_number) == -1) {
            break;
        }

        image_number++;
    }

    // Stop streaming
    if (stop_streaming(fd) == -1) {
        fprintf(stderr, "Error stopping stream during cleanup\n");
    }

    // Unmap buffers
    if (unmap_buffers(fd) == -1) {
        fprintf(stderr, "Error unmapping buffers during cleanup\n");
    }

    // Close the device
    if (close_device(fd) == -1) {
        fprintf(stderr, "Error closing device during cleanup\n");
    }

    return EXIT_SUCCESS;
}

