#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define UDP_PORT 5000
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4
#define MAX_DGRAM_SIZE 65000

// Structure to hold frame data
typedef struct {
    void *start;
    size_t length;
} buffer_t;

// Global variables
static int camera_fd = -1;
static buffer_t buffers[NUM_BUFFERS];
static int sockfd = -1;
static volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Function to initialize the camera device
int init_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    // Map buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    // Queue buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    return 0;
}

// Function to create a UDP socket
int create_socket() {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }
    return sockfd;
}

// Function to send a frame over UDP
int send_frame(int sockfd, const char *server_ip, int server_port, int frame_index, const buffer_t *buffers, int num_buffers) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid server IP address");
        return -1;
    }

    int total_fragments = (buffers[0].length + MAX_DGRAM_SIZE - 1) / MAX_DGRAM_SIZE; // Calculate total fragments
    for (int fragment_index = 0; fragment_index < total_fragments; fragment_index++) {
        int payload_size = 0;
        const char *payload = NULL;
        int buffer_index = fragment_index % num_buffers; // Cycle through buffers

        // Determine the payload size and data for this fragment
        int start_offset = fragment_index * MAX_DGRAM_SIZE;
        int end_offset = (fragment_index + 1) * MAX_DGRAM_SIZE;
        if (start_offset >= buffers[buffer_index].length) {
            continue; // Fragment is empty
        }
        if (end_offset > buffers[buffer_index].length) {
            end_offset = buffers[buffer_index].length;
        }
        payload_size = end_offset - start_offset;
        payload = (char *)buffers[buffer_index].start + start_offset;

        // Create the header
        unsigned int header[4];
        header[0] = frame_index;
        header[1] = fragment_index;
        header[2] = total_fragments;
        header[3] = payload_size;

        // Send the header and payload
        char header_buffer[sizeof(header)];
        memcpy(header_buffer, header, sizeof(header));
        if (sendto(sockfd, header_buffer, sizeof(header_buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Error sending header");
            return -1;
        }

        if (sendto(sockfd, payload, payload_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Error sending payload");
            return -1;
        }
    }
    return 0;
}

// Function to uninitialize the camera device
void uninit_camera(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
    if (ioctl(fd, VIDIOC_STREAMOFF, &buffers[0].type) < 0) {
        perror("Error stopping streaming");
    }
    close(fd);
}

// Function to close the socket
void close_socket(int sockfd) {
    close(sockfd);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    camera_fd = open_camera(DEVICE_NAME);
    if (camera_fd < 0) {
        return 1;
    }

    // Initialize the camera device
    if (init_camera(camera_fd) < 0) {
        close(camera_fd);
        return 1;
    }

    // Create the UDP socket
    sockfd = create_socket();
    if (sockfd < 0) {
        uninit_camera(camera_fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        close_socket(sockfd);
        uninit_camera(camera_fd);
        return 1;
    }

    int frame_index = 0;
    while (!terminate) {
        // Dequeue a buffer
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Send the frame
        if (send_frame(sockfd, server_ip, server_port, frame_index, buffers, NUM_BUFFERS) < 0) {
            break;
        }

        // Requeue the buffer
        if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }

        frame_index++;
    }

    // Stop streaming
    if (ioctl(camera_fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
    }

    // Close the socket
    close_socket(sockfd);

    // Uninitialize the camera device
    uninit_camera(camera_fd);

    return 0;
}

