#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

// Structure to hold the buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int fd = -1; // File descriptor for the video device
static buffer_t *buffers = NULL; // Array of buffer structures
static unsigned int n_buffers = 0; // Number of buffers
static int image_fd = -1; // File descriptor for the image file
static volatile int keep_running = 1; // Flag to control the main loop

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd);
int start_capturing(int fd);
int stop_capturing(int fd);
int save_image(const void *buffer, size_t bytes_used);
int uninit_device(int fd);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, stopping...");
    keep_running = 0;
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        return -1;
    }

    // Set the video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Error allocating buffer array");
        return -1;
    }
    n_buffers = req.count;

    // Map the buffers
    for (i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to save the image to a file
int save_image(const void *buffer, size_t bytes_used) {
    image_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (image_fd == -1) {
        perror("Error opening image file");
        return -1;
    }

    ssize_t bytes_written = write(image_fd, buffer, bytes_used);
    if (bytes_written == -1) {
        perror("Error writing image data");
        close(image_fd);
        return -1;
    }

    if (bytes_written != bytes_used) {
        fprintf(stderr, "Warning: Incomplete write to image file\n");
    }

    if (close(image_fd) == -1) {
        perror("Error closing image file");
        return -1;
    }
    image_fd = -1; // Reset image_fd after closing
    return 0;
}

// Function to uninitialize the device
int uninit_device(int fd) {
    unsigned int i;

    for (i = 0; i < n_buffers; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    free(buffers);
    buffers = NULL;
    n_buffers = 0;

    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Capture and save the image
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        stop_capturing(fd);
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    if (save_image(buffers[buf.index].start, buf.bytesused) == -1) {
        stop_capturing(fd);
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        stop_capturing(fd);
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Uninitialize the device
    if (uninit_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Image captured and saved to %s\n", IMAGE_FILE);
    return EXIT_SUCCESS;
}

