#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7

// Define servo parameters
#define SERVO_MIN_PULSE_WIDTH 1000 // Minimum pulse width (us)
#define SERVO_MAX_PULSE_WIDTH 2000 // Maximum pulse width (us)
#define SERVO_MID_PULSE_WIDTH 1500 // Mid pulse width (us)
#define SERVO_PERIOD 20000         // Period for 50Hz (us)

// Define servo position range
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125

// Global variables
volatile int pan_position = 75;
volatile int tilt_position = 75;

// Function prototypes
int initialize_gpio();
void set_servo_position(int servo_pin, int position);
void handle_button_press(int button_pin, int servo_pin, int *position);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop servos
    set_servo_position(PAN_SERVO_PIN, 75);
    set_servo_position(TILT_SERVO_PIN, 75);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);

    return 0;
}

// Set servo position using PWM
void set_servo_position(int servo_pin, int position) {
    // Map position (25-125) to pulse width (1000-2000)
    int pulse_width = (int)(((float)(position - SERVO_MIN_POSITION) / (SERVO_MAX_POSITION - SERVO_MIN_POSITION)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);

    // Set PWM duty cycle
    gpioPWM(servo_pin, pulse_width * 10); // pigpio duty cycle is 0-255, pulse width is 0-1000
}

// Handle button press
void handle_button_press(int button_pin, int servo_pin, int *position) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (active low)
        // Increment position
        *position += 5;
        if (*position > SERVO_MAX_POSITION) {
            *position = SERVO_MAX_POSITION;
        }
        set_servo_position(servo_pin, *position);
        gpioDelay(50); // Debounce delay
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Main loop
    while (1) {
        // Handle button presses
        handle_button_press(PAN_LEFT_PIN, PAN_SERVO_PIN, &pan_position);
        handle_button_press(PAN_RIGHT_PIN, PAN_SERVO_PIN, &pan_position);
        handle_button_press(TILT_UP_PIN, TILT_SERVO_PIN, &tilt_position);
        handle_button_press(TILT_DOWN_PIN, TILT_SERVO_PIN, &tilt_position);

        gpioDelay(50); // Polling interval
    }

