#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2

// Structure to hold the buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
static int                  fd                  = -1;
static struct buffer        buffers[NUM_BUFFERS];
static unsigned int         n_buffers           = 0;
static unsigned int         current_buffer      = 0;
static volatile int         running             = 1;

// Function prototypes
int  init_v4l2(void);
int  deinit_v4l2(void);
int  capture_frame(unsigned char **frame_data);
int  yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height);
void box_blur(unsigned char *rgb, int width, int height);
int  save_jpeg(unsigned char *rgb, int width, int height, const char *filename);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Initialize V4L2 device
int init_v4l2(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    n_buffers = req.count;
    printf("Requested %d buffers\n", n_buffers);

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        return -1;
    }

    return 0;
}

// Deinitialize V4L2 device
int deinit_v4l2(void) {
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }

    return 0;
}

// Capture a single frame from the camera
int capture_frame(unsigned char **frame_data) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout: No frame received\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = current_buffer;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = buffers[current_buffer].start;
    current_buffer = (current_buffer + 1) % n_buffers;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Convert YUYV to RGB24
int yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height; i += 2) {
        unsigned char y1 = yuyv[i * 2];
        unsigned char u = yuyv[i * 2 + 1];
        unsigned char y2 = yuyv[i * 2 + 3];
        unsigned char v = yuyv[i * 2 + 3 + 1];

        // YUV to RGB conversion (simplified, no gamma correction)
        int r1 = y1 + 1.370705 * (v - 128);
        int g1 = y1 - 0.698001 * (v - 128) - 0.336331 * (u - 128);
        int b1 = y1 + 1.732446 * (u - 128);

        int r2 = y2 + 1.370705 * (v - 128);
        int g2 = y2 - 0.698001 * (v - 128) - 0.336331 * (u - 128);
        int b2 = y2 + 1.732446 * (u - 128);

        // Clamp values to 0-255
        r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
        g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
        b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

        r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
        g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
        b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

        rgb[i * 6 + 0] = (unsigned char)r1;
        rgb[i * 6 + 1] = (unsigned char)g1;
        rgb[i * 6 + 2] = (unsigned char)b1;

        rgb[i * 6 + 3] = (unsigned char)r2;
        rgb[i * 6 + 4] = (unsigned char)g2;
        rgb[i * 6 + 5] = (unsigned char)b2;
    }
    return 0;
}

// Apply 5x5 box blur
void box_blur(unsigned char *rgb, int width, int height) {
    unsigned char *temp = (unsigned char *)malloc(width * height * 3);
    if (temp == NULL) {
        perror("Failed to allocate temporary buffer for blur");
        return;
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0;
            for (int i = -BLUR_RADIUS; i <= BLUR_RADIUS; i++) {
                for (int j = -BLUR_RADIUS; j <= BLUR_RADIUS; j++) {
                    int nx = x + i;
                    int ny = y + j;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        r += rgb[(ny * width + nx) * 3 + 0];
                        g += rgb[(ny * width + nx) * 3 + 1];
                        b += rgb[(ny * width + nx) * 3 + 2];
                    }
                }
            }
            r /= (BLUR_RADIUS * 2 + 1) * (BLUR_RADIUS * 2 + 1);
            g /= (BLUR_RADIUS * 2 + 1) * (BLUR_RADIUS * 2 + 1);
            b /= (BLUR_RADIUS * 2 + 1) * (BLUR_RADIUS * 2 + 1);

            temp[(y * width + x) * 3 + 0] = (unsigned char)r;
            temp[(y * width + x) * 3 + 1] = (unsigned char)g;
            temp[(y * width + x) * 3 + 2] = (unsigned char)b;
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

// Save JPEG image
int save_jpeg(unsigned char *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Error opening output file");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE); // Quality 75

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    unsigned char *yuyv_frame = NULL;
    unsigned char *rgb_frame = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2
    if (init_v4l2() < 0) {
        fprintf(stderr, "V4L2 initialization failed\n");
        return 1;
    }

    // Allocate memory for RGB frame
    rgb_frame = (unsigned char *)malloc(WIDTH * HEIGHT * 3);
    if (rgb_frame == NULL) {
        perror("Failed to allocate memory for RGB frame");
        deinit_v4l2();
        return 1;
    }

    // Capture and process frame
    if (capture_frame(&yuyv_frame) == 0) {
        if (yuyv_to_rgb(yuyv_frame, rgb_frame, WIDTH, HEIGHT) == 0) {
            box_blur(rgb_frame, WIDTH, HEIGHT);

            // Generate filename
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

            // Save JPEG
            if (save_jpeg(rgb_frame, WIDTH, HEIGHT, filename) == 0) {
                printf("Saved JPEG to %s\n", filename);
            } else {
                fprintf(stderr, "JPEG save failed\n");
            }
        } else {
            fprintf(stderr, "YUYV to RGB conversion failed\n");
        }
    } else {
        fprintf(stderr, "Frame capture failed\n");
    }

    // Clean up
    free(rgb_frame);
    deinit_v4l2();

    return 0;
}

