#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_PATH "/dev/video0"

// Function to open the video device
int open_device(const char *device_path) {
    int fd = open(device_path, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }
    return 0;
}

// Function to enumerate supported frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_frmsizeenum *frmsize) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, frmsize) == -1) {
        perror("Error enumerating frame sizes");
        return -1;
    }
    return 0;
}

// Function to enumerate supported frame intervals
int enumerate_frame_intervals(int fd, struct v4l2_frmivalenum *frmival) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, frmival) == -1) {
        perror("Error enumerating frame intervals");
        return -1;
    }
    return 0;
}

// Function to query control information
int query_control(int fd, struct v4l2_queryctrl *ctrl) {
    if (ioctl(fd, VIDIOC_QUERYCTRL, ctrl) == -1) {
        perror("Error querying control");
        return -1;
    }
    return 0;
}

// Function to print supported resolutions and frame rates
void print_resolutions_frame_rates(int fd) {
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    int i = 0;

    memset(&frmsize, 0, sizeof(frmsize));
    memset(&frmival, 0, sizeof(frmival));

    printf("Supported Resolutions and Frame Rates:\n");
    printf("------------------------------------\n");

    while (enumerate_frame_sizes(fd, &frmsize) != -1) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            memset(&frmival, 0, sizeof(frmival));
            frmival.pixel_format = frmsize.pixel_format;
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;

            if (enumerate_frame_intervals(fd, &frmival) != -1) {
                if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                    printf("  Resolution: %dx%d, Frame Rate: %.2f fps\n",
                           frmsize.discrete.width, frmsize.discrete.height,
                           (double)frmival.discrete.numerator / frmival.discrete.denominator);
                } else {
                    printf("  Resolution: %dx%d, Frame Rate: Variable\n",
                           frmsize.discrete.width, frmsize.discrete.height);
                }
            } else {
                printf("  Resolution: %dx%d, Frame Rate: Unknown\n",
                       frmsize.discrete.width, frmsize.discrete.height);
            }
        }
        i++;
        if (i > 10) break; // Limit the number of resolutions printed
        frmsize.index++;
    }
}

// Function to check if autofocus is supported
int is_autofocus_supported(int fd) {
    struct v4l2_queryctrl ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (query_control(fd, &ctrl) == -1) {
        // Control might not exist, so assume not supported
        return 0;
    }

    if (ctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        return 0; // Autofocus is disabled
    }

    return 1; // Autofocus is supported
}

int main() {
    int fd;
    struct v4l2_capability cap;

    // Open the device
    fd = open_device(DEVICE_PATH);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (query_capabilities(fd, &cap) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_PATH);
        close(fd);
        return EXIT_FAILURE;
    }

    // Print supported resolutions and frame rates
    print_resolutions_frame_rates(fd);

    // Check if autofocus is supported
    int autofocus_supported = is_autofocus_supported(fd);
    printf("Autofocus supported: %s\n", autofocus_supported ? "Yes" : "No");

    // Close the device
    close(fd);

    return EXIT_SUCCESS;
}

