#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo center position and range
#define SERVO_CENTER 1500
#define SERVO_MIN 1000
#define SERVO_MAX 2000

// Global variables for servo positions
int pan_position = SERVO_CENTER;
int tilt_position = SERVO_CENTER;

// Function prototypes
void initialize_gpio();
void set_servo_position(int pan, int tilt);
void handle_button_input();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Set servo pins as output
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);
}

// Function to set servo positions
void set_servo_position(int pan, int tilt) {
    gpioServo(PAN_SERVO_PIN, pan);
    gpioServo(TILT_SERVO_PIN, tilt);
}

// Function to handle button input
void handle_button_input() {
    if (gpioRead(UP_BUTTON_PIN) == 0) {
        tilt_position += 10;
        if (tilt_position > SERVO_MAX) {
            tilt_position = SERVO_MAX;
        }
        set_servo_position(pan_position, tilt_position);
    }
    if (gpioRead(DOWN_BUTTON_PIN) == 0) {
        tilt_position -= 10;
        if (tilt_position < SERVO_MIN) {
            tilt_position = SERVO_MIN;
        }
        set_servo_position(pan_position, tilt_position);
    }
    if (gpioRead(LEFT_BUTTON_PIN) == 0) {
        pan_position -= 10;
        if (pan_position < SERVO_MIN) {
            pan_position = SERVO_MIN;
        }
        set_servo_position(pan_position, tilt_position);
    }
    if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
        pan_position += 10;
        if (pan_position > SERVO_MAX) {
            pan_position = SERVO_MAX;
        }
        set_servo_position(pan_position, tilt_position);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Print startup message
    printf("Pan-Tilt Servo Control\n");
    printf("Pan Servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("Tilt Servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("UP: GPIO%d\n", UP_BUTTON_PIN);
    printf("DOWN: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("LEFT: GPIO%d\n", LEFT_BUTTON_PIN);
    printf("RIGHT: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: %d\n", SERVO_CENTER);

    // Set initial servo positions
    set_servo_position(SERVO_CENTER, SERVO_CENTER);

    // Main loop
    while (1) {
        handle_button_input();
        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

