#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int log_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_get_value(void);
int capture_image(void);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(gpio_line, "motion_capture") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read GPIO value
int gpio_get_value(void) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Function to capture an image using libcamera-still
int capture_image(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", timeinfo);
    snprintf(command, sizeof(command), "libcamera-still -o %s/%s.jpg --width %d --height %d -q %d --timeout 2000 --nopreview",
             IMAGE_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        perror("Error executing libcamera-still");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fd == -1) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd == -1) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (flock(log_fd, LOCK_EX) == -1) {
        perror("Error acquiring lock on log file");
        return -1;
    }

    dprintf(log_fd, "%s: %s\n", timestamp, message);
    fsync(log_fd);
    if (flock(log_fd, LOCK_UN) == -1) {
        perror("Error releasing lock on log file");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

