void cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    log_event("Motion capture started");

    // Main loop
    while (!terminate) {
        int value = gpio_get_value();
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value, exiting\n");
            break;
        }

        if (value == 1) { // Rising edge detected
            log_event("Motion detected!");
            if (capture_image() == 0) {
                log_event("Image captured successfully");
            } else {
                log_event("Image capture failed");
            }
            // Debounce delay
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
            nanosleep(&delay, NULL);
        }

        // Small delay to avoid busy-waiting
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    log_event("Motion capture stopped");
    return 0;
}

