// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define servo limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables for current angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int set_servo_angle(int gpio, int angle);
int read_input();
void signal_handler(int signal);

// Function to set the servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate failure
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    // Set the PWM pulse width
    gpioPWM(gpio, pulse_width);

    return 0; // Indicate success
}

// Function to read input from stdin
int read_input() {
    char input;
    int pan_change = 0;
    int tilt_change = 0;

    // Read input character
    input = getchar();

    // Handle input based on arrow keys
    switch (input) {
        case 'w':
            tilt_change = -5; // Up
