// Function to initialize the OLED display
int oled_init() {
    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialization sequence
    if (i2cWriteByteData(i2c_handle, 0x00, 0xAE) < 0) { // Display off
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xD5) < 0) { // Set display clock divide ratio/oscillator frequency
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x80) < 0) { // --ratio
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xA8) < 0) { // Set multiplex ratio
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x3F) < 0) { // --ratio
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xD3) < 0) { // Set display offset
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) { // --offset
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x40) < 0) { // Set start line address
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x8D) < 0) { // Charge pump setting
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x14) < 0) { // --enable
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x20) < 0) { // Memory addressing mode
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) { // --mode
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xA1) < 0) { // Segment remap
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xC8) < 0) { // COM scan direction
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xDA) < 0) { // COM pins hardware configuration
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x12) < 0) { // --config
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x81) < 0) { // Contrast control
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xCF) < 0) { // --contrast
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xD9) < 0) { // Precharge period
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xF1) < 0) { // --period
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xDB) < 0) { // VCOM deselect level
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x40) < 0) { // --level
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xA4) < 0) { // Display all points off
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xA6) < 0) { // Normal display
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0xAF) < 0) { // Display on
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    oled_clear();
    return 0;
}

// Function to clear the OLED display buffer
void oled_clear() {
    memset(display_buffer, 0, sizeof(display_buffer));
}

// Function to set a pixel in the OLED display buffer
void oled_set_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        return;
    }
    int page = y / 8;
    int bit = y % 8;
    if (color) {
        display_buffer[x + page * OLED_WIDTH] |= (1 << bit);
    } else {
        display_buffer[x + page * OLED_WIDTH] &= ~(1 << bit);
    }
}

// Function to draw a character on the OLED display
void oled_draw_char(int x, int y, char c, int color) {
    if (c < 32 || c > 126) {
        c = 0; // Use space for invalid characters
    }
    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 8; j++) {
            if ((font[c][i] >> j) & 0x01) {
                oled_set_pixel(x + i, y + j, color);
            }
        }
    }
}

// Function to draw a string on the OLED display
void oled_draw_string(int x, int y, const char *str, int color) {
    int current_x = x;
    while (*str) {
        oled_draw_char(current_x, y, *str, color);
        current_x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000; // Convert to Celsius
    } else {
        fprintf(stderr, "Error reading temperature file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    static unsigned long long prev_non_idle_total = 0;
    int usage = 0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat file\n");
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;
    unsigned long long non_idle_total = total - idle_total;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle_total = idle_total - prev_idle_total;
    unsigned long long delta_non_idle_total = non_idle_total - prev_non_idle_total;

    usage = (int)(((delta_non_idle_total) / (double)delta_total) * 100.0);

    prev_total = total;
    prev_idle_total = idle_total;
    prev_non_idle_total = non_idle_total;

    return usage;
}

// Function to display data on the OLED screen
void display_data(int temp, int usage) {
    oled_clear();

    char temp_str[20];
    char usage_str[20];

    snprintf(temp_str, sizeof(temp_str), "Temp: %d C", temp);
    snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);

    oled_draw_string(0, 0, temp_str, 1);
    oled_draw_string(0, 16, usage_str, 1);

    // Update the display
    i2cWriteByteData(i2c_handle, 0x00, 0x21); // Column address
    i2cWriteByteData(i2c_handle, 0x00, 0x00); // Start column
    i2cWriteByteData(i2c_handle, 0x00, 0x7F); // End column

    i2cWriteByteData(i2c_handle, 0x00, 0x22); // Page address
    i2cWriteByteData(i2c_handle, 0x00, 0x00); // Start page
    i2cWriteByteData(i2c_handle, 0x00, 0x07); // End page

    for (int i = 0; i < OLED_WIDTH * (OLED_HEIGHT / 8); i++) {
        if (i2cWriteByteData(i2c_handle, 0x40, display_buffer[i]) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
            break;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize OLED display
    if (oled_init() < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        if (temp == -1 || usage == -1) {
            oled_clear();
            oled_draw_string(0, 0, "Error", 1);
            oled_draw_string(0, 16, "Reading data", 1);
        } else {
            display_data(temp, usage);
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    // Clean up
    oled_clear();
    i2cWriteByteData(i2c_handle, 0x00, 0xAE); // Display off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

