    gpioSetAlertFunc(SENSOR1_GPIO, sensor1_callback);
    gpioSetAlertFunc(SENSOR2_GPIO, sensor2_callback);
    gpioSetAlertFunc(SENSOR3_GPIO, sensor3_callback);

    // Initialize the I2C connection to the LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate the flow rates and volumes
        float flow_rate1 = calculate_flow_rate(sensor1_pulse_count);
        float flow_rate2 = calculate_flow_rate(sensor2_pulse_count);
        float flow_rate3 = calculate_flow_rate(sensor3_pulse_count);

        sensor1_volume += flow_rate1 / 60.0; // Accumulate volume over time
        sensor2_volume += flow_rate2 / 60.0;
        sensor3_volume += flow_rate3 / 60.0;

        // Log the data to the console
        printf("Sensor 1: Flow Rate = %.2f LPM, Volume = %.2f L\n", flow_rate1, sensor1_volume);
        printf("Sensor 2: Flow Rate = %.2f LPM, Volume = %.2f L\n", flow_rate2, sensor2_volume);
        printf("Sensor 3: Flow Rate = %.2f LPM, Volume = %.2f L\n", flow_rate3, sensor3_volume);

        // Update the LCD display every 10 seconds
        if (sensor1_pulse_count > 0 || sensor2_pulse_count > 0 || sensor3_pulse_count > 0) {
            update_lcd(flow_rate1, flow_rate2, flow_rate3, sensor1_volume, sensor2_volume, sensor3_volume);
