        // Reset pulse counts for the next interval
        sensor1_pulse_count = 0;
        sensor2_pulse_count = 0;
        sensor3_pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    gpioTerminate();
    i2cClose(i2c_handle);
    return 0;
