#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define WIND_SPEED_GPIO 17
#define LCD_I2C_ADDR 0x27
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_CHANNEL 0
#define WIND_SPEED_SCALE 0.5 // m/s per pulse
#define WIND_DIRECTION_MIN_ADC 0
#define WIND_DIRECTION_MAX_ADC 1023
#define WIND_DIRECTION_MIN_DEGREES 0
#define WIND_DIRECTION_MAX_DEGREES 359
#define SAMPLE_WINDOW_MS 500
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS 1

// Global variables
static volatile int pulse_count = 0;
static int spi_handle;
static int i2c_handle;
static volatile int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
int read_mcp3008(int channel);
float calculate_wind_speed(int pulse_count);
float calculate_wind_direction(int adc_value);
void display_wind_data(float wind_speed, float wind_direction);
void signal_handler(int signal);
void cleanup();

// Function to handle anemometer pulses
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * WIND_SPEED_SCALE;
}

// Function to calculate wind direction
float calculate_wind_direction(int adc_value) {
    if (adc_value < WIND_DIRECTION_MIN_ADC) {
        return WIND_DIRECTION_MIN_DEGREES; // Clamp to minimum
    } else if (adc_value > WIND_DIRECTION_MAX_ADC) {
        return WIND_DIRECTION_MAX_DEGREES; // Clamp to maximum
    } else {
        return ((float)(adc_value - WIND_DIRECTION_MIN_ADC) / (WIND_DIRECTION_MAX_ADC - WIND_DIRECTION_MIN_ADC)) * (WIND_DIRECTION_MAX_DEGREES - WIND_DIRECTION_MIN_DEGREES) + WIND_DIRECTION_MIN_DEGREES;
    }
}

// Function to display wind data on LCD
void display_wind_data(float wind_speed, float wind_direction) {
    char buffer[17]; // 16 characters + null terminator

    // Format wind speed
    snprintf(buffer, sizeof(buffer), "Speed: %.1f m/s", wind_speed);

    // Set cursor to first line
    char cmd[2];
    cmd[0] = 0x80; // Set cursor to first line
    cmd[1] = 0x00; // Clear display
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (clear display)\n");
        return;
    }

    // Send wind speed string
    if (i2cWriteDevice(i2c_handle, buffer, strlen(buffer)) != 0) {
        fprintf(stderr, "Error: I2C write failed (wind speed)\n");
        return;
    }

    // Move cursor to second line
    cmd[0] = 0xC0; // Set cursor to second line
    cmd[1] = 0x00; // Clear display
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (clear display)\n");
        return;
    }

    // Format wind direction
    snprintf(buffer, sizeof(buffer), "Dir: %.0f deg", wind_direction);

    // Send wind direction string
    if (i2cWriteDevice(i2c_handle, buffer, strlen(buffer)) != 0) {
        fprintf(stderr, "Error: I2C write failed (wind direction)\n");
        return;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioSetISRFuncEx(WIND_SPEED_GPIO, RISING_EDGE, 0, pulse_counter, NULL); // Disable interrupt
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for anemometer
    gpioSetMode(WIND_SPEED_GPIO, PI_INPUT);
    gpioSetPullUpDown(WIND_SPEED_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize SPI
    spi_handle = spiOpen(MCP3008_SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0); // I2C bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up interrupt for anemometer pulses
    if (gpioSetISRFuncEx(WIND_SPEED_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up interrupt\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read wind vane data
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read wind vane data\n");
            continue; // Continue to the next iteration
        }

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: Wind vane sensor absent (ADC value: %d)\n", adc_value);
        }

        // Calculate wind speed and direction
        float wind_speed = calculate_wind_speed(pulse_count);
        float wind_direction = calculate_wind_direction(adc_value);

        // Display wind data on LCD
        display_wind_data(wind_speed, wind_direction);

        // Reset pulse count for the next sample window
        pulse_count = 0;

        // Wait for the next sample window
        gpioDelay(SAMPLE_WINDOW_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

