int lcd_init(int i2c_fd) {
    // Initialize LCD in 4-bit mode
    lcd_send_command(i2c_fd, 0x33); // Initialize
    lcd_send_command(i2c_fd, 0x32); // Initialize
    lcd_send_command(i2c_fd, 0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(i2c_fd, 0x0C); // Display on, cursor off, blink off
    lcd_send_command(i2c_fd, 0x06); // Increment cursor, no shift
    lcd_clear(i2c_fd);
    return 0;
}

int lcd_send_command(int i2c_fd, unsigned char command) {
    unsigned char data_u, data_l;
    data_u = (command & 0xF0) | 0x04 | 0x08; // En=1, Rs=0
    data_l = ((command << 4) & 0xF0) | 0x04 | 0x08; // En=1, Rs=0

    wiringPiI2CWrite(i2c_fd, data_u);
    wiringPiI2CWrite(i2c_fd, data_l);
    return 0;
}

