    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and alert function
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL);

    // Initialize wiringPi I2C
    i2c_fd = wiringPiI2CSetup(lcd_address);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init(i2c_fd) != 0) {
        fprintf(stderr, "LCD initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Count pulses for 1 second
        gpioDelay(1000); // Delay for 1 second
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(current_pulse_count);

        // Display flow rate on LCD
        lcd_clear(i2c_fd);
        lcd_set_cursor(i2c_fd, 0, 0);
        lcd_print(i2c_fd, "Flow Rate:");
        lcd_set_cursor(i2c_fd, 1, 0);
        char buffer[17];
        snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
        lcd_print(i2c_fd, buffer);

        // Check for sensor failure (no pulses for a long time)
        static time_t last_pulse_time = time(NULL);
        if (current_pulse_count == 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_pulse_time) > 10) {
                fprintf(stderr, "Warning: No pulses detected for 10 seconds. Check sensor connection.\n");
                lcd_clear(i2c_fd);
                lcd_set_cursor(i2c_fd, 0, 0);
                lcd_print(i2c_fd, "Sensor Error!");
                lcd_set_cursor(i2c_fd, 1, 0);
                lcd_print(i2c_fd, "Check Connection");
            }
            last_pulse_time = current_time;
        }
    }

    // Cleanup
    lcd_clear(i2c_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

