#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Define matrix size
const int matrix_size = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs
    for (int i = 0; i < matrix_size; i++)
    {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 1); // Set HIGH for common anode
    }

    // Set column pins as outputs
    for (int i = 0; i < matrix_size; i++)
    {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 0); // Set LOW for common anode
    }

    return 0;
}

// Function to display a single frame of the animation
void display_frame(int row, int col, int direction)
{
    // Set row HIGH
    gpioWrite(row_pins[row], 1);

    // Set column LOW
    gpioWrite(col_pins[col], 0);

    // Delay for scan time
    gpioDelay(800); // 800 microseconds

    // Clear row and column
    gpioWrite(row_pins[row], 1); // Turn off LED
    gpioWrite(col_pins[col], 0); // Keep column low
}

// Function to generate the wave pattern
void generate_wave(int *wave_pattern, int direction)
{
    for (int i = 0; i < matrix_size; i++)
    {
        wave_pattern[i] = i; // Left to right
    }

    if (direction == -1) // Right to left
    {
        for (int i = 0; i < matrix_size; i++)
        {
            wave_pattern[i] = matrix_size - 1 - i;
        }
    }
}

// Function to shift the wave pattern
void shift_wave(int *wave_pattern, int direction)
{
    int temp = wave_pattern[0];
    for (int i = 0; i < matrix_size - 1; i++)
    {
        wave_pattern[i] = wave_pattern[i + 1];
    }
    wave_pattern[matrix_size - 1] = temp + direction; // Shift the last element

    // Wrap around if necessary
    if (wave_pattern[matrix_size - 1] < 0)
    {
        wave_pattern[matrix_size - 1] = matrix_size - 1;
    }
    if (wave_pattern[matrix_size - 1] >= matrix_size)
    {
        wave_pattern[matrix_size - 1] = 0;
    }
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        int wave_pattern[matrix_size];
        generate_wave(wave_pattern, 1); // Left to right

        for (int i = 0; i < matrix_size; i++)
        {
            display_frame(row_pins[i], col_pins[wave_pattern[i]], 1);
        }

        gpioDelay(100000); // Delay between wave shifts (100ms)

        int wave_pattern2[matrix_size];
        generate_wave(wave_pattern2, -1); // Right to left

        for (int i = 0; i < matrix_size; i++)
        {
            display_frame(row_pins[i], col_pins[wave_pattern2[i]], -1);
        }

        gpioDelay(100000); // Delay between wave shifts (100ms)
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

