// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// VL53L3CX register addresses (Example - refer to datasheet for complete list)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L3CX_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD 0x001E
#define VL53L3CX_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE 0x001F
#define VL53L3CX_REG_START_STOP_CONTROL 0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE 0x001A
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint8_t status;
    uint16_t spad_count;
    uint16_t peak_signal_rate;
} sensor_data_t;

// Function prototypes
int init_vl53l3cx();
int read_distance(sensor_data_t *data);
char* get_iso8601_timestamp();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the VL53L3CX sensor
int init_vl53l3cx() {
    // Example initialization sequence (refer to ULD documentation for complete sequence)
    // This is a placeholder - replace with actual initialization steps
    uint8_t model_id;

    // Read sensor model ID
    if (i2cReadByteData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID) < 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    // Placeholder for model ID check (replace with actual check)
    model_id = i2cReadByteData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xE0) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure ROI (example)
    if (i2cWriteByteData(i2c_handle, VL53L3CX_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD, 0x00) < 0) {
        fprintf(stderr, "Error writing ROI config\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L3CX_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE, 0x0A) < 0) {
        fprintf(stderr, "Error writing ROI config\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L3CX_REG_START_STOP_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    printf("VL53L3CX initialized successfully\n");
    return 0;
}

