int read_distance(sensor_data_t *data) {
    // Read range status
    int range_status = i2cReadByteData(i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        data->status = 0xFF; // Indicate error
        return -1;
    }
    data->status = (uint8_t)range_status;

    // Read distance
    int distance = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        data->distance = 0xFFFF; // Indicate error
        return -1;
    }
    data->distance = (uint16_t)distance;

    // Read SPAD count
    int spad_count = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_SPAD_NB);
    if (spad_count < 0) {
        fprintf(stderr, "Error reading SPAD count\n");
        data->spad_count = 0xFFFF; // Indicate error
        return -1;
    }
    data->spad_count = (uint16_t)spad_count;

    // Read peak signal rate
    int peak_signal_rate = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE);
    if (peak_signal_rate < 0) {
        fprintf(stderr, "Error reading peak signal rate\n");
        data->peak_signal_rate = 0xFFFF; // Indicate error
        return -1;
    }
    data->peak_signal_rate = (uint16_t)peak_signal_rate;

    return 0;
}

