    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L3CX sensor
    if (init_vl53l3cx() != 0) {
        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read distance measurements
        if (read_distance(&sensor_data) == 0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log data to console
            printf("%s - Distance: %d mm, Status: 0x%02X, SPAD Count: %d, Peak Signal Rate: %d\n",
                   timestamp, sensor_data.distance, sensor_data.status, sensor_data.spad_count, sensor_data.peak_signal_rate);

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

