#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip name
#define GPIO_CHIP_NAME "gpiochip4"

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
int control_led(int on);
int log_event(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s', trying 'gpiochip0'\n", GPIO_CHIP_NAME);
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip 'gpiochip0'\n");
            return -1;
        }
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d\n", SENSOR_PIN);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d\n", LED_PIN);
        return -1;
    }

    // Request sensor line as input
    if (gpiod_line_request_input(sensor_line, "sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line as input\n");
        return -1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output\n");
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1;
    }
    return value;
}

// Control LED (1 for ON, 0 for OFF)
int control_led(int on) {
    if (gpiod_line_set_value(led_line, on) < 0) {
        fprintf(stderr, "Error setting LED value\n");
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(void) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(log_file, "%s Object detected\n", timestamp);
    fclose(log_file);

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_sensor_value = 1; // Assume no object initially

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting\n");
            break;
        }

        if (sensor_value == 0 && last_sensor_value == 1) {
            // Object detected (falling edge)
            printf("Object detected!\n");
            if (log_event() < 0) {
                fprintf(stderr, "Error logging event\n");
            }

            // Blink LED
            if (control_led(1) < 0) {
                fprintf(stderr, "Error turning LED on\n");
            }
            usleep(100000); // 100 ms
            if (control_led(0) < 0) {
                fprintf(stderr, "Error turning LED off\n");
            }
        }

        last_sensor_value = sensor_value;
        usleep(100000); // 100 ms polling interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return 0;
}

