typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Verify PART_ID
    status = i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
        return -1;
    }

    status = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", status);
        return -1;
    }

    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", status);
        return -1;
    }

    // Set CH_LIST to enable PS1 and ALS_VIS channels
    status = i2cWriteByteData(i2c_handle, SI1145_REG_CH_LIST, 0x77); //0x77 enables PS1 and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing to CH_LIST register: %d\n", status);
        return -1;
    }

    // Force measurement
    status = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND register (ALS_FORCE): %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND register (PS_FORCE): %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int status;
    uint16_t prox, als;

    // Read proximity data
    status = i2cReadWordData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    prox = (uint16_t)status;

    // Read ambient light data
    status = i2cReadWordData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    als = (uint16_t)status;

    *proximity = (int)prox;
    *ambient_light = (int)als;

    return 0;
}

