#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define WATERING_THRESHOLD 15.0 // cm
#define POLLING_INTERVAL 60    // seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void log_data(double distance, const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1 ms

    return 0;
}

// Generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width = 0;
    int timeout_count = 0;

    // Wait for the echo pin to go high (rising edge)
    while (gpioRead(ECHO_PIN) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        if (timeout_count++ > TIMEOUT_US) {
            return -1; // Timeout
        }
        gpioDelay(1); // Check every 1 us
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low (falling edge)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timeout_count++ > TIMEOUT_US) {
            return -2; // Timeout
        }
        gpioDelay(1); // Check every 1 us
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    return pulse_width;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return ((double)pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert ns to s, and by 2 for one-way distance
}

// Log data to file with ISO 8601 timestamp
void log_data(double distance, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm, %s\n", buf, distance, message);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Plant Watering Reminder System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            if (pulse_width == -1) {
                log_data(-1.0, "Timeout waiting for rising edge.");
            } else {
                log_data(-1.0, "Timeout waiting for falling edge.");
            }
        } else {
            double distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_data(distance, "OK");
                if (distance < WATERING_THRESHOLD) {
                    log_data(distance, "Time to water the plant!");
                }
            } else {
                log_data(distance, "Out of range.");
            }
        }

        sleep(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

