#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// APDS9960 I2C address
#define APDS9960_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ID 0x92
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90

// Register addresses for color and proximity data
#define APDS9960_RED 0x96
#define APDS9960_GREEN 0x98
#define APDS9960_BLUE 0x9A
#define APDS9960_CLEAR 0x9C
#define APDS9960_PROX 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_apds9960();
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear, uint8_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int initialize_apds9960() {
    int status;

    // Verify sensor ID
    status = i2cWriteByteData(i2c_handle, APDS9960_ID, 0x00); // Dummy write to read ID
    if (status < 0) {
        fprintf(stderr, "Error writing to ID register: %s\n", strerror(errno));
        return -1;
    }
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure sensor registers
    status = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03); // Enable PON and AEN
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB); // Set integration time
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6); // Set wait time
    if (status < 0) {
        fprintf(stderr, "Error writing to WTIME register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87); // Set pulse length
    if (status < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03); // Set gain
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01); // Set proximity drive strength
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

