    if (part_id < 0) {
        return -1;
    }
    if (part_id != 0x82) { // Expected Si1182 part ID
        fprintf(stderr, "Error: Incorrect part ID 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }
    return 0;
}

