#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define TRIGGER_COMMAND 0x01 // Example trigger command
#define MEASUREMENT_DELAY_MS 50
#define SAMPLE_INTERVAL_MS 200
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int trigger_measurement();
int read_distance(unsigned char *data);
float convert_to_mm(unsigned char *data);
int log_data(float distance_mm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, TRIGGER_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return 1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    return 0;
}

