#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG 0x58 // Example register, adjust based on datasheet
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
FILE *log_file;
int distance_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the ICU-20201 sensor
int initialize_sensor() {
    int who_am_i;

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("ICU-20201 sensor initialized successfully.\n");
    return 0;
}

// Reads the distance measurement from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Read two bytes from the distance register
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

