#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the Omron B5L-LD50-07050 sensor address
#define SENSOR_ADDRESS 0x50

// Define the command frame to request a distance measurement
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}

// Define the number of samples to take per cycle
#define NUM_SAMPLES 10

// Define the threshold distance for intrusion detection (in mm)
#define INTRUSION_THRESHOLD 1000

// Define the delay between sampling cycles (in ms)
#define SAMPLE_DELAY 100

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer

// Function prototypes
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int request_distance_measurement(int fd);
int read_distance_response(int fd, unsigned char *response);
int validate_response(unsigned char *response);
int get_distance(unsigned char *response);
double calculate_average_distance(int *distances, int num_samples);
int log_intrusion(double average_distance);
void signal_handler(int signal);

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    int result = write(fd, data, len);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    int result = read(fd, data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to request a distance measurement
int request_distance_measurement(int fd) {
    unsigned char command[4] = COMMAND_FRAME;
    if (i2c_write(fd, command, 4) != 0) {
        fprintf(stderr, "Error requesting distance measurement\n");
        return -1;
    }
    return 0;
}

// Function to read the distance response
int read_distance_response(int fd, unsigned char *response) {
    if (i2c_read(fd, response, 15) != 0) {
        fprintf(stderr, "Error reading distance response\n");
        return -1;
    }
    return 0;
}

// Function to validate the response header
int validate_response(unsigned char *response) {
    if (response[0] != 0x50) {
        fprintf(stderr, "Error: Invalid response header (0x%02X)\n", response[0]);
        return -1;
    }
    return 0;
}

// Function to extract the distance from the response
int get_distance(unsigned char *response) {
    int distance = (response[11] << 8) | response[12];
    return distance;
}

// Function to calculate the average distance
double calculate_average_distance(int *distances, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Function to log an intrusion event
int log_intrusion(double average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int distances[NUM_SAMPLES];
        int valid_samples = 0;

        // Sample the sensor multiple times
        for (int i = 0; i < NUM_SAMPLES; i++) {
            // Request a distance measurement
            if (request_distance_measurement(i2c_fd) != 0) {
                fprintf(stderr, "Error requesting distance measurement, retrying...\n");
                usleep(10000); // 10 ms delay
                continue;
            }

            // Wait for the measurement to complete (at least 10 ms)
            usleep(10000);

            // Read the distance response
            unsigned char response[15];
            if (read_distance_response(i2c_fd, response) != 0) {
                fprintf(stderr, "Error reading distance response, retrying...\n");
                usleep(10000); // 10 ms delay
                continue;
            }

            // Validate the response
            if (validate_response(response) != 0) {
                fprintf(stderr, "Error validating response, retrying...\n");
                usleep(10000); // 10 ms delay
                continue;
            }

            // Extract the distance
            int distance = get_distance(response);

            // Basic data validation (example: check for reasonable distance range)
            if (distance > 0 && distance < 5000) {
                distances[i] = distance;
                valid_samples++;
            } else {
                fprintf(stderr, "Invalid distance reading: %d, skipping sample\n", distance);
            }

            usleep(10000); // 10 ms delay between samples
        }

        // Calculate the average distance
        if (valid_samples > 0) {
            double average_distance = calculate_average_distance(distances, NUM_SAMPLES);

            // Check for intrusion
            if (average_distance < INTRUSION_THRESHOLD) {
                log_intrusion(average_distance);
            }
        } else {
            fprintf(stderr, "No valid distance readings, skipping intrusion check\n");
        }

        // Delay between sampling cycles
        usleep(SAMPLE_DELAY * 1000); // Convert ms to us
    }

    // The program should never reach here due to the infinite loop
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

