#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_REG_MODEL_ID 0xC0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int verify_sensor();
int start_measurement();
int read_distance(int *distance);
void print_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify sensor presence by reading model ID
int verify_sensor() {
    char buf[1];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_MODEL_ID, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        return -1;
    }

    if (buf[0] != 0xEE) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0xEE)\n", buf[0]);
        return -1;
    }

    return 0;
}

// Start a single measurement
int start_measurement() {
    char buf[1];
    buf[0] = 0x01;
    int result = i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_SYSRANGE_START, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to start measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Wait for interrupt
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        result = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, buf, 1);
