            fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
            return -1;
        }
        if (buf[0] & 0x01) {
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for interrupt\n");
        return -1;
    }

    // Read distance
    result = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1]; // Little-endian

    // Clear interrupt
    buf[0] = 0x01;
    result = i2cWriteI2CBlockData(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Print distance with timestamp
void print_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Distance: %d mm\n", timestamp, distance);
}

