    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance;

    // Main loop
    while (!terminate) {
        if (start_measurement() != 0) {
            fprintf(stderr, "Error starting measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(50); // Wait for measurement to complete

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        print_distance(distance);

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

