#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x39

// Register addresses
#define REG_CONFIG 0x18
#define REG_IRQ_STATUS 0x25
#define REG_PROX_LSB 0x2A
#define REG_PROX_MSB 0x2B

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_proximity();
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1182 sensor
int init_sensor() {
    int result;

    // Enable proximity mode
    result = i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read proximity data from the sensor
int read_proximity() {
    int result;
    unsigned char lsb, msb;

    // Check if data is ready
    result = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
    if (result < 0) {
        fprintf(stderr, "Error reading IRQ status register: %d\n", result);
        return -1;
    }

    // Read LSB
    result = i2cReadByteData(i2c_handle, REG_PROX_LSB);
    if (result < 0) {
        fprintf(stderr, "Error reading LSB register: %d\n", result);
        return -1;
    }
    lsb = (unsigned char)result;

    // Read MSB
    result = i2cReadByteData(i2c_handle, REG_PROX_MSB);
    if (result < 0) {
        fprintf(stderr, "Error reading MSB register: %d\n", result);
        return -1;
    }
    msb = (unsigned char)result;

    // Combine LSB and MSB to form 16-bit value
    int proximity_value = (msb << 8) | lsb;

    return proximity_value;
}

int main() {
    int proximity_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        proximity_value = read_proximity();
        if (proximity_value >= 0) {
            printf("Proximity: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Error reading proximity data\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

