#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define SCALE_FACTOR 0.125f
#define RETRY_DELAY_MS 100
#define SLEEP_MS 500

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_close(int fd);
int i2c_write(int fd, unsigned char reg, unsigned char value);
int i2c_read(int fd, unsigned char reg, unsigned char *value);
int mlx75030_read_distance(int fd, float *distance);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// MLX75030 read distance function
int mlx75030_read_distance(int fd, float *distance) {
    unsigned char low_byte, high_byte;
    int16_t raw_distance;

    // Read low byte
    if (i2c_read(fd, DISTANCE_REG, &low_byte) < 0) {
        fprintf(stderr, "Error reading low byte from sensor\n");
        return -1;
    }

    // Read high byte
    if (i2c_read(fd, DISTANCE_REG + 1, &high_byte) < 0) {
        fprintf(stderr, "Error reading high byte from sensor\n");
        return -1;
    }

    // Combine bytes (little-endian)
    raw_distance = (int16_t)((high_byte << 8) | low_byte);

    // Convert to millimeters
    *distance = (float)raw_distance * SCALE_FACTOR;

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    float distance;
    struct timespec sleep_time = {SLEEP_MS / 1000, (SLEEP_MS % 1000) * 1000000};
    struct timespec retry_time = {RETRY_DELAY_MS / 1000, (RETRY_DELAY_MS % 1000) * 1000000};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        i2c_close(i2c_fd);
        return 1;
    }

    // Verify device presence (read a register)
    unsigned char test_reg = 0x01; // Example register to read
    if (i2c_read(i2c_fd, test_reg, &test_reg) < 0) {
        fprintf(stderr, "Error verifying device presence\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (mlx75030_read_distance(i2c_fd, &distance) == 0) {
            printf("Distance: %.2f mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying in %d ms\n", (int)retry_time.tv_nsec / 1000000);
            nanosleep(&retry_time, NULL);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    i2c_close(i2c_fd);

    return 0;
}

