#include <time.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x44

// Define OPT3101 register addresses (Example - Refer to datasheet for actual values)
#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT 0x02
#define OPT3101_REG_ERROR 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a 16-bit register from the OPT3101
int read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char buf[1];
    buf[0] = reg_addr;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading data from I2C device.\n");
        return -1;
    }
    return 0;
}

// Function to write a 16-bit register to the OPT3101
int write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char buf[3];
    buf[0] = reg_addr;
    buf[1] = (data >> 8) & 0xFF; // MSB
    buf[2] = data & 0xFF;      // LSB

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing data to I2C device.\n");
        return -1;
    }
    return 0;
}

// Function to read distance data from the OPT3101
int read_distance(int handle, uint16_t *distance) {
    return read_register(handle, OPT3101_REG_DISTANCE, distance);
}

// Function to read ambient light data from the OPT3101
int read_ambient_light(int handle, uint16_t *ambient_light) {
    return read_register(handle, OPT3101_REG_AMBIENT, ambient_light);
}

// Function to read error flags from the OPT3101
int read_error_flags(int handle, uint16_t *error_flags) {
    return read_register(handle, OPT3101_REG_ERROR, error_flags);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("OPT3101 data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t distance, ambient_light, error_flags;

        // Read sensor data
        if (read_distance(i2c_handle, &distance) == 0 &&
            read_ambient_light(i2c_handle, &ambient_light) == 0 &&
            read_error_flags(i2c_handle, &error_flags) == 0) {

            // Log data to console
            printf("Distance: %d, Ambient Light: %d, Error Flags: 0x%04X\n", distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

