#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants for timeout and speed of sound
#define TIMEOUT_US 200000 // 200 ms in microseconds
#define SPEED_OF_SOUND 0.0343 // cm/us

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    // Validate pulse width
    if (pulse_width <= 0 || pulse_width > 38000) {
        fprintf(stderr, "Error: Invalid pulse width: %ld\n", pulse_width);
        return -1; // Indicate invalid pulse width
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance reading with a timestamp
void log_reading(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        double distance;
        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);
        } else {
            distance = -1.0; // Indicate error
        }

        // Log the reading
        if (distance > 0) {
            log_reading(distance);
        } else {
            fprintf(stderr, "Error: Could not read distance\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

