#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define RANGE_RESOLUTION 0.0486
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_uart(const char *device, speed_t baud_rate);
int read_radar_data(int fd, unsigned char *buffer, size_t buffer_size);
int validate_magic_word(const unsigned char *buffer, size_t buffer_size);
int parse_range_profile(const unsigned char *buffer, short *range_profile, size_t buffer_size);
float calculate_distance(const short *range_profile, size_t num_bins, float range_resolution);
int detect_intrusion(float distance, float threshold);
int control_led(int gpio_pin, int on);
int log_intrusion(const char *timestamp, float distance, const char *filename);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read radar data from UART
int read_radar_data(int fd, unsigned char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != buffer_size) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %zu\n", bytes_read, buffer_size);
    }
    return (int)bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, size_t buffer_size) {
    if (buffer_size < 8) {
        fprintf(stderr, "Error: Buffer too small for magic word.\n");
        return 0;
    }

    const unsigned char *magic_word = (const unsigned char *)"\x02\x01\x04\x03\x06\x05\x08\x07";
    if (memcmp(buffer, magic_word, 8) == 0) {
        return 1;
    } else {
        fprintf(stderr, "Error: Invalid magic word.\n");
        return 0;
    }
}

// Parse range profile
int parse_range_profile(const unsigned char *buffer, short *range_profile, size_t buffer_size) {
    if (buffer_size != 128) {
        fprintf(stderr, "Error: Invalid range profile size.\n");
        return -1;
    }

    for (size_t i = 0; i < 64; ++i) {
        range_profile[i] = (short)((buffer[i * 2 + 1] << 8) | buffer[i * 2]);
    }
    return 0;
}

// Calculate distance
float calculate_distance(const short *range_profile, size_t num_bins, float range_resolution) {
    for (size_t i = 0; i < num_bins; ++i) {
        if (range_profile[i] > 0) {
            return (float)i * range_resolution;
        }
    }
    return -1.0; // No target detected
}

// Detect intrusion
int detect_intrusion(float distance, float threshold) {
    return (distance >= 0.0 && distance <= threshold) ? 1 : 0;
}

// Control LED
int control_led(int gpio_pin, int on) {
    gpioWrite(gpio_pin, on);
    return 0;
}

// Log intrusion
int log_intrusion(const char *timestamp, float distance, const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.6f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(uart_fd);
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Main loop
    unsigned char buffer[136]; // 8 + 128
    short range_profile[64];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    while (program_running) {
        // Read radar data
        int bytes_read = read_radar_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate magic word
        if (!validate_magic_word(buffer, bytes_read)) {
            fprintf(stderr, "Magic word validation failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Parse range profile
        if (parse_range_profile(buffer + 8, range_profile, sizeof(buffer) - 8) == -1) {
            fprintf(stderr, "Error parsing range profile, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate distance
        float distance = calculate_distance(range_profile, 64, RANGE_RESOLUTION);

        // Detect intrusion
        if (detect_intrusion(distance, DISTANCE_THRESHOLD)) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            // Log intrusion
            if (log_intrusion(timestamp, distance, "intrusion_log.csv") == -1) {
                fprintf(stderr, "Error logging intrusion.\n");
            }

            // Control LED
            control_led(GPIO_LED, 1);
            sleep(LED_ON_TIME);
            control_led(GPIO_LED, 0);
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup
    close(uart_fd);
    gpioTerminate();

    return 0;
}

