#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor();
void control_buzzer(int state);
void log_state(int sensor_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Function to log the state to a file
void log_state(int sensor_value) {
    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(fp, "%s, Sensor: %d, Buzzer: %d\n", timestamp, sensor_value, gpioRead(BUZZER_PIN));
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_sensor_value = -1; // Initialize to an invalid value

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value != previous_sensor_value) {
            // Update buzzer state based on sensor value
            control_buzzer(sensor_value == 0 ? 1 : 0);

            // Log the state
            log_state(sensor_value);

            // Update previous sensor value
            previous_sensor_value = sensor_value;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    control_buzzer(0); // Turn off buzzer
    gpioTerminate();    // Terminate pigpio

    return 0;
}

