#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(float *distance);
int log_distance(float distance);
void trigger_alert(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    int high_byte;
    int low_byte;
    float distance;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;

    // Main loop
    while (!terminate) {
        // Check for termination signal before reading the sensor
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    // Read high byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return 1;
    }

    // Combine high and low bytes
    int16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert to centimeters (example conversion, adjust as needed)
    *distance = (float)raw_distance * 0.1f; // Example scaling

    return 0;
}

// Log distance to file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(fp, "%s, %.2f cm\n", timestamp, distance);
    fclose(fp);

    return 0;
}

// Trigger GPIO alert
void trigger_alert(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        gpioDelay(500 * 1000);   // Wait 500ms
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

