#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_distance(time_t timestamp, int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Check model ID
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_MODEL_ID, 0); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to model ID register: %s\n", strerror(errno));
        return -1;
    }
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID register: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to reset register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous ranging
    status = i2cWriteByteData(i2c_handle, 0x007, 0x01); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to start ranging register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for ranging to start
    int timeout = 0;
    while (1) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x00); // Dummy write to set register pointer
        if (status < 0) {
            fprintf(stderr, "Error writing to sysrange start register: %s\n", strerror(errno));
            return -1;
        }
        int sysrange_start = i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START);
        if (sysrange_start < 0) {
            fprintf(stderr, "Error reading sysrange start register: %s\n", strerror(errno));
            return -1;
        }
        if ((sysrange_start & 0x01) == 0) break;
        gpioDelay(1); // Wait 1 ms
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Timeout waiting for ranging to start\n");
            return -1;
        }
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    uint8_t data[2];

    // Read distance data
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to result range status register: %s\n", strerror(errno));
        return -1;
    }
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (data[0] << 8) | data[1];

    return distance;
}

// Log distance to CSV file
void log_distance(time_t timestamp, int distance) {
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print parking guidance message
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
