    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance, frequency;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Map distance to blink frequency
            frequency = map_distance_to_frequency(distance);

            // Blink LED
            blink_led(frequency);

            // Log data
            clock_gettime(CLOCK_REALTIME, &ts);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

