int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ch201_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

