int read_distance(float *distance) {
    char buf[2];
    int result;

    // Read 2 bytes from register 0x00 (example, adjust as needed)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert raw distance to millimeters (example conversion, adjust as needed)
    *distance = (float)raw_distance * 0.1; // Example: 0.1 mm per unit

    return 0;
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    // Clamp distance to the defined range
    if (distance < config.distance_min) {
        distance = config.distance_min;
    } else if (distance > config.distance_max) {
        distance = config.distance_max;
    }

    // Linear mapping
    frequency = config.blink_freq_max - (distance - config.distance_min) * (config.blink_freq_max - config.blink_freq_min) / (config.distance_max - config.distance_min);

    return frequency;
}

// Blink LED
void blink_led(float frequency) {
    static int led_state = 0; // 0 = off, 1 = on
    static struct timespec last_change_time;
    struct timespec current_time;
    long elapsed_ns;

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    elapsed_ns = (current_time.tv_sec - last_change_time.tv_sec) * 1000000000L + (current_time.tv_nsec - last_change_time.tv_nsec);

    if (led_state == 0) {
        // Turn LED on
        gpioWrite(config.led_gpio, 1);
        led_state = 1;
        last_change_time = current_time;
    } else {
        // Turn LED off
        gpioWrite(config.led_gpio, 0);
        led_state = 0;
        last_change_time = current_time;
    }

    // Wait for the next half-cycle
    gpioDelay((int)((1.0 / frequency) * 500000.0)); // Convert Hz to us, half cycle
}

// Log data to stdout
void log_data(float distance, float frequency) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld,%.2f,%.2f\n", ts.tv_sec, ts.tv_nsec, distance, frequency);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

