#define DISTANCE_REG 0x00
#define DISTANCE_CM 0x00 // Register to read distance from
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_distance(uint16_t *distance);
char* get_timestamp();
int log_data(const char *timestamp, uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    char *log_file_path;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance data
int read_distance(uint16_t *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Get timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(const char *timestamp, uint16_t distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx75030_address = MLX75030_ADDR,
        .log_file_path = "distance_log.csv"
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;
        int retry = 0;
        int read_result = -1;

        // Retry loop for reading distance
        while (retry < RETRY_COUNT && read_result < 0) {
            if (trigger_measurement() != 0) {
                fprintf(stderr, "Error triggering measurement, retrying...\n");
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            gpioDelay(10000); // Delay 10ms for measurement to complete

            read_result = read_distance(&distance);
            if (read_result < 0) {
                fprintf(stderr, "Error reading distance, retrying...\n");
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            } else {
                // Data read successfully, break the retry loop
                break;
            }
            retry++;
        }

        if (read_result == 0) {
            // Get timestamp
            char *timestamp = get_timestamp();

            // Log data
            if (log_data(timestamp, distance) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sampling interval
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

