// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables for debouncing
static volatile unsigned long last_change_time_1 = 0;
static volatile unsigned long last_change_time_2 = 0;

// Global variable for the log file
