            last_change_time_1 = current_time;
        } else if (sensor_1_value == 1 && (current_time - last_change_time_1) > (DEBOUNCE_TIME * 1000)) {
            log_event(1, "CLEARED");
            last_change_time_1 = current_time;
        }

        // Read sensor 2
        int sensor_2_value = read_sensor(SENSOR_2_GPIO);
        current_time = gpioTick();

        // Check for state change and debounce
        if (sensor_2_value == 0 && (current_time - last_change_time_2) > (DEBOUNCE_TIME * 1000)) {
            log_event(2, "DETECTED");
            last_change_time_2 = current_time;
        } else if (sensor_2_value == 1 && (current_time - last_change_time_2) > (DEBOUNCE_TIME * 1000)) {
            log_event(2, "CLEARED");
            last_change_time_2 = current_time;
        }

        // Delay for 10 milliseconds
        gpioDelay(10);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop is ever modified.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

