#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int trigger_measurement(int fd);
int wait_for_data_ready(int fd, int timeout_ms);
int read_distance(int fd, uint16_t *distance);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(const char* timestamp, int distance);
void signal_handler(int sig);

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Trigger measurement function
int trigger_measurement(int fd) {
    return i2c_write_reg(fd, MEAS_TRIGGER, 0x01);
}

// Wait for data ready function
int wait_for_data_ready(int fd, int timeout_ms) {
    uint8_t status;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 1000000; // 1 ms

    for (int i = 0; i < timeout_ms; ++i) {
        if (i2c_read_reg(fd, MEAS_STATUS, &status) == 0) {
            if (status & 0x01) {
                return 0; // Data ready
            }
        } else {
            return -1; // Error reading status
        }
        nanosleep(&ts, NULL);
    }
    fprintf(stderr, "Timeout waiting for data ready\n");
    return -1; // Timeout
}

// Read distance function
int read_distance(int fd, uint16_t *distance) {
    uint8_t high, low;

    if (i2c_read_reg(fd, DIST_HIGH, &high) != 0) return -1;
    if (i2c_read_reg(fd, DIST_LOW, &low) != 0) return -1;

    *distance = (high << 8) | low;
    return 0;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S%z", tm_info);
    return timestamp_str;
}

// Log data function
int log_data(const char* timestamp, int distance) {
    if (csv_file == NULL) {
        fprintf(stderr, "Error: CSV file not opened\n");
        return -1;
    }

    fprintf(csv_file, "%s,%d\n", timestamp, distance);
    fflush(csv_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    char timestamp_str[32];
    uint16_t distance;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
        } else {
            // Wait for data ready
            if (wait_for_data_ready(i2c_fd, TIMEOUT_MS) == 0) {
                // Read distance
                if (read_distance(i2c_fd, &distance) == 0) {
                    // Get timestamp
                    get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

                    // Log data
                    if (log_data(timestamp_str, distance) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error reading distance\n");
                }
            } else {
                fprintf(stderr, "Error waiting for data ready\n");
            }
        }

        // Sleep for sampling interval
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_fd);
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }

    return 0;
}

