        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
        } else {
            // Wait for data ready
            if (wait_for_data_ready(i2c_fd, TIMEOUT_MS) == 0) {
