#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance data (replace with actual register address)
#define DISTANCE_REG 0x00 // Example register address

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    int distance_register;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize_i2c(int i2c_bus, int mlx75030_address) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(i2c_bus, mlx75030_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance data from the sensor with retries
int read_distance(int i2c_handle, int reg_addr, uint16_t *distance) {
    int retries = 3;
    int result;
    char buf[2];

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);
        if (result == 2) {
            *distance = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Failure
}

// Function to log the distance data with a timestamp
void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("%ld ms: Distance = %u mm\n", milliseconds, distance);
}

// Function to close the I2C connection and terminate pigpio
void cleanup(int i2c_handle) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, MLX75030_ADDR) != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("MLX75030 ToF sensor data acquisition started...\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;

        if (read_distance(i2c_handle, DISTANCE_REG, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup(i2c_handle);
    return 0;
}

