#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_SYSRANGE_START 0x0009
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0046
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init();
int vl53l4cx_read_distance(uint16_t *distance);
void signal_handler(int signal);

// Helper function to read a byte from a register
int i2c_read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register value\n");
        return -1;
    }
    return 0;
}

// Helper function to write a byte to a register
int i2c_write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg >> 8; // MSB of register address
    buf[1] = reg & 0xFF; // LSB of register address
    char data[2];
    data[0] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for write\n");
        return -1;
    }
    if (i2cWriteDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error writing register value\n");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init() {
    // Soft reset
    if (i2c_write_register(i2c_handle, 0x7FFF, 0x00) != 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Start ranging
    if (i2c_write_register(i2c_handle, VL53L4CX_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int vl53l4cx_read_distance(uint16_t *distance) {
    uint8_t range_status;
    uint8_t high_byte, low_byte;

    // Check interrupt status
    if (i2c_read_register(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    if (range_status & 0x01) {
        // Read distance data
        if (i2c_read_register(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &high_byte) != 0) {
            fprintf(stderr, "Error: Failed to read high byte of distance\n");
            return -1;
        }
        if (i2c_read_register(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &low_byte) != 0) {
            fprintf(stderr, "Error: Failed to read low byte of distance\n");
            return -1;
        }

        *distance = (high_byte << 8) | low_byte;
        return 0;
    } else {
        return -1; // No interrupt
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init() != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    struct timespec ts;
    char timestamp[30];

    while (!terminate) {
        // Read distance
        if (vl53l4cx_read_distance(&distance) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Format timestamp
                struct tm tm_info;
                localtime_r(&ts.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                // Log distance
                printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error: Failed to get timestamp\n");
            }
        } else {
            // No interrupt, skip
        }

        gpioDelay(500000); // Wait 500 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

