#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE -90.0        // degrees
#define MAX_ANGLE 90.0         // degrees

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_data(float distance, float angle);
float measure_distance();
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Stop the servo
    set_servo_angle(0.0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log data to a file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // cm

    return distance;
}

// Function to map distance to servo angle
float map_distance_to_angle(float distance) {
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    return angle;
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    // Map angle to pulse width (1ms - 2ms)
    int pulse_width = (int)((angle + 90.0) / 180.0 * 1000.0 + 1000.0); // Map -90 to 90 to 1000 to 2000
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Distance measurement failed or timed out.\n");
            log_data(-1.0, -1.0); // Log error values
        }

        gpioDelay(200); // 200 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(0.0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

