// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 1234
#define MESSAGE_QUEUE_SIZE 16
#define MESSAGE_QUEUE_FLAG 0666
#define MESSAGE_QUEUE_MAX_MESSAGES 10

// VL53L1X Register Addresses
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message Queue Structure
typedef struct {
    long mtype; // Message type (must be > 0)
    int distance;
} message_t;

// Global Variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_buzzer(int distance);
void log_distance(int distance);
void signal_handler(int signal);
int i2c_write_byte_data(int handle, int reg, int data);
int i2c_read_byte_data(int handle, int reg);

// I2C Write Function with Error Handling
int i2c_write_byte_data(int handle, int reg, int data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: reg=0x%02X, data=0x%02X, error=%d\n", reg, data, result);
        return -1;
    }
    return 0;
}

// I2C Read Function with Error Handling
int i2c_read_byte_data(int handle, int reg) {
