// Read Distance Function
int read_distance(int *distance) {
    int ready = 0;
    int attempts = 0;
    int max_attempts = 10; // Limit the number of attempts

    while (!ready && attempts < max_attempts) {
        int status = i2c_read_byte_data(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading range status, attempt %d\n", attempts + 1);
            attempts++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        ready = (status & 0x01) != 0;
        gpioDelay(1000); // Wait 1ms
        attempts++;
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for data ready after %d attempts\n", max_attempts);
        return -1;
    }

    int high_byte = i2c_read_byte_data(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    int low_byte = i2c_read_byte_data(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

    if (high_byte < 0 || low_byte < 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;
    return 0;
}

// Control Buzzer Function
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

// Log Distance Function
void log_distance(int distance) {
    message_t msg;
    msg.mtype = 1; // Message type
    msg.distance = distance;

    if (msgsnd(message_queue_id, &msg, sizeof(message_t) - sizeof(long), 0) == -1) {
        perror("msgsnd failed");
    }
}

// Signal Handler Function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Create message queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, MESSAGE_QUEUE_FLAG | MESSAGE_QUEUE_SIZE);
    if (message_queue_id == -1) {
        perror("msgget failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (program_running) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_buzzer(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(50000); // 50ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
    msgctl(message_queue_id, IPC_RMID, NULL); // Remove message queue

    return 0;
}

