// I2C Write Function with Error Handling
int i2c_write_byte_data(int handle, int reg, int data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: reg=0x%02X, data=0x%02X, error=%d\n", reg, data, result);
        return -1;
    }
    return 0;
}

// I2C Read Function with Error Handling
