#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define BUZZER_THRESHOLD 30.0  // cm
#define BUZZER_DURATION 1000   // ms

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;
volatile int program_running = 1;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
float calculateDistance(int start_tick, int end_tick);
void displayDistance(float distance);
void activateBuzzer();
void deactivateBuzzer();
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate echo start received
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Indicate echo end received
    }
}

// Function to calculate distance from pulse width
float calculateDistance(int start_tick, int end_tick) {
    int pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        // Handle tick wraparound
        pulse_width += 0xFFFFFFFF; // Add maximum 32-bit value
    }

    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to display the distance on the console
void displayDistance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Function to activate the buzzer
void activateBuzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
}

// Function to deactivate the buzzer
void deactivateBuzzer() {
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    deactivateBuzzer(); // Ensure buzzer is off
    gpioTerminate();    // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    float distance;
    int echo_timeout = 0;

    while (program_running) {
        triggerSensor(); // Send trigger pulse

        echo_start_tick = 0; // Reset echo start time
        echo_end_tick = 0;   // Reset echo end time
        echo_received = 0;   // Reset echo received flag
        echo_timeout = 0;

        gpioDelay(10); // Wait for echo

        // Check for timeout
        while (!echo_received && !echo_timeout) {
            if (echo_start_tick == 0 && gpioRead(ECHO_PIN) == 1) {
                echo_start_tick = gpioTick();
            }
            if (echo_start_tick != 0 && gpioRead(ECHO_PIN) == 0) {
                echo_end_tick = gpioTick();
                echo_received = 1;
            }
            if (echo_start_tick != 0 && gpioTick() - echo_start_tick > TIMEOUT_US) {
                echo_timeout = 1;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (echo_timeout) {
            fprintf(stderr, "Timeout waiting for echo\n");
            displayDistance(-1.0); // Indicate timeout
        } else {
            distance = calculateDistance(echo_start_tick, echo_end_tick);

            if (distance < 2.0 || distance > 400.0) {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
                displayDistance(-2.0); // Indicate invalid reading
            } else {
                displayDistance(distance);

                if (distance < BUZZER_THRESHOLD) {
                    activateBuzzer();
                } else {
                    deactivateBuzzer();
                }
            }
        }

        gpioDelay(100); // Delay between readings
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

