                displayDistance(-2.0); // Indicate invalid reading
            } else {
                displayDistance(distance);

                if (distance < BUZZER_THRESHOLD) {
                    activateBuzzer();
                } else {
                    deactivateBuzzer();
                }
            }
        }

        gpioDelay(100); // Delay between readings
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
