#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0041
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// VL53L1X initialization sequence (Example - adjust based on datasheet)
const uint8_t vl53l1x_init_data[] = {
    0x00, 0x01, // Example register and value
    0x01, 0x02, // Example register and value
    0x02, 0x03  // Example register and value
};

// VL53L1X initialization function
int vl53l1x_init() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
        log_event("Error: VL53L1X software reset failed");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Check device ID (example)
    int device_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (device_id < 0) {
        log_event("Error: VL53L1X device ID read failed");
        return -1;
    }
    if (device_id != 0xEA) {
        log_event("Error: VL53L1X device ID mismatch");
        return -1;
    }

    // Write initialization data (example)
    for (size_t i = 0; i < sizeof(vl53l1x_init_data) / 2; ++i) {
        if (i2cWriteByteData(i2c_handle, vl53l1x_init_data[2 * i], vl53l1x_init_data[2 * i + 1]) < 0) {
            log_event("Error: VL53L1X initialization write failed");
            return -1;
        }
    }

    // Start ranging (example)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x02) < 0) {
        log_event("Error: VL53L1X start ranging failed");
        return -1;
    }

    log_event("VL53L1X initialized successfully");
    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance() {
    int distance = -1;
    int retries = 3;

    while (retries > 0) {
        // Read range status
        int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            log_event("Error: VL53L1X range status read failed");
            retries--;
            gpioDelay(10000); // Wait 10ms
            continue;
        }

        // Read distance
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            log_event("Error: VL53L1X distance read failed");
            retries--;
            gpioDelay(10000); // Wait 10ms
            continue;
        }

        // Check for valid range
        if ((range_status & 0x1F) == 0) { // Check first 5 bits
            break; // Valid range
        } else {
            log_event("Error: VL53L1X invalid range");
            retries--;
            gpioDelay(10000); // Wait 10ms
        }
    }

    if (retries == 0) {
        log_event("Error: VL53L1X read distance failed after multiple retries");
        return -1;
    }

    return distance;
