    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: I2C open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (vl53l1x_init() < 0) {
        log_event("Error: VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
