    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_event("Error: MQTT mosquitto_new failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_event("Error: MQTT connect failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_state = CLOSE_ANGLE; // Initial state: closed
    while (!terminate) {
        int distance = vl53l1x_read_distance();
        if (distance > 0) {
            char log_message[100];
            sprintf(log_message, "Distance: %d mm", distance);
            log_event(log_message);

            if (distance < DISTANCE_THRESHOLD && gate_state == CLOSE_ANGLE) {
                servo_open();
                gate_state = OPEN_ANGLE;
            } else if (distance > DISTANCE_THRESHOLD * 2 && gate_state == OPEN_ANGLE) {
                servo_close();
                gate_state = CLOSE_ANGLE;
            }
        } else {
            log_event("Error: VL53L1X read failed");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated");
    return 0;
}

