#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343  // cm/us
#define MIN_PULSE_WIDTH 100    // microseconds
#define MAX_PULSE_WIDTH 30000  // microseconds
#define TIMEOUT 60             // milliseconds
#define MEASUREMENT_INTERVAL 200 // milliseconds

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void log_distance(double distance);
void signal_handler(int signal);
char* iso8601_timestamp();

// Function to generate an ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        pulse_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        pulse_end = tick;
        pulse_valid = 1; // Set validity flag on falling edge
    }
}

// Function to log distance to file
void log_distance(double distance) {
    char *timestamp = iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Initialize TRIG pin to LOW
    gpioWrite(TRIG_PIN, 0);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        pulse_start = 0; // Reset pulse start time
        pulse_end = 0;   // Reset pulse end time
        pulse_valid = 0; // Reset pulse validity

        gpioDelay(TIMEOUT); // Wait for echo or timeout

        if (pulse_valid) {
            // Calculate pulse duration, accounting for wraparound
            int pulse_duration = pulse_end - pulse_start;
            if (pulse_end < pulse_start) {
                pulse_duration = (0xFFFFFFFF - pulse_start) + pulse_end + 1; // Handle wraparound
            }

            // Validate pulse width
            if (pulse_duration >= MIN_PULSE_WIDTH && pulse_duration <= MAX_PULSE_WIDTH) {
                // Calculate distance
                double distance = (double)pulse_duration * SPEED_OF_SOUND / 2.0;

                // Log distance
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                char *timestamp = iso8601_timestamp();
                fprintf(stderr, "%s,Invalid pulse width: %d microseconds\n", timestamp, pulse_duration);
                if (log_file != NULL) {
                    fprintf(log_file, "%s,Invalid pulse width: %d microseconds\n", timestamp, pulse_duration);
                    fflush(log_file);
                }
                free(timestamp);
            }
        } else {
            char *timestamp = iso8601_timestamp();
            fprintf(stderr, "%s,Timeout waiting for echo\n", timestamp);
            if (log_file != NULL) {
                fprintf(log_file, "%s,Timeout waiting for echo\n", timestamp);
                fflush(log_file);
            }
            free(timestamp);
        }

        gpioDelay(MEASUREMENT_INTERVAL); // Wait before next measurement
    }

    // Clean up
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    printf("Ultrasonic distance measurement stopped.\n");

    return 0;
}

