#define INTERRUPT_PIN 24

// Define VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// Define distance thresholds (in cm)
#define OPEN_THRESHOLD 50
#define CLOSE_THRESHOLD 60

// Define servo pulse widths (in microseconds)
#define SERVO_OPEN 1500
#define SERVO_CLOSED 1000

// Define VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile int gate_open = 0; // 0 = closed, 1 = open
volatile int object_detected = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_vl53l1x();
int read_distance();
void control_gate(int open);
void log_data(int gate_state, int distance);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Example: Check sensor model ID (adjust based on datasheet)
    char model_id;
    int result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1);
    if (result != 1) {
        fprintf(stderr, "VL53L1X model ID read failed: %d\n", result);
        return 1;
    }

    // Example: Expected model ID (adjust based on datasheet)
    if (model_id != 0xEACC) {
        fprintf(stderr, "VL53L1X model ID mismatch: 0x%02X\n", model_id);
        return 1;
    }

    // Add more initialization steps here based on the VL53L1X datasheet
    // For example, writing configuration registers to set timing budget, inter-measurement period, etc.

    return 0;
}

