    char data[2];
    int distance;

    // Example: Read distance (adjust based on datasheet)
    int result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (result != 2) {
        fprintf(stderr, "Distance read failed: %d\n", result);
        return -1; // Indicate error
    }

    distance = (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit distance value

    return distance;
}

