    if (open) {
        gpioPWM(SERVO_PIN, SERVO_OPEN); // Open the gate
        gate_open = 1;
        object_detected = 1; // Set object detected flag
    } else {
        gpioPWM(SERVO_PIN, SERVO_CLOSED); // Close the gate
        gate_open = 0;
        object_detected = 0; // Clear object detected flag
    }
}

