void log_data(int gate_state, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Gate: %s, Distance: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            gate_state ? "Open" : "Closed", distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    int distance = read_distance();
    if (distance > 0) {
        if (distance < OPEN_THRESHOLD && !gate_open) {
            control_gate(1); // Open the gate
        } else if (distance > CLOSE_THRESHOLD && gate_open) {
            control_gate(0); // Close the gate
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(SERVO_PIN, 0); // Stop PWM signal
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (init_pigpio()) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c()) {
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x()) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Initialize servo to closed position
    gpioPWM(SERVO_PIN, SERVO_CLOSED);

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL);

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read distance and log data
        int distance = read_distance();
        if (distance > 0) {
            log_data(gate_open, distance);
        } else {
            log_data(gate_open, -1); // Log error
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(100); // 100 ms
    }

    return 0;
}

