#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

// Define VL53L1X register addresses
#define VL53L1X_REG_SYSRANGE_START 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile int distance = 0; // Distance in mm
volatile int motor_state = 0; // 0: stopped, 1: forward, 2: backward

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void trigger_isr(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// VL53L1X initialization function
int vl53l1x_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error: Soft reset failed (status = %d)\n", status);
        return -1;
    }
    gpioDelay(1); // Wait 1 ms

    // Start measurement
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status != 0) {
        fprintf(stderr, "Error: Start measurement failed (status = %d)\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    int status;
    int range_status;
    int retries = 0;
    int delay_ms = 10;

    // Poll until data is ready
    do {
        range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error: Failed to read range status (status = %d)\n", range_status);
            return -1;
        }
        if (!(range_status & 0x01)) {
            gpioDelay(1); // Wait 1 ms
        }
        retries++;
        if (retries > 100) {
            fprintf(stderr, "Error: Timeout waiting for data ready\n");
            return -1;
        }
    } while (!(range_status & 0x01));

    // Read distance
    status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read distance (status = %d)\n", status);
        return -1;
    }

    *distance = status;
    return 0;
}

// Motor forward function
void motor_forward() {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    motor_state = 1;
    printf("Motor: Forward\n");
}

// Motor backward function
void motor_backward() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    motor_state = 2;
    printf("Motor: Backward\n");
}

// Motor stop function
void motor_stop() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    motor_state = 0;
    printf("Motor: Stopped\n");
}

// Trigger ISR function
void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    int status;
    int distance_mm;

    // Read distance
    status = vl53l1x_read_distance(&distance_mm);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to read distance in ISR\n");
        return;
    }

    distance = distance_mm;

    // Control motor based on distance
    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
        motor_backward();
    } else {
        motor_stop();
    }

    printf("Distance: %d mm, Motor: %s\n", distance, motor_state == 0 ? "Stopped" : (motor_state == 1 ? "Forward" : "Backward"));
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    // Set up ISR for rising edge on TRIGGER_PIN
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        gpioDelay(100); // Delay 100 ms
    }

    return 0;
}

