#define LED2 18
#define LED3 27
#define LED4 22

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_ELECONFIG0 0x5E
#define MPR121_ELECONFIG1 0x5F

// Define proximity threshold
#define PROXIMITY_THRESHOLD 1

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

