int mpr121_reset() {
    char buf[2];
    buf[0] = 0x80; // Reset register address
    buf[1] = 0x63; // Reset value

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete
    return 0;
}

// Function to initialize the MPR121
