// Read a register from the MPR121
int read_mpr121_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register to the MPR121
int write_mpr121_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Read the electrode status from the MPR121
int read_mpr121_electrode_status() {
    int status = read_mpr121_register(0x00);
    if (status < 0) return -1;
    return status;
}

// Callback function for proximity detection
void proximity_detected_callback() {
    printf("Proximity detected on electrode 0!\n");
    log_event();
    gpioWrite(GPIO_LED, 1); // Turn on LED
    gpioDelay(1000);        // Wait for 1 second
    gpioWrite(GPIO_LED, 0); // Turn off LED
}

// Log the event to a file
void log_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

