    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 27 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int status = read_mpr121_electrode_status();
        if (status < 0) {
            fprintf(stderr, "Error reading electrode status\n");
            break;
        }

        if (status & 0x01) { // Check if electrode 0 is touched
            proximity_detected_callback();
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
