#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width with timeout
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for rising edge with timeout
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (start_time - end_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1; // Timeout
        }
    }

    // Wait for falling edge with timeout
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (end_time - start_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return ((double)pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
}

// Log the distance to a file with ISO 8601 timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        double distance = 0.0;
        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);

            // Validate the distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Sensor absent or timeout\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

