// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define I2C_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
void control_gate(int distance);
void log_event(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_RANGING 0x0015
#define VL53L1X_REG_DISTANCE_MSB 0x0089
#define VL53L1X_REG_DISTANCE_LSB 0x008A

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_event("Error writing to I2C device.");
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        log_event("Error writing register address for read.");
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        log_event("Error reading from I2C device.");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two VL53L1X registers
int read_16bit(int handle, uint8_t reg, uint16_t *value) {
    uint8_t msb, lsb;

    if (read_register(handle, reg, &msb) != 0) return -1;
    if (read_register(handle, reg + 1, &lsb) != 0) return -1;

    *value = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is initially closed

