    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Control the gate
            control_gate(distance);

            // Log the distance
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %d cm, Gate: %s", distance, gpioRead(GATE_GPIO) ? "OPEN" : "CLOSED");
            log_event(log_message);
        } else {
            log_event("Error reading distance.");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    uint8_t model_id;

    // Check model ID
    if (read_register(i2c_handle, VL53L1X_REG_MODEL_ID, &model_id) != 0) {
        log_event("Error reading model ID.");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        log_event("Incorrect model ID.");
        return -1;
    }
    char log_message[50];
    snprintf(log_message, sizeof(log_message), "Model ID: 0x%02X", model_id);
    log_event(log_message);

    // Set ranging mode to short
    if (write_register(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00) != 0) {
        log_event("Error setting ranging mode.");
        return -1;
    }
    log_event("Ranging mode set to short.");

    // Start ranging
    if (write_register(i2c_handle, VL53L1X_REG_START_RANGING, 0x01) != 0) {
        log_event("Error starting ranging.");
        return -1;
    }
    log_event("Ranging started.");

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    uint16_t raw_distance;

    if (read_16bit(i2c_handle, VL53L1X_REG_DISTANCE_MSB, &raw_distance) != 0) {
        log_event("Error reading distance data.");
        return -1;
    }

    *distance = (int)(raw_distance / 10); // Convert mm to cm
    return 0;
}

// Control the gate based on distance
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GATE_GPIO, 1); // Open the gate
        gate_open = 1;
        log_event("Gate opened.");
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GATE_GPIO, 0); // Close the gate
        gate_open = 0;
        log_event("Gate closed.");
    }
}

// Log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

