#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define SERVO_MIN_PULSE 500    // Minimum pulse width (us)
#define SERVO_MAX_PULSE 2500   // Maximum pulse width (us)
#define SERVO_CENTER_ANGLE 90  // Center angle (degrees)
#define SERVO_CENTER_PULSE (SERVO_MIN_PULSE + (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 2) // Center pulse width (us)
#define SERVO_RANGE 180        // Servo range (degrees)
#define SERVO_RANGE_PULSE (SERVO_MAX_PULSE - SERVO_MIN_PULSE) // Servo range (us)
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int pulse_width_history[MOVING_AVG_SIZE];
int pulse_width_history_index = 0;
int pulse_width_count = 0;
int echo_start_tick = 0;
int echo_end_tick = 0;
int echo_valid = 0;

// Function prototypes
void triggerSensor();
double measureDistance();
double calculateDistance(int pulse_width);
double movingAverage(double new_value);
double mapDistanceToAngle(double distance);
int setServoAngle(double angle);
void logData(double distance, double angle);
void echo_callback(int gpio, int level, uint32_t tick, void *user);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measureDistance() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_valid = 0;

    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    triggerSensor();

    // Wait for timeout or echo
    int timeout_count = 0;
    while (!echo_valid && timeout_count < TIMEOUT_US && program_running) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback

    if (!echo_valid) {
        return -1.0; // Indicate invalid reading
    }

    int pulse_width = echo_end_tick - echo_start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick wrap-around
    }

    return calculateDistance(pulse_width);
}

// Function to calculate distance from pulse width
double calculateDistance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to calculate moving average
double movingAverage(double new_value) {
    pulse_width_history[pulse_width_history_index] = new_value;
    pulse_width_history_index = (pulse_width_history_index + 1) % MOVING_AVG_SIZE;
    if (pulse_width_count < MOVING_AVG_SIZE) {
        pulse_width_count++;
    }

    double sum = 0.0;
    for (int i = 0; i < pulse_width_count; i++) {
        sum += pulse_width_history[i];
    }
    return sum / pulse_width_count;
}

// Function to map distance to servo angle using a logarithmic mapping
double mapDistanceToAngle(double distance) {
    // Define the distance range and angle range
    double min_distance = 2.0;
    double max_distance = 400.0;
    double min_angle = 0.0;
    double max_angle = 180.0;

    // Ensure distance is within the valid range
    if (distance < min_distance) {
        distance = min_distance;
    } else if (distance > max_distance) {
        distance = max_distance;
    }

    // Apply logarithmic mapping
    double angle = (log10(distance) - log10(min_distance)) / (log10(max_distance) - log10(min_distance)) * (max_angle - min_angle) + min_angle;

    return angle;
}

// Function to set the servo angle
int setServoAngle(double angle) {
    // Convert angle to pulse width
    int pulse_width = SERVO_MIN_PULSE + (int)((angle / 180.0) * SERVO_RANGE_PULSE);

    // Set the servo pulse width
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to log data to a CSV file
void logData(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset echo_valid flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set echo_valid flag
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the servo
    gpioServo(SERVO_PIN, 0); // Disable servo signal

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize pulse width history
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        pulse_width_history[i] = 0;
    }
    pulse_width_count = 0;

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register signal handler
    signal(SIGINT, signalHandler);

    // Main loop
    while (program_running) {
        double distance = measureDistance();

        if (distance > 0) {
            double avg_distance = movingAverage(distance);
            double angle = mapDistanceToAngle(avg_distance);

            if (setServoAngle(angle) == 0) {
                logData(avg_distance, angle);
            } else {
