        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup (should not reach here if signal handler is working)
    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

