#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define GPIO_INTERRUPT 27
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_proximity(int *proximity);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_INTERRUPT, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up\n");
        return -1;
    }
    return 0;
}

// Function to initialize the sensor (example configuration)
int init_sensor() {
    // Example: Write a configuration register (replace with actual Si1102 config)
    char config_data[2] = {0x10, 0x01}; // Example register and value
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read proximity value from the sensor
int read_proximity(int *proximity) {
    char data[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG_LOW, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }

    *proximity = (data[0] << 8) | data[1];
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;
    if (read_proximity(&proximity) == 0) {
        const char *status = (proximity > threshold) ? "ALERT" : "SAFE";
        log_data(proximity, status);
    } else {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
    }
}

// Function to log data to file
void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                SI1102_ADDR = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

