    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                SI1102_ADDR = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

