// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms timeout

// Global variables
static volatile int running = 1;
static volatile int echo_start = 0;
static volatile int echo_end = 0;

// Function prototypes
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
float map_distance_to_frequency(float distance);
void set_pwm_frequency(float frequency);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
    } else if (level == 0) {
        echo_end = tick;
    }
}

// Function to calculate distance from pulse width
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0; // Indicate timeout
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s
}

// Function to map distance to frequency using a logarithmic formula
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate out-of-range
    }
    return MIN_FREQUENCY * exp((distance - MIN_DISTANCE) / 50.0);
}

// Function to set PWM frequency on the speaker pin
void set_pwm_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        frequency = MIN_FREQUENCY; // Clamp frequency
    }

    int range = 1000000 / frequency; // Calculate PWM range
    gpioPWM(SPEAKER_PIN, 128); // 50% duty cycle (128/255)
    gpioSetPWMrange(SPEAKER_PIN, range);
    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
}

// Cleanup function to stop PWM and terminate pigpio
void cleanup() {
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio
}

