    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set PWM mode to hardware PWM
    gpioSetPWMmode(SPEAKER_PIN, PI_PWM_MODE_MS);

    // Set PWM range and frequency (initial values)
    gpioSetPWMrange(SPEAKER_PIN, 1000000); // Set range to 1 MHz
    gpioSetPWMfrequency(SPEAKER_PIN, 440);  // Set initial frequency to 440 Hz
    gpioPWM(SPEAKER_PIN, 128); // 50% duty cycle

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    float previous_frequency = 440.0; // Initial frequency
    uint32_t pulse_width;

    while (running) {
        // Trigger the ultrasonic sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for echo or timeout
        pulse_width = 0;
        echo_start = 0;
        echo_end = 0;
        gpioDelay(1); // Small delay to allow echo to start

        while (running && echo_end == 0 && gpioTick() - echo_start < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
        }

        if (echo_end == 0) {
            // Timeout occurred
            printf("Timeout waiting for echo\n");
            set_pwm_frequency(previous_frequency); // Keep previous frequency
        } else {
            // Calculate distance
            pulse_width = echo_end - echo_start;
            float distance = calculate_distance(pulse_width);

            if (distance < 0) {
                // Timeout or invalid pulse width
                printf("Invalid distance measurement\n");
                set_pwm_frequency(previous_frequency); // Keep previous frequency
            } else {
                // Map distance to frequency
                float frequency = map_distance_to_frequency(distance);

                if (frequency < 0) {
                    // Out-of-range distance
                    printf("Distance out of range\n");
                    set_pwm_frequency(previous_frequency); // Keep previous frequency
                } else {
                    // Set PWM frequency
                    set_pwm_frequency(frequency);
                    previous_frequency = frequency;
                }
            }
        }

        gpioDelay(50); // Delay between measurements
    }

    return 0;
}

