#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 5.0  // cm
#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200 // Hz
#define MAX_FREQUENCY 2000 // Hz
#define TIMEOUT_US 100000  // 100 ms

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
long getPulseWidth();
float calculateDistance(long pulseWidth);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void echoCallback(int gpio, int level, uint32_t tick);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        pulse_end = tick;
        echo_received = 0; // Reset the flag
    }
}

// Function to measure the pulse width of the echo signal
long getPulseWidth() {
    pulse_start = 0;
    pulse_end = 0;
    echo_received = 0; // Reset the flag before starting measurement

    triggerSensor(); // Send a trigger pulse

    // Wait for the pulse to end or timeout
    int timeout_count = 0;
    while (pulse_end == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (pulse_end == 0) {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1; // Indicate timeout
    }

    long pulseWidth = pulse_end - pulse_start;
    return pulseWidth;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulseWidth) {
    // Speed of sound in air (approx. 343 m/s) and conversion to cm/us
    // distance = (pulseWidth * speed_of_sound) / 2
    // speed_of_sound = 0.0343 cm/us
    // distance = (pulseWidth * 0.0343) / 2
    return (pulseWidth * 0.0343) / 2.0;
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }
    return frequency;
}

// Function to set the buzzer frequency using pigpio
void setBuzzerFrequency(float frequency) {
    int range = 1000000; // Range for hardware PWM
    int dutyCycle = 128; // 50% duty cycle
    gpioHardwarePWM(BUZZER_PIN, (int)frequency, dutyCycle * range / 100); // Set frequency and duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    // Main loop
    while (1) {
        long pulseWidth = getPulseWidth();
        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            float frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            // Handle timeout or error
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }
        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

