#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int pulse_width = gpioRead(ECHO_PIN);

        if (pulse_width < 0) {
            fprintf(stderr, "Error reading echo pin\n");
            gpioDelay(500);
            continue;
        }

        float distance = (float)pulse_width / 2 / 29.1;

        if (distance < 2 || distance > 400) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10) {
                printf(", Too close!");
            }
            printf("\n");
        }

        gpioDelay(500);
    }

    gpioTerminate();
    return 0;
}

