    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for write operation
    tx_buf[1] = value;

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
