#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define SI1175_ADDR 0x60      // Si1175 I2C address
#define ALS_VISIBLE_REG_LOW 0x22 // ALS Visible Low Byte Register
#define ALS_VISIBLE_REG_HIGH 0x23 // ALS Visible High Byte Register
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_fp = NULL; // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_open(const char *bus);
int i2c_close(int fd);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int count);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
  int fd = open(bus, O_RDWR);
  if (fd < 0) {
    fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
    return -1;
  }
  return fd;
}

// I2C close function
int i2c_close(int fd) {
  if (fd >= 0) {
    close(fd);
  }
  return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int count) {
  if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
    return -1;
  }

  if (write(fd, &reg, 1) != 1) {
    fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
    return -1;
  }

  if (read(fd, buf, count) != count) {
    fprintf(stderr, "Error reading bytes: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;

  if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
    return -1;
  }

  if (write(fd, buf, 2) != 2) {
    fprintf(stderr, "Error writing byte: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Read ALS Visible value function
uint16_t read_als_visible(int fd) {
  uint8_t buf[2];
  if (i2c_read_bytes(fd, ALS_VISIBLE_REG_LOW, buf, 2) != 0) {
    fprintf(stderr, "Error reading ALS Visible value\n");
    return 0; // Return 0 on error
  }
  return (uint16_t)((buf[1] << 8) | buf[0]);
}

// Get ISO 8601 timestamp function
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
  time_t timer;
  struct tm *tm_info;

  time(&timer);
  tm_info = gmtime(&timer);

  strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
  return timestamp_str;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, uint16_t als_visible) {
  if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
    fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
  terminate = 1;
}

int main() {
  // Install signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = i2c_open(I2C_BUS);
  if (i2c_fd < 0) {
    return 1;
  }

  // Open log file
  log_fp = fopen(LOG_FILE, "a");
  if (log_fp == NULL) {
    fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    i2c_close(i2c_fd);
    return 1;
  }

  // Write header row if the file is newly created
  fseek(log_fp, 0, SEEK_END);
  long file_size = ftell(log_fp);
  if (file_size == 0) {
    fprintf(log_fp, "timestamp,als_visible\n");
  }
  rewind(log_fp);

  // Main loop
  while (!terminate) {
    // Read ALS Visible value
    uint16_t als_visible = read_als_visible(i2c_fd);

    // Get timestamp
    char timestamp_str[32];
    get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

    // Log data
    if (log_data(log_fp, timestamp_str, als_visible) != 0) {
      fprintf(stderr, "Error logging data\n");
    }

    // Flush the log file to ensure data is written
    fflush(log_fp);

    // Wait for the next sample
    sleep(SAMPLE_INTERVAL_SEC);
  }

  // Cleanup
  i2c_close(i2c_fd);
  if (log_fp != NULL) {
    fclose(log_fp);
  }

  fprintf(stderr, "Program terminated.\n");
  return 0;
}

