#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define RESET_REG 0x30
#define RESET_VALUE 0x01
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x41
#define ALS_LOW_REG 0x22
#define ALS_HIGH_REG 0x23
#define PS1_LOW_REG 0x18
#define PS1_HIGH_REG 0x19
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als(int *als);
int read_ps1(int *ps1);
char* get_timestamp();
int log_data(int als, int ps1);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1120 sensor
int initialize_sensor() {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, RESET_REG, RESET_VALUE);
        if (result == 0) {
            gpioDelay(10); // Wait for reset to complete
            break;
        } else {
            fprintf(stderr, "Error writing to reset register (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset sensor after %d attempts.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id >= 0) {
            if (part_id == PART_ID_VALUE) {
                break;
            } else {
                fprintf(stderr, "Error: Incorrect Part ID (0x%02X, expected 0x%02X) (attempt %d)\n", part_id, PART_ID_VALUE, retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        } else {
            fprintf(stderr, "Error reading part ID (attempt %d): %d\n", retries + 1, part_id);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to verify Part ID after %d attempts.\n", MAX_RETRIES);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

