#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_REG_LSB 0x22
#define AMBIENT_REG_MSB 0x23
#define PROX_REG_LSB 0x24
#define PROX_REG_MSB 0x25
#define LUX_SCALE 0.1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int init_sensor(int fd);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(float lux, int proximity);
void signal_handler(int sig);
char* get_timestamp();

// I2C read function
int i2c_read_reg(int fd, unsigned char reg) {
    int result;
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register and value");
        return -1;
    }

    return 0;
}

// Sensor initialization function
int init_sensor(int fd) {
    int part_id;

    // Read Part ID register
    part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        return -1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error writing to measurement rate register\n");
        return -1;
    }

    return 0;
}

// Sensor data reading function
int read_sensor_data(int fd, float *lux, int *proximity) {
    int ambient_lsb, ambient_msb, prox_lsb, prox_msb;

    ambient_lsb = i2c_read_reg(fd, AMBIENT_REG_LSB);
    ambient_msb = i2c_read_reg(fd, AMBIENT_REG_MSB);
    prox_lsb = i2c_read_reg(fd, PROX_REG_LSB);
    prox_msb = i2c_read_reg(fd, PROX_REG_MSB);

    if (ambient_lsb < 0 || ambient_msb < 0 || prox_lsb < 0 || prox_msb < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine LSB and MSB for ambient light and proximity
    int ambient_raw = (ambient_msb << 8) | ambient_lsb;
    int proximity_raw = (prox_msb << 8) | prox_lsb;

    // Convert ambient light to lux
    *lux = ambient_raw * LUX_SCALE;
    *proximity = proximity_raw;

    return 0;
}

// Data logging function
void log_data(float lux, int proximity) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
    free(timestamp);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Timestamp function
char* get_timestamp() {
    struct timespec ts;
    char *timestamp = malloc(30 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    time_t rawtime = ts.tv_sec;
    struct tm *timeinfo = localtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 30 - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000); // Add milliseconds

    return timestamp;
}

int main() {
    float lux;
    int proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            // Log data
            log_data(lux, proximity);

            // Print data to stdout
            char *timestamp = get_timestamp();
            if (timestamp != NULL) {
                printf("%s,%.2f,%d\n", timestamp, lux, proximity);
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to get timestamp for stdout\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

