        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            // Log data
            log_data(lux, proximity);

            // Print data to stdout
            char *timestamp = get_timestamp();
            if (timestamp != NULL) {
                printf("%s,%.2f,%d\n", timestamp, lux, proximity);
                free(timestamp);
            } else {
