            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

