    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Write initialization sequence
        status = i2cWriteByteData(i2c_handle, 0x07, 0x03);
        if (status < 0) {
            fprintf(stderr, "Error writing to register 0x07: %d\n", status);
