            goto retry;
        }

        status = i2cWriteByteData(i2c_handle, 0x22, 0x49);
        if (status < 0) {
            fprintf(stderr, "Error writing to register 0x22: %d\n", status);
            goto retry;
        }

        status = i2cWriteByteData(i2c_handle, 0x0C, 0x03);
        if (status < 0) {
            fprintf(stderr, "Error writing to register 0x0C: %d\n", status);
            goto retry;
        }

        status = i2cWriteByteData(i2c_handle, 0x0F, 0x0F);
        if (status < 0) {
