        return -1;
    }
    low_byte = status;

    // Read high byte
    status = i2cReadByteData(i2c_handle, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error reading high byte from register 0x17: %d\n", status);
        return -1;
    }
    high_byte = status;

    // Combine bytes into 16-bit unsigned integer
    *proximity = ((unsigned int)high_byte << 8) | low_byte;

    return 0;
}

