#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance();
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance() {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100); // Delay between measurements

        float distance = calculate_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: Could not measure distance\n");
        }

        control_buzzer(distance);
        gpioDelay(1000); // Print distance every second
    }

    return 0;
}

