#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants for servo control
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Constants for distance calculation
#define SOUND_SPEED 34300.0 // cm/s

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo signal timeout (high)\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1.0;
    }

    end_tick = gpioTick();

    // Calculate the pulse width in microseconds
    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SOUND_SPEED / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    // Ensure angle is within valid range
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to calculate servo angle based on distance
int calculateServoAngle(float distance) {
    // Ensure distance is within valid range
    if (distance < 20) distance = 20;
    if (distance > 200) distance = 200;

    // Calculate angle based on linear mapping
    float angle = (200 - distance) / (200 - 20) * 180.0;

    return (int)angle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure distance
        float distance = measureDistance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate servo angle
        int servo_angle = calculateServoAngle(distance);

        // Set servo angle
        setServoAngle(servo_angle);

