#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(float *temperature, float *humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library and opens the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Writes to the Si7005's configuration register
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Reads temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;

    // Read temperature
    result = i2cWriteByte(i2c_handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to write temperature register address: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Read humidity
    result = i2cWriteByte(i2c_handle, HUMID_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to write humidity register address: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    result = i2cReadI2CBlockData(i2c_handle, HUMID_REG, (char *)buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

