#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider to 7 (125 Hz)
    if (i2cWriteByteData(i2c_handle, 0x19, 7) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, 0x1C, 0) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to ±250 deg/s
    if (i2cWriteByteData(i2c_handle, 0x1B, 0) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read MPU-6050 data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14);

    if (result < 0) {
        fprintf(stderr, "Error: Could not read MPU-6050 data (result = %d)\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z  = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

