    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (handle = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
