#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus number
#define I2C_BUS 1

// Command for high repeatability measurement
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC8_POLY 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    uint8_t temp_crc = crc8((uint8_t *)buf, 2);
    uint8_t hum_crc = crc8((uint8_t *)buf + 3, 2);

    if (temp_crc != buf[2] || hum_crc != buf[5]) {
        fprintf(stderr, "CRC checksum failure\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[3] << 8) | buf[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

