#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature(int handle, int reg);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
float read_temperature(int handle, int reg) {
    int raw_data = i2cReadWordData(handle, reg);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature from register 0x%02X: %d\n", reg, raw_data);
        return -1000.0; // Indicate an error
    }
    // Convert raw data to Celsius (see MLX90614 datasheet)
    float temp_celsius = (float)raw_data * 0.02 - 273.15;
    return temp_celsius;
}

// Log temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float ambient_temp = read_temperature(i2c_handle, AMBIENT_TEMP_REG);
        float object_temp = read_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (ambient_temp > -999.0 && object_temp > -999.0) {
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging temperature data.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data. Skipping logging.\n");
        }

        sleep(SLEEP_DURATION);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

