#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x08
#define DATA_LENGTH 9
#define SCALE_FACTOR_PRESSURE 60.0f
#define SCALE_FACTOR_TEMPERATURE 200.0f
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(unsigned char *data);
int validate_crc(const unsigned char *data, int len);
sensor_data_t convert_data(const unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the sensor
int init_sensor() {
    char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for at least 1 ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading from sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Function to convert raw data to physical units
sensor_data_t convert_data(const unsigned char *data) {
    sensor_data_t converted_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    converted_data.pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    converted_data.temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE;

    return converted_data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f,%.2f\n", buf, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC checksums
            if (validate_crc(data, DATA_LENGTH)) {
                // Convert data to physical units
                sensor_data = convert_data(data);

                // Log data
                log_data(sensor_data);

                // Print data to console
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.pressure, sensor_data.temperature);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

