#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40 sensor
int read_sht40(int fd, float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        // Send measurement command
        result = i2c_smbus_write_byte_data(fd, SHT40_ADDR, MEASURE_CMD);
        if (result < 0) {
            perror("Error writing to I2C device");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (at least 10 ms)
        usleep(10000);

        // Read 6 bytes of data
        result = i2c_smbus_read_i2c_block_data(fd, SHT40_ADDR, 6, data);
        if (result < 0) {
            perror("Error reading from I2C device");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // CRC validation
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_temperature = (data[0] << 8) | data[1];
        unsigned int raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
        *humidity = 100.0 * raw_humidity / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after multiple retries\n");
    return -1; // Failure
}

// Function to log data to file
void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(log_fp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

