#define TRIGGER_CMD_MSB 0x21
#define TRIGGER_CMD_LSB 0x96
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_BASE_MS 10
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger continuous measurement
int trigger_measurement() {
    uint8_t cmd[2] = {TRIGGER_CMD_MSB, TRIGGER_CMD_LSB};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (trigger): %d, retry %d\n", result, retries + 1);
            gpioDelay((BACKOFF_BASE_MS * (1 << retries)) * 1000); // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

