#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int command, unsigned short *raw_value);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int command, unsigned short *raw_value) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %s\n", pigpio_error(result));
        return -1;
    }

    // Wait for measurement to complete (up to 20ms)
    gpioDelay(20000); // 20ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data: %s\n", pigpio_error(result));
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert temperature
float convert_temperature(unsigned short raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert humidity
float convert_humidity(unsigned short raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

