    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(gpioInitialise()));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        unsigned short raw_temp, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(TEMP_CMD, &raw_temp) == 0) {
            // Read humidity
            if (read_sensor_data(HUMID_CMD, &raw_humidity) == 0) {
                // Convert data
                temperature = convert_temperature(raw_temp);
                humidity = convert_humidity(raw_humidity);

                // Log data
                log_data(temperature, humidity);
            } else {
                fprintf(stderr, "Error reading humidity\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Wait for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

