#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"
#define SLEEP_DURATION_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, unsigned char *data, int length);
int i2c_read(int fd, unsigned char *data, int length);
int crc8(const unsigned char *data, int len);
int sdp800_read_data(int fd, int *pressure, int *temperature, int *scale_factor);
float convert_pressure(int raw_pressure, int scale_factor);
float convert_temperature(int raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int length) {
    if (write(fd, data, length) != length) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int length) {
    if (read(fd, data, length) != length) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// SDP800 read data function
int sdp800_read_data(int fd, int *pressure, int *temperature, int *scale_factor) {
    unsigned char data[DATA_LENGTH];
    int retries = 3;

    while (retries > 0) {
        if (i2c_read(fd, data, DATA_LENGTH) == 0) {
            // CRC validation
            if (crc8(data, 2) != 0 || crc8(data + 3, 2) != 0 || crc8(data + 6, 2) != 0) {
                fprintf(stderr, "CRC validation failed. Retrying...\n");
                retries--;
                usleep(10000); // 10 ms delay
                continue;
            }

            *pressure = (data[0] << 8) | data[1];
            *temperature = (data[3] << 8) | data[4];
            *scale_factor = (data[6] << 8) | data[7];

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error. Retrying...\n");
            retries--;
            usleep(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "Failed to read data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw pressure to Pa
float convert_pressure(int raw_pressure, int scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Convert raw temperature to °C
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    int pressure, temperature, scale_factor;
    while (program_running) {
        // Trigger measurement
        unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
        if (i2c_write(i2c_fd, command, 2) != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
        } else {
            usleep(45000); // Wait 45 ms

            // Read data
            if (sdp800_read_data(i2c_fd, &pressure, &temperature, &scale_factor) == 0) {
                // Convert data
                float pressure_pa = convert_pressure(pressure, scale_factor);
                float temperature_c = convert_temperature(temperature);

                // Log data
                if (log_data(log_file, pressure_pa, temperature_c) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data.\n");
            }
        }

        usleep(SLEEP_DURATION_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

