#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define SAMPLE_INTERVAL_SEC 5
#define CRC_ERROR_TEMP -999.0
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
float convert_to_celsius(uint16_t raw_temp);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return -45.0 + 175.0 * ((float)raw_temp / 65535.0);
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen("enclosure_temp_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_log_file == NULL) {
        error_log_file = fopen("error_log.txt", "a");
        if (error_log_file == NULL) {
            perror("Error opening error log file");
            return -1;
        }
    }

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and files
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[3];
    uint16_t raw_temperature;
    float temperature;

    printf("Starting temperature monitoring...\n");

    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            log_error("Failed to send measurement command");
        } else {
            // Wait for conversion (at least 15 ms)
            gpioDelay(15000); // 15 ms

            // Read sensor data
            if (read_sensor_data(sensor_data) == 0) {
                // Calculate CRC
                uint8_t crc = calculate_crc(sensor_data, 2);

                // Validate CRC
                if (crc == sensor_data[2]) {
                    // Convert to Celsius
                    raw_temperature = (sensor_data[0] << 8) | sensor_data[1];
                    temperature = convert_to_celsius(raw_temperature);

                    // Log temperature
                    if (log_temperature(temperature) != 0) {
                        log_error("Failed to log temperature");
                    }
                } else {
                    log_error("CRC validation failed");
                    temperature = CRC_ERROR_TEMP;
                }
            } else {
                log_error("Failed to read sensor data");
                temperature = CRC_ERROR_TEMP;
            }
        }

        // Sleep for the specified interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

