#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define SLEEP_DURATION 5 // seconds

// CRC-8 parameters
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(int bus, int addr);
int sht40_read_data(int fd, unsigned char *data);
int crc8(const unsigned char *data, int len);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(int bus, int addr) {
    int fd = i2cOpen(bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", fd);
        return -1;
    }
    return fd;
}

// SHT40 read data function
int sht40_read_data(int fd, unsigned char *data) {
    unsigned char cmd = MEASURE_CMD;
    if (i2cWriteDevice(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    usleep(8500); // Wait for measurement (8.5 ms)

    if (i2cReadDevice(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Humidity conversion function
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Data logging function
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup I2C
    i2c_fd = i2c_setup(I2C_BUS, SHT40_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    unsigned char data[6];
    unsigned short raw_temp, raw_humidity;
    float temperature, humidity;
    int crc_temp, crc_humidity;

    printf("Starting SHT40 data logging...\n");

    while (!terminate) {
        // Read data from SHT40
        if (sht40_read_data(i2c_fd, data) == 0) {
            // Extract raw temperature and humidity values
            raw_temp = (data[0] << 8) | data[1];
            raw_humidity = (data[3] << 8) | data[4];

            // Calculate CRC values
            crc_temp = crc8(data, 2);
            crc_humidity = crc8(data + 3, 2);

            // Validate CRC values
            if (crc_temp != data[2] || crc_humidity != data[5]) {
                fprintf(stderr, "CRC validation failed\n");
                fprintf(log_fp, "CRC validation failed\n");
            } else {
                // Convert raw values to temperature and humidity
                temperature = convert_temperature(raw_temp);
                humidity = convert_humidity(raw_humidity);

                // Log data to file
                if (log_data(log_fp, temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading SHT40 data\n");
            fprintf(log_fp, "Error reading SHT40 data\n");
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup
    printf("Closing I2C device and log file...\n");
    i2cClose(i2c_fd);
    fclose(log_fp);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

