#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define SCALE_PRESSURE 240.0
#define SCALE_TEMPERATURE 200.0
#define OFFSET_TEMPERATURE -45.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, unsigned char command_msb, unsigned char command_lsb);
int read_data(int handle, unsigned char *data, int count);
unsigned char calculate_crc(unsigned char data[], int len);
int validate_crc(unsigned char data[], int len);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char calculate_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, unsigned char command_msb, unsigned char command_lsb) {
    char buf[2];
    buf[0] = command_msb;
    buf[1] = command_lsb;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw pressure to Pascals
float convert_pressure(int raw_pressure) {
    return (float)raw_pressure / SCALE_PRESSURE;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / SCALE_TEMPERATURE + OFFSET_TEMPERATURE;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[6];
        int raw_pressure, raw_temperature;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD_MSB, MEASURE_CMD_LSB) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Retry
        }

        // Wait for measurement (at least 1 ms)
        gpioDelay(1000); // 1 ms

        // Read data
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read data\n");
            continue; // Retry
        }

        // Validate CRC
        if (!validate_crc(data, 6)) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Retry
        }

        // Extract raw values
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        // Convert to physical units
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        // Delay before next measurement
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

