#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float temperature[BUFFER_SIZE];
    float humidity[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(CircularBuffer *buffer, float temperature, float humidity);
void print_buffer(CircularBuffer *buffer);
void signal_handler(int signal);
void cleanup();

// Circular buffer functions
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

void add_to_buffer(CircularBuffer *buffer, float temperature, float humidity) {
    buffer->temperature[buffer->head] = temperature;
    buffer->humidity[buffer->head] = humidity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

void print_buffer(CircularBuffer *buffer) {
    printf("\n--- Sensor Data Log ---\n");
    int start = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        printf("[%s.%03ld] Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, ts.tv_nsec / 1000000, buffer->temperature[index], buffer->humidity[index]);
    }
    printf("--- End of Log ---\n\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

