#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int addr);
int send_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
int check_crc(unsigned char *data, int len);
int read_measurement(int handle, unsigned char *data);
int convert_data(unsigned char *data, float *co2, float *temperature, float *humidity);
int log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c(SCD40_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for 1 second
    gpioDelay(1000000); // 1 second

    // Main loop
    while (!terminate) {
        unsigned char data[9];
        float co2, temperature, humidity;

        // Read measurement
        if (read_measurement(i2c_handle, data) != 0) {
            fprintf(stderr, "Failed to read measurement. Retrying.\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        if (convert_data(data, &co2, &temperature, &humidity) != 0) {
            fprintf(stderr, "Failed to convert data. Skipping.\n");
            continue;
        }

        // Log data
        if (log_data(co2, temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement.\n");
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

