// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to SCD40
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Check CRC-8 checksum
int check_crc(unsigned char *data, int len) {
    for (int i = 0; i < len - 1; i += 2) {
        unsigned short word = (data[i] << 8) | data[i + 1];
        unsigned char crc = data[i + 2];

        unsigned char crc_calculated = 0xFF;
        for (int j = 0; j < 8; j++) {
            if ((crc_calculated ^ word) & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
            word <<= 1;
        }

        if (crc_calculated != crc) {
            fprintf(stderr, "CRC check failed at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Read measurement from SCD40
int read_measurement(int handle, unsigned char *data) {
    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send read measurement command.\n");
        return -1;
    }

    gpioDelay(1000); // Wait 1 ms

    if (read_data(handle, data, 9) != 0) {
        fprintf(stderr, "Failed to read measurement data.\n");
        return -1;
    }

    if (check_crc(data, 9) != 0) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }

    return 0;
}

// Convert raw data to CO2, temperature, and humidity
int convert_data(unsigned char *data, float *co2, float *temperature, float *humidity) {
    unsigned short co2_raw = (data[0] << 8) | data[1];
    unsigned short temperature_raw = (data[3] << 8) | data[4];
    unsigned short humidity_raw = (data[6] << 8) | data[7];

    *co2 = (float)co2_raw;
    *temperature = -45 + 175 * ((float)temperature_raw / 65535.0);
    *humidity = 100 * ((float)humidity_raw / 65535.0);

    return 0;
}

