    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fclose(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed. Terminating...\n");
}

