// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int init_circular_buffer(circular_buffer_t *buffer);
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint8_t *data);
int validate_crc(uint16_t data, uint8_t crc);
int stop_periodic_measurement();
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data);
void control_led(uint16_t co2);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off LED initially
    return 0;
}

// Initialize circular buffer
int init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    uint8_t cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Get data ready status
int get_data_ready_status() {
    uint8_t cmd[2] = {(CMD_GET_DATA_READY_STATUS >> 8) & 0xFF, CMD_GET_DATA_READY_STATUS & 0xFF};
    uint8_t status[3];
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready status command: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)status, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }
    return (status[0] << 8) | status[1];
}

// Read measurement data
int read_measurement(uint8_t *data) {
    uint8_t cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    uint8_t data_msb = (data >> 8) & 0xFF;
    uint8_t data_lsb = data & 0xFF;

    crc_calculated ^= data_msb;
    for (int i = 0; i < 8; i++) {
        if (crc_calculated & 0x80) {
            crc_calculated = (crc_calculated << 1) ^ 0x31;
        } else {
            crc_calculated <<= 1;
        }
    }

    crc_calculated ^= data_lsb;
    for (int i = 0; i < 8; i++) {
        if (crc_calculated & 0x80) {
            crc_calculated = (crc_calculated << 1) ^ 0x31;
        } else {
            crc_calculated <<= 1;
        }
    }

    return (crc_calculated == crc);
}

// Stop periodic measurement
int stop_periodic_measurement() {
    uint8_t cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data) {
    if (buffer->count == 0) {
        return -1; // Buffer is empty
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    return 0;
}

// Control LED based on CO2 level
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&buffer);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;
    int data_ready;

    while (!terminate) {
        // Check if data is ready
        data_ready = get_data_ready_status();
        if (data_ready & 0x01) {
            // Read measurement data
            if (read_measurement(data) == 0) {
                // Validate CRC checksums
                if (validate_crc((data[0] << 8) | data[1], data[2]) &&
                    validate_crc((data[3] << 8) | data[4], data[5]) &&
                    validate_crc((data[6] << 8) | data[7], data[8])) {

                    // Convert data to sensor readings
                    sensor_data.co2 = (data[0] << 8) | data[1];
                    sensor_data.temperature = -45 + 175 * ((float)((data[3] << 8) | data[4])) / 65535;
                    sensor_data.humidity = 100 * ((float)((data[6] << 8) | data[7])) / 65535;

                    // Add data to circular buffer
                    add_to_buffer(&buffer, sensor_data);

                    // Print sensor readings
                    printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
                           sensor_data.co2, sensor_data.temperature, sensor_data.humidity);

                    // Control LED
                    control_led(sensor_data.co2);
                } else {
                    fprintf(stderr, "CRC checksum validation failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
            }
        } else {
            fprintf(stderr, "Data not ready yet\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

