#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define CONSECUTIVE_FAILURES 3

volatile sig_atomic_t program_running = 1;

// Structure to hold temperature data
typedef struct {
    double temperature;
    int valid;
} TemperatureData;

// Function prototypes
int initialize_gpio();
TemperatureData read_temperature();
void log_temperature(TemperatureData data);
void handle_signal(int signal);
void cleanup();

FILE *log_file = NULL;

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int consecutive_failures = 0;
    TemperatureData temp_data;

    while (program_running) {
        temp_data = read_temperature();

        if (temp_data.valid) {
            log_temperature(temp_data);
            consecutive_failures = 0; // Reset failure counter
        } else {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES) {
                fprintf(stderr, "SENSOR MALFUNCTION\n");
                log_temperature((TemperatureData){.temperature = -999.0, .valid = 0}); // Log error
                consecutive_failures = 0; // Reset counter after logging
            }
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: Use pull-down resistor

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open temperature_log.txt");
        gpioTerminate();
        return 1;
    }

    return 0;
}

TemperatureData read_temperature() {
    TemperatureData data = {.temperature = 0.0, .valid = 0};
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int high_state = 0; // 0 = low, 1 = high

    // Wait for the first rising edge with timeout
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return data; // Return invalid data
        }
    }
    start_tick = gpioTick();

    // Wait for the first falling edge with timeout
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return data; // Return invalid data
        }
    }
    end_tick = gpioTick();
    low_tick = end_tick - start_tick;

    // Wait for the second rising edge with timeout
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for second rising edge\n");
            return data; // Return invalid data
        }
    }
    start_tick = gpioTick();

    // Wait for the second falling edge with timeout
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if ((end_tick - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for second falling edge\n");
            return data; // Return invalid data
        }
    }
    end_tick = gpioTick();
    high_tick = end_tick - start_tick;

    // Calculate total cycle width
    uint32_t total_cycle_width = low_tick + high_tick;

    if (total_cycle_width == 0) {
        fprintf(stderr, "Total cycle width is zero, cannot calculate temperature\n");
        return data; // Return invalid data
    }

    // Calculate temperature
    data.temperature = 4215.0 - (2143.0 * (double)high_tick / (double)total_cycle_width);

    // Validate temperature
    if (data.temperature >= MIN_TEMP && data.temperature <= MAX_TEMP) {
        data.valid = 1;
    } else {
        fprintf(stderr, "Temperature out of range: %.2f\n", data.temperature);
        data.valid = 0;
    }

    return data;
}

void log_temperature(TemperatureData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (data.temperature == -999.0) {
        fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
    } else {
        fprintf(log_file, "%s Temperature: %.2f °C\n", timestamp, data.temperature);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

void handle_signal(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

