// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400 // High repeatability, clock stretching disabled
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define OFFSET_PERIOD 3600 // seconds (1 hour)
#define OFFSET_TEMP_AMPLITUDE 2.0
#define OFFSET_HUMID_AMPLITUDE 5.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sensor_data(unsigned char *data);
int validate_crc(unsigned char *data, int data_len);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
float apply_offset(float temperature, float humidity, time_t current_time);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 calculation (as per SHT35 datasheet)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15 ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(unsigned char *data, int data_len) {
    unsigned char crc_temp = crc8(data, 2);
    unsigned char crc_humidity = crc8(data + 3, 2);

    if (crc_temp != data[2] || crc_humidity != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

