    float temp_offset = OFFSET_TEMP_AMPLITUDE * sin((2 * M_PI * current_time) / OFFSET_PERIOD);
    float humidity_offset = OFFSET_HUMID_AMPLITUDE * sin((2 * M_PI * current_time) / OFFSET_PERIOD + M_PI / 2); // 90 degrees out of phase
    return temperature + temp_offset + humidity_offset;
}

