    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char sensor_data[6];
    float temperature, humidity;

    while (!terminate) {
        int retry = 0;
        int read_success = 0;

        while (retry < RETRY_COUNT && !read_success) {
            if (read_sensor_data(sensor_data) == 0) {
                if (validate_crc(sensor_data, 6) == 0) {
                    unsigned short raw_temp = (sensor_data[0] << 8) | sensor_data[1];
                    unsigned short raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

                    temperature = convert_temperature(raw_temp);
                    humidity = convert_humidity(raw_humidity);

                    // Apply offset
                    temperature = apply_offset(temperature, humidity, time(NULL));

                    // Data validation
                    if (temperature >= -50.0 && temperature <= 100.0 && humidity >= 0.0 && humidity <= 100.0) {
                        log_data(temperature, humidity);
                        read_success = 1;
                    } else {
                        fprintf(stderr, "Invalid sensor data: temperature=%.2f, humidity=%.2f\n", temperature, humidity);
                        temperature = NAN;
                        humidity = NAN;
                    }
                } else {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Sensor read failed, retrying...\n");
            }
            retry++;
            if (!read_success && retry < RETRY_COUNT) {
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read sensor data after %d retries, logging NaN values\n", RETRY_COUNT);
            log_data(NAN, NAN);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

