#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int count);
int i2c_write_byte(int fd, unsigned char reg);
int crc8(const unsigned char *data, int len);
int read_sensor_data(int fd, float *temperature, float *humidity);
int log_data(const char *filename, float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C setup function
int i2c_setup(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int count) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buf, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, unsigned char reg) {
    unsigned char buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, float *temperature, float *humidity) {
    unsigned char buf[3];
    int retries = 3;
    int delay_ms = 10;

    // Read humidity
    while (retries > 0) {
        if (i2c_write_byte(fd, HUMID_CMD) == 0) {
            gpioDelay(10); // Wait for measurement
            if (i2c_read_bytes(fd, 0, buf, 3) == 0) {
                unsigned int raw_humidity = (buf[0] << 8) | buf[1];
                if (crc8(buf, 2) == buf[2]) {
                    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "CRC error on humidity read\n");
                    retries--;
                    gpioDelay(delay_ms);
                    delay_ms *= 2; // Exponential backoff
                }
            } else {
                fprintf(stderr, "I2C read error on humidity\n");
                retries--;
                gpioDelay(delay_ms);
                delay_ms *= 2; // Exponential backoff
            }
        } else {
            fprintf(stderr, "I2C write error on humidity\n");
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries\n");
        *humidity = -999.0; // Indicate error
        return -1;
    }

    // Read temperature (paired reading)
    retries = 3;
    delay_ms = 10;
    while (retries > 0) {
        if (i2c_write_byte(fd, 0xE0) == 0) { // Paired reading command
            gpioDelay(10); // Wait for measurement
            if (i2c_read_bytes(fd, 0, buf, 3) == 0) {
                unsigned int raw_temperature = (buf[0] << 8) | buf[1];
                if (crc8(buf, 2) == buf[2]) {
                    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "CRC error on temperature read\n");
                    retries--;
                    gpioDelay(delay_ms);
                    delay_ms *= 2; // Exponential backoff
                }
            } else {
                fprintf(stderr, "I2C read error on temperature\n");
                retries--;
                gpioDelay(delay_ms);
                delay_ms *= 2; // Exponential backoff
            }
        } else {
            fprintf(stderr, "I2C write error on temperature\n");
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries\n");
        *temperature = -999.0; // Indicate error
        return -1;
    }

    return 0;
}

// Log data function
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup I2C
    i2c_fd = i2c_setup(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int log_result;

