#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_BYTES 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define CRC_DATA_LENGTH 6 // Pressure + Temperature data length

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == 0xFF);
}

// Convert raw data to pressure and temperature
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factor bytes
    uint8_t scale_factor[3] = {data[6], data[7], data[8]};

    // Convert scale factor to a float
    float scale_factor_float = 0.0;
    for (int i = 0; i < 3; i++) {
        scale_factor_float = scale_factor_float * 256.0 + scale_factor[i];
    }

    // Convert raw values to pressure and temperature
    sensor_data->pressure = (float)raw_pressure / scale_factor_float - 1000.0;
    sensor_data->temperature = (float)raw_temperature / 200.0 - 45.0;

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *sensor_data) {
    size_t bytes_written = fwrite(&sensor_data->pressure, sizeof(float), 1, fp);
    bytes_written += fwrite(&sensor_data->temperature, sizeof(float), 1, fp);
    if (bytes_written != 2) {
        fprintf(stderr, "Failed to write data to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (send_measurement_command() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t sensor_values;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC checksums
        if (!validate_crc(sensor_data, 3) || !validate_crc(sensor_data + 3, 3)) {
            fprintf(stderr, "CRC checksum error, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        if (convert_data(sensor_data, &sensor_values) != 0) {
            fprintf(stderr, "Error converting data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(&sensor_values) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close data file
    fclose(fp);

    return 0;
}

