#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SLEEP_DURATION 5 // seconds

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const char *buffer);
float convert_to_pascal(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buffer, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksums
int validate_crc(const char *buffer) {
    uint8_t data[2];
    uint8_t crc;

    // Pressure data
    data[0] = buffer[0];
    data[1] = buffer[1];
    crc = buffer[2];
    if (calculate_crc(data, 2) != crc) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }

    // Temperature data
    data[0] = buffer[3];
    data[1] = buffer[4];
    crc = buffer[5];
    if (calculate_crc(data, 2) != crc) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }

    // Status data
    data[0] = buffer[6];
    data[1] = buffer[7];
    crc = buffer[8];
    if (calculate_crc(data, 2) != crc) {
        fprintf(stderr, "CRC error in status data\n");
        return -1;
    }

    return 0;
}

// Convert raw pressure to Pascal
float convert_to_pascal(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Log data to file
int log_data(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
