#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define FLOW_MIN 0.0
#define FLOW_MAX 10.0
#define FLOW_MIN_COUNTS 1638
#define FLOW_MAX_COUNTS 14745
#define FLOW_MIN_PASCAL 0.0
#define FLOW_MAX_PASCAL 100.0 // Assuming 10 SLPM corresponds to 100 Pa
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, uint16_t *raw_data);
float convert_to_flow(uint16_t raw_data);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate, float pressure_Pa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, uint16_t *raw_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw data to flow rate (SLPM)
float convert_to_flow(uint16_t raw_data) {
    // Mask off status bits and shift right by 2
    uint16_t flow_reading = (raw_data & 0x3FFF) >> 2;

    // Linear interpolation
    float flow_rate = FLOW_MIN;
    if (flow_reading > FLOW_MIN_COUNTS) {
        flow_rate = FLOW_MIN + (float)(flow_reading - FLOW_MIN_COUNTS) * (FLOW_MAX - FLOW_MIN) / (FLOW_MAX_COUNTS - FLOW_MIN_COUNTS);
    }

    return flow_rate;
}

// Function to set the fan speed using PWM
void set_fan_speed(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100)
    int duty_cycle = (int)(flow_rate / FLOW_MAX * 100.0);

    // Set PWM duty cycle
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(float flow_rate, float pressure_Pa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_Pa);
    fflush(log_file); // Ensure data is written to disk immediately
}

