    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to hardware PWM mode
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float flow_rate, pressure_Pa;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle, &raw_data) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow(raw_data);

            // Calculate pressure (Pa) - Assuming a linear relationship
            pressure_Pa = flow_rate * (FLOW_MAX_PASCAL / FLOW_MAX);

            // Set fan speed
            set_fan_speed(flow_rate);

            // Log data
            log_data(flow_rate, pressure_Pa);

            printf("Flow Rate: %.2f SLPM, Pressure: %.2f Pa\n", flow_rate, pressure_Pa);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

