#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure LPS33HW
    if (write_register(CTRL_REG1, 0xB0) != 0) {
        fprintf(stderr, "Failed to configure LPS33HW\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data;

        // Read pressure and temperature
        if (read_pressure(&data.pressure) != 0) {
            fprintf(stderr, "Failed to read pressure\n");
        }
        if (read_temperature(&data.temperature) != 0) {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Log the data
        log_data(data.pressure, data.temperature);

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_register(WHO_AM_I);
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%X\n", who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read a single register
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read register 0x%X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a single register
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write register 0x%X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read pressure data
int read_pressure(int32_t *pressure) {
    int xl = read_register(PRESS_OUT_XL);
    int l = read_register(PRESS_OUT_L);
    int h = read_register(PRESS_OUT_H);

    if (xl < 0 || l < 0 || h < 0) {
        return -1;
    }

    *pressure = (int32_t)xl | ((int32_t)l << 8) | ((int32_t)h << 16);
    return 0;
}

// Read temperature data
int read_temperature(int16_t *temperature) {
    int l = read_register(TEMP_OUT_L);
    int h = read_register(TEMP_OUT_H);

    if (l < 0 || h < 0) {
        return -1;
    }

    *temperature = (int16_t)l | ((int16_t)h << 8);
    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime_r(&t, NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(fp);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Exiting...\n");
}

