#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(int i2c_handle);
float process_temperature(int raw_temp);
void update_circular_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from STLM75
int read_temperature(int i2c_handle) {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1; // Indicate error
    }
    return raw_temp;
}

// Function to process raw temperature data
float process_temperature(int raw_temp) {
    // Swap bytes (little-endian to big-endian)
    raw_temp = (raw_temp << 8) | (raw_temp >> 8);
    // Extract 9-bit value and right-shift by 7
    raw_temp = raw_temp >> 7;
    // Convert to Celsius
    return (float)raw_temp / 2.0;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average temperature
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on average temperature
void control_led(float average_temperature) {
    if (average_temperature > 28.0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with zeros
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_temp = read_temperature(i2c_handle);
        if (raw_temp >= 0) {
            float temperature = process_temperature(raw_temp);
            update_circular_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping iteration due to temperature read error.\n");
        }
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

