#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define CMD_START_CONT_MEAS 0x0010
#define CMD_STOP_CONT_MEAS 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_SET_MEAS_INTERVAL 0x4600

// CRC-8 parameters
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd30();
int set_measurement_interval(int interval);
int start_measurement();
int stop_measurement();
int is_data_ready();
int read_measurement(float *co2, float *temperature, float *humidity);
int calculate_crc(unsigned char data[], int len);
int log_data(float co2, float temperature, float humidity);
void ventilation_control(float co2);
void signal_handler(int signal);

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Set measurement interval to 2 seconds
    if (set_measurement_interval(2) != 0) {
        fprintf(stderr, "Error setting measurement interval.\n");
        return -1;
    }

    // Start continuous measurement
    if (start_measurement() != 0) {
        fprintf(stderr, "Error starting continuous measurement.\n");
        return -1;
    }

    return 0;
}

// Function to set the measurement interval
int set_measurement_interval(int interval) {
    unsigned char buf[3];
    buf[0] = (CMD_SET_MEAS_INTERVAL >> 8) & 0xFF;
    buf[1] = CMD_SET_MEAS_INTERVAL & 0xFF;
    buf[2] = interval;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

// Function to start continuous measurement
int start_measurement() {
    unsigned char buf[2];
    buf[0] = (CMD_START_CONT_MEAS >> 8) & 0xFF;
    buf[1] = CMD_START_CONT_MEAS & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

// Function to stop continuous measurement
int stop_measurement() {
    unsigned char buf[2];
    buf[0] = (CMD_STOP_CONT_MEAS >> 8) & 0xFF;
    buf[1] = CMD_STOP_CONT_MEAS & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

// Function to check if data is ready
int is_data_ready() {
    unsigned char buf[2];
    unsigned char read_buf[3];
    int ready;

    buf[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
    buf[1] = CMD_GET_DATA_READY & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    ready = (read_buf[0] << 8) | read_buf[1];
    return ready;
}

// Function to read measurement data
int read_measurement(float *co2, float *temperature, float *humidity) {
    unsigned char buf[2];
    unsigned char read_buf[18];
    unsigned char co2_data[6];
    unsigned char temp_data[6];
    unsigned char hum_data[6];
    unsigned char crc;
    unsigned char crc_calculated;
    int i;

    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 18) != 18) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Extract CO2 data
    for (i = 0; i < 6; i++) {
        co2_data[i] = read_buf[i];
    }

    // Extract temperature data
    for (i = 6; i < 12; i++) {
        temp_data[i - 6] = read_buf[i];
    }

    // Extract humidity data
    for (i = 12; i < 18; i++) {
        hum_data[i - 12] = read_buf[i];
    }

    // Calculate CRC for CO2
    crc = read_buf[5];
    crc_calculated = calculate_crc(co2_data, 5);
    if (crc != crc_calculated) {
        fprintf(stderr, "CO2 CRC mismatch.\n");
        return -1;
    }

    // Calculate CRC for temperature
    crc = read_buf[11];
    crc_calculated = calculate_crc(temp_data, 5);
    if (crc != crc_calculated) {
        fprintf(stderr, "Temperature CRC mismatch.\n");
        return -1;
    }

    // Calculate CRC for humidity
    crc = read_buf[17];
    crc_calculated = calculate_crc(hum_data, 5);
    if (crc != crc_calculated) {
        fprintf(stderr, "Humidity CRC mismatch.\n");
        return -1;
    }

    // Convert data to float
    *co2 = *((float *)co2_data);
    *temperature = *((float *)temp_data);
    *humidity = *((float *)hum_data);

    return 0;
}

// Function to calculate CRC-8 checksum
int calculate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INITIAL;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

// Function to log data to file
int log_data(float co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Function to control ventilation system
void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, stopping...\n");
}

int main() {
    float co2, temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (is_data_ready() == 1) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity);

                // Control ventilation
                ventilation_control(co2);
            } else {
                fprintf(stderr, "Error reading measurement data.\n");
            }
        } else {
            fprintf(stderr, "Data not ready.\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Stop continuous measurement
    stop_measurement();

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

