    if (crc != crc_calculated) {
        fprintf(stderr, "CO2 CRC mismatch.\n");
        return -1;
    }

    // Calculate CRC for temperature
    crc = read_buf[11];
    crc_calculated = calculate_crc(temp_data, 5);
    if (crc != crc_calculated) {
        fprintf(stderr, "Temperature CRC mismatch.\n");
        return -1;
    }

    // Calculate CRC for humidity
    crc = read_buf[17];
    crc_calculated = calculate_crc(hum_data, 5);
    if (crc != crc_calculated) {
        fprintf(stderr, "Humidity CRC mismatch.\n");
        return -1;
    }

    // Convert data to float
    *co2 = *((float *)co2_data);
    *temperature = *((float *)temp_data);
    *humidity = *((float *)hum_data);

    return 0;
}

// Function to calculate CRC-8 checksum
int calculate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INITIAL;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

// Function to log data to file
int log_data(float co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Function to control ventilation system
void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, stopping...\n");
}

int main() {
    float co2, temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (is_data_ready() == 1) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity);

                // Control ventilation
                ventilation_control(co2);
            } else {
                fprintf(stderr, "Error reading measurement data.\n");
            }
        } else {
            fprintf(stderr, "Data not ready.\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Stop continuous measurement
    stop_measurement();

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

