            sensor_data.pressure = convert_pressure(raw_pressure, (float)raw_scale_factor);
            sensor_data.temperature = convert_temperature(raw_temperature);
            sensor_data.scale_factor = (float)raw_scale_factor;

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the specified interval
        gpioDelay(interval * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
