#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3615
#define DATA_LEN 9
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int len);
int16_t convert_pressure(int16_t raw_pressure, float scale_factor_pressure);
float convert_temperature(int16_t raw_temperature, float scale_factor_temperature);
sensor_data_t process_sensor_data(const char *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 validation function
int validate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0x00) ? 0 : -1; // Return 0 for success, -1 for failure
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw pressure data
int16_t convert_pressure(int16_t raw_pressure, float scale_factor_pressure) {
    return (int16_t)(raw_pressure / scale_factor_pressure);
}

// Function to convert raw temperature data
float convert_temperature(int16_t raw_temperature, float scale_factor_temperature) {
    return (float)raw_temperature / 200.0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const char *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    float scale_factor_pressure = (float)((data[6] << 8) | data[7]);
    float scale_factor_temperature = (float)((data[2] << 8) | data[3]);

    sensor_data.pressure = convert_pressure(raw_pressure, scale_factor_pressure);
    sensor_data.temperature = convert_temperature(raw_temperature, scale_factor_temperature);

    return sensor_data;
}

// Function to log sensor data
void log_data(sensor_data_t data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", data.pressure, data.temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data[DATA_LEN];
        int retry = 0;

        // Retry loop for I2C communication
        while (retry < RETRY_COUNT) {
            // Send measurement command
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                // Wait for conversion (at least 45 ms)
                gpioDelay(50000); // 50 ms

                // Read data from sensor
                if (read_data(i2c_handle, data, DATA_LEN) == 0) {
                    // Validate CRC
                    if (validate_crc(data, DATA_LEN) == 0) {
                        // Process sensor data
                        sensor_data_t sensor_data = process_sensor_data(data);

                        // Log data
                        log_data(sensor_data);

                        // Break out of retry loop on success
                        break;
                    } else {
                        fprintf(stderr, "CRC validation failed\n");
                    }
                } else {
                    fprintf(stderr, "Failed to read data, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to send command, retrying...\n");
            }

            // Exponential backoff
            gpioDelay(RETRY_DELAY_MS * (1 << retry) * 1000); // Convert ms to us
            retry++;
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

