#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the I2C device
int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read bytes from the I2C device
int i2c_read(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the HDC1000 sensor
int hdc1000_init(int fd) {
    // Configure the sensor for combined temperature and humidity measurement at 14-bit resolution
    if (i2c_write(fd, CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int hdc1000_read(int fd, float *temperature, float *humidity) {
    unsigned char buf[4];

    // Trigger a temperature and humidity measurement
    if (i2c_write(fd, TEMP_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (at least 20 ms)
    usleep(20000); // 20 ms

    // Read the temperature and humidity data
    if (i2c_read(fd, TEMP_REG, buf, 4) != 0) {
        fprintf(stderr, "Failed to read temperature and humidity data\n");
        return -1;
    }

    // Convert the raw data to temperature and humidity
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    unsigned int raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (hdc1000_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize HDC1000 sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (1) {
        // Read temperature and humidity
        if (hdc1000_read(i2c_fd, &temperature, &humidity) == 0) {
            // Print the temperature and humidity to the console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

