#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALE_FACTOR 0.1f
#define READ_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int read_pressure(int fd, float *pressure_kPa);
void log_reading(float pressure_kPa);
void signal_handler(int signal);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read pressure function
int read_pressure(int fd, float *pressure_kPa) {
    uint8_t msb, lsb;

    if (i2c_read_reg(fd, PRESSURE_MSB_REG, &msb) != 0) {
        fprintf(stderr, "Error reading MSB\n");
        return -1;
    }

    if (i2c_read_reg(fd, PRESSURE_LSB_REG, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB\n");
        return -1;
    }

    int16_t raw_pressure = (msb << 8) | lsb;
    *pressure_kPa = (float)raw_pressure * SCALE_FACTOR;
    return 0;
}

// Log reading function
void log_reading(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

// Signal handler function
