        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        float pressure;
        if (read_pressure(i2c_fd, &pressure) == 0) {
            log_reading(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

