#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define CRC_DATA_LENGTH 2
#define CRC_DATA_MASK 0xFF

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, const unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
sensor_data_t convert_data(const unsigned char *raw_data);
int log_data(const sensor_data_t *data);
void signal_handler(int sig);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len);
    return (crc == data[len]);
}

// Data conversion function
sensor_data_t convert_data(const unsigned char *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure = (float)raw_pressure / PRESSURE_SCALE;
    data.temperature = (float)raw_temperature / TEMPERATURE_SCALE;

    return data;
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, const unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Data logging function
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        unsigned char raw_data[9];

        // Send measurement command
        if (i2c_write(i2c_fd, cmd, 2) < 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Wait for measurement (45ms)
        usleep(45000);

        // Read sensor data
        if (i2c_read(i2c_fd, raw_data, 9) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Validate CRCs
        if (!validate_crc(raw_data, CRC_DATA_LENGTH) || !validate_crc(raw_data + 3, CRC_DATA_LENGTH)) {
            fprintf(stderr, "CRC validation failed, skipping data point...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_data);

        // Log data
        if (log_data(&data) < 0) {
            fprintf(stderr, "Error logging data...\n");
        }

        // Wait before next measurement
        usleep(100000); // 100ms
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

