            fprintf(stderr, "CRC validation failed, skipping data point...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_data);

        // Log data
        if (log_data(&data) < 0) {
            fprintf(stderr, "Error logging data...\n");
        }

        // Wait before next measurement
        usleep(100000); // 100ms
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
