#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure(uint16_t *raw_pressure);
float convert_to_kPa(uint16_t raw_pressure);
void log_pressure(float pressure_kPa);
void check_pressure_range(float pressure_kPa);
void signal_handler(int signal);
int write_to_log(const char *timestamp, float pressure_kPa);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(uint16_t *raw_pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = (buf[0] << 8) | buf[1]; // Big-endian
    return 0;
}

// Convert raw pressure to kPa
float convert_to_kPa(uint16_t raw_pressure) {
    return (float)raw_pressure * SCALE_FACTOR;
}

// Log pressure to file
int write_to_log(const char *timestamp, float pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Check pressure range and log warning
void check_pressure_range(float pressure_kPa) {
    if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure out of range: %.2f kPa\n", pressure_kPa);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created (size 0)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_pressure;
    float pressure_kPa;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read pressure
        if (read_pressure(&raw_pressure) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(raw_pressure);

            // Get current timestamp
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log pressure
            if (write_to_log(timestamp, pressure_kPa) != 0) {
                fprintf(stderr, "Error writing to log, but continuing...\n");
            }

            // Check pressure range
            check_pressure_range(pressure_kPa);

            printf("%s,%.2f kPa\n", timestamp, pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        // Wait 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

