#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define SENT protocol parameters
#define SYNC_PULSE_TICKS 56
#define NIBBLE_TICKS_MIN 12
#define NIBBLE_TICKS_MAX 271
#define TICK_TIME_US 3

// Define pressure conversion parameters
#define SCALE 0.1
#define OFFSET 100.0

// Define timeout values (in milliseconds)
#define TIMEOUT_MS 100

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sent_data(int gpio_pin);
float calculate_pressure(int raw_value);
void log_pressure_data(int sensor_id, float pressure);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
} sensor_config_t;

// Array of sensor configurations
sensor_config_t sensors[] = {
    {SENSOR1_GPIO, 1},
    {SENSOR2_GPIO, 2},
    {SENSOR3_GPIO, 3}
};

int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Function to read SENT data from a sensor
int read_sent_data(int gpio_pin) {
    int i, j;
    int nibble;
    int data[4];
    int checksum;
    int pulse_width;
    long start_time, end_time, diff;
    int timeout_count = 0;

    // Wait for the synchronization pulse
    while (gpioRead(gpio_pin) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Timeout waiting for synchronization pulse on GPIO %d\n", gpio_pin);
        return -1; // Timeout error
    }
    timeout_count = 0;

    // Measure the synchronization pulse width
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1);
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Timeout waiting for sync pulse end on GPIO %d\n", gpio_pin);
        return -1; // Timeout error
    }
    timeout_count = 0;

    while (gpioRead(gpio_pin) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1);
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Timeout waiting for sync pulse end on GPIO %d\n", gpio_pin);
        return -1; // Timeout error
    }
    timeout_count = 0;

    diff = gpioTick() - start_time;
    if (diff < (SYNC_PULSE_TICKS * TICK_TIME_US) || diff > ((SYNC_PULSE_TICKS + 1) * TICK_TIME_US)) {
        fprintf(stderr, "Error: Invalid synchronization pulse width on GPIO %d: %ld us\n", gpio_pin, diff);
        return -1; // Bus error
    }

    // Read the status nibble
    nibble = 0;
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(gpio_pin) == 0 && timeout_count < TIMEOUT_MS) {
            gpioDelay(1);
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_MS) {
            fprintf(stderr, "Error: Timeout waiting for status nibble start on GPIO %d\n", gpio_pin);
            return -1; // Timeout error
        }
        timeout_count = 0;

        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < (NIBBLE_TICKS_MIN * TICK_TIME_US) || diff > (NIBBLE_TICKS_MAX * TICK_TIME_US)) {
            fprintf(stderr, "Error: Invalid status nibble pulse width on GPIO %d: %ld us\n", gpio_pin, diff);
            return -1; // Bus error
        }

        if (gpioRead(gpio_pin) == 1) {
            nibble |= (1 << (3 - i));
        }
        while (gpioRead(gpio_pin) == 1 && timeout_count < TIMEOUT_MS) {
            gpioDelay(1);
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_MS) {
            fprintf(stderr, "Error: Timeout waiting for status nibble end on GPIO %d\n", gpio_pin);
            return -1; // Timeout error
        }
        timeout_count = 0;
    }

    data[0] = nibble;

    // Read the data nibbles
    for (i = 1; i < 4; i++) {
        nibble = 0;
        for (j = 0; j < 4; j++) {
            start_time = gpioTick();
            while (gpioRead(gpio_pin) == 0 && timeout_count < TIMEOUT_MS) {
                gpioDelay(1);
                timeout_count++;
            }
            if (timeout_count >= TIMEOUT_MS) {
                fprintf(stderr, "Error: Timeout waiting for data nibble %d start on GPIO %d\n", i, gpio_pin);
                return -1; // Timeout error
            }
            timeout_count = 0;

            end_time = gpioTick();
            diff = end_time - start_time;
            if (diff < (NIBBLE_TICKS_MIN * TICK_TIME_US) || diff > (NIBBLE_TICKS_MAX * TICK_TIME_US)) {
                fprintf(stderr, "Error: Invalid data nibble %d pulse width on GPIO %d: %ld us\n", i, gpio_pin, diff);
                return -1; // Bus error
            }

            if (gpioRead(gpio_pin) == 1) {
                nibble |= (1 << (3 - j));
            }
            while (gpioRead(gpio_pin) == 1 && timeout_count < TIMEOUT_MS) {
                gpioDelay(1);
                timeout_count++;
            }
            if (timeout_count >= TIMEOUT_MS) {
                fprintf(stderr, "Error: Timeout waiting for data nibble %d end on GPIO %d\n", i, gpio_pin);
                return -1; // Timeout error
            }
            timeout_count = 0;
        }
        data[i] = nibble;
    }

    // Read the checksum nibble
    nibble = 0;
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(gpio_pin) == 0 && timeout_count < TIMEOUT_MS) {
            gpioDelay(1);
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_MS) {
            fprintf(stderr, "Error: Timeout waiting for checksum nibble start on GPIO %d\n", gpio_pin);
            return -1; // Timeout error
        }
        timeout_count = 0;

        end_time = gpioTick();
        diff = end_time - start_time;
        if (diff < (NIBBLE_TICKS_MIN * TICK_TIME_US) || diff > (NIBBLE_TICKS_MAX * TICK_TIME_US)) {
            fprintf(stderr, "Error: Invalid checksum nibble pulse width on GPIO %d: %ld us\n", gpio_pin, diff);
            return -1; // Bus error
        }

        if (gpioRead(gpio_pin) == 1) {
            nibble |= (1 << (3 - i));
        }
        while (gpioRead(gpio_pin) == 1 && timeout_count < TIMEOUT_MS) {
            gpioDelay(1);
            timeout_count++;
        }
        if (timeout_count >= TIMEOUT_MS) {
            fprintf(stderr, "Error: Timeout waiting for checksum nibble end on GPIO %d\n", gpio_pin);
            return -1; // Timeout error
        }
        timeout_count = 0;
    }

    checksum = nibble;

    // Validate the checksum
    int sum = 0;
    for (i = 0; i < 4; i++) {
        sum += data[i];
    }
    if ((sum % 16) != checksum) {
        fprintf(stderr, "Error: Checksum mismatch on GPIO %d. Calculated: %d, Received: %d\n", gpio_pin, sum % 16, checksum);
        return -1; // Bus error
    }

    // Combine the nibbles to form the raw pressure value
    int raw_value = 0;
    for (i = 0; i < 3; i++) {
        raw_value = (raw_value << 4) | data[i];
    }

    return raw_value;
}

// Function to calculate pressure from the raw value
float calculate_pressure(int raw_value) {
    return raw_value * SCALE + OFFSET;
}

// Function to log pressure data to a file
void log_pressure_data(int sensor_id, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open pressure_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, Sensor: %d, Pressure: %.2f Pa\n", timestamp, sensor_id, pressure);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Brake pressure monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int raw_value = read_sent_data(sensors[i].gpio_pin);
            if (raw_value != -1) {
                float pressure = calculate_pressure(raw_value);
                log_pressure_data(sensors[i].sensor_id, pressure);
                printf("Sensor %d: Pressure = %.2f Pa\n", sensors[i].sensor_id, pressure);
            } else {
                fprintf(stderr, "Error: Failed to read data from sensor %d\n", sensors[i].sensor_id);
            }
        }
        gpioDelay(100); // Delay between readings
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

