#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID 0x0117
#define TEMP_FILE "greenhouse_temps.dat"
#define READ_INTERVAL_SEC 60

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
void write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    char *temp_file;
    int read_interval;
} config_t;

config_t config = {I2C_BUS, TMP117_ADDR, TEMP_FILE, READ_INTERVAL_SEC};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        fprintf(stderr, "Device ID verification failed\n");
        cleanup();
        return 1;
    }

    // Open the temperature file in append binary mode
    fp = fopen(config.temp_file, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature file\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -1000.0) { // Check for read error
            write_temperature_to_file(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(config.read_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read device ID: %d\n", result);
        return 1;
    }

    uint16_t device_id = (buf[0] << 8) | buf[1];
    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID);
        return 1;
    }
    return 0;
}

// Read temperature from the sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Write temperature to file
void write_temperature_to_file(float temperature) {
    uint32_t temp_int = *(uint32_t*)&temperature; // Cast float to uint32_t
    uint8_t buffer[4];
    buffer[0] = temp_int & 0xFF;       // Byte 0 (LSB)
    buffer[1] = (temp_int >> 8) & 0xFF; // Byte 1
    buffer[2] = (temp_int >> 16) & 0xFF; // Byte 2
    buffer[3] = (temp_int >> 24) & 0xFF; // Byte 3 (MSB)

    size_t bytes_written = fwrite(buffer, 1, 4, fp);
    if (bytes_written != 4) {
        fprintf(stderr, "Failed to write temperature to file\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

