// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_measurement_command(int handle);
int read_sensor_data(int handle, unsigned char *data);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_hum);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char sensor_data[6];
        unsigned short raw_temp, raw_hum;
        float temperature, humidity;

        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            fprintf(stderr, "Failed to send measurement command.\n");
            continue; // Retry
        }

        // Wait for conversion (at least 8.5 ms)
        gpioDelay(10000); // 10 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue; // Retry
        }

        // Validate CRC checksums
        if (validate_crc(sensor_data) != 0) {
            fprintf(stderr, "CRC checksum validation failed.\n");
            continue; // Retry
        }

        // Convert raw data to temperature and humidity
        raw_temp = (sensor_data[0] << 8) | sensor_data[1];
        raw_hum = (sensor_data[3] << 8) | sensor_data[4];
        temperature = convert_temperature(raw_temp);
        humidity = convert_humidity(raw_hum);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command(int handle) {
    int result = i2cWriteByteData(handle, 0, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, unsigned char *data) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }
    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksums
int validate_crc(const unsigned char *data) {
    unsigned char temp_crc = crc8(data, 2);
    if (temp_crc != data[2]) {
        fprintf(stderr, "Temperature CRC check failed. Expected: 0x%02X, Got: 0x%02X\n", data[2], temp_crc);
        return 1;
    }

    unsigned char hum_crc = crc8(data + 3, 2);
    if (hum_crc != data[5]) {
        fprintf(stderr, "Humidity CRC check failed. Expected: 0x%02X, Got: 0x%02X\n", data[5], hum_crc);
        return 1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * ((float)raw_temp / 65535.0);
}

// Convert raw humidity to percentage RH
float convert_humidity(unsigned short raw_hum) {
    return -6.0 + 125.0 * ((float)raw_hum / 65535.0);
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

