// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define RESOLUTION 0.0078125f
#define SAMPLE_INTERVAL 5 // seconds
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for temperature data
typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureData;

// Circular buffer
TemperatureData temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void store_temperature(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
float read_temperature() {
    char buf[2];
