#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define LOG_FILE "shtc3_environment.log"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
int convert_temperature(unsigned short raw_temp);
int convert_humidity(unsigned short raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the SHTC3
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the SHTC3
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksums
int validate_crc(const unsigned char *data, int len) {
    if (len < 2) return 0; // Not enough data for CRC

    unsigned char temp_crc = crc8(data, len - 1);
    if (temp_crc != data[len - 1]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return 0;
    }

    unsigned char humidity_crc = crc8(data + 3, len - 5);
    if (humidity_crc != data[len - 2]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return 0;
    }

    return 1;
}

// Function to convert raw temperature to Celsius
int convert_temperature(unsigned short raw_temp) {
    float temperature = 175.0 * raw_temp / 65535.0 - 45.0;
    return (int)(temperature * 100.0); // Return as integer representing two decimal places
}

// Function to convert raw humidity to percentage
int convert_humidity(unsigned short raw_humidity) {
    float humidity = 100.0 * raw_humidity / 65535.0;
    return (int)(humidity * 100.0); // Return as integer representing two decimal places
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[6];
        int retries = 0;

        // Retry loop for I2C communication
        while (retries < RETRY_COUNT) {
            // Send measurement command
            if (send_command(i2c_handle, MEASURE_CMD) == 0) {
                // Wait for measurement (at least 12.4 ms)
                gpioDelay(12400); // Delay in microseconds

                // Read data
                if (read_data(i2c_handle, data, 6) == 0) {
                    // Validate CRC
                    if (validate_crc(data, 6)) {
                        // Convert raw data
                        int raw_temp = (data[0] << 8) | data[1];
                        int raw_humidity = (data[3] << 8) | data[4];

                        // Convert to Celsius and percentage
                        float temperature = (float)convert_temperature(raw_temp) / 100.0;
                        float humidity = (float)convert_humidity(raw_humidity) / 100.0;

                        // Validate temperature and humidity
                        if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                            // Log data
                            if (log_data(temperature, humidity) == 0) {
                                // Print to stdout
                                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                            } else {
                                fprintf(stderr, "Failed to log data\n");
                            }
                        } else {
                            fprintf(stderr, "Invalid temperature or humidity values: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
                        }
                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "CRC validation failed, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Failed to read data, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to send command, retrying...\n");
            }
            retries++;
            gpioDelay(1000); // Wait before retrying
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // Delay in microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

