#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_FIELD_REG 0x00 // Example register address for magnetic field
#define TEMP_REG 0x01       // Example register address for temperature
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(float *magnetic_field, float *temperature);
int log_data(float magnetic_field, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.magnetic_field, &sensor_data.temperature) == 0) {
            // Log data
            if (log_data(sensor_data.magnetic_field, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            sensor_data.magnetic_field = -999.0; // Indicate error
            sensor_data.temperature = -999.0;    // Indicate error
            log_data(sensor_data.magnetic_field, sensor_data.temperature);
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *magnetic_field, float *temperature) {
    char buf[2];
    int result;

    // Read magnetic field
    result = i2cReadI2CBlockData(i2c_handle, MAG_FIELD_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return 1;
    }
    int raw_magnetic_field = (buf[0] << 8) | buf[1];
    *magnetic_field = raw_magnetic_field * 0.1;

    // Read temperature
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return 1;
