#define TEMP_RESOLUTION 0.0078125f
#define MAX_REINIT_ATTEMPTS 3
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    float temp_resolution;
    char *log_file_path;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .tmp117_address = TMP117_ADDR,
    .temp_resolution = TEMP_RESOLUTION,
    .log_file_path = LOG_FILE
};

int main() {
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
