    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    int attempts = 0;
    int result;

    while (attempts < MAX_REINIT_ATTEMPTS) {
        i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
        if (i2c_handle >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C open failed (attempt %d): %d\n", attempts + 1, i2c_handle);
            attempts++;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to initialize I2C after %d attempts\n", MAX_REINIT_ATTEMPTS);
    return -1; // Failure
}

