    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    raw_temp = (int16_t)result;

    // Handle two's complement conversion
    if (raw_temp & 0x8000) {
        raw_temp = -((~raw_temp & 0xFFFF) + 1);
    }

    *temperature = (float)raw_temp * config.temp_resolution;

    return 0;
}

