// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define SLPM_OFFSET 0.1
#define SLPM_SCALE 0.8
#define SLPM_MAX 25.0
#define TEMP_OFFSET 0.1
#define TEMP_SCALE 0.8
#define TEMP_MAX 80.0
#define TEMP_MIN -40.0
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *raw_flow, uint16_t *raw_temp);
float convert_flow(uint16_t raw_flow);
float convert_temperature(uint16_t raw_temp);
int log_data(float flow, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_flow, uint16_t *raw_temp) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Convert raw flow data to SLPM
float convert_flow(uint16_t raw_flow) {
    return ((float)raw_flow / 16384.0 - SLPM_OFFSET) / SLPM_SCALE * SLPM_MAX;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((float)raw_temp / 4096.0 - TEMP_OFFSET) / TEMP_SCALE * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
}

// Log data to file
int log_data(float flow, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint16_t raw_flow, raw_temp;
    float flow, temperature;
    int read_count = 0;

    while (!terminate) {
        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            read_count++;
            if (read_count > 2) { // Skip first two reads
                flow = convert_flow(raw_flow);
                temperature = convert_temperature(raw_temp);

                if (log_data(flow, temperature) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

