#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85
#define TIMEOUT_US 100

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
} DHT11Data;

// Global variables
static volatile int timings[MAX_TIMINGS];
static volatile int index = 0;
static volatile int data_ready = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void dht11_callback(int gpio, int level, uint32_t tick);
int read_dht11_data(DHT11Data *data);
int validate_checksum(DHT11Data data);
void log_error(const char *message, int status_code);
void log_reading(int humidity, int temperature);
void signal_handler(int signal);

// Callback function for DHT11 data acquisition
void dht11_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (level == PI_TIMEOUT) {
        // Timeout occurred
        if (index == 0) {
            log_error("Start signal timeout", 1);
        } else if (index < 2) {
            log_error("Response timeout", 2);
        } else {
            log_error("Data bit timeout", 3);
        }
        data_ready = 0; // Reset data ready flag
        return;
    }

    diff = tick - last_tick;
    last_tick = tick;

    if (diff > TIMEOUT_US) {
        log_error("Timeout occurred", 4);
        data_ready = 0; // Reset data ready flag
        return;
    }

    if (index < MAX_TIMINGS) {
        timings[index++] = diff;
    }

    if (index >= MAX_TIMINGS) {
        data_ready = 1; // Data acquisition complete
    }
}

// Function to read DHT11 data
int read_dht11_data(DHT11Data *data) {
    int i, j;
