#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c_command(int handle, unsigned char command[2]);
int read_i2c_data(int handle, unsigned char *data, int count);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
float convert_temperature(unsigned short raw_temperature);
float convert_humidity(unsigned short raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Temperature conversion function
float convert_temperature(unsigned short raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Humidity conversion function
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// I2C write function with retry
int write_i2c_command(int handle, unsigned char command[2]) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(handle, command, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// I2C read function with retry
int read_i2c_data(int handle, unsigned char *data, int count) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

