int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[6];
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    unsigned short raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (write_i2c_command(i2c_handle, command) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            fprintf(log_file, "Error: Failed to send measurement command\n");
        } else {
            gpioDelay(15); // Wait for measurement (at least 15 ms)

            // Read data
            if (read_i2c_data(i2c_handle, data, 6) != 0) {
                fprintf(stderr, "Failed to read data\n");
                fprintf(log_file, "Error: Failed to read data\n");
            } else {
                // Validate CRC
                if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                    // Convert raw values
                    raw_temperature = (data[0] << 8) | data[1];
                    raw_humidity = (data[3] << 8) | data[4];

                    temperature = convert_temperature(raw_temperature);
                    humidity = convert_humidity(raw_humidity);

                    // Log data
                    log_data(temperature, humidity);
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                } else {
                    fprintf(stderr, "CRC validation failed\n");
                    fprintf(log_file, "Error: CRC validation failed\n");
                }
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

