        cct2 = calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);

        // Calculate average CCT
        average_cct_value = average_cct(cct1, cct2);

        // Log the data
        if (log_data(average_cct_value) != 0) {
