// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read a register
int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int r_low, r_high, g_low, g_high, b_low, b_high;

    r_low = read_register(handle, RED_REG);
    r_high = read_register(handle, RED_REG + 1);
    g_low = read_register(handle, GREEN_REG);
    g_high = read_register(handle, GREEN_REG + 1);
    b_low = read_register(handle, BLUE_REG);
    b_high = read_register(handle, BLUE_REG + 1);

    if (r_low < 0 || r_high < 0 || g_low < 0 || g_high < 0 || b_low < 0 || b_high < 0) {
        return -1;
    }

    *red = (uint16_t)((r_high << 8) | r_low);
    *green = (uint16_t)((g_high << 8) | g_low);
    *blue = (uint16_t)((b_high << 8) | b_low);

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float x = (float)red / (float)(red + green + blue);
    float y = (float)green / (float)(red + green + blue);

    float n = (x - 0.3320) / (0.1858 - y);

    float cct = 449.0 * n * n * n + 3525.0 * n * n + 6823.3 * n + 5520.33;

    return cct;
}

// Function to calculate the average CCT
float average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

