#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN 0.0
#define P_MAX 800.0
#define TEMP_MIN 40.0
#define TEMP_MAX 80.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_raw_data(int handle, uint16_t reg, uint16_t *data);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read raw data from the sensor
int read_raw_data(int handle, uint16_t reg, uint16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);

    if (result != 2) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tstruct);

        fprintf(log_file, "%s,ERROR,Failed to read register 0x%04X: %d\n", timestamp, reg, result);
        fflush(log_file);
        return -1; // Indicate failure
    }

    *data = (buf[0] << 8) | buf[1]; // Combine bytes into a 16-bit value
    return 0; // Indicate success
}

// Function to convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (P_MAX - P_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * 0.01 - TEMP_MIN;
}

