    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_pressure, raw_temperature;
    float pressure_kPa, temperature_C;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(i2c_handle, PRESSURE_REG, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read pressure data\n");
        } else if (read_raw_data(i2c_handle, TEMPERATURE_REG, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read temperature data\n");
        } else {
            // Convert data
