#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
int calculate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len) {
    int crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    char buffer[9];
    while (!terminate) {
        // Read data from the sensor
        if (read_data(i2c_handle, buffer, 9) == 0) {
            // Validate CRC for pressure
            if (!validate_crc(buffer, 1)) {
                fprintf(stderr, "Pressure CRC mismatch\n");
                continue;
            }

            // Validate CRC for temperature
            if (!validate_crc(buffer + 2, 1)) {
                fprintf(stderr, "Temperature CRC mismatch\n");
                continue;
            }

            // Validate CRC for status
            if (!validate_crc(buffer + 4, 1)) {
                fprintf(stderr, "Status CRC mismatch\n");
                continue;
            }

            // Convert raw data to physical units
            int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
            int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);

            // Log the data
            log_data(pressure, temperature);

            // Check for pressure threshold
            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa)\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

