#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define GPIO_CHIP "gpiochip0"
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_SCALE 0.0625

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word_data(int fd, uint8_t reg);
float convert_to_celsius(int16_t raw_temp);
void control_led(float temperature);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);
int setup_i2c(void);
void cleanup_i2c(void);

// I2C read function
int i2c_read_word_data(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read temperature data");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Temperature conversion function
float convert_to_celsius(int16_t raw_temp) {
    return (float)(raw_temp >> 4) * TEMP_SCALE;
}

// LED control function
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// GPIO setup function
int setup_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "temperature_monitor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(led_line);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn LED off
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// I2C setup function
int setup_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// I2C cleanup function
void cleanup_i2c(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (setup_i2c() < 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        cleanup_gpio();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        int raw_temp = i2c_read_word_data(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(raw_temp);

        // Control LED
        control_led(temperature);

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup_gpio();
    cleanup_i2c();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

