#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR_BYTES 3
#define DATA_BYTES 9
#define SLEEP_MS 45

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int16_t convert_pressure(uint16_t raw_pressure, uint16_t scale_factor);
float convert_temperature(uint16_t raw_temperature);
int log_data(float differential_pressure, float temperature);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to convert raw pressure to Pascals
int16_t convert_pressure(uint16_t raw_pressure, uint16_t scale_factor) {
    return (int16_t)((int32_t)raw_pressure / (int32_t)scale_factor);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0f;
}

// Function to log data to a file
int log_data(float differential_pressure, float temperature) {
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa, %.2f °C\n", timestamp, differential_pressure, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement
        gpioDelay(SLEEP_MS);

        // Read data
        char buffer[DATA_BYTES];
        if (read_data(i2c_handle, buffer, DATA_BYTES) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(buffer, 3)) {
            fprintf(stderr, "Pressure CRC validation failed\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(buffer + 3, 3)) {
            fprintf(stderr, "Temperature CRC validation failed\n");
            continue;
        }

        // Extract raw data
        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint8_t pressure_crc = buffer[2];
        uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
        uint8_t temperature_crc = buffer[5];
        uint8_t scale_factor_msb = buffer[6];
        uint8_t scale_factor_lsb = buffer[7];
        uint8_t scale_factor_msb2 = buffer[8];

        // Combine scale factor bytes
        uint16_t scale_factor = (scale_factor_msb << 8) | scale_factor_lsb;

        // Convert data
        int16_t pressure = convert_pressure(raw_pressure, scale_factor);
        float temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data((float)pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Differential Pressure: %.2f Pa, Temperature: %.2f °C\n", (float)pressure, temperature);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

