#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xF3
#define MEASURE_HUM_CMD 0xF5
#define READ_TEMP_AFTER_RH_CMD 0xE0
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL 60 // seconds
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int command, uint16_t *raw_data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int validate_sensor();
void log_data(float temperature, float humidity);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        log_error("Sensor validation failed");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(MEASURE_TEMP_CMD, &raw_temperature) != 0) {
            log_error("Failed to read temperature");
            continue; // Continue to the next iteration
        }

        // Read humidity
        if (read_sensor_data(MEASURE_HUM_CMD, &raw_humidity) != 0) {
            log_error("Failed to read humidity");
            continue; // Continue to the next iteration
        }

        // Convert data
        temperature = convert_temperature(raw_temperature);
        humidity = convert_humidity(raw_humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int command, uint16_t *raw_data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, &command, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (command 0x%02X): %d\n", command, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(20000); // Wait 20ms

        char buffer[2];
        result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read failed (command 0x%02X): %d\n", command, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        *raw_data = (buffer[0] << 8) | buffer[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return 1; // Failure
}

// Convert temperature
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert humidity
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Validate sensor
int validate_sensor() {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", result);
        return 1;
    }

    uint16_t sensor_id = (buffer[0] << 8) | buffer[1];
    if (sensor_id != 0x4142) { // Expected ID for Si7021
        fprintf(stderr, "Incorrect sensor ID: 0x%04X\n", sensor_id);
        return 1;
    }

    return 0;
}

// Log data to file and stdout
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open log file\n");
    }

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(stdout); // Flush stdout to ensure immediate output
}

// Log error to file and stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open log file\n");
    }

    fprintf(stderr, "%s,ERROR,%s\n", timestamp, message);
    fflush(stderr);
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

