#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0xE0
#define LOG_FILE "temperature_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C device
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read temperature from the STS40 sensor
int read_temperature(float *temperature) {
    unsigned char cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    unsigned char data[3];
    int result;

    // Send measurement command
    result = write(i2c_fd, cmd, 2);
    if (result != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    usleep(10000); // 10 ms

    // Read temperature data
    result = read(i2c_fd, data, 3);
    if (result != 3) {
        perror("Error reading from I2C device");
        return -1;
    }

    // CRC Check
    unsigned char crc = data[2];
    unsigned char crc_calculated = 0xFF;
    unsigned char data_msb = data[0];
    unsigned char data_lsb = data[1];

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_msb;
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
        data_msb = (data_msb << 1) & 0xFF; // Shift to the next byte
    }

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    // Convert raw data to temperature
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;

    return 0;
}

// Function to log the temperature to a file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", buf, temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    float temperature;

    // Main loop
    while (1) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(5);
    }

    return 0;
}

