// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int send_command(int handle, unsigned short command);
int read_data(int handle, char *buffer, int count);
unsigned char calculate_crc(const char *data, int len);
float convert_pressure(int raw_pressure, int scale_factor);
float convert_temperature(int raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    char buffer[9];
    int raw_pressure, raw_temperature, scale_factor;
    float pressure, temperature;
    unsigned char crc_pressure, crc_temperature, crc_scale;

    while (!terminate) {
        // Send continuous measurement command
        if (send_command(i2c_handle, 0x3615) != 0) {
            fprintf(stderr, "Failed to send command. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue;
        }

        gpioDelay(50); // Wait for measurement

        // Read data from sensor
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Extract raw data
        raw_pressure = (buffer[0] << 8) | buffer[1];
        crc_pressure = buffer[2];
