#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define CSV_FILE_NAME_FORMAT "%Y%m%d_%H%M%S.csv"
#define CSV_FILE_NAME_MAX_LENGTH 32
#define CSV_FILE_NAME_BUFFER_SIZE 64
#define CSV_FLUSH_INTERVAL 60 // seconds

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static circular_buffer_t buffer;
static pthread_t logging_thread;
static FILE *error_log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
int validate_crc(const unsigned char *data, int len);
int convert_data(const unsigned char *raw_data, sensor_data_t *data);
int add_to_buffer(circular_buffer_t *buffer, const sensor_data_t *data);
int write_buffer_to_csv(circular_buffer_t *buffer);
void *logging_thread_function(void *arg);
void log_error(const char *message);

// CRC-8 validation function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0x00) ? 0 : -1; // Return 0 for success, -1 for failure
}

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Create log directory if it doesn't exist
    struct stat st = {0};
    if (stat(LOG_DIR, &st) == -1) {
        if (mkdir(LOG_DIR, 0777) == -1) {
            log_error("Failed to create log directory");
            pthread_mutex_destroy(&buffer.mutex);
            i2cClose(i2c_handle);
            gpioTerminate();
            return -1;
        }
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        log_error("Failed to open error log file");
        pthread_mutex_destroy(&buffer.mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    gpioDelay(1000); // Wait 1 second
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    char raw_data[9];
    int result = i2cWriteReadDevice(i2c_handle, buf, 2, raw_data, 9);
    if (result != 0) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Validate CRC for CO2
    if (validate_crc(raw_data, 3) != 0) {
        log_error("CO2 CRC validation failed");
        return -1;
    }

    // Validate CRC for Temperature
    if (validate_crc(raw_data + 3, 3) != 0) {
        log_error("Temperature CRC validation failed");
        return -1;
    }

    // Validate CRC for Humidity
    if (validate_crc(raw_data + 6, 3) != 0) {
        log_error("Humidity CRC validation failed");
        return -1;
    }

    // Convert data
    if (convert_data(raw_data, data) != 0) {
        log_error("Failed to convert sensor data");
        return -1;
    }

    return 0;
}

// Function to convert raw data to CO2, temperature, and humidity
int convert_data(const unsigned char *raw_data, sensor_data_t *data) {
    unsigned int co2_raw = (raw_data[0] << 8) | raw_data[1];
    unsigned int temperature_raw = (raw_data[3] << 8) | raw_data[4];
    unsigned int humidity_raw = (raw_data[6] << 8) | raw_data[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to add data to the circular buffer
int add_to_buffer(circular_buffer_t *buffer, const sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = *data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Function to write the buffer to a CSV file
int write_buffer_to_csv(circular_buffer_t *buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[CSV_FILE_NAME_BUFFER_SIZE];
    strftime(filename, CSV_FILE_NAME_BUFFER_SIZE, LOG_DIR CSV_FILE_NAME_FORMAT, t);

    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }

    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
    pthread_mutex_lock(&buffer->mutex);
    int start = buffer->tail;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", buffer->data[index].timestamp, buffer->data[index].co2, buffer->data[index].temperature, buffer->data[index].humidity);
    }
    pthread_mutex_unlock(&buffer->mutex);
    fclose(fp);
    return 0;
}

// Function to handle the logging thread
void *logging_thread_function(void *arg) {
    while (running) {
        sleep(CSV_FLUSH_INTERVAL);
        if (running) {
            write_buffer_to_csv(&buffer);
        }
    }
    return NULL;
}

// Function to log errors to a file
void log_error(const char *message) {
    if (error_log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(error_log_file, "%ld: %s\n", now, message);
        fflush(error_log_file);
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        pthread_mutex_destroy(&buffer.mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(error_log_file);
        return 1;
    }

    // Create and start the logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_function, NULL) != 0) {
        log_error("Failed to create logging thread");
        pthread_mutex_destroy(&buffer.mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(error_log_file);
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (running) {
        if (read_sensor_data(&data) == 0) {
            data.timestamp = time(NULL);
            add_to_buffer(&buffer, &data);
        }
        sleep(5);
    }

    // Stop periodic measurement
    char buf[2];
    buf[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, buf, 2);

    // Join the logging thread
    pthread_join(logging_thread, NULL);

    // Write any remaining data to CSV file
    write_buffer_to_csv(&buffer);

    // Clean up
    pthread_mutex_destroy(&buffer.mutex);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(error_log_file);

    return 0;
}

