#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10110 I2C address
#define ICP10110_ADDR 0x63

// ICP-10110 Registers
#define WHO_AM_I 0x08
#define MEASURE 0x00
#define PRESSURE_TEMP_DATA 0x00

// Calibration Coefficients Registers
#define CALIB_COEFF_START 0x05

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration coefficients
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
} calibration_coeffs_t;

calibration_coeffs_t coeffs;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int verify_sensor();
int read_calibration_coefficients(calibration_coeffs_t *coeffs);
int trigger_measurement();
int read_pressure_temperature(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_coeffs_t *coeffs);
double convert_temperature(int32_t raw_temperature, const calibration_coeffs_t *coeffs);
char* get_iso8601_timestamp();
int log_data(double pressure, double temperature);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the sensor
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x08\n", who_am_i);
        return -1;
    }
    printf("Sensor verified successfully\n");
    return 0;
}

// Function to read calibration coefficients
int read_calibration_coefficients(calibration_coeffs_t *coeffs) {
    char buffer[8];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_START, buffer, 8) != 8) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    coeffs->c0 = (int32_t)((((uint32_t)buffer[0]) << 24) | (((uint32_t)buffer[1]) << 16) | (((uint32_t)buffer[2]) << 8) | (uint32_t)buffer[3]);
    coeffs->c1 = (int32_t)((((uint32_t)buffer[4]) << 24) | (((uint32_t)buffer[5]) << 16) | (((uint32_t)buffer[6]) << 8) | (uint32_t)buffer[7]);

    // Read c00 and c10 from registers 0x09 and 0x0A
    if (i2cReadI2CBlockData(i2c_handle, 0x09, buffer, 4) != 4) {
        fprintf(stderr, "Failed to read c00 and c10 coefficients\n");
        return -1;
    }

    coeffs->c00 = (int32_t)((((uint32_t)buffer[0]) << 24) | (((uint32_t)buffer[1]) << 16) | (((uint32_t)buffer[2]) << 8) | (uint32_t)buffer[3]);
    coeffs->c10 = (int32_t)((((uint32_t)buffer[0]) << 24) | (((uint32_t)buffer[1]) << 16) | (((uint32_t)buffer[2]) << 8) | (uint32_t)buffer[3]);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, MEASURE, 0x00) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Function to read pressure and temperature data
int read_pressure_temperature(int32_t *pressure, int32_t *temperature) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, PRESSURE_TEMP_DATA, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read pressure and temperature data\n");
        return -1;
    }

    *pressure = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | (uint32_t)buffer[2];
    *temperature = ((uint32_t)buffer[3] << 16) | ((uint32_t)buffer[4] << 8) | (uint32_t)buffer[5];

    return 0;
}

// Function to convert raw pressure to hPa
double convert_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_coeffs_t *coeffs) {
    double p = (double)raw_pressure;
    double t = (double)raw_temperature;
    double c0 = (double)coeffs->c0;
    double c1 = (double)coeffs->c1;
    double c00 = (double)coeffs->c00;
    double c10 = (double)coeffs->c10;

    double pressure = c0 + p * (c1 + p * (c00 + p * c10));
    return pressure / 100.0; // Convert to hPa
}

// Function to convert raw temperature to Celsius
double convert_temperature(int32_t raw_temperature, const calibration_coeffs_t *coeffs) {
    double t = (double)raw_temperature;
    double c0 = (double)coeffs->c0;
    double c1 = (double)coeffs->c1;
    double c00 = (double)coeffs->c00;
    double c10 = (double)coeffs->c10;

    double temperature = c0 + t * (c1 + t * (c00 + t * c10));
    return temperature / 100.0; // Convert to Celsius
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to a file
int log_data(double pressure, double temperature) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    free(timestamp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(&coeffs) != 0) {
        i2cClose(i2c_handle);
