#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x63
#define LED_GPIO 17
#define LED_CHIP "gpiochip0"
#define PRESSURE_THRESHOLD 95000.0f
#define HIGH_ACCURACY_CMD 0x4011
#define OTP_REG 0x66
#define OTP_DATA_LEN 4

// Global variables
int i2c_fd = -1;
struct gpiod_chip *led_chip = NULL;
struct gpiod_line *led_line = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int32_t c0, c1, c00, c10;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t val);
int read_calibration_data(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
int verify_crc(uint8_t *data);
int32_t convert_pressure(uint32_t raw_pressure, uint32_t raw_temperature);
float convert_temperature(uint32_t raw_temperature);
void control_led(struct gpiod_line *led_line, int frequency);
void signal_handler(int sig);
void cleanup();

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = val;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read calibration data from OTP memory
int read_calibration_data(int fd) {
    uint8_t data[OTP_DATA_LEN];
    if (i2c_read_bytes(fd, OTP_REG, data, OTP_DATA_LEN) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    c0 = (data[0] << 8) | data[1];
    c1 = (data[2] << 8) | data[3];

    // Read c00 and c10 from registers 0x68 and 0x6A
    if (i2c_read_bytes(fd, 0x68, (uint8_t *)&c00, 2) != 0) {
        fprintf(stderr, "Failed to read c00\n");
        return -1;
    }
    if (i2c_read_bytes(fd, 0x6A, (uint8_t *)&c10, 2) != 0) {
        fprintf(stderr, "Failed to read c10\n");
        return -1;
    }

    return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_byte(fd, 0x00, HIGH_ACCURACY_CMD >> 8) != 0) return -1;
    if (i2c_write_byte(fd, 0x01, HIGH_ACCURACY_CMD & 0xFF) != 0) return -1;
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

// Verify CRC
int verify_crc(uint8_t *data) {
    uint8_t crc = 0;
    for (int i = 0; i < 5; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[5]);
}

// Convert raw pressure to Pascals
int32_t convert_pressure(uint32_t raw_pressure, uint32_t raw_temperature) {
    int32_t p = 0;
    // Placeholder for actual conversion formula from datasheet
    // This is a simplified example and needs to be replaced with the correct formula
    p = (int32_t)((raw_pressure - 32768) * 100); // Example conversion
    return p;
}

// Convert raw temperature to Celsius
float convert_temperature(uint32_t raw_temperature) {
    float t = 0.0f;
    // Placeholder for actual conversion formula from datasheet
    // This is a simplified example and needs to be replaced with the correct formula
    t = (float)(raw_temperature - 32768) / 100.0f; // Example conversion
    return t;
}

// Control LED blinking frequency
void control_led(struct gpiod_line *led_line, int frequency) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
    off_time.tv_sec = 0;
    off_time.tv_nsec = 500 * 1000 * 1000; // 500 ms

    if (frequency == 1) {
        off_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
    } else if (frequency == 5) {
        on_time.tv_nsec = 100 * 1000 * 1000; // 100 ms
        off_time.tv_nsec = 100 * 1000 * 1000; // 100 ms
    }

    while (!terminate) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Failed to set LED value");
            break;
        }
        nanosleep(&on_time, NULL);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Failed to set LED value");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data, exiting\n");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "pressure_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        uint32_t raw_pressure, raw_temperature;
        int32_t pressure;
        float temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete (20 ms)
        usleep(20000);

        // Read sensor data
        if (read_sensor_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Verify CRC
        if (!verify_crc(data)) {
            fprintf(stderr, "CRC verification failed\n");
            continue;
        }

        // Extract raw pressure and temperature
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        // Convert to Pascals and Celsius
        pressure = convert_pressure(raw_pressure, raw_temperature);
        temperature = convert_temperature(raw_temperature);

        printf("Pressure: %d Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < PRESSURE_THRESHOLD) {
            control_led(led_line, 5); // Blink at 5 Hz
        } else {
            control_led(led_line, 1); // Blink at 1 Hz
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

