    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
    off_time.tv_sec = 0;
    off_time.tv_nsec = 500 * 1000 * 1000; // 500 ms

    if (frequency == 1) {
        off_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
    } else if (frequency == 5) {
        on_time.tv_nsec = 100 * 1000 * 1000; // 100 ms
        off_time.tv_nsec = 100 * 1000 * 1000; // 100 ms
    }

    while (!terminate) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Failed to set LED value");
            break;
        }
        nanosleep(&on_time, NULL);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Failed to set LED value");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data, exiting\n");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "pressure_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        uint32_t raw_pressure, raw_temperature;
        int32_t pressure;
        float temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete (20 ms)
        usleep(20000);

        // Read sensor data
        if (read_sensor_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Verify CRC
        if (!verify_crc(data)) {
            fprintf(stderr, "CRC verification failed\n");
            continue;
        }

        // Extract raw pressure and temperature
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        // Convert to Pascals and Celsius
        pressure = convert_pressure(raw_pressure, raw_temperature);
        temperature = convert_temperature(raw_temperature);

        printf("Pressure: %d Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < PRESSURE_THRESHOLD) {
            control_led(led_line, 5); // Blink at 5 Hz
        } else {
            control_led(led_line, 1); // Blink at 1 Hz
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

