#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

int i2c_handle;
int server_fd;

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND, 0) != 0) {
            fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned short raw_temperature = (data[0] << 8) | data[1];
        unsigned short raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
        *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to format temperature and humidity into an HTML string
char *format_html(float temperature, float humidity) {
    char *html = malloc(256); // Allocate memory for the HTML string
    if (html == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTML string.\n");
        return NULL;
    }
    snprintf(html, 256, "<html><body><h1>Temperature: %.2f C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
    return html;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (1) {
        // Accept connection
        int new_socket = accept(server_fd, (struct sockaddr *)NULL, NULL);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for connections
        }

        // Read temperature and humidity
        float temperature, humidity;
        if (read_sht40(&temperature, &humidity) == 0) {
            // Format data into HTML
            char *html = format_html(temperature, humidity);
            if (html != NULL) {
                // Send HTTP response
                char response[512];
                snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n%s", html);
                send(new_socket, response, strlen(response), 0);
                free(html);
            } else {
                const char *error_html = "<html><body><h1>Error: Failed to format data.</h1></body></html>";
                send(new_socket, error_html, strlen(error_html), 0);
            }
        } else {
            const char *error_html = "<html><body><h1>Error: Failed to read sensor data.</h1></body></html>";
            send(new_socket, error_html, strlen(error_html), 0);
        }

        // Close connection
        close(new_socket);
    }

    // Cleanup (should not reach here, signal handler will do this)
    i2cClose(i2c_handle);
    close(server_fd);
    gpioTerminate();
    return 0;
}

