        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    *raw_temp = (buf[0] << 8) | buf[1];

    // Apply two's complement if negative
    if (*raw_temp & 0x8000) {
        *raw_temp = -*raw_temp;
    }

    // Shift right by 4 bits to get the 12-bit value
    *raw_temp >>= 4;

    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return raw_temp * TEMP_SCALE;
}

