    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    int raw_temp;
    float celsius;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&raw_temp) == 0) {
            // Convert to Celsius
            celsius = convert_to_celsius(raw_temp);

            // Log temperature
            if (log_temperature(celsius) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Wait for 5 seconds
        gpioDelay(READ_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

