#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 Registers
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMPERATURE_MSB 0x00
#define TEMPERATURE_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor: Heater disabled, 14-bit resolution
    if (i2cWriteByteData(i2c_handle, CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw temperature and humidity data
int read_raw_data(uint16_t *temperature, uint16_t *humidity) {
    char buf[4];

    if (i2cReadI2CBlockData(i2c_handle, TEMPERATURE_MSB, buf, 4) != 4) {
        fprintf(stderr, "Error reading data from sensor: %d\n", i2c_handle);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert raw data to temperature and humidity
void convert_data(uint16_t raw_temperature, uint16_t raw_humidity, float *temperature, float *humidity) {
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;
}

// Function to log temperature and humidity data
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() < 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Trigger measurement
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Retry
        }

        // Wait for measurement to complete (with timeout)
        int timeout_count = 0;
        while (i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG) & 0x01) {
            gpioDelay(10); // Wait 10 ms
            timeout_count++;
            if (timeout_count > 50) { // 50 * 10 ms = 500 ms timeout
                fprintf(stderr, "Measurement timeout\n");
                break; // Exit loop, retry
            }
        }

        if (timeout_count > 50) {
            continue; // Retry
        }

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_humidity) < 0) {
            fprintf(stderr, "Failed to read raw data\n");
            continue; // Retry
        }

        // Convert data
        convert_data(raw_temperature, raw_humidity, &temperature, &humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000); // 5000 ms = 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

