#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int write_i2c(int handle, uint8_t *data, int count);
int read_i2c(int handle, uint8_t *data, int count);
int crc8(const uint8_t *data, int len);
int verify_crc(const uint8_t *data, int len);
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c(int handle, uint8_t *data, int count) {
    int result = i2cWriteDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC checksum
int verify_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data = {0, 0};
    uint8_t raw_data[6];
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};

    // Send measurement command
    if (write_i2c(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return data; // Return default values
    }

    // Wait for measurement to complete (45ms)
    gpioDelay(45000); // Delay in microseconds

    // Read sensor data
    if (read_i2c(i2c_handle, raw_data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return data; // Return default values
    }

    // Verify CRC checksums
    if (!verify_crc(raw_data, 3) || !verify_crc(raw_data + 3, 3)) {
        fprintf(stderr, "CRC checksum verification failed\n");
        return data; // Return default values
    }

    // Extract pressure and temperature values
    data.pressure = (raw_data[0] << 8) | raw_data[1];
    data.temperature = (raw_data[3] << 8) | raw_data[4];

    return data;
}

// Log sensor data
void log_data(sensor_data_t data) {
    printf("Pressure: %d Pa, Temperature: %d C\n", data.pressure, data.temperature);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c(I2C_BUS, SDP800_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();
        log_data(sensor_data);
        gpioDelay(SLEEP_MS * 1000); // Delay in microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

