sensor_data_t read_sensor_data() {
    sensor_data_t data = {0, 0};
    uint8_t raw_data[6];
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};

    // Send measurement command
    if (write_i2c(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return data; // Return default values
    }

    // Wait for measurement to complete (45ms)
    gpioDelay(45000); // Delay in microseconds

    // Read sensor data
    if (read_i2c(i2c_handle, raw_data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return data; // Return default values
    }

    // Verify CRC checksums
    if (!verify_crc(raw_data, 3) || !verify_crc(raw_data + 3, 3)) {
        fprintf(stderr, "CRC checksum verification failed\n");
        return data; // Return default values
    }

    // Extract pressure and temperature values
    data.pressure = (raw_data[0] << 8) | raw_data[1];
    data.temperature = (raw_data[3] << 8) | raw_data[4];

    return data;
}

// Log sensor data
void log_data(sensor_data_t data) {
    printf("Pressure: %d Pa, Temperature: %d C\n", data.pressure, data.temperature);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c(I2C_BUS, SDP800_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();
        log_data(sensor_data);
        gpioDelay(SLEEP_MS * 1000); // Delay in microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

