#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define TARGET_PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for target temperature profile
typedef struct {
    int time_seconds;
    float target_temp_celsius;
} TargetProfile;

// Function Prototypes
int read_max6675(int spi_handle, float *temperature);
int read_target_profile(const char *filename, TargetProfile **profile, int *profile_size);
float pid_control(float setpoint, float actual_temp, float *integral, float *previous_error);
void set_relay_duty_cycle(int gpio_pin, float duty_cycle);
void log_data(FILE *log_file, float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    unsigned char tx_buf[2] = {0x00, 0x00};
    unsigned char rx_buf[2];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract temperature data (bits 3-14)
    int raw_temp = ((rx_buf[0] & 0x03) << 8) | rx_buf[1];

    // Check for open circuit
    if (raw_temp & 0x04) {
        fprintf(stderr, "Error: Thermocouple open circuit\n");
        return -1;
    }

    // Convert to Celsius (0.25 degrees per bit)
    *temperature = (float)raw_temp * 0.25;

    return 0;
}

// Function to read target temperature profile from file
int read_target_profile(const char *filename, TargetProfile **profile, int *profile_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open target profile file\n");
        return -1;
    }

    char line[256];
    *profile_size = 0;
    *profile = NULL;

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse time and temperature
        char *token = strtok(line, ",");
        if (token != NULL) {
            int time_seconds = atoi(token);
            token = strtok(NULL, ",");
            if (token != NULL) {
                float target_temp_celsius = atof(token);

                // Allocate memory for the profile
                TargetProfile *new_profile = realloc(*profile, (*profile_size + 1) * sizeof(TargetProfile));
                if (new_profile == NULL) {
                    fprintf(stderr, "Error: Memory allocation failed\n");
                    fclose(fp);
                    free(*profile);
                    return -1;
                }
                *profile = new_profile;

                // Store the time and temperature
                (*profile)[*profile_size].time_seconds = time_seconds;
                (*profile)[*profile_size].target_temp_celsius = target_temp_celsius;
                (*profile_size)++;
            } else {
                fprintf(stderr, "Error: Invalid target profile format\n");
                fclose(fp);
                free(*profile);
                return -1;
            }
        } else {
            fprintf(stderr, "Error: Invalid target profile format\n");
            fclose(fp);
            free(*profile);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to calculate PID output
float pid_control(float setpoint, float actual_temp, float *integral, float *previous_error) {
    float error = setpoint - actual_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp output to 0.0-1.0 range
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the solid-state relay duty cycle
void set_relay_duty_cycle(int gpio_pin, float duty_cycle) {
    // In a real application, you would use PWM to control the duty cycle.
    // This example just sets the GPIO pin high or low based on the duty cycle.
    if (duty_cycle > 0.5) {
        gpioWrite(gpio_pin, 1); // Turn on the relay
    } else {
        gpioWrite(gpio_pin, 0); // Turn off the relay
    }
}

// Function to log data to CSV file
void log_data(FILE *log_file, float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off the relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn off the relay

    // Read target temperature profile
    TargetProfile *target_profile = NULL;
    int target_profile_size = 0;
    if (read_target_profile(TARGET_PROFILE_FILE, &target_profile, &target_profile_size) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // PID variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Main loop
    time_t start_time = time(NULL);
    int current_profile_index = 0;
    while (!terminate) {
        // Get current time
        time_t current_time = time(NULL);
        int elapsed_time = (int)(current_time - start_time);

        // Check if we need to update the target temperature
        while (current_profile_index < target_profile_size && target_profile[current_profile_index].time_seconds <= elapsed_time) {
            // Update the target temperature
            // In a real application, you would update the PID setpoint here
            // For this example, we just print the target temperature
            printf("Target temperature: %.2f C\n", target_profile[current_profile_index].target_temp_celsius);
            current_profile_index++;
        }

        // Read temperature from MAX6675
        float temperature;
        if (read_max6675(spi_handle, &temperature) == 0) {
            // Calculate PID output
            float duty_cycle = pid_control(target_profile[current_profile_index].target_temp_celsius, temperature, &integral, &previous_error);

            // Set relay duty cycle
            set_relay_duty_cycle(RELAY_GPIO, duty_cycle);

            // Log data
            log_data(log_file, temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        // Wait for the next sample period
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    free(target_profile);
    cleanup();
    return 0;
}

