#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SENSOR_ID_1 "28-0316994d66ff"
#define SENSOR_ID_2 "28-0316994d66ff" // Replace with the second sensor ID
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define LOG_FILE "greenhouse.log"
#define SETPOINT_DEFAULT 25.0
#define Kp_DEFAULT 1.0
#define Ki_DEFAULT 0.1
#define Kd_DEFAULT 0.01

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float setpoint = SETPOINT_DEFAULT;
static float Kp = Kp_DEFAULT;
static float Ki = Ki_DEFAULT;
static float Kd = Kd_DEFAULT;

// Function prototypes
float read_temperature(const char *sensor_id);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_heater(float pid_output);
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int crc8(const unsigned char *data, int len);

// CRC-8 calculation (Dallas Semiconductor)
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x18;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from DS18B20 sensor
float read_temperature(const char *sensor_id) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s\n", path);
        return -1000.0; // Indicate error
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from %s\n", path);
        fclose(fp);
        return -1000.0; // Indicate error
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Error: CRC check failed for sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Could not find temperature in %s\n", path);
        return -1000.0; // Indicate error
    }

    long temperature_milli = strtol(temp_str + 2, NULL, 10);
    return (float)temperature_milli / 1000.0;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the heater (relay and PWM)
void set_heater(float pid_output) {
    int duty_cycle = (int)(pid_output * PWM_RANGE); // Scale PID output to PWM range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(PWM_GPIO, duty_cycle);
    if (duty_cycle > 0) {
        gpioWrite(HEATER_GPIO, 1); // Enable relay
    } else {
        gpioWrite(HEATER_GPIO, 0); // Disable relay
    }
}

// Function to log data to file
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc == 5) {
        setpoint = atof(argv[1]);
        Kp = atof(argv[2]);
        Ki = atof(argv[3]);
        Kd = atof(argv[4]);
    } else {
        printf("Using default values: Setpoint=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n", SETPOINT_DEFAULT, Kp_DEFAULT, Ki_DEFAULT, Kd_DEFAULT);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float integral = 0.0;
    float previous_error = 0.0;
    float temperature1, temperature2, average_temperature;
    float pid_output;
    int pwm_duty_cycle;

    // Main loop
    while (running) {
        // Read temperatures from sensors
        temperature1 = read_temperature(SENSOR_ID_1);
        temperature2 = read_temperature(SENSOR_ID_2);

        if (temperature1 < -999.0 || temperature2 < -999.0) {
            fprintf(stderr, "Error: Could not read temperature from one or more sensors\n");
        } else {
            // Calculate average temperature
            average_temperature = (temperature1 + temperature2) / 2.0;

            // Calculate PID output
            pid_output = calculate_pid(setpoint, average_temperature, &integral, &previous_error);

            // Set heater
            set_heater(pid_output);
            pwm_duty_cycle = gpioGetPWMdutycycle(PWM_GPIO);

            // Log data
            log_data(average_temperature, setpoint, pid_output, pwm_duty_cycle);
        }

        sleep(5);
