#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define POLLING_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_read_data(float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// AHT20 Initialization Sequence
int aht20_init() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed (write): %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for initialization to complete
    return 0;
}

// AHT20 Data Reading Function
int aht20_read_data(float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    char data[6];
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Send measurement trigger command
        if (i2cWriteDevice(i2c_handle, trigger_cmd, 3) != 0) {
            fprintf(stderr, "Error: Failed to send measurement trigger command (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS); // Wait for measurement to complete

        // Read 6 bytes of data
        int bytes_read = i2cReadDevice(i2c_handle, data, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error: Failed to read data (attempt %d, read %d bytes)\n", retries + 1, bytes_read);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        // Check status byte
        status = (data[0] & 0x80);
        if (status != 0) {
            fprintf(stderr, "Error: AHT20 busy or not calibrated (status byte: 0x%02X)\n", data[0]);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
            continue;
        }

        // Calculate humidity
        uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = ((float)raw_humidity / 0x100000) * 100;

        return 0; // Success
    }

    fprintf(stderr, "Error: AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Dehumidifier Control Function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Data Logging Function
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code: %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for dehumidifier relay
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure relay is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;

    // Main loop
    while (!terminate) {
        if (aht20_read_data(&humidity) == 0) {
            log_data(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Error: Failed to read humidity data\n");
        }

        gpioDelay(POLLING_INTERVAL_S * 1000); // Poll every 5 seconds
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

