#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char val);
int htu21d_read_humidity(int fd);
int htu21d_read_temperature(int fd);
int calculate_crc(unsigned char data[], int nbrOfBytes);
int post_data(int socket_fd, float humidity);
void signal_handler(int sig);
void cleanup();

// I2C read function with retry and CRC check
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 0;
    int result;
    unsigned char write_buf[1] = {reg};

    while (retries < MAX_RETRIES) {
        if (write(fd, write_buf, 1) != 1) {
            syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (read(fd, buf, len) == len) {
            // CRC Check
            unsigned char crc = calculate_crc(buf, len - 1);
            if (crc == buf[len - 1]) {
                return 0; // Success
            } else {
                syslog(LOG_ERR, "CRC check failed for I2C read.");
                retries++;
                sleep(RETRY_DELAY_SEC);
                continue;
            }
        } else {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }
    }

    syslog(LOG_ERR, "I2C read failed after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    int retries = 0;
    unsigned char buf[2] = {reg, val};

    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
        }
    }

    syslog(LOG_ERR, "I2C write failed after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// HTU21D read humidity function
int htu21d_read_humidity(int fd) {
    unsigned char buf[3];
    int humidity_raw;

    if (i2c_write_byte(fd, 0xE5, 0x00) != 0) { // Trigger humidity measurement
        syslog(LOG_ERR, "Failed to trigger humidity measurement.");
        return -1;
    }

    sleep(0.05); // Wait for measurement (datasheet specifies 50ms)

    if (i2c_read_bytes(fd, 0xE5, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read humidity data.");
        return -1;
    }

    humidity_raw = (buf[0] << 8) | buf[1];
    humidity_raw &= 0xFFFC; // Clear status bits
    return humidity_raw;
}

// HTU21D read temperature function
int htu21d_read_temperature(int fd) {
    unsigned char buf[3];
    int temperature_raw;

    if (i2c_write_byte(fd, 0xE3, 0x00) != 0) { // Trigger temperature measurement
        syslog(LOG_ERR, "Failed to trigger temperature measurement.");
        return -1;
    }

    sleep(0.05); // Wait for measurement (datasheet specifies 50ms)

    if (i2c_read_bytes(fd, 0xE3, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read temperature data.");
        return -1;
    }

    temperature_raw = (buf[0] << 8) | buf[1];
    temperature_raw &= 0xFFFC; // Clear status bits
    return temperature_raw;
}

// CRC calculation function
int calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = 0;
    unsigned char bit;

    for (int byteCtr = 0; byteCtr < nbrOfBytes; ++byteCtr) {
        crc ^= (data[byteCtr]);
        for (int bitCtr = 8; bitCtr; --bitCtr) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// HTTP POST function
int post_data(int socket_fd, float humidity) {
    char json_data[100];
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming HTTP port
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) { // Replace with API endpoint IP
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        return -1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        return -1;
    }

    char request[200];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s", strlen(json_data), json_data);

    if (send(socket_fd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        return -1;
    }

    char response[1024];
    ssize_t bytes_received = recv(socket_fd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        return -1;
    }
    response[bytes_received] = '\0';
    syslog(LOG_INFO, "HTTP Response: %s", response);

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
