// I2C read function with retry and CRC check
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 0;
    int result;
    unsigned char write_buf[1] = {reg};

    while (retries < MAX_RETRIES) {
        if (write(fd, write_buf, 1) != 1) {
            syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (read(fd, buf, len) == len) {
            // CRC Check
            unsigned char crc = calculate_crc(buf, len - 1);
            if (crc == buf[len - 1]) {
                return 0; // Success
            } else {
                syslog(LOG_ERR, "CRC check failed for I2C read.");
                retries++;
                sleep(RETRY_DELAY_SEC);
                continue;
            }
        } else {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }
    }

    syslog(LOG_ERR, "I2C read failed after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    int retries = 0;
    unsigned char buf[2] = {reg, val};

    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
        }
    }

    syslog(LOG_ERR, "I2C write failed after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// HTU21D read humidity function
int htu21d_read_humidity(int fd) {
    unsigned char buf[3];
    int humidity_raw;

    if (i2c_write_byte(fd, 0xE5, 0x00) != 0) { // Trigger humidity measurement
        syslog(LOG_ERR, "Failed to trigger humidity measurement.");
        return -1;
    }

    sleep(0.05); // Wait for measurement (datasheet specifies 50ms)

    if (i2c_read_bytes(fd, 0xE5, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read humidity data.");
        return -1;
    }

    humidity_raw = (buf[0] << 8) | buf[1];
    humidity_raw &= 0xFFFC; // Clear status bits
    return humidity_raw;
}

// HTU21D read temperature function
int htu21d_read_temperature(int fd) {
    unsigned char buf[3];
    int temperature_raw;

    if (i2c_write_byte(fd, 0xE3, 0x00) != 0) { // Trigger temperature measurement
        syslog(LOG_ERR, "Failed to trigger temperature measurement.");
        return -1;
