        return -1;
    }

    char request[200];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s", strlen(json_data), json_data);

