        }

        gpioDelay(10); // Wait for conversion

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            double temperature = compensate_temperature(raw_temperature, calib);
            pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

            // Log pressure breaches
            if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
                log_pressure_breach(pressure);
            }

            printf("Pressure: %.2f hPa\n", pressure);
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        gpioDelay(2000); // Sample every 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
