// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 2

// Define motor run time
#define MOTOR_RUN_TIME 5 // seconds

// Global variables for GPIO file descriptors
int rain_sensor_fd = -1;
int motor_ena_fd = -1;
int motor_in1_fd = -1;
int motor_in2_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
int read_rain_sensor();
void control_motor(int direction, int duration);
void log_event(const char *message);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received signal, shutting down...");
        // Stop the motor
        control_motor(MOTOR_STOP, 0);

        // Unexport GPIO pins
        gpio_unexport(RAIN_SENSOR_PIN);
