// Function to read the rain sensor value
int read_rain_sensor() {
    int value = gpio_get_value(RAIN_SENSOR_PIN);
    if (value < 0) {
        log_event("Error reading rain sensor value");
        return -1; // Indicate an error
    }
    return value;
}

// Function to control the motor
void control_motor(int direction, int duration) {
    char message[128];

    if (direction == MOTOR_FORWARD) {
        snprintf(message, sizeof(message), "Motor running forward for %d seconds", duration);
        log_event(message);

        // Set motor direction
        if (gpio_set_value(MOTOR_IN1_PIN, 1) < 0) {
            log_event("Error setting IN1 pin");
        }
        if (gpio_set_value(MOTOR_IN2_PIN, 0) < 0) {
            log_event("Error setting IN2 pin");
        }

        // Enable the motor
        if (gpio_set_value(MOTOR_ENA_PIN, 1) < 0) {
            log_event("Error setting ENA pin");
        }

        // Wait for the specified duration
        sleep(duration);

        // Stop the motor
        if (gpio_set_value(MOTOR_ENA_PIN, 0) < 0) {
            log_event("Error setting ENA pin");
        }

        log_event("Motor stopped");
    } else if (direction == MOTOR_REVERSE) {
        snprintf(message, sizeof(message), "Motor running reverse for %d seconds", duration);
        log_event(message);

        // Set motor direction
        if (gpio_set_value(MOTOR_IN1_PIN, 0) < 0) {
            log_event("Error setting IN1 pin");
        }
        if (gpio_set_value(MOTOR_IN2_PIN, 1) < 0) {
            log_event("Error setting IN2 pin");
        }

        // Enable the motor
        if (gpio_set_value(MOTOR_ENA_PIN, 1) < 0) {
            log_event("Error setting ENA pin");
        }

        // Wait for the specified duration
        sleep(duration);

        // Stop the motor
        if (gpio_set_value(MOTOR_ENA_PIN, 0) < 0) {
            log_event("Error setting ENA pin");
        }

        log_event("Motor stopped");
    } else if (direction == MOTOR_STOP) {
        log_event("Motor stopping immediately");
        // Stop the motor
        if (gpio_set_value(MOTOR_ENA_PIN, 0) < 0) {
            log_event("Error setting ENA pin");
        }
        log_event("Motor stopped");
    } else {
        log_event("Invalid motor direction");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(RAIN_SENSOR_PIN) < 0 ||
        gpio_export(MOTOR_ENA_PIN) < 0 ||
        gpio_export(MOTOR_IN1_PIN) < 0 ||
        gpio_export(MOTOR_IN2_PIN) < 0) {
        log_event("Failed to export GPIO pins. Exiting.");
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(RAIN_SENSOR_PIN, "in") < 0 ||
        gpio_set_direction(MOTOR_ENA_PIN, "out") < 0 ||
        gpio_set_direction(MOTOR_IN1_PIN, "out") < 0 ||
        gpio_set_direction(MOTOR_IN2_PIN, "out") < 0) {
        log_event("Failed to set GPIO directions. Exiting.");
        gpio_unexport(RAIN_SENSOR_PIN);
        gpio_unexport(MOTOR_ENA_PIN);
        gpio_unexport(MOTOR_IN1_PIN);
        gpio_unexport(MOTOR_IN2_PIN);
        return 1;
    }

    // Initialize motor to stopped state
    if (gpio_set_value(MOTOR_ENA_PIN, 0) < 0) {
        log_event("Failed to initialize motor. Exiting.");
        gpio_unexport(RAIN_SENSOR_PIN);
        gpio_unexport(MOTOR_ENA_PIN);
        gpio_unexport(MOTOR_IN1_PIN);
        gpio_unexport(MOTOR_IN2_PIN);
        return 1;
    }

    log_event("Rain sensor monitoring started");

    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            log_event("Rain detected!");
            control_motor(MOTOR_FORWARD, MOTOR_RUN_TIME);
        } else if (rain_detected < 0) {
            log_event("Error reading rain sensor, exiting");
            break;
        }

        sleep(2);
    }

    // Unexport GPIO pins before exiting
    gpio_unexport(RAIN_SENSOR_PIN);
    gpio_unexport(MOTOR_ENA_PIN);
    gpio_unexport(MOTOR_IN1_PIN);
    gpio_unexport(MOTOR_IN2_PIN);

    return 0;
}

