#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU stat file path
#define CPU_STAT_FILE "/proc/stat"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_stat();
float calculate_cpu_load(int prev_idle, int prev_non_idle, int curr_idle, int curr_non_idle);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stat() {
    FILE *fp;
    char line[256];
    int user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;

    // Read CPU stats from file
    fp = fopen(CPU_STAT_FILE, "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    // Read the first line (CPU stats)
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    // Parse the line
    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d %d %d",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Read CPU stats again to get current values
    fp = fopen(CPU_STAT_FILE, "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d %d %d",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return (user - prev_user) + (nice - prev_nice) + (system - prev_system) + (steal - prev_steal);
}

// Function to calculate CPU load
float calculate_cpu_load(int prev_idle, int prev_non_idle, int curr_idle, int curr_non_idle) {
    int prev_total = prev_idle + prev_non_idle;
    int curr_total = curr_idle + curr_non_idle;

    if (prev_total == curr_total) {
        return 0.0; // Avoid division by zero
    }

    return (float)(curr_total - prev_total) / (float)(curr_total - prev_total + curr_idle - prev_idle);
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Common-anode LED: 0 = fully on, 255 = fully off
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int prev_idle, prev_non_idle, curr_idle, curr_non_idle;
    float cpu_load;
    int red, green, blue;

    // Initial CPU stat read
    prev_idle = read_cpu_stat();
    prev_non_idle = read_cpu_stat();

    // Main loop
    while (program_running) {
        // Read CPU stats
        curr_idle = read_cpu_stat();
        curr_non_idle = read_cpu_stat();

        if (curr_idle == -1 || curr_non_idle == -1) {
            fprintf(stderr, "Error reading CPU stats, exiting...\n");
            break;
        }

        // Calculate CPU load
        cpu_load = calculate_cpu_load(prev_idle, prev_non_idle, curr_idle, curr_non_idle);

        // Map CPU load to color gradient
        if (cpu_load <= 0.5) {
            // Green to Yellow
            green = (int)(cpu_load * 255 * 2);
            red = 0;
            blue = 255 - green;
        } else {
            // Yellow to Red
            red = (int)((cpu_load - 0.5) * 255 * 2);
            green = 255 - red;
            blue = 0;
        }

        // Clamp values to 0-255 range
        red = (red < 0) ? 0 : (red > 255) ? 255 : red;
        green = (green < 0) ? 0 : (green > 255) ? 255 : green;
        blue = (blue < 0) ? 0 : (blue > 255) ? 255 : blue;

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous values
        prev_idle = curr_idle;
        prev_non_idle = curr_non_idle;

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up and exit
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    return 0;
}

