#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} log_entry_t;

// Circular buffer
log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, uint32_t *data);
float extract_temperature(uint32_t data);
int check_fault(uint32_t data);
int calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read data from MAX31855 via SPI
int read_max31855(int spi_handle, uint32_t *data) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    *data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];
    return 0;
}

// Function to extract thermocouple temperature from the 32-bit data
float extract_temperature(uint32_t data) {
    int16_t raw_temp = (data >> 18) & 0x3FFF; // Extract 14-bit temperature
    if (data & (1 << 16)) {
        raw_temp |= 0xC000; // Sign extend if negative
    }
    return raw_temp * 0.25;
}

// Function to check for MAX31855 faults
int check_fault(uint32_t data) {
    if (data & (1 << 16)) {
        fprintf(stderr, "MAX31855 Fault: ");
        if (data & (1 << 0)) fprintf(stderr, "OC ");
        if (data & (1 << 1)) fprintf(stderr, "SCG ");
        if (data & (1 << 2)) fprintf(stderr, "SCV ");
        fprintf(stderr, "\n");
        return -1;
    }
    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0) {
        return 0;
    } else if (temperature < 40.0) {
        return (int)((temperature - 25.0) * 50.0 / 15.0);
    } else if (temperature < 60.0) {
        return (int)((temperature - 40.0) * 150.0 / 20.0 + 50.0);
    } else {
        return 255;
    }
}

// Function to update fan speed using hardware PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%d] Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n", index, timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint32_t raw_data;
    float temperature;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature data from MAX31855
        if (read_max31855(spi_handle, &raw_data) == 0) {
            // Check for faults
            if (check_fault(raw_data) == 0) {
                // Extract temperature
                temperature = extract_temperature(raw_data);

                // Calculate duty cycle
                duty_cycle = calculate_duty_cycle(temperature);

                // Update fan speed
                update_fan_speed(duty_cycle);

                // Log data
                log_data(temperature, duty_cycle);

                printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
            } else {
                // Fault detected, skip fan update
                fprintf(stderr, "Skipping fan update due to MAX31855 fault\n");
            }
        } else {
            // SPI transfer error, skip fan update
            fprintf(stderr, "Skipping fan update due to SPI error\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Print log buffer
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

