#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// MAX31865 Configuration Values
#define MAX31865_CONFIG_DEFAULT 0xC2 // 3-wire, bias enabled, 50/60 Hz filter

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int cs_init(void);
int read_register(uint8_t reg, uint16_t *value);
int write_register(uint8_t reg, uint16_t value);
float calculate_temperature(uint16_t rtd_value);
int log_data(float temperature);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
  spi_fd = open(SPI_DEVICE, O_RDWR);
  if (spi_fd < 0) {
    perror("Error opening SPI device");
    return -1;
  }

  // Configure SPI mode
  uint8_t mode = SPI_MODE_0;
  if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
    perror("Error setting SPI mode");
    close(spi_fd);
    return -1;
  }

  // Configure SPI speed
  uint32_t speed = SPI_SPEED;
  if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
    perror("Error setting SPI speed");
    close(spi_fd);
    return -1;
  }

  return 0;
}

// Chip Select Initialization
int cs_init(void) {
  chip = gpiod_chip_open_by_name("gpiochip0");
  if (!chip) {
    perror("Error opening GPIO chip");
    return -1;
  }

  cs_line = gpiod_chip_get_line(chip, CS_PIN);
  if (!cs_line) {
    perror("Error getting GPIO line");
    gpiod_chip_close(chip);
    return -1;
  }

  if (gpiod_line_request_output(cs_line, "rtd_monitor", 1) != 0) {
    perror("Error requesting GPIO line for output");
    gpiod_chip_close(chip);
    gpiod_line_release(cs_line);
    return -1;
  }

  return 0;
}

// Read a register from the MAX31865
int read_register(uint8_t reg, uint16_t *value) {
  uint8_t tx_buf[3];
  uint8_t rx_buf[3];
  struct spi_ioc_transfer transfer[1];

  tx_buf[0] = reg | 0x80; // Set MSB for read operation
  tx_buf[1] = 0x00;       // Dummy byte
  tx_buf[2] = 0x00;       // Dummy byte

  memset(transfer, 0, sizeof(transfer));

  transfer[0].tx_buf = (unsigned long)tx_buf;
  transfer[0].rx_buf = (unsigned long)rx_buf;
  transfer[0].len = 3;
  transfer[0].speed_hz = SPI_SPEED;
  transfer[0].bits_per_word = 8;

  gpiod_line_set_value(cs_line, 0); // Assert CS
  if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
    perror("Error reading SPI data");
    gpiod_line_set_value(cs_line, 1); // De-assert CS
    return -1;
  }
  gpiod_line_set_value(cs_line, 1); // De-assert CS

  *value = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];
  return 0;
}

// Write a register to the MAX31865
int write_register(uint8_t reg, uint16_t value) {
  uint8_t tx_buf[3];
  struct spi_ioc_transfer transfer[1];

  tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
  tx_buf[1] = (value >> 8) & 0xFF; // MSB
  tx_buf[2] = value & 0xFF;       // LSB

  memset(transfer, 0, sizeof(transfer));

  transfer[0].tx_buf = (unsigned long)tx_buf;
  transfer[0].rx_buf = (unsigned long)NULL; // No receive buffer
  transfer[0].len = 3;
  transfer[0].speed_hz = SPI_SPEED;
  transfer[0].bits_per_word = 8;

  gpiod_line_set_value(cs_line, 0); // Assert CS
  if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
    perror("Error writing SPI data");
    gpiod_line_set_value(cs_line, 1); // De-assert CS
    return -1;
  }
  gpiod_line_set_value(cs_line, 1); // De-assert CS

  return 0;
}

// Calculate temperature using the Callendar-Van Dusen equation
float calculate_temperature(uint16_t rtd_value) {
  // Constants for PT100 RTD
  const float A = -0.000000000001; // -1e-12
  const float B = 0.000000000001;  // 1e-12
  const float C = 0.000000000001;  // 1e-12
  const float R0 = 100.0;           // Resistance at 0°C
  const float RTD_NOMINAL = 100.0; // Nominal RTD resistance
  const float RREF = 430.0;         // Reference resistor value

