  float rtd_resistance = (float)rtd_value * RREF / 32768.0;

  // Calculate the temperature using the Callendar-Van Dusen equation
  float temperature = (rtd_resistance / R0 - 1) / (A + B * rtd_resistance + C * rtd_resistance * rtd_resistance);

  return temperature;
}

