  terminate = 1;
  printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup(void) {
  if (spi_fd != -1) {
    close(spi_fd);
  }
  if (cs_line) {
    gpiod_line_release(cs_line);
  }
  if (chip) {
    gpiod_chip_close(chip);
  }
  if (log_file) {
    fclose(log_file);
  }
}

int main() {
