#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 readings/second)
#define BUFFER_SIZE 1200

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
sensor_data_t *circular_buffer;
int buffer_index = 0;
int buffer_count = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss);
float calculate_pressure(int raw_temperature, int raw_pressure, const bmp180_calibration_data_t *calibration_data);
void add_to_circular_buffer(sensor_data_t *buffer, int buffer_size, time_t timestamp, float pressure, int *index, int *count);
float calculate_rolling_average(sensor_data_t *buffer, int buffer_size, int count);
void trigger_alert(int gpio_pin, float pressure, float rolling_average);
void timer_callback(void *userdata);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    uint8_t data[22];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0xAA, (char *)data, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration_data->ac1 = (data[0] << 8) | data[1];
    calibration_data->ac2 = (data[2] << 8) | data[3];
    calibration_data->ac3 = (data[4] << 8) | data[5];
    calibration_data->ac4 = (data[6] << 8) | data[7];
    calibration_data->ac5 = (data[8] << 8) | data[9];
    calibration_data->ac6 = (data[10] << 8) | data[11];
    calibration_data->b1 = (data[12] << 8) | data[13];
    calibration_data->b2 = (data[14] << 8) | data[15];
    calibration_data->mb = (data[16] << 8) | data[17];
    calibration_data->mc = (data[18] << 8) | data[19];
    calibration_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    int result;

    buf[0] = 0x2E; // Temperature measurement command
    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, buf[0]);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int i2c_handle, int oss) {
    char buf[3];
    int result;

    buf[0] = 0x34 + (oss << 6); // Pressure measurement command
    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, buf[0]);
    if (result != 0) {
        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - oss);
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temperature, int raw_pressure, const bmp180_calibration_data_t *calibration_data) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)calibration_data->ac6) * (long)calibration_data->ac5) >> 15;
    x1 = ((long)calibration_data->mc << 11) / (b5 + calibration_data->md);
    b6 = b5 + x1;
    x2 = ((long)calibration_data->b2 * ((b6 * b6) >> 12)) >> 11;
    x3 = ((long)calibration_data->ac2 * b6) >> 11;
    b3 = (((((long)calibration_data->ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((long)calibration_data->ac3 * b6) >> 13;
    x2 = ((long)calibration_data->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2 + 2) >> 2);
    b4 = ((unsigned long)calibration_data->ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (float)p / 100.0f; // Convert to hPa
}

// Function to add data to the circular buffer
void add_to_circular_buffer(sensor_data_t *buffer, int buffer_size, time_t timestamp, float pressure, int *index, int *count) {
    buffer[*index].timestamp = timestamp;
    buffer[*index].pressure = pressure;
    *index = (*index + 1) % buffer_size;
    if (*count < buffer_size) {
        *count += 1;
    }
}

// Function to calculate the rolling average of the last 60 seconds
float calculate_rolling_average(sensor_data_t *buffer, int buffer_size, int count) {
    if (count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += buffer[i].pressure;
    }
    return sum / count;
}

// Function to trigger an alert if the pressure deviates from the rolling average
void trigger_alert(int gpio_pin, float pressure, float rolling_average) {
    float difference = pressure - rolling_average;
    if (fabs(difference) > 5.0f) {
        gpioWrite(gpio_pin, 1); // Set GPIO HIGH
        printf("Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", pressure, rolling_average);
        gpioDelay(1000000); // Wait 1 second
        gpioWrite(gpio_pin, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback(void *userdata) {
    int raw_temperature, raw_pressure;
    float pressure, rolling_average;

    raw_temperature = read_raw_temperature(i2c_handle);
    if (raw_temperature == -1) {
        fprintf(stderr, "Error reading raw temperature, skipping sample.\n");
        return;
    }

    raw_pressure = read_raw_pressure(i2c_handle, OSS);
    if (raw_pressure == -1) {
        fprintf(stderr, "Error reading raw pressure, skipping sample.\n");
        return;
    }

    pressure = calculate_pressure(raw_temperature, raw_pressure, &calibration_data);

    time_t now = time(NULL);
    add_to_circular_buffer(circular_buffer, BUFFER_SIZE, now, pressure, &buffer_index, &buffer_count);

    rolling_average = calculate_rolling_average(circular_buffer, BUFFER_SIZE, buffer_count);
    trigger_alert(ALERT_GPIO, pressure, rolling_average);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

