// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 Registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration Data Registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting
#define OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
void log_data(double temperature, double pressure);
void timer_interrupt_handler();
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_16(int reg, int *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (read_16(BMP180_REG_MSB, raw_temperature) != 0) return -1;

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << OSS)) ; // Wait for conversion

    int msb, lsb, xlsb;
    if (read_16(BMP180_REG_MSB, &msb) != 0) return -1;
    if (read_16(BMP180_REG_LSB, &lsb) != 0) return -1;
    if (read_16(BMP180_REG_XLSB, &xlsb) != 0) return -1;

    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = ((long)ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((long)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)ac4 * (unsigned long)(X1_pressure + X2_pressure + 32768)) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    double calculated_pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return calculated_pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(log_file);
}

// Timer interrupt handler
void timer_interrupt_handler()
{
    int raw_temperature, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 500 ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

