#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < 40.0) {
        duty_cycle = 0;
    } else if (temperature > 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)((temperature - 40.0) / (70.0 - 40.0) * 255.0);
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    float temperature;
    int duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and PWM frequency
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider using a default temperature or previous value here
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);

            printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        }

        sleep(5);
    }

    // Clean up and exit
    gpioPWM(FAN_GPIO, 0); // Stop the fan
    gpioTerminate();       // Terminate pigpio
    printf("Fan control program stopped.\n");

    return 0;
}

