#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_ADDR_76 0x76
#define BMP280_ADDR_77 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_DATA_REG 0xF7
#define BMP280_STATUS_REG 0xF3

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1
#define BMP280_OVERSAMPLING_PRESS 1

// Global variables
int i2c_fd = -1;
int bmp280_address = BMP280_ADDR_76;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Calibration data
short dig_T1, dig_T2, dig_T3;
short dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int bmp280_init(int fd);
int bmp280_read_calibration_data(int fd);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Helper function to read a single byte from an I2C register
int i2c_read_reg(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Helper function to write a single byte to an I2C register
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the BMP280 sensor
int bmp280_init(int fd) {
    int chip_id = i2c_read_reg(fd, BMP280_CHIP_ID_REG);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    if (bmp280_read_calibration_data(fd) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    // Set forced mode with oversampling x1 for temperature and pressure
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write control register\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP280
int bmp280_read_calibration_data(int fd) {
    unsigned char data[24];
    for (int i = 0; i < 24; i++) {
        int value = i2c_read_reg(fd, 0x88 + i);
        if (value < 0) {
            return -1;
        }
        data[i] = (unsigned char)value;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (short)((data[3] << 8) | data[2]);
    dig_T3 = (short)((data[5] << 8) | data[4]);
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (short)((data[9] << 8) | data[8]);
    dig_P3 = (short)((data[11] << 8) | data[10]);
    dig_P4 = (short)((data[13] << 8) | data[12]);
    dig_P5 = (short)((data[15] << 8) | data[14]);
    dig_P6 = (short)((data[17] << 8) | data[16]);
    dig_P7 = (short)((data[19] << 8) | data[18]);
    dig_P8 = (short)((data[21] << 8) | data[20]);
    dig_P9 = (short)((data[23] << 8) | data[22]);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    unsigned char data[6];
    for (int i = 0; i < 6; i++) {
        int value = i2c_read_reg(fd, BMP280_DATA_REG + i);
        if (value < 0) {
            return -1;
        }
        data[i] = (unsigned char)value;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Function to compensate temperature using Bosch formula
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure using Bosch formula
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p / 100.0; // Convert to hPa
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Attempt to open BMP280 at address 0x76
    bmp280_address = BMP280_ADDR_76;
    if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        fprintf(stderr, "Trying address 0x77...\n");
        bmp280_address = BMP280_ADDR_77;
        if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            fprintf(stderr, "Failed to open BMP280 at both addresses.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    int status;

    // Main loop
    while (program_running) {
        // Read raw data
        status = bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure);
        if (status != 0) {
            fprintf(stderr, "Error reading raw data, attempting to re-initialize...\n");
            fprintf(stderr, "Trying address 0x76...\n");
            bmp280_address = BMP280_ADDR_76;
            if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
                perror("Failed to acquire bus access and/or talk to slave");
                fprintf(stderr, "Trying address 0x77...\n");
                bmp280_address = BMP280_ADDR_77;
                if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
                    perror("Failed to acquire bus access and/or talk to slave");
                    fprintf(stderr, "Failed to open BMP280 at both addresses.\n");
                    program_running = 0; // Exit loop if re-initialization fails
                    break;
                }
            }
            if (bmp280_init(i2c_fd) != 0) {
                fprintf(stderr, "Failed to re-initialize BMP280 sensor.\n");
                program_running = 0;
                break;
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // Compensate temperature and pressure
        temperature = bmp280_compensate_temperature(raw_temperature);
        pressure = bmp280_compensate_pressure(raw_pressure, temperature);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

