#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Data structure for temperature readings
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

// Circular buffer structure
typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static CircularBuffer temp_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void init_gpio();
void set_led(int on);
void add_reading(CircularBuffer *cb, float temperature);
float calculate_average(CircularBuffer *cb);
void *data_acquisition_thread(void *arg);
void signal_handler(int sig);
void cleanup();

// Helper function to get current timestamp
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    return buf;
}

// Initialize I2C bus
int init_i2c() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        i2c_fd = gpiod_i2c_open(I2C_BUS, LM75_ADDR, 0); // flags = 0
        if (i2c_fd >= 0) {
            printf("I2C initialized successfully.\n");
            return 0;
        } else {
            fprintf(stderr, "%s I2C initialization failed: %s. Retrying in %d ms.\n", get_timestamp(), strerror(errno), RETRY_DELAY_MS);
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    fprintf(stderr, "%s I2C initialization failed after multiple retries.\n", get_timestamp());
    return -1;
}

// Read temperature from LM75 sensor
int read_temperature(float *temperature) {
    unsigned char data[2];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = gpiod_i2c_read(i2c_fd, data, 2);
        if (result == 2) {
            // Convert raw data to temperature
            int16_t raw_temp = (data[0] << 8) | data[1];
            raw_temp = raw_temp >> 5; // Shift right by 5 bits
            *temperature = (float)raw_temp / 256.0;
            return 0; // Success
        } else {
            fprintf(stderr, "%s I2C read failed: %s. Retrying in %d ms.\n", get_timestamp(), strerror(errno), RETRY_DELAY_MS);
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    fprintf(stderr, "%s I2C read failed after multiple retries.\n", get_timestamp());
    return -1; // Failure
}

// Initialize GPIO pin for LED control
void init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "%s Failed to open GPIO chip: %s\n", get_timestamp(), strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "%s Failed to get GPIO line: %s\n", get_timestamp(), strerror(errno));
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "%s Failed to request GPIO line: %s\n", get_timestamp(), strerror(errno));
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    printf("GPIO initialized successfully.\n");
}

// Set LED state
void set_led(int on) {
    if (on) {
        gpiod_line_set_value(gpio_line, 1);
    } else {
        gpiod_line_set_value(gpio_line, 0);
    }
}

// Add a temperature reading to the circular buffer
void add_reading(CircularBuffer *cb, float temperature) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head].timestamp = time(NULL);
    cb->buffer[cb->head].temperature = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

// Calculate the average temperature from the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    pthread_mutex_lock(&cb->mutex);
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i].temperature;
    }
    pthread_mutex_unlock(&cb->mutex);
    return sum / cb->count;
}

// Data acquisition thread function
void *data_acquisition_thread(void *arg) {
    float temperature;

    while (running) {
        if (read_temperature(&temperature) == 0) {
            add_reading(&temp_buffer, temperature);
            float avg_temp = calculate_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, avg_temp);

            if (temperature > TEMP_THRESHOLD) {
                set_led(1);
            } else {
                set_led(0);
            }
        } else {
            fprintf(stderr, "%s Failed to read temperature.\n", get_timestamp());
        }
        sleep(1);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        gpiod_i2c_close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main() {
    // Initialize circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;
    pthread_mutex_init(&temp_buffer.mutex, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    init_gpio();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create data acquisition thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "%s Failed to create data acquisition thread: %s\n", get_timestamp(), strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Wait for the thread to finish (or signal to terminate)
    pthread_join(thread_id, NULL);

    // Cleanup resources before exiting
    cleanup();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

