void set_pwm_duty_cycle(int gpio, int duty_cycle);
void signal_handler(int signal);
int load_configuration(const char *filename);
void log_error(const char *message);

// SPI read function
int spi_read_register(int handle, unsigned char reg, unsigned char *data, int len) {
    char tx_buf[1];
    char rx_buf[len + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != 0) {
        log_error("SPI read failed");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI write function
int spi_write_register(int handle, unsigned char reg, unsigned char data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        log_error("SPI write failed");
        return -1;
    }

    return 0;
}

// Read RTD temperature function
double read_rtd_temperature(int handle) {
    unsigned char data[2];
    int rtd_code;
    double rtd_resistance;
    double temperature;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_read_register(handle, 0x01, data, 2) == 0) {
            rtd_code = (data[0] << 8) | data[1];
            rtd_code = rtd_code >> 1; // Remove fault bit

            // Check for faults
            if (data[0] & 0x01) {
                unsigned char fault_status;
                if (spi_read_register(handle, 0x07, &fault_status, 1) == 0) {
                    if (fault_status & 0x01) {
                        log_error("MAX31865 Fault: Open Circuit");
                        return NAN;
                    } else if (fault_status & 0x02) {
                        log_error("MAX31865 Fault: Short to GND");
                        return NAN;
                    } else if (fault_status & 0x04) {
                        log_error("MAX31865 Fault: Short to VCC");
                        return NAN;
                    } else if (fault_status & 0x08) {
                        log_error("MAX31865 Fault: Over/Under Voltage");
                        return NAN;
                    }
                } else {
                    log_error("Failed to read fault status");
                    return NAN;
                }
            }

            rtd_resistance = ((double)rtd_code / 32768.0) * R_REF;
            temperature = (rtd_resistance / R0 - 1) / A;

            // Callendar-Van Dusen equation for t >= 0
            if (temperature >= 0) {
                temperature = (rtd_resistance / R0 - 1) / A;
                temperature += (pow(temperature, 2) * B) / 2;
                temperature = 1.0 / temperature;
            } else {
                // Use the full Callendar-Van Dusen equation for t < 0
                temperature = (rtd_resistance / R0 - 1) / A;
                temperature += (pow(temperature, 2) * B) / 2;
                temperature = 1.0 / temperature;
            }

            return temperature;
        } else {
            log_error("Failed to read RTD code, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    log_error("Failed to read RTD temperature after multiple retries");
    return NAN;
}

// PID control function
double pid_control(double setpoint, double actual_temperature, double Kp, double Ki, double Kd, double *integral, double *previous_error, double last_time) {
    double current_time = time_time();
    double dt = current_time - last_time;
    if (dt == 0) dt = 0.01; // Avoid division by zero

    double error = setpoint - actual_temperature;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;

    double output = Kp * error + Ki * (*integral) + Kd * derivative;

    *previous_error = error;
    last_time = current_time;

    return output;
}

// Set PWM duty cycle function
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Signal handler function
