    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return -1;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (json_is_real(target_temp)) {
        target_temperature = json_real_value(target_temp);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (json_is_real(kp)) {
        Kp = json_real_value(kp);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (json_is_real(ki)) {
        Ki = json_real_value(ki);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (json_is_real(kd)) {
        Kd = json_real_value(kd);
    }

    json_decref(root);
    return 0;
}

// Log error function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode for heater control
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    if (spi_write_register(spi_handle, 0x80, 0xC1) != 0) {
        log_error("MAX31865 initialization failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load configuration
    if (load_configuration("config.json") != 0) {
        printf("Using default configuration.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double temperature = read_rtd_temperature(spi_handle);

        if (isnan(temperature)) {
            log_error("Invalid temperature reading, shutting down");
            set_pwm_duty_cycle(GPIO_HEATER, 0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        if (temperature > MAX_TEMP) {
