            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        double pid_output = pid_control(target_temperature, temperature, Kp, Ki, Kd, &integral, &previous_error, last_time);
        int duty_cycle = (int)pid_output;

        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        set_pwm_duty_cycle(GPIO_HEATER, duty_cycle);

