#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 //oss = 0
#define BMP180_CMD_PRESSURE1 0x74 //oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 //oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 //oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0-3)
#define BMP180_OSS 3

// Temperature and pressure thresholds
#define TEMPERATURE_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char val);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd);
int bmp180_read_raw_pressure(int fd);
float bmp180_calculate_temperature(int ut);
float bmp180_calculate_pressure(int up);
void log_breach(float temperature, float pressure);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = read(fd, buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char val) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = val;
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// Read calibration data from BMP180
int bmp180_read_calibration_data(int fd) {
    unsigned char buf[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, buf, 22) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature value from BMP180
int bmp180_read_raw_temperature(int fd) {
    unsigned char buf[2];
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Failed to write temperature command.\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms

    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) != 0) {
        fprintf(stderr, "Failed to read raw temperature data.\n");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Read raw pressure value from BMP180
int bmp180_read_raw_pressure(int fd) {
    unsigned char buf[3];
    unsigned char cmd = BMP180_CMD_PRESSURE3; //oss = 3
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, cmd) != 0) {
        fprintf(stderr, "Failed to write pressure command.\n");
        return -1;
    }
    usleep(26000); // Wait 25.5ms

    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) != 0) {
        fprintf(stderr, "Failed to read raw pressure data.\n");
        return -1;
    }

    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
}

// Calculate temperature in degrees Celsius
float bmp180_calculate_temperature(int ut) {
    long x1, x2, b5;
    x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
float bmp180_calculate_pressure(int up) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    long ut = bmp180_read_raw_temperature(i2c_fd);
    long x1_temp, x2_temp, b5_temp;

    x1_temp = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    x2_temp = ((long)mc << 11) / (x1_temp + md);
    b5_temp = x1_temp + x2_temp;

    b6 = b5_temp - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
