#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_GPIO 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Circular buffer
sensor_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature);
float calculate_pressure(int raw_pressure, int raw_temperature);
void timer_callback();
void signal_handler(int signal);
void cleanup();

// Function to read a 16-bit value from the BMP180
int16_t read_i2c_word(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_i2c_uword(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C unsigned word from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(BMP180_REG_CAL_B1);
    b2 = read_i2c_word(BMP180_REG_CAL_B2);
    mb = read_i2c_word(BMP180_REG_CAL_MB);
    mc = read_i2c_word(BMP180_REG_CAL_MC);
    md = read_i2c_word(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (minimum)

    *raw_temperature = read_i2c_word(BMP180_REG_MSB);
    if (*raw_temperature == -1) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    *raw_pressure = read_i2c_word(BMP180_REG_MSB);
    *raw_pressure = (*raw_pressure << 8) | read_i2c_uword(BMP180_REG_LSB);

    if (*raw_pressure == -1) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return 0;
}

// Function to calculate true temperature in degrees Celsius
float calculate_temperature(int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + (long)md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + (long)md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = ((long)ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((long)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)ac4 * (unsigned long)(X1_pressure + X2_pressure + 32768)) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    float calculated_pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return calculated_pressure;
}

// Timer callback function
void timer_callback()
{
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        // Store data in circular buffer
        buffer[buffer_index].timestamp = time(NULL);
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].pressure = pressure;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Control fan based on temperature
        if (temperature > 30.0) {
            gpioWrite(FAN_GPIO, 1); // Turn fan on
        } else {
            gpioWrite(FAN_GPIO, 0); // Turn fan off
        }

        // Print data to stdout
        printf("%ld,%.2f,%.2f\n", time(NULL), temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup()
{
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    gpioSetTimerFunc(0, 500, timer_callback); // Timer 0, every 500 ms

    // Keep the program running
    while (1) {
        gpioDelay(1000); // Sleep for 1 second
    }

    return 0;
}

