    if (i2cWriteI2CBlockData(i2c_handle, control_reg, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 26ms for OSS = 3

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - oss);
    return 0;
}

// Function to calculate pressure using the Bosch compensation formulas
double calculate_pressure(int raw_temp, int raw_pressure, int oss)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + (long)md);
    b5 = x1 + x2;

    // Pressure calculations
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << oss) + 2) / 4;
    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return (double)p;
}

// Function to log pressure to a file
void log_pressure(double pressure)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa\n", s, pressure);
    fclose(fp);
}

// Function to toggle logging
void toggle_logging()
{
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup()
{
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

