#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define TARGET_TEMP 25.0  // Default target temperature
#define MAX_DUTY_CYCLE 800 // 80% of 1000
#define LOG_FILE "heater_log.csv"

// PI Controller Gains
#define Kp 10.0
#define Ki 0.1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
float calculate_pi_control(float current_temperature, float target_temperature, float *integral, float previous_error);
void set_heater_duty_cycle(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);
void safe_shutdown();

// Function to read temperature from MAX31855 via SPI
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        log_data(-999.0, -1); // Log error
        return -999.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-999.0, -1); // Log error
        return -999.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(-999.0, -1); // Log error
        return -999.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-999.0, -1); // Log error
        return -999.0;
    }

    // Extract temperature data (bits 31:18, signed 14-bit value)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// PI Controller with anti-windup
float calculate_pi_control(float current_temperature, float target_temperature, float *integral, float previous_error) {
    float error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup: Limit integral term
    float integral_limit = 100.0; // Adjust as needed
    if (*integral > integral_limit) {
        *integral = integral_limit;
    } else if (*integral < -integral_limit) {
        *integral = -integral_limit;
    }

    float output = Kp * error + Ki * (*integral);

    // Limit output to safe range
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    } else if (output < 0) {
        output = 0;
    }

    return output;
}

// Function to set the heater duty cycle using PWM
void set_heater_duty_cycle(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to a CSV file
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Safe shutdown function
void safe_shutdown() {
    set_heater_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);      // Close SPI
    fclose(log_file);          // Close log file
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

int main(int argc, char *argv[]) {
    float target_temperature = TARGET_TEMP;
    float current_temperature;
    float integral = 0.0;
    float previous_error = 0.0;
    int duty_cycle;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Using target temperature: %.2f\n", target_temperature);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        current_temperature = read_temperature();

        if (current_temperature == -999.0) {
            // Error already logged in read_temperature
            sleep(1); // Wait before retrying
            continue;
        }

        duty_cycle = (int)calculate_pi_control(current_temperature, target_temperature, &integral, previous_error);
        set_heater_duty_cycle(duty_cycle);
        log_data(current_temperature, duty_cycle);

        previous_error = target_temperature - current_temperature;
        sleep(1); // Control loop frequency
    }

    safe_shutdown();
    return 0;
}

