#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds (millidegrees Celsius)
#define TEMP_LOW   40000
#define TEMP_MED   60000

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp = -1; // Initialize to an invalid value

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: Error occurred while reading temperature file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using pigpio
void set_rgb_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the duty cycle
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the duty cycle
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the duty cycle
}

// Function to map temperature to RGB color
void map_temp_to_color(int temp, int *red, int *green, int *blue)
{
    if (temp < TEMP_LOW) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp < TEMP_MED) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main()
{
    int temp, red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error: Could not read temperature, skipping cycle.\n");
            sleep(0.5);
            continue;
        }

        // Map temperature to RGB color
        map_temp_to_color(temp, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup: Turn off LEDs and terminate pigpio
    set_rgb_color(0, 0, 0); // Turn off all LEDs
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

