#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define MAX_BACKOFF_DELAY 60 // seconds

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables
static volatile int running = 1;
static int dht22_data_ready = 0;
static DHT22Data dht22_data;

// Function prototypes
void signal_handler(int signal);
int initialize_pigpio();
int read_dht22_data(DHT22Data *data);
int validate_checksum(unsigned char data[5]);
int post_data(float temperature, float humidity);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(DHT22_GPIO, PI_OUTPUT); // Set GPIO as output initially
    return 0;
}

// Read data from DHT22 sensor
int read_dht22_data(DHT22Data *data) {
    int i, j;
    unsigned int tick;
    unsigned char data_bits[40];
    unsigned char checksum;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us

    // Switch to input mode
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data
    for (i = 0; i < 40; i++) {
        // Wait for low
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > 200) {
                fprintf(stderr, "Timeout waiting for low signal\n");
                return 1;
            }
        }

        // Measure high time
        tick = gpioTick();
