        data_bytes[i] = 0;
        for (j = 0; j < 8; j++) {
            data_bytes[i] <<= 1;
            data_bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (validate_checksum(data_bytes) != 0) {
        fprintf(stderr, "Checksum validation failed\n");
        return 1;
    }

