    data->humidity = (float)(((unsigned int)data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data->temperature = (float)(((unsigned int)data_bytes[2] << 8) | data_bytes[3]) / 10.0;
    if (data->temperature > 125) {
        data->temperature -= 256;
    }
    data->valid = 1;

    return 0;
}

// Validate checksum
int validate_checksum(unsigned char data[5]) {
    unsigned char checksum = data[0] + data[1] + data[2] + data[3];
    return (checksum == data[4]) ? 0 : 1;
}

