#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 3

// GPIO pin for button interrupt
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
int i2c_handle;
volatile int logging_enabled = 0;
volatile unsigned int last_tick = 0;
FILE *log_file = NULL;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
void log_data(double pressure);
void button_isr(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_16(int reg, int *value)
{
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MD, &md) != 0) return -1;

    // Basic validation (example: check if AC1 is a reasonable value)
    if (ac1 < -32768 || ac1 > 32767) {
        fprintf(stderr, "Error: Invalid AC1 value: %d\n", ac1);
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature data: %d\n", result);
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (OSS = 3: 26ms)
    gpioDelay(26000);

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temperature)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;

    unsigned long X1_pressure = (unsigned long)ac3 * B6 / pow(2, 13);
    unsigned long X2_pressure = (unsigned long)b1 * (B6 * B6) / pow(2, 12);
    unsigned long X3_pressure = (X1_pressure + X2_pressure + 2) / 4;
    unsigned long B4 = (unsigned long)ac4 * (X3_pressure + 32768) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to log data to a file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Interrupt service routine for the button
void button_isr(int gpio, int level, unsigned int tick, void *user)
{
    unsigned int diff = tick - last_tick;

    if (level == 0) // Falling edge
    {
        if (diff > DEBOUNCE_TIME)
        {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
            last_tick = tick;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set up interrupt on GPIO4 (falling edge)
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int raw_temperature, raw_pressure;
    double pressure;
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                pressure = calculate_pressure(raw_pressure, raw_temperature);

                // Log the data
                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            printf("Logging disabled\n");
        }

        gpioDelay(2000000); // Sample every 2 seconds
    }

    return 0;
}

