// DHT22 Sensor Functions
int read_dht22(int gpio, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;
    long startTime, endTime;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioSetMode(gpio, PI_INPUT);

    startTime = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - startTime > 100) return -1; // Timeout
    }

    startTime = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - startTime > 100) return -1; // Timeout
    }

    startTime = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - startTime > 100) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        startTime = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - startTime > 100) return -1; // Timeout
        }

        startTime = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - startTime > 100) return -1; // Timeout
        }

        endTime = gpioTick();
        if (endTime - startTime > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        syslog(LOG_ERR, "DHT22 Checksum failure");
        return -1;
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

