    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Set timeout to 10 seconds
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L); // Set connection timeout to 5 seconds
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL); // Ensure no extra headers are set
        curl_easy_setopt(curl, CURLOPT_HTTP2, 0L); // Disable HTTP/2

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        if (response_code < 200 || response_code > 299) {
            syslog(LOG_ERR, "HTTP request failed with code: %ld", response_code);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return 0;
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    char *server_url = SERVER_URL;
    float humidity, temperature;
    int retries = 0;
    int backoff_delay = BACKOFF_DELAY;
    int curl_retries = 0;
    int curl_backoff_delay = MAX_BACKOFF_DELAY_CURL;
    int curl_backoff_delay_retry = MAX_BACKOFF_DELAY_CURL_RETRY;
    int curl_backoff_delay_retry2 = MAX_BACKOFF_DELAY_CURL_RETRY2;
    int curl_backoff_delay_retry3 = MAX_BACKOFF_DELAY_CURL_RETRY3;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "DHT22 monitor started, server URL: %s", server_url);

    while (!terminate) {
        retries = 0;
        backoff_delay = BACKOFF_DELAY;
        while (retries < MAX_RETRIES) {
            if (read_dht22(DHT22_GPIO, &humidity, &temperature) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%, Temperature: %.2f°C", humidity, temperature);

                curl_retries = 0;
                curl_backoff_delay = MAX_BACKOFF_DELAY_CURL;
                while (curl_retries < MAX_RETRIES_CURL) {
                    if (post_humidity_data(server_url, humidity) == 0) {
                        syslog(LOG_INFO, "Humidity data posted successfully");
                        break; // Exit curl retry loop on success
                    } else {
                        syslog(LOG_ERR, "Failed to post humidity data, retrying...");
                        curl_retries++;
                        sleep(curl_backoff_delay);
                        if (curl_retries < 2) {
                            curl_backoff_delay = MAX_BACKOFF_DELAY_CURL_RETRY;
                        } else if (curl_retries < 3) {
                            curl_backoff_delay = MAX_BACKOFF_DELAY_CURL_RETRY2;
                        } else {
                            curl_backoff_delay = MAX_BACKOFF_DELAY_CURL_RETRY3;
                        }
                    }
                }

                if (curl_retries == MAX_RETRIES_CURL) {
                    syslog(LOG_ERR, "Failed to post humidity data after multiple retries");
                }

                break; // Exit sensor retry loop on success
            } else {
                syslog(LOG_ERR, "Failed to read DHT22 sensor, retrying...");
                retries++;
                sleep(backoff_delay);
                backoff_delay *= 2; // Exponential backoff
                if (backoff_delay > MAX_BACKOFF_DELAY) {
                    backoff_delay = MAX_BACKOFF_DELAY;
                }
            }
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to read DHT22 sensor after multiple retries");
        }

        sleep(10); // Read every 10 seconds
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return 0;
}

