#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK_PIN 11
#define SPI_CS_PIN 8
#define SPI_DO_PIN 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define failsafe temperature limits
#define MIN_TEMPERATURE 0.0
#define MAX_TEMPERATURE 100.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
float read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void log_data(float temperature, int duty_cycle, float pid_output);
void handle_thermocouple_fault(uint8_t fault_bits);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioSetMode(SPI_DO_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 100); // Set PWM range to 0-100 for percentage

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Disable heater
    set_pwm_duty_cycle(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

// Read temperature from MAX31855
float read_temperature() {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Extract fault bits
    uint8_t fault_bits = buffer[3] & 0x07;

    // Check for thermocouple faults
    if (fault_bits != 0) {
        handle_thermocouple_fault(fault_bits);
        return -1000.0; // Indicate error
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t raw_temperature = ((buffer[0] << 8) | buffer[1]) >> 2;
    float temperature = raw_temperature * 0.25;

    // Failsafe check
    if (temperature < MIN_TEMPERATURE || temperature > MAX_TEMPERATURE) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Set PWM duty cycle for the heater
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle thermocouple faults
void handle_thermocouple_fault(uint8_t fault_bits) {
    fprintf(stderr, "Thermocouple fault detected: 0x%02X\n", fault_bits);
    fprintf(log_file, "Thermocouple fault detected: 0x%02X\n", fault_bits);
    fflush(log_file);

    // Disable heater
    set_pwm_duty_cycle(0);

    // Reset PID state
    float integral = 0.0;
    float previous_error = 0.0;

    // Log the error and reset the PID state
    fprintf(log_file, "Resetting PID state and disabling heater.\n");
    fflush(log_file);

    // Simulate a delay (e.g., wait for a minute)
    gpioDelay(60000000); // 60 seconds

    // Re-enable heater (optional, depending on your application)
    // set_pwm_duty_cycle(50); // Example: Re-enable with 50% duty cycle
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    float integral = 0.0;
    float previous_error = 0.0;
    float pid_output;
    float temperature;
    int duty_cycle;

    // Main loop
    while (running) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            pid_output = calculate_pid(TARGET_TEMPERATURE, temperature, &integral, &previous_error);
            duty_cycle = (int)pid_output; // Map PID output to duty cycle (0-100)

            // Clamp duty cycle to 0-100
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;

            set_pwm_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping PID calculation.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

