    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider adding a retry mechanism or exiting the program
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, continuing.\n");
