#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int crc8(const unsigned char *data, int len);
float read_flow_rate(int i2c_handle);
void log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);
int initialize_i2c(int bus, int addr);
void cleanup();

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read flow rate from a sensor
float read_flow_rate(int i2c_handle) {
    unsigned char cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    unsigned char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0;
    }

    gpioDelay(10); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0;
    }

    // CRC validation
    int crc_calculated = crc8(buffer, 2);
    if (crc_calculated != buffer[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1.0;
    }

    // Convert raw value to flow rate (ml/min)
    int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value * 0.01;
}

// Log flow rates to a file
void log_flow_rates(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C connection
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C connections
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1 = -1.0, flow2 = -1.0;
        int retries1 = 0, retries2 = 0;

        // Read flow rate from sensor 1 with retries
        while (retries1 < RETRY_COUNT && flow1 < 0) {
            flow1 = read_flow_rate(i2c_handle1);
            if (flow1 < 0) {
                fprintf(stderr, "Retrying sensor 1 (%d/%d)\n", retries1 + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS);
                retries1++;
            }
        }

        // Read flow rate from sensor 2 with retries
        while (retries2 < RETRY_COUNT && flow2 < 0) {
            flow2 = read_flow_rate(i2c_handle2);
            if (flow2 < 0) {
                fprintf(stderr, "Retrying sensor 2 (%d/%d)\n", retries2 + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS);
                retries2++;
            }
        }

        // Log flow rates if both sensors were read successfully
        if (flow1 >= 0 && flow2 >= 0) {
            log_flow_rates(flow1, flow2);
        } else {
            fprintf(stderr, "Failed to read from one or more sensors.\n");
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

