#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int current_state = 0; // 0: 00, 1: 01, 2: 11, 3: 10
volatile int rotation_count = 0;
volatile int program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor_a();
int read_sensor_b();
int update_state(int a, int b);
double calculate_angle(int state);
int log_data(double angle);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int a;
    int b;
    int state;
} EncoderState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);

    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of Sensor A
int read_sensor_a() {
    return gpioRead(SENSOR_A_PIN);
}

// Function to read the state of Sensor B
int read_sensor_b() {
    return gpioRead(SENSOR_B_PIN);
}

// Function to update the encoder state based on sensor readings
int update_state(int a, int b) {
    int new_state = current_state;

    if (a == 1 && b == 0) {
        new_state = (current_state + 1) % 4;
    } else if (a == 0 && b == 1) {
        new_state = (current_state + 3) % 4;
    }

    if (new_state != current_state) {
        current_state = new_state;
        return 1; // State changed
    }

    return 0; // State did not change
}

// Function to calculate the normalized angular position
double calculate_angle(int state) {
    return (double)rotation_count * 360.0 / PULSES_PER_REVOLUTION;
}

// Function to log data to a file
int log_data(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, angle);
    fclose(fp);
    return 0; // Indicate success
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int a = read_sensor_a();
        int b = read_sensor_b();

        if (update_state(a, b)) {
            rotation_count++;
            double angle = calculate_angle(current_state);
