#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define RED_REG 0x60
#define IR_REG 0x62
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define FIFO_SIZE 2 // Number of readings to store

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int red;
    int ir;
} sensor_data_t;

// Circular buffer for storing sensor readings
sensor_data_t fifo[FIFO_SIZE];
int fifo_head = 0;
int fifo_count = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_sensor_data(int *red, int *ir);
void control_led(int state);
void log_data(int red, int ir);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *red, int *ir) {
    char buf[4];
    int bytes_read;

    // Read Red data
    bytes_read = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading Red data: %d\n", bytes_read);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR data
    bytes_read = i2cReadI2CBlockData(i2c_handle, IR_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading IR data: %d\n", bytes_read);
        return -1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log data to file
void log_data(int red, int ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, ir;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&red, &ir) == 0) {
            log_data(red, ir);

            // FIFO buffer implementation
            fifo[fifo_head].red = red;
            fifo[fifo_head].ir = ir;
            fifo_head = (fifo_head + 1) % FIFO_SIZE;
            if (fifo_count < FIFO_SIZE) {
                fifo_count++;
            }

            // Control LED based on IR reading
            if (ir > IR_THRESHOLD) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

