#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define RED_FIFO_REG 0x02
#define IR_FIFO_REG 0x04
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio, int state);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int signal);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    if (i2c_smbus_write_byte_data(fd, reg, value) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t red_data[2], ir_data[2];
    int result;

    result = i2c_smbus_read_i2c_block_data(fd, RED_FIFO_REG, 2, (char *)red_data);
    if (result != 2) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    *red = (red_data[1] << 8) | red_data[0];

    result = i2c_smbus_read_i2c_block_data(fd, IR_FIFO_REG, 2, (char *)ir_data);
    if (result != 2) {
        fprintf(stderr, "Error reading IR data: %s\n", strerror(errno));
        return -1;
    }
    *ir = (ir_data[1] << 8) | ir_data[0];

    return 0;
}

// Control LED function
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log data function
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    uint8_t part_id;
    uint16_t red, ir;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
