#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *audio_line = NULL;
static struct gpiod_line *gain_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int sample_audio(void);
int log_event(void);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (audio_line) {
        gpiod_line_release(audio_line);
    }
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

// Setup GPIO pins
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get audio input line
    audio_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!audio_line) {
        perror("Error getting audio input line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get gain control line
    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        perror("Error getting gain control line");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_line);
        return -1;
    }

    // Request audio input line as input
    ret = gpiod_line_request_input(audio_line, "audio_sampler");
    if (ret < 0) {
        perror("Error requesting audio input line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        return -1;
    }

    // Request gain control line as output
    ret = gpiod_line_request_output(gain_line, "audio_sampler", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting gain control line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        return -1;
    }

    return 0;
}

// Sample audio input
int sample_audio(void) {
    int value;
    int ret;

    ret = gpiod_line_get_value(audio_line);
    if (ret < 0) {
        perror("Error reading audio input line");
        return -1;
    }
    value = ret;

    return value;
}

// Log audio event
int log_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s LEVEL\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main(void) {
    int audio_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        audio_value = sample_audio();
        if (audio_value < 0) {
            fprintf(stderr, "Error sampling audio. Continuing...\n");
            continue;
        }

        if (audio_value == 1) {
            log_event();
        }

        // Delay for 10 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

