int validate_crc(const unsigned char *data);
float convert_to_flow_rate(int raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize the sensor
int initialize_sensor() {
    char command[2];
    command[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    command[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        log_error("Failed to initialize sensor.");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read sensor data.");
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(const unsigned char *data) {
    unsigned char crc = 0xFF;
    unsigned char data_msb = data[0];
    unsigned char data_lsb = data[1];

    for (int i = 0; i < 2; i++) {
        crc ^= data_msb;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
        data_msb = data_lsb;
    }

    if (crc != data[2]) {
        log_error("CRC validation failed.");
        return -1;
    }
    return 0;
}

// Function to convert raw flow value to uL/min
float convert_to_flow_rate(int raw_flow) {
    return (float)raw_flow / 1000.0;
}

// Function to log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (flow_log_fp == NULL) {
        log_error("Flow log file is not open.");
        return -1;
    }

    fprintf(flow_log_fp, "%s,%.3f\n", timestamp, flow_rate);
    fflush(flow_log_fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to log errors to file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (error_log_fp == NULL) {
        fprintf(stderr, "Error log file is not open.\n");
        return;
    }

    fprintf(error_log_fp, "%s: %s\n", timestamp, message);
    fflush(error_log_fp);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    flow_log_fp = fopen(FLOW_LOG_FILE, "a");
    if (flow_log_fp == NULL) {
        log_error("Failed to open flow log file.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_log_fp == NULL) {
        log_error("Failed to open error log file.");
        fclose(flow_log_fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    unsigned char sensor_data[3];
    int raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data) == 0) {
                // Convert to flow rate
                raw_flow = (sensor_data[0] << 8) | sensor_data[1];
                flow_rate = convert_to_flow_rate(raw_flow);

                // Data validation
                if (flow_rate >= FLOW_RATE_MIN && flow_rate <= FLOW_RATE_MAX) {
                    // Log flow rate
                    if (log_flow_rate(flow_rate) != 0) {
                        log_error("Failed to log flow rate.");
                    }
                } else {
                    log_error("Flow rate out of range.");
                }
            }
        }

        gpioDelay(1000); // 1000 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(flow_log_fp);
    fclose(error_log_fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

