    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d,%.2f\n", timestamp, tvoc, eco2, iaq) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

