    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[7];
    int tvoc, eco2;
    float iaq;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Extract TVOC and eCO2 values
            tvoc = extract_tvoc(sensor_data);
            eco2 = extract_eco2(sensor_data);

            // Calculate IAQ
            iaq = calculate_iaq(tvoc, eco2);

            // Log data
            if (log_data(log_file, tvoc, eco2, iaq) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        // Wait for the next interval
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

