#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_DURATION_S 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log intrusion alert
void log_intrusion_alert()
{
    char timestamp[20];
    get_timestamp(timestamp);
    printf("%s - Intrusion Alert: Sensor touched for %d seconds!\n", timestamp, INTRUSION_DURATION_S);
}

// Function to cleanup GPIO resources
void cleanup()
{
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    struct timespec intrusion_start_time;
    int intrusion_active = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line as input
    if (gpiod_line_request(line, CONSUMER_LABEL, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d (physical pin %d)...\n", GPIO_LINE, 11);

    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (value == 1) { // Sensor touched
            if (!intrusion_active) {
                intrusion_active = 1;
                clock_gettime(CLOCK_MONOTONIC, &intrusion_start_time);
            }

            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - intrusion_start_time.tv_sec) + (current_time.tv_nsec - intrusion_start_time.tv_nsec) / 1000000000.0;

            if (elapsed_time >= INTRUSION_DURATION_S) {
                log_intrusion_alert();
                intrusion_active = 0; // Reset intrusion flag
            }
        } else { // Sensor released
            intrusion_active = 0; // Reset intrusion flag
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("Tamper detection system stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

