#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define ALSA_DEVICE "default" // Or "hw:0,0" if needed
#define SAMPLE_RATE 44100
#define CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S24_LE
#define PERIOD_SIZE 1024
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define FILE_NAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle = NULL;
FILE *audio_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_alsa(snd_pcm_t **pcm_handle, const char *device_name, unsigned int sample_rate, unsigned int channels, snd_pcm_format_t format, int period_size);
int initialize_gpio(struct gpiod_chip **gpio_chip, struct gpiod_line **gpio_line, const char *chip_name, int pin);
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file);
void signal_handler(int sig);
void cleanup(snd_pcm_t *pcm_handle, FILE *audio_file, struct gpiod_chip *gpio_chip, struct gpiod_line *gpio_line);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle, const char *device_name, unsigned int sample_rate, unsigned int channels, snd_pcm_format_t format, int period_size) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, device_name, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", device_name, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, format)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, channels)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
