#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    int flame_start_time;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the fan based on flame detection
void control_fan(int flame_detected) {
    if (flame_detected) {
        // Calculate duty cycle based on flame duration
        int duration = time(NULL) - state.flame_start_time;
        float duty_cycle = (float)duration / 10.0; // Scale to 0-10 seconds
        if (duty_cycle > 80.0) {
            duty_cycle = 80.0;
        }
        int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // Scale to 0-255
        gpioPWM(FAN_PIN, pwm_value);
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Turn off fan
    gpioTerminate();      // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    log_event("System started");

    int last_state = 1; // Assume no flame initially
    time_t last_change_time = time(NULL);

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, log and retry
            log_event("Error reading flame sensor, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Debouncing and flame detection logic
        if (sensor_value == 0 && last_state == 1) { // Flame detected (LOW)
            if (time(NULL) - last_change_time > 0.05) { // 50ms debounce
                state.flame_detected = 1;
                state.flame_start_time = time(NULL);
                control_fan(1);
                log_event("Flame detected");
                last_state = 0;
                last_change_time = time(NULL);
            }
        } else if (sensor_value == 1 && last_state == 0) { // Flame ended (HIGH)
            if (time(NULL) - last_change_time > 0.05) { // 50ms debounce
                state.flame_detected = 0;
                control_fan(0);
                log_event("Flame ended");
                last_state = 1;
                last_change_time = time(NULL);
            }
        }

        gpioDelay(50); // Poll every 50 ms
    }

    cleanup();
    return 0;
}

