#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define HEATMAP_SIZE 32768
#define FRAME_PERIOD_MS 100
#define MAGIC_NUMBER 0x52444144

// Configuration struct
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period_ms;
} config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_heatmap_data(uint8_t *data);
int write_log_header(FILE *fp, config_t config);
int write_log_frame(FILE *fp, uint8_t *data, uint64_t timestamp, int frame_number);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Read heatmap data from SPI
int read_heatmap_data(uint8_t *data) {
    char tx_buffer[HEATMAP_SIZE] = {0}; // Dummy transmit buffer
    char rx_buffer[HEATMAP_SIZE];

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, HEATMAP_SIZE) != HEATMAP_SIZE) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    memcpy(data, rx_buffer, HEATMAP_SIZE);
    return 0;
}

// Write log file header
int write_log_header(FILE *fp, config_t config) {
    uint64_t timestamp = time(NULL);
    uint8_t header[16];

    // Magic number
    header[0] = (MAGIC_NUMBER >> 24) & 0xFF;
    header[1] = (MAGIC_NUMBER >> 16) & 0xFF;
    header[2] = (MAGIC_NUMBER >> 8) & 0xFF;
    header[3] = MAGIC_NUMBER & 0xFF;

    // Timestamp (8 bytes)
    memcpy(header + 4, &timestamp, 8);

    // Configuration struct (8 bytes)
    uint8_t config_bytes[8];
    memcpy(config_bytes, &config, 8);
    memcpy(header + 12, config_bytes, 8);

    if (fwrite(header, 1, 16, fp) != 16) {
        fprintf(stderr, "Failed to write log header\n");
        return -1;
    }

    return 0;
}

