#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        free(timestamp);
        return NULL;
    }

    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log message.\n");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }

    free(timestamp);
    return 0;
}

// Function to read the flame sensor state
int read_flame_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to handle state transitions
void handle_state_transition(int new_state) {
    static int current_state = -1; // Initialize to an invalid state

    if (new_state != current_state) {
        if (new_state == 0) {
            if (log_message("Flame Detected") != 0) {
                fprintf(stderr, "Failed to log flame detected event.\n");
            }
        } else if (new_state == 1) {
            if (log_message("Flame Cleared") != 0) {
                fprintf(stderr, "Failed to log flame cleared event.\n");
            }
        } else {
            fprintf(stderr, "Invalid state received: %d\n", new_state);
        }
        current_state = new_state;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value >= 0) {
            handle_state_transition(sensor_value);
        } else {
            fprintf(stderr, "Error reading sensor value, retrying...\n");
        }

        struct timespec delay = {0, 100000000}; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

