#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    struct timespec ts;
    char timestamp[32];
    int value;

    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get line request configuration
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    // Request the line
    line = gpiod_chip_request_lines(chip, &config, 1, NULL);
    if (!line) {
        fprintf(stderr, "Error requesting line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Format timestamp
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Read line value
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }

        // Log flame detection status
        if (value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Wait for the next poll interval
        struct timespec sleep_time;
        sleep_time.tv_sec = POLL_INTERVAL_SEC;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

