#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor outputs
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set LEFT_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set CENTER_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set RIGHT_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (!terminate) {
        // Read the digital values from the GPIO pins
        int left_value = gpioRead(LEFT_PIN);
        int center_value = gpioRead(CENTER_PIN);
        int right_value = gpioRead(RIGHT_PIN);

        // Print the sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

