#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL}; // Array to hold the line objects

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines for each channel
    for (int i = 0; i < num_channels; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            // Clean up already requested lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line for input
        int ret = gpiod_line_request(line, "touch_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            // Clean up already requested lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        lines[i] = line; // Store the line pointer
    }

    // Main loop to read and log sensor data
    while (1) {
        for (int i = 0; i < num_channels; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading value from GPIO %d: %s\n", gpio_pins[i], strerror(errno));
                // Attempt to continue, but may need to exit if errors persist
            } else {
                printf("GPIO %d: %d ", gpio_pins[i], value);
            }
        }
        printf("\n");
        usleep(100000); // 100 ms delay
    }

    // The following lines will never be reached in normal execution
    // due to the infinite loop.  They are included for completeness.
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 0;
}

