#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    for (int i = 0; i < num_channels; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pin);
            gpioTerminate();
            return 1; // Indicate failure
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor for GPIO %d\n", pin);
            gpioTerminate();
            return 1; // Indicate failure
        }
    }
    return 0; // Indicate success
}

// Function to read the sensor data and format the output string
void read_sensor_data(char *output_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    int milliseconds = (int)(rawtime * 1000.0); // Convert seconds to milliseconds

    snprintf(output_buffer, buffer_size, "[%+d ms] ", milliseconds);

    for (int i = 0; i < num_channels; i++) {
        int pin = sensor_pins[i];
        int value = gpioRead(pin);
        if (i > 0) {
            snprintf(output_buffer + strlen(output_buffer), buffer_size - strlen(output_buffer), " ");
        }
        snprintf(output_buffer + strlen(output_buffer), buffer_size - strlen(output_buffer), "CH%d=%d", i + 1, value);
    }
    snprintf(output_buffer + strlen(output_buffer), buffer_size - strlen(output_buffer), "\n");
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure the GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Main loop to read and log sensor data
    char output_buffer[256]; // Buffer to store the formatted output string
    while (program_running) {
        read_sensor_data(output_buffer, sizeof(output_buffer));
        printf("%s", output_buffer);
        fflush(stdout); // Ensure the output is printed immediately
        gpioDelay(100000); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

