#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read sensor states and log them
    while (program_running) {
        // Read sensor states
        int sensor1_state = gpioRead(SENSOR_1_GPIO);
        int sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Get current time
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log sensor states to the console
        printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
               (sensor1_state == 0) ? "LOW" : "HIGH",
               (sensor2_state == 0) ? "LOW" : "HIGH");

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

