#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the touch sensor channels
const int gpio_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, struct gpiod_line **lines, const int *gpio_pins, int num_channels);
int read_touch_sensor(struct gpiod_line **lines, int num_channels);
void log_data(int *sensor_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    exit(0);
}

// Function to set up GPIO lines
int setup_gpio(struct gpiod_chip *chip, struct gpiod_line **lines, const int *gpio_pins, int num_channels) {
    for (int i = 0; i < num_channels; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!line) {
            fprintf(stderr, "Error: Could not get line %d: %s\n", gpio_pins[i], strerror(errno));
            return -1;
        }
        lines[i] = line;

        int ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d as input: %s\n", gpio_pins[i], strerror(errno));
            gpiod_line_release(line);
            return -1;
        }
    }
    return 0;
}

// Function to read the touch sensor data
int read_touch_sensor(struct gpiod_line **lines, int num_channels) {
    int sensor_data[num_channels];
    for (int i = 0; i < num_channels; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read value from line %d: %s\n", gpiod_line_get_offset(lines[i]), strerror(errno));
            return -1; // Indicate an error
        }
        sensor_data[i] = value;
    }
    return 0; // Indicate success
}

// Function to log the data to the console
void log_data(int *sensor_data) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    printf("%s", buf);
    for (int i = 0; i < num_channels; i++) {
        printf(",%d", sensor_data[i]);
    }
    printf("\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO lines
    if (setup_gpio(chip, lines, gpio_pins, num_channels) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor_data[8];
        if (read_touch_sensor(lines, num_channels) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

