#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Print startup banner
    printf("Tilt Sensor Monitoring Program\n");
    printf("Monitoring GPIO %d (physical pin 7)\n", TILT_SENSOR_GPIO);
    printf("Press Ctrl+C to exit\n");

    // Main loop
    while (program_running) {
        // Read the current state of the tilt sensor
        current_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the GPIO read result
        if (current_state != 0 && current_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read result: %d\n", current_state);
            gpioTerminate();
            return 1;
        }

        // Check for state change
        if (current_state != previous_state) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the timestamped message
            if (current_state == 0) {
                printf("%s - Tilted\n", timestamp);
            } else {
                printf("%s - Not Tilted\n", timestamp);
            }

            // Flush stdout to ensure immediate output
            fflush(stdout);

            // Update previous state
            previous_state = current_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

