#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define CSV_FILENAME "uv_als_log.csv"

// Si1145 Registers
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_FORCE 0x06
#define SI1145_REG_UVINDEX_LSB 0x2C
#define SI1145_REG_ALS_VIS_LSB 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *uv_index, uint16_t *als_visible);
int log_data(float uv_index, uint16_t als_visible);
void signal_handler(int signal);
int safe_i2c_read(int handle, uint8_t reg, uint8_t *data, int count);
int safe_i2c_write(int handle, uint8_t reg, uint8_t data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1145 sensor
int initialize_sensor() {
    uint8_t part_id;

    // Verify PART ID
    if (safe_i2c_read(i2c_handle, SI1145_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Error reading PART ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (safe_i2c_write(i2c_handle, SI1145_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure CHLIST
    if (safe_i2c_write(i2c_handle, SI1145_REG_CHLIST, 0x01) != 0) {
        fprintf(stderr, "Error writing CHLIST\n");
        return -1;
    }

    // Trigger measurement
    if (safe_i2c_write(i2c_handle, SI1145_REG_ALS_FORCE, 0x06) != 0) {
        fprintf(stderr, "Error writing ALS_FORCE\n");
        return -1;
    }

    return 0;
}

// Reads UV index and Visible ALS data from the sensor
int read_sensor_data(float *uv_index, uint16_t *als_visible) {
    uint8_t uv_index_lsb, uv_index_msb, als_vis_lsb, als_vis_msb;

    // Read UV Index
    if (safe_i2c_read(i2c_handle, SI1145_REG_UVINDEX_LSB, &uv_index_lsb, 1) != 0) {
        fprintf(stderr, "Error reading UV Index LSB\n");
        return -1;
    }
    if (safe_i2c_read(i2c_handle, SI1145_REG_UVINDEX_LSB + 1, &uv_index_msb, 1) != 0) {
        fprintf(stderr, "Error reading UV Index MSB\n");
        return -1;
    }
    *uv_index = (float)((uint16_t)uv_index_msb << 8 | uv_index_lsb) / 100.0; // UV Index is stored as a value * 100

    // Read Visible ALS
    if (safe_i2c_read(i2c_handle, SI1145_REG_ALS_VIS_LSB, &als_vis_lsb, 1) != 0) {
        fprintf(stderr, "Error reading ALS Vis LSB\n");
        return -1;
    }
    if (safe_i2c_read(i2c_handle, SI1145_REG_ALS_VIS_LSB + 1, &als_vis_msb, 1) != 0) {
        fprintf(stderr, "Error reading ALS Vis MSB\n");
        return -1;
    }
    *als_visible = (uint16_t)als_vis_msb << 8 | als_vis_lsb;

    return 0;
}

// Logs data to the CSV file
int log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Safe I2C read with error handling
int safe_i2c_read(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Safe I2C write with error handling
int safe_i2c_write(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    float uv_index;
    uint16_t als_visible;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&uv_index, &als_visible) == 0) {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            if (log_data(uv_index, als_visible) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

