#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// GPIO pin for alarm
#define ALARM_PIN 17

// Flow rate scale factor (ml/min)
#define FLOW_SCALE_FACTOR 0.036

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_fd1 = -1; // I2C file descriptor for sensor 1
int i2c_fd2 = -1; // I2C file descriptor for sensor 2
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int valid;
} sensor_data_t;

// Function prototypes
int i2c_init(int address);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int crc8(const unsigned char *data, int len);
float convert_flow_rate(int raw_flow);
void log_flow_rate(float avg_flow);
void set_alarm(float avg_flow);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int i2c_init(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Flow rate conversion function
float convert_flow_rate(int raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Flow rate logging function
void log_flow_rate(float avg_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);
    fflush(log_file);
}

// Alarm control function
void set_alarm(float avg_flow) {
    if (avg_flow < 0.5) {
        gpioWrite(ALARM_PIN, 1); // Set alarm high
    } else {
        gpioWrite(ALARM_PIN, 0); // Set alarm low
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Initialize I2C
    i2c_fd1 = i2c_init(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        cleanup();
        return 1;
    }

    i2c_fd2 = i2c_init(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start measurement command
    unsigned char start_measurement_cmd[2] = {0x36, 0x08};
    if (i2c_write(i2c_fd1, start_measurement_cmd, 2) < 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 1\n");
        cleanup();
        return 1;
    }
    if (i2c_write(i2c_fd2, start_measurement_cmd, 2) < 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 2\n");
        cleanup();
        return 1;
    }

    // Wait for 100ms
    gpioDelay(100000); // 100ms

    // Main loop
    while (!terminate) {
        sensor_data_t sensor1_data = {0.0, 0};
        sensor_data_t sensor2_data = {0.0, 0};

        // Read sensor 1
        unsigned char sensor1_data_buffer[9];
        if (i2c_read(i2c_fd1, sensor1_data_buffer, 9) == 0) {
            // Validate CRC
            int crc1 = crc8(sensor1_data_buffer, 3);
            if (crc1 == sensor1_data_buffer[3]) {
                // Extract flow rate
                int raw_flow1 = (sensor1_data_buffer[0] << 8) | sensor1_data_buffer[1];
                sensor1_data.flow_rate = convert_flow_rate(raw_flow1);
                sensor1_data.valid = 1;
            } else {
                fprintf(stderr, "CRC error for sensor 1\n");
                sensor1_data.valid = 0;
            }
        } else {
            fprintf(stderr, "I2C read error for sensor 1\n");
            sensor1_data.valid = 0;
        }

        // Read sensor 2
        unsigned char sensor2_data_buffer[9];
        if (i2c_read(i2c_fd2, sensor2_data_buffer, 9) == 0) {
            // Validate CRC
            int crc2 = crc8(sensor2_data_buffer, 3);
            if (crc2 == sensor2_data_buffer[3]) {
                // Extract flow rate
                int raw_flow2 = (sensor2_data_buffer[0] << 8) | sensor2_data_buffer[1];
                sensor2_data.flow_rate = convert_flow_rate(raw_flow2);
                sensor2_data.valid = 1;
            } else {
                fprintf(stderr, "CRC error for sensor 2\n");
                sensor2_data.valid = 0;
            }
        } else {
            fprintf(stderr, "I2C read error for sensor 2\n");
            sensor2_data.valid = 0;
        }

        // Calculate average flow rate
        float avg_flow = 0.0;
        int valid_count = 0;
        if (sensor1_data.valid) {
            avg_flow += sensor1_data.flow_rate;
            valid_count++;
        }
        if (sensor2_data.valid) {
            avg_flow += sensor2_data.flow_rate;
            valid_count++;
        }

        if (valid_count > 0) {
            avg_flow /= valid_count;
            log_flow_rate(avg_flow);
            set_alarm(avg_flow);
        } else {
            fprintf(stderr, "No valid sensor readings\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

