#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x55
#define MODE_CONTROL_REG 0x1D
#define MODE_CONTROL_VALUE 0x10
#define OPERATING_STATUS_REG 0x1B
#define OPERATING_STATUS_BIT 0
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define SCALING_FACTOR 0.0009765625
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILENAME "fan_health.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int count);
int init_sensor(int fd);
int check_operating_status(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // Failure after retries
}

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            fprintf(stderr, "I2C slave ioctl error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (register select) error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (read(fd, value, 1) != 1) {
            fprintf(stderr, "I2C read error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
        } else {
            return 0; // Success
        }
    }
    return -1; // Failure after retries
}

// I2C read multiple registers with retry
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int count) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            fprintf(stderr, "I2C slave ioctl error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (register select) error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        result = read(fd, data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (errno: %d)\n", strerror(errno), errno);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // Failure after retries
}

// Initialize the sensor
int init_sensor(int fd) {
    if (i2c_write_reg(fd, MODE_CONTROL_REG, MODE_CONTROL_VALUE) != 0) {
        fprintf(stderr, "Failed to initialize sensor.\n");
        return -1;
    }
    return 0;
}

// Check the operating status
int check_operating_status(int fd) {
    uint8_t status;
    int retries = 3;

    while (retries > 0) {
        if (i2c_read_reg(fd, OPERATING_STATUS_REG, &status) == 0) {
            if ((status >> OPERATING_STATUS_BIT) & 1) {
                return 0; // Active
            } else {
                fprintf(stderr, "Sensor not active.\n");
                return -1; // Not active
            }
        } else {
            fprintf(stderr, "Failed to read operating status.\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    return -1; // Failure after retries
}

// Read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_regs(fd, ACCEL_X_LSB_REG, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data.\n");
        return -1;
    }

    raw_x = (int16_t)((data[1] << 8) | data[0]);
    raw_y = (int16_t)((data[3] << 8) | data[2]);
    raw_z = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)raw_x * SCALING_FACTOR;
    *y = (float)raw_y * SCALING_FACTOR;
    *z = (float)raw_z * SCALING_FACTOR;

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to CSV file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s (errno: %d)\n", strerror(errno), errno);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }
    rewind(csv_file);

    // Initialize sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(csv_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check operating status
    if (check_operating_status(i2c_fd) != 0) {
        fprintf(stderr, "Sensor not active after initialization.\n");
        fclose(csv_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    fprintf(stderr, "Closing I2C device and CSV file...\n");
    fclose(csv_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

