#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the stall detection time (in seconds)
#define STALL_TIME 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int detect_stall(int sensor1_value, int sensor2_value);
int log_stall();
void signal_handler(int signal);

