        fp = fopen(LOG_FILE, "r");
        if (fp != NULL) {
            char line[256];
            int found = 0;
            while (fgets(line, sizeof(line), fp) != NULL) {
                if (strstr(line, timestamp) != NULL) {
                    found = 1;
                    break;
                }
            }
            fclose(fp);
            if (found) {
