#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170-Q1 Register Addresses
#define TMAG5170_REG_DEVICE_ID 0x00
#define TMAG5170_REG_X_AXIS 0x01
#define TMAG5170_REG_Y_AXIS 0x03
#define TMAG5170_REG_Z_AXIS 0x05
#define TMAG5170_REG_CONFIG 0x07

// Configuration values
#define TMAG5170_CONTINUOUS_MODE 0x03 // Continuous conversion mode, all axes enabled
#define TMAG5170_RANGE_50MT 0x00       // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mT(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to initialize the TMAG5170-Q1 sensor
int initialize_sensor() {
    // Verify device ID
    char buf[1];
    buf[0] = TMAG5170_REG_DEVICE_ID;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to device ID register: %s\n", strerror(errno));
        return -1;
    }
    char device_id;
    if (i2cReadDevice(i2c_handle, &device_id, 1) != 1) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }

    if (device_id != 0x8D) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x8D)\n", device_id);
        return -1;
    }

    // Configure the sensor for continuous conversion mode and 50 mT range
    char config_data[2];
    config_data[0] = TMAG5170_REG_CONFIG;
    config_data[1] = (TMAG5170_CONTINUOUS_MODE << 4) | TMAG5170_RANGE_50MT;

    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char reg[1];
    char data[6];

    // Read X axis
    reg[0] = TMAG5170_REG_X_AXIS;
    if (i2cWriteDevice(i2c_handle, reg, 1) != 0) {
        fprintf(stderr, "Error writing to X axis register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to convert raw data to mT
float convert_to_mT(int16_t raw_value) {
    // LSB scale factor for 50 mT range is 0.000006 mT/LSB
    return (float)raw_value * 0.000006;
}

// Function to log data to CSV file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X(mT),Y(mT),Z(mT)\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_mT, y_mT, z_mT;
    while (!terminate) {
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            x_mT = convert_to_mT(raw_x);
            y_mT = convert_to_mT(raw_y);
            z_mT = convert_to_mT(raw_z);

            if (log_data(x_mT, y_mT, z_mT) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

