#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex and condition variable
pthread_mutex_t mutex;
pthread_cond_t condition;

// Define the sensor states
typedef enum {
    SENSOR_A_HIGH,
    SENSOR_A_LOW,
    SENSOR_B_HIGH,
    SENSOR_B_LOW,
    SENSOR_A_B_HIGH,
    SENSOR_A_B_LOW,
    SENSOR_A_LOW_B_HIGH,
    SENSOR_A_LOW_B_LOW
} sensor_state_t;

// Define the rotation direction
typedef enum {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    NONE
} rotation_direction_t;

// Global variables
static volatile sensor_state_t current_state = SENSOR_A_LOW_B_LOW; // Initial state
static volatile rotation_direction_t rotation_direction = NONE;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void log_rotation_event(rotation_direction_t direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);
void *main_loop(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to log rotation events to a file
void log_rotation_event(rotation_direction_t direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%s.%03ld: Rotation: %s\n", timestamp, milliseconds, direction == CLOCKWISE ? "CW" : "CCW");
    fclose(fp);
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&mutex);
    sensor_state_t new_state;

    if (level == 1) {
        new_state = SENSOR_A_HIGH;
    } else {
        new_state = SENSOR_A_LOW;
    }

    if (current_state == SENSOR_A_LOW_B_LOW) {
        if (new_state == SENSOR_A_HIGH) {
            rotation_direction = CLOCKWISE;
        } else {
            rotation_direction = COUNTER_CLOCKWISE;
        }
    } else if (current_state == SENSOR_A_HIGH_B_LOW) {
        if (new_state == SENSOR_A_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    } else if (current_state == SENSOR_A_LOW_B_HIGH) {
        if (new_state == SENSOR_A_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    } else if (current_state == SENSOR_A_HIGH_B_HIGH) {
        if (new_state == SENSOR_A_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    }

    current_state = new_state;
    pthread_cond_signal(&condition);
    pthread_mutex_unlock(&mutex);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&mutex);
    sensor_state_t new_state;

    if (level == 1) {
        new_state = SENSOR_B_HIGH;
    } else {
        new_state = SENSOR_B_LOW;
    }

    if (current_state == SENSOR_A_LOW_B_LOW) {
        if (new_state == SENSOR_B_HIGH) {
            rotation_direction = COUNTER_CLOCKWISE;
        } else {
            rotation_direction = CLOCKWISE;
        }
    } else if (current_state == SENSOR_A_HIGH_B_LOW) {
        if (new_state == SENSOR_B_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    } else if (current_state == SENSOR_A_LOW_B_HIGH) {
        if (new_state == SENSOR_B_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    } else if (current_state == SENSOR_A_HIGH_B_HIGH) {
        if (new_state == SENSOR_B_HIGH) {
            rotation_direction = NONE;
        } else {
            rotation_direction = NONE;
        }
    }

    current_state = new_state;
    pthread_cond_signal(&condition);
    pthread_mutex_unlock(&mutex);
}

// Main loop function
void *main_loop(void *arg) {
    (void)arg; // unused
    while (running) {
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&condition, &mutex);
        pthread_mutex_unlock(&mutex);

        pthread_mutex_lock(&mutex);
        if (rotation_direction != NONE) {
            log_rotation_event(rotation_direction);
            rotation_direction = NONE; // Reset direction after logging
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    printf("Caught signal, exiting gracefully...\n");
    running = 0; // Set the flag to exit the main loop
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&mutex); // Destroy the mutex
    pthread_cond_destroy(&condition); // Destroy the condition variable
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        cleanup();
        return 1;
    }
    if (pthread_cond_init(&condition, NULL) != 0) {
        perror("Condition variable initialization failed");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routines
    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor A\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor B\n");
        cleanup();
        return 1;
    }

    // Create the main loop thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, main_loop, NULL) != 0) {
        perror("Failed to create main loop thread");
        cleanup();
        return 1;
    }

    // Wait for the main loop thread to finish
    pthread_join(thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

