    printf("Caught signal, exiting gracefully...\n");
    running = 0; // Set the flag to exit the main loop
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&mutex); // Destroy the mutex
    pthread_cond_destroy(&condition); // Destroy the condition variable
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        cleanup();
        return 1;
    }
    if (pthread_cond_init(&condition, NULL) != 0) {
        perror("Condition variable initialization failed");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routines
    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor A\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor B\n");
        cleanup();
        return 1;
    }

    // Create the main loop thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, main_loop, NULL) != 0) {
        perror("Failed to create main loop thread");
        cleanup();
        return 1;
    }

    // Wait for the main loop thread to finish
    pthread_join(thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

