#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *touch_line;
struct gpiod_line *led_line;

// Function prototypes
int setup_gpio(void);
int read_touch_sensor(void);
int write_led(int value);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up GPIO...\n");
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int setup_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request touch sensor line for input with rising edge events
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request(touch_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting touch sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Request LED line for output
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Set initial LED state to LOW
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting initial LED value: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    return 0;
}

// Function to read the touch sensor value
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to write to the LED
int write_led(int value) {
    if (gpiod_line_set_value(led_line, value) < 0) {
        fprintf(stderr, "Error writing to LED: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    struct gpiod_line_event event;
    struct timespec debounce_start_time;
    int led_state = 0; // 0 = off, 1 = on

    // Main loop
    while (1) {
        // Read touch sensor
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            cleanup_gpio();
            return 1;
        }

        // Check for rising edge
        if (touch_value == 1) {
            // Check debounce time
            if (clock_gettime(CLOCK_MONOTONIC, &debounce_start_time) == 0) {
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                long elapsed_time_ns = (current_time.tv_sec - debounce_start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - debounce_start_time.tv_nsec);

                if (elapsed_time_ns >= DEBOUNCE_TIME_MS * 1000000) {
                    // Toggle LED state
                    led_state = !led_state;
                    if (write_led(led_state) < 0) {
                        fprintf(stderr, "Error writing to LED, exiting.\n");
                        cleanup_gpio();
                        return 1;
                    }
                    // Reset debounce timer
                    clock_gettime(CLOCK_MONOTONIC, &debounce_start_time);
                }
            } else {
                fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            }
        }

        // Small delay to avoid busy-waiting
        usleep(1000); // 1 ms
    }

    return 0;
}

