#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 2

// Global variables
volatile int running = 1; // Flag to control the main loop
FILE *log_file = NULL;      // File pointer for the log file

// Structure to hold the last state of the sensors
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates last_states = {0, 0};

// Function prototypes
void signal_handler(int signal);
void log_data(int sensor1_state, int sensor2_state);
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
double calculate_rpm();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log data to the CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick1 = 0;
    static int last_state1 = 0;

    if (level != last_state1) {
        uint32_t current_tick = gpioTick();
        if (current_tick - last_tick1 > DEBOUNCE_TIME * 1000) {
            last_states.sensor1_state = level;
            log_data(level, last_states.sensor2_state);
            last_tick1 = current_tick;
            last_state1 = level;
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick2 = 0;
    static int last_state2 = 0;

    if (level != last_state2) {
        uint32_t current_tick = gpioTick();
        if (current_tick - last_tick2 > DEBOUNCE_TIME * 1000) {
            last_states.sensor2_state = level;
            log_data(last_states.sensor1_state, level);
            last_tick2 = current_tick;
            last_state2 = level;
        }
    }
}

// Function to calculate RPM
double calculate_rpm() {
    static uint32_t last_tick = 0;
    static int pulse_count = 0;
    uint32_t current_tick = gpioTick();
    double time_diff, rpm;

    if (pulse_count == 0) {
        last_tick = current_tick;
        pulse_count = 1;
        return 0.0; // Initial state, return 0 RPM
    }

    time_diff = (double)(current_tick - last_tick) / 1000000.0; // Time difference in seconds
    if (time_diff > 0) {
        rpm = (60.0 / time_diff) / PULSES_PER_REVOLUTION;
    } else {
        rpm = 0.0; // Avoid division by zero
    }

    last_tick = current_tick;
    pulse_count = 0; // Reset pulse count after calculation
    return rpm;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback functions for the sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double rpm = calculate_rpm();
        printf("RPM: %.2f\n", rpm);
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and exit
    gpioSetAlertFuncEx(SENSOR1_GPIO, NULL, NULL); // Disable callback
    gpioSetAlertFuncEx(SENSOR2_GPIO, NULL, NULL); // Disable callback

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("RPM monitoring stopped.\n");

    return 0;
}

