#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    int part_id;

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence by reading PART_ID register
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure sensor for continuous measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Reads heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    int hr, spo2_val;

    // Read heart rate data
    hr = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (hr < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", hr);
        return -1;
    }

    // Read SpO2 data
    spo2_val = i2cReadByteData(i2c_handle, SPO2_REG);
