#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define POLL_INTERVAL_MS 100
#define THRESHOLD_DURATION_S 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int check_threshold(int sensor1_value, int sensor2_value);
void activate_alarm(int alarm_pin);
void deactivate_alarm(int alarm_pin);
void log_event(const char *event_type, int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check if threshold is exceeded
int check_threshold(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 1 || sensor2_value == 1);
}

// Function to activate the alarm
void activate_alarm(int alarm_pin) {
    gpioWrite(alarm_pin, 1);
}

// Function to deactivate the alarm
void deactivate_alarm(int alarm_pin) {
    gpioWrite(alarm_pin, 0);
}

// Function to log events to file
void log_event(const char *event_type, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - Sensor 1: %d, Sensor 2: %d\n", timestamp, event_type, sensor1_value, sensor2_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int sensor1_value, sensor2_value;
    int threshold_exceeded = 0;
    time_t threshold_start_time = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        sensor1_value = read_sensor(SENSOR_1_PIN);
        sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values!\n");
            log_event("ERROR", sensor1_value, sensor2_value);
            gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Check if threshold is exceeded
        if (check_threshold(sensor1_value, sensor2_value)) {
            if (!threshold_exceeded) {
                threshold_exceeded = 1;
                threshold_start_time = time(NULL);
                log_event("THRESHOLD_EXCEEDED", sensor1_value, sensor2_value);
            }

            // Check if threshold has been exceeded for the required duration
            if (time(NULL) - threshold_start_time >= THRESHOLD_DURATION_S) {
                activate_alarm(ALARM_PIN);
                log_event("ALARM_ACTIVATED", sensor1_value, sensor2_value);
            }
        } else {
            // Check if both sensors are LOW
            if (threshold_exceeded) {
                deactivate_alarm(ALARM_PIN);
                log_event("ALARM_DEACTIVATED", sensor1_value, sensor2_value);
                threshold_exceeded = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

