#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define CTRL1_REG 0x1F
#define CTRL1_VALUE 0x00
#define ACCEL_X_LSB_REG 0x28
#define ACCEL_X_MSB_REG 0x29
#define ACCEL_Y_LSB_REG 0x2A
#define ACCEL_Y_MSB_REG 0x2B
#define ACCEL_Z_LSB_REG 0x2C
#define ACCEL_Z_MSB_REG 0x2D
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define POLLING_INTERVAL_MS 100
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(double magnitude);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_VALUE);
        if (result == 0) {
            printf("Sensor initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing sensor (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Reads the 3-axis acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB_REG, buffer, 6);
        if (result == 6) {
            // Combine LSB and MSB for each axis (little-endian)
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculates the Euclidean vibration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Controls the LED based on the vibration magnitude
void control_led(double magnitude) {
    if (magnitude > VIBRATION_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        gpioDelay(1000000);      // Wait for 1 second
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Logs the event to the log file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int16_t x, y, z;
    double magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Control LED
            control_led(magnitude);

            // Log event if threshold exceeded
            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Skipping this iteration.\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

