#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
const int gpio_pins[] = {2, 3, 4, 17, 27};
const int num_sensors = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[5] = {NULL, NULL, NULL, NULL, NULL};
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int log_event(int gpio_pin);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);
char* iso8601_timestamp(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read the state of a single sensor
int read_sensor(int gpio_pin) {
    int value = -1;
    int line_index = -1;

    for (int i = 0; i < num_sensors; i++) {
        if (gpio_pins[i] == gpio_pin) {
            line_index = i;
            break;
        }
    }

    if (line_index == -1) {
        syslog(LOG_ERR, "Invalid GPIO pin: %d", gpio_pin);
        return -1;
    }

    int retries = 3;
    while (retries > 0) {
        int ret = gpiod_line_get_value(lines[line_index]);
        if (ret >= 0) {
            value = ret;
            break;
        } else {
            syslog(LOG_ERR, "Failed to read GPIO %d: %s", gpio_pin, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    if (retries == 0) {
        syslog(LOG_ERR, "Failed to read GPIO %d after multiple retries", gpio_pin);
        return -1;
    }

    return value;
}

// Function to log a flame detection event
int log_event(int gpio_pin) {
    FILE *fp = NULL;
    char *timestamp = iso8601_timestamp();

    fp = fopen("/var/log/flame_events.log", "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        free(timestamp);
        return -1;
    }

    // Acquire exclusive lock on the log file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        free(timestamp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, gpio_pin, gpio_pin);
    fflush(fp);

    // Release the lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    fclose(fp);
    free(timestamp);
    return 0;
}

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Function to setup GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    for (int i = 0; i < num_sensors; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %d: %s", gpio_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        int ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request GPIO line %d as input: %s", gpio_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    for (int i = 0; i < num_sensors; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        syslog(LOG_ERR, "GPIO setup failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Flame monitor started");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int current_value = read_sensor(gpio_pins[i]);
            if (current_value == 0) { // Flame detected (LOW signal)
                // Debounce
                usleep(50000); // 50ms
                int debounced_value = read_sensor(gpio_pins[i]);
                if (debounced_value == 0) {
                    if (log_event(gpio_pins[i]) == 0) {
                        syslog(LOG_INFO, "Flame detected on GPIO %d", gpio_pins[i]);
                    } else {
                        syslog(LOG_ERR, "Failed to log event for GPIO %d", gpio_pins[i]);
                    }
                }
            }
        }
        sleep(1); // Check every 1 second
    }

    // Cleanup and exit
    cleanup_gpio();
    syslog(LOG_INFO, "Flame monitor stopped");
    closelog();
    return 0;
}

