    for (i = 0; i < num_sensors; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for pin %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", sensor_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Reads the state of a single sensor pin
int read_sensor(int pin) {
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensor_pins[i] == pin) {
            return gpiod_line_get_value(lines[i]);
        }
    }
    return -1; // Should not happen, but return -1 to indicate an error
}

// Logs an event to the console with an ISO-8601 timestamp
void log_event(int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Sensor %d (BCM %d): %s\n", timestamp, pin, sensor_pins[pin], state ? "TOUCHED" : "RELEASED");
}

// Cleans up GPIO resources
void cleanup_gpio() {
    int i;

    // Release lines
    for (i = 0; i < num_sensors; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    int i, current_state, previous_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (i = 0; i < num_sensors; i++) {
            current_state = read_sensor(sensor_pins[i]);

            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, exiting.\n", sensor_pins[i]);
                cleanup_gpio();
                return 1;
            }

            previous_state = (i > 0) ? (gpiod_line_get_value(lines[i - 1]) == 1) : 0; // Get previous sensor state

            if (current_state != previous_state) {
                log_event(sensor_pins[i], current_state);
            }
        }

        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

