#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define CONFIG_VALUE 0x0000 // ALS Gain 1/8, Integration Time 100ms
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_lux(int *lux);
int set_led_brightness(int brightness);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int config_veml7700() {
    char buf[2];
    buf[0] = CONFIG_REG & 0xFF; // Low byte
    buf[1] = (CONFIG_REG >> 8) & 0xFF; // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
int read_lux(int *lux) {
    char buf[1];
    buf[0] = ALS_REG & 0xFF; // Low byte

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS register address: %s\n", strerror(errno));
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ALS register: %s\n", strerror(errno));
        return -1;
    }

    *lux = (data[1] << 8) | data[0]; // Combine bytes to form 16-bit value
    return 0;
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    gpioPWM(LED_GPIO, brightness);
    return 0;
}

// Log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700 sensor
    if (config_veml7700() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int lux, brightness, error_code;
    int last_error_code = 0;

    // Main loop
    while (!terminate) {
        error_code = 0;
        if (read_lux(&lux) != 0) {
            error_code = 1;
        } else {
            // Adaptive brightness logic
            if (lux < 100) {
                brightness = PWM_RANGE;
            } else if (lux < 500) {
                brightness = (3 * PWM_RANGE) / 4;
            } else if (lux < 1000) {
                brightness = (PWM_RANGE) / 2;
            } else {
                brightness = (PWM_RANGE) / 4;
            }

            if (set_led_brightness(brightness) != 0) {
                error_code = 2;
            }
        }

        log_data(lux, brightness, error_code);
        last_error_code = error_code;

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

