#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor_channel(int channel);
int log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor state
typedef struct {
    int last_state[8];
    unsigned long last_debounce_time[8];
} SensorState;

SensorState sensor_state = {{0}, {0}};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially off

    // Set sensor pins as input with pull-down resistors
    int sensor_pins[] = SENSOR_PINS;
    for (int i = 0; i < 8; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
        sensor_state.last_state[i] = 0; // Initialize last state to 0 (released)
        sensor_state.last_debounce_time[i] = 0;
    }

    return 0;
}

// Function to read sensor channel with debouncing
int read_sensor_channel(int channel) {
    int reading = gpioRead(channel);
    unsigned long now = gpioTick();

    if (reading != sensor_state.last_state[channel - 2]) {
        if (now - sensor_state.last_debounce_time[channel - 2] > DEBOUNCE_TIME * 1000) {
            sensor_state.last_state[channel - 2] = reading;
            sensor_state.last_debounce_time[channel - 2] = now;
            return reading;
        }
    }
    return 0; // Return 0 if not debounced
}

// Function to log touch event to file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Keypad simulation started. Press Ctrl+C to exit.\n");

    int any_touched = 0;

    while (running) {
        int sensor_pins[] = SENSOR_PINS;
        for (int i = 0; i < 8; i++) {
            int touch = read_sensor_channel(sensor_pins[i]);

            if (touch == 1) {
                if (log_touch_event(sensor_pins[i]) == 0) {
                    printf("Channel %d touched.\n", sensor_pins[i]);
                }
                any_touched = 1;
            }
        }

        if (any_touched) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        any_touched = 0; // Reset for next iteration
        gpioDelay(50); // Poll every 50 ms
    }

    cleanup();
    return 0;
}

