#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810 // Continuous conversion, auto full-scale, 100ms conversion time
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_opt3001();
int read_opt3001(uint16_t *raw_data);
float calculate_lux(uint16_t raw_data);
int log_data(float lux_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_opt3001() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_WORD);
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the result register from the OPT3001 sensor
int read_opt3001(uint16_t *raw_data) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Byte swap for big-endian
    *raw_data = ((result & 0xFF00) >> 8) | ((result & 0x00FF) << 8);

    return 0;
}

// Calculate lux value from raw data
