    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        log_event("Program terminated by user (Ctrl+C).");

        // Close the log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Reset GPIO pins
        gpioWrite(ALERT_LED_PIN, 0); // Ensure LED is off
        gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set flame sensor pin to input
        gpioSetMode(ALERT_LED_PIN, PI_INPUT); // Set alert LED pin to input

        // Terminate pigpio
        if (pigpio_initialized) {
            gpioTerminate();
        }

        exit(0);
    }
}

