            log_event("Flame detected!");
            trigger_alert();
        } else if (flame_detected > 0) {
            // No flame detected
        } else {
            // Error reading sensor, already logged in read_flame_sensor
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

