#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50 // milliseconds
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a touch event to the file
int log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

int main() {
    int touch_state = 0; // 0 = released, 1 = pressed
    int last_touch_state = 0;
    int gpio_status;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input with a pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file for appending
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Release GPIO resources before exiting
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the current state of the GPIO pin
        touch_state = gpioRead(GPIO_PIN);

        // Debounce and log touch events
        if (touch_state != last_touch_state) {
            gpio_status = gpioRead(GPIO_PIN);
            if (gpio_status == 1) {
                if (log_touch_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }
            } else {
                if (log_touch_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch release event.\n");
                }
            }
            last_touch_state = touch_state;
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Debounce delay in microseconds
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup and exit
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    gpioTerminate();
    return 0;
}

