#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define FLOW_COMMAND_1 0x36
#define FLOW_COMMAND_2 0x08
#define FLOW_SCALE_FACTOR 90.0
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data);
float convert_to_ml_min(int16_t raw_flow);
void log_data(float flow_rate, int status_code, const char *status_string);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the SLF3S-1300F
int read_sensor_data(uint8_t *data) {
    char command[2] = {FLOW_COMMAND_1, FLOW_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data) {
    uint8_t crc = 0xFF;
    uint8_t data_msb = data[0];
    uint8_t data_lsb = data[1];

    for (int i = 0; i < 2; i++) {
        crc ^= data_msb;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
        data_msb = data_lsb;
    }

    if (crc != data[2]) {
        fprintf(stderr, "CRC validation failed: expected 0x%02X, got 0x%02X\n", data[2], crc);
        return -1;
    }
    return 0;
}

// Convert raw flow value to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_SCALE_FACTOR;
}

// Log data to CSV file
void log_data(float flow_rate, int status_code, const char *status_string) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%s\n", timestamp, flow_rate, status_code, status_string);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_data(0.0, 1, "I2C Initialization Failed");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[3];
    int16_t raw_flow;
    float flow_rate;
    int status_code = 0;
    char status_string[64];

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data) == 0) {
                // Convert to ml/min
                raw_flow = (sensor_data[0] << 8) | sensor_data[1];
                flow_rate = convert_to_ml_min(raw_flow);

                // Validate flow rate
                if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX) {
                    status_code = 0;
                    snprintf(status_string, sizeof(status_string), "OK");
                } else {
                    status_code = 2;
                    snprintf(status_string, sizeof(status_string), "INVALID");
                }

                // Log data
                log_data(flow_rate, status_code, status_string);
                printf("Flow Rate: %.2f ml/min, Status: %s\n", flow_rate, status_string);
            } else {
                // CRC validation failed
                log_data(0.0, 1, "CRC Validation Failed");
                fprintf(stderr, "CRC validation failed. Attempting to re-initialize I2C.\n");
                i2cClose(i2c_handle);
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed.\n");
                }
            }
        } else {
