}

// Initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);

    if (!left_line || !middle_line || !right_line) {
        perror("Error getting GPIO line");
        if (left_line) gpiod_line_release(left_line);
        if (middle_line) gpiod_line_release(middle_line);
        if (right_line) gpiod_line_release(right_line);
        if (chip) gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(left_line, "obstacle_avoidance");
    if (ret < 0) {
        perror("Error requesting left GPIO line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(middle_line, "obstacle_avoidance");
    if (ret < 0) {
