        line = middle_line;
    } else if (gpio_pin == RIGHT_SENSOR) {
        line = right_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }

    return value;
}

