#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_DELAY_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a flame event to the log file
int log_flame_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Flame detected\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to print a flame event to stdout
void print_flame_event(const char *timestamp) {
    printf("%s - Flame detected!\n", timestamp);
}

// Function to handle a flame detection event
void handle_flame_detection(const char *timestamp) {
    if (log_flame_event(timestamp) == 0) {
        print_flame_event(timestamp);
    } else {
        fprintf(stderr, "Failed to log flame event.\n");
    }
}

// Function to read the flame sensor with debouncing
int read_flame_sensor(struct gpiod_line *line) {
    int value;
    int ret;

    ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        perror("Error reading GPIO line");
        return -1;
    }

    if (value == 0) { // Flame detected (active-low)
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);
        return 0; // Return 0 to indicate flame detected after debouncing
    }

    return -1; // No flame detected
}

// Function to monitor the flame sensor for falling edges
void monitor_flame_sensor(struct gpiod_line *line) {
    int prev_value = 1; // Initialize to no flame detected
    int current_value;
    int ret;

    while (!terminate) {
        ret = gpiod_line_get_value(line, &current_value);
        if (ret < 0) {
            perror("Error reading GPIO line");
            break;
        }

        if (current_value == 0 && prev_value == 1) { // Falling edge detected
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                handle_flame_detection(timestamp);
                free(timestamp);
            }
        }

        prev_value = current_value;
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10 * 1000000; // Check every 10ms
        nanosleep(&delay, NULL);
    }
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_request_config config_out;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("flame_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
