    log_file = fopen("flame_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Monitor the flame sensor
    monitor_flame_sensor(line);

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

