int log_event(int led_state);
void cleanup_gpio(void);
void signal_handler(int signal);

// Function to setup GPIO lines
int setup_gpio(void) {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Request touch sensor line as input
    touch_line = gpiod_chip_get_line(gpio_chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting touch sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to toggle the LED
int toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading current LED value: %s\n", strerror(errno));
        return -1;
    }

    int new_value = !current_value;
    if (gpiod_line_set_value(led_line, new_value) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }
    return new_value;
}

// Function to log the event
