        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    int led_state = 0; // Initial LED state

    // Main loop
    while (1) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            break;
        }

        if (touch_value == 1) {
            led_state = toggle_led();
            if (led_state < 0) {
                fprintf(stderr, "Error toggling LED, exiting.\n");
                break;
            }
            log_event(led_state);
        }

        // Poll for touch events with a timeout
        struct gpiod_line_event event;
        struct timespec timeout = {1, 0}; // 1 second
        int ret = gpiod_line_event_wait(touch_line, &event, &timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit gracefully
                break;
            } else {
                fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

