    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request flame sensor line as input
    ret = gpiod_line_request_input(flame_line, "flame_alert");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    // Request buzzer line as output
    ret = gpiod_line_request_output(buzzer_line, "flame_alert", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for a given duration
int activate_buzzer(int duration_ms) {
    int i, ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 100 ms

    // Activate buzzer
    ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
        return -1;
    }

    // Sleep for the specified duration
    for (i = 0; i < duration_ms / 100; i++) {
        if (terminate) break; // Check for termination signal
        nanosleep(&sleep_time, NULL);
    }

    // Deactivate buzzer
    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&now);
    timeinfo = localtime(&now);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write to log file
    fprintf(log_file, "%s: %s\n", timestamp, message);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Deactivate buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Release lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    int flame_detected = 0;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Log system start
    log_event("System started");

    // Main loop
    while (!terminate) {
        int current_value = read_flame_sensor();
        if (current_value < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        // Detect flame (LOW signal)
        if (current_value == 0 && !flame_detected) {
            flame_detected = 1;
            log_event("Flame detected!");
            if (activate_buzzer(2000) < 0) {
                fprintf(stderr, "Error activating buzzer, exiting.\n");
                break;
            }
        } else if (current_value == 1) {
            flame_detected = 0;
        }

        // Sleep for 500 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Log system stop
    log_event("System stopped");

    // Cleanup and exit
    cleanup();
    return 0;
}

