    // Main loop
    while (1) {
        // Read sensor states
        int new_sensor1_state = read_sensor(SENSOR1_GPIO);
        int new_sensor2_state = read_sensor(SENSOR2_GPIO);
        int new_sensor3_state = read_sensor(SENSOR3_GPIO);

        if (new_sensor1_state == -1 || new_sensor2_state == -1 || new_sensor3_state == -1) {
            gpioDelay(100); // Wait 100ms before retrying
            continue; // Skip to the next iteration
        }

        // Check for state changes and log them
        if (new_sensor1_state != sensor1.last_state) {
            log_state(SENSOR1_GPIO, new_sensor1_state);
            sensor1.last_state = new_sensor1_state;
        }
        if (new_sensor2_state != sensor2.last_state) {
            log_state(SENSOR2_GPIO, new_sensor2_state);
            sensor2.last_state = new_sensor2_state;
        }
        if (new_sensor3_state != sensor3.last_state) {
            log_state(SENSOR3_GPIO, new_sensor3_state);
            sensor3.last_state = new_sensor3_state;
        }

        gpioDelay(100); // Wait 100ms
    }

    return 0;
}

