#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d from chip '%s': %s\n", GPIO_LINE, GPIO_CHIP, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the flame detection event
int log_flame_detection() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int last_state = 1; // Assume initially no flame (HIGH)
    int current_state;

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        current_state = read_flame_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_state == 0 && last_state == 1) {
            // Falling edge detected
            printf("FLAME DETECTED\n");
            if (log_flame_detection() != 0) {
                fprintf(stderr, "Error logging flame detection.\n");
            }
        }

        last_state = current_state;
        gpiod_line_release(line);
        gpiod_line_request_input(line, "flame_sensor");
        struct timespec delay = {0, 100000000}; // 100 ms
        nanosleep(&delay, NULL);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

