#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for sensor inputs and output bits
const int sensor_pins[] = {5, 6, 7, 8, 9, 10, 11, 12};
const int output_pins[] = {17, 18, 19, 20, 21, 22, 23, 24};
const int num_channels = 8;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[num_channels];
static struct gpiod_line *output_lines[num_channels];
static volatile sig_atomic_t terminate = 0;
static int counter = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int channel);
void update_output(int bit, int value);
void increment_counter(void);
void log_touch_event(int channel, int counter_value);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up resources...\n");
    // Release sensor lines
    for (int i = 0; i < num_channels; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
            sensor_lines[i] = NULL;
        }
    }

    // Release output lines
    for (int i = 0; i < num_channels; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
            output_lines[i] = NULL;
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request sensor input lines
    for (i = 0; i < num_channels; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(sensor_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Request output lines
    for (i = 0; i < num_channels; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(output_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Read sensor value for a given channel
int read_sensor(int channel) {
    int value = -1;
    int retries = 3;

    while (retries > 0) {
        value = gpiod_line_get_value(sensor_lines[channel]);
        if (value >= 0) {
            return value;
        } else {
            fprintf(stderr, "Error reading sensor line %d: %s\n", sensor_pins[channel], strerror(errno));
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }

    return -1; // Indicate error after retries
}

// Update the output bit for a given channel
void update_output(int bit, int value) {
    int result = gpiod_line_set_value(output_lines[bit], value);
    if (result < 0) {
        fprintf(stderr, "Error setting output line %d: %s\n", output_pins[bit], strerror(errno));
    }
}

// Increment the counter and update the output bits
void increment_counter(void) {
    counter = (counter + 1) % 256;
    for (int i = 0; i < num_channels; i++) {
        update_output(i, (counter >> i) & 1);
    }
}

// Log touch event to file
void log_touch_event(int channel, int counter_value) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm *tm = gmtime(&t);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter_value);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Stabilization delay
    usleep(200000); // 200 ms

    // Main loop
    int sensor_values[num_channels];
    int previous_sensor_values[num_channels];

    for (int i = 0; i < num_channels; i++) {
        sensor_values[i] = 0;
        previous_sensor_values[i] = 0;
    }

    while (!terminate) {
        for (int i = 0; i < num_channels; i++) {
            sensor_values[i] = read_sensor(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i + 1);
                continue;
            }

            if (sensor_values[i] == 1 && previous_sensor_values[i] == 0) {
                // Rising edge detected
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                log_touch_event(i, counter);
                increment_counter();
            }
            previous_sensor_values[i] = sensor_values[i];
        }
        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

