#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate and LED duration
#define SAMPLING_RATE 8000 // Hz
#define LED_DURATION 100    // ms

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", MIC_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        return -1;
    }
    return 0;
}

// Function to sample the microphone input
int sample_microphone()
{
    return gpioRead(MIC_PIN);
}

// Function to control the LED
void control_led(int on)
{
    if (gpioWrite(LED_PIN, on) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LED_PIN);
    }
}

// Function to handle sound peak detection and LED control
void handle_sound_peak()
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    printf("%ld\n", timestamp_ms);
    control_led(1); // Turn LED on
    gpioDelay(LED_DURATION * 1000); // Delay for 100ms
    control_led(0); // Turn LED off
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (sample_microphone() == 1) {
            handle_sound_peak();
        }
        gpioDelay(125); // Delay for 125 microseconds (8kHz sampling rate)
    }

    // Clean up and exit
    printf("Exiting gracefully...\n");
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    return 0;
}

