#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49

// Define register addresses
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a register from the Si1175
int read_register(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }
    return 0;
}

// Function to read ALS visible data
int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t lsb, msb;

    if (read_register(fd, ALS_VIS_LSB_REG, &lsb) != 0) {
        fprintf(stderr, "Error reading ALS visible LSB\n");
        return -1;
    }

    if (read_register(fd, ALS_VIS_MSB_REG, &msb) != 0) {
        fprintf(stderr, "Error reading ALS visible MSB\n");
        return -1;
    }

    *als_visible = (msb << 8) | lsb;
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("Si1175 ALS Visible Data Reader\n");

    // Main loop
    while (1) {
        uint16_t als_visible;

        if (read_als_visible(i2c_fd, &als_visible) == 0) {
            printf("ALS Visible: %u\n", als_visible);
        } else {
            fprintf(stderr, "Failed to read ALS visible data\n");
        }

        usleep(100000); // 100 ms
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

