#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        fprintf(stderr, "Error getting GPIO line for LEFT_PIN: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!middle_line) {
        fprintf(stderr, "Error getting GPIO line for MIDDLE_PIN: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        fprintf(stderr, "Error getting GPIO line for RIGHT_PIN: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        return 1;
    }

    // Request GPIO lines as input
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for LEFT_PIN as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return 1;
    }

    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for MIDDLE_PIN as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return 1;
    }

    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for RIGHT_PIN as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        // Log sensor values
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

