#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for each channel
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Function prototypes
int read_sensor_channel(int channel);
void log_sensor_data(int channel_states[8]);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    exit(0);
}

// Function to read the state of a single sensor channel
int read_sensor_channel(int channel) {
    int value = -1; // Initialize to an invalid value
    int pin = gpio_pins[channel];

    if (lines[channel]) {
        value = gpiod_line_get_value(lines[channel]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", pin, strerror(errno));
            return -1; // Indicate an error
        }
    } else {
        fprintf(stderr, "Line %d not initialized\n", pin);
        return -1; // Indicate an error
    }

    return value;
}

// Function to log the sensor data to the console
void log_sensor_data(int channel_states[8]) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double elapsed_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    printf("[%03.3fs] ", elapsed_time);

    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, channel_states[i]);
    }
    printf("\n");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines for each channel
    for (int i = 0; i < num_channels; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!line) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }

        int ret = gpiod_line_request_input(line, "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", gpio_pins[i], strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        lines[i] = line;
    }

    // Main loop to read and log sensor data
    while (1) {
        int channel_states[8];

        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_sensor_channel(i);
            if (channel_states[i] == -1) {
                // Handle read error, but continue to the next channel
                channel_states[i] = 0; // Set to a default value to avoid further issues
            }
        }

        log_sensor_data(channel_states);

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200 * 1000 * 1000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

