void fade_to_color(int red, int green, int blue, int duration_ms) {
    int steps = NUM_FADE_STEPS;
    int delay_ms = duration_ms / steps;
    float red_increment = (float)red / steps;
    float green_increment = (float)green / steps;
    float blue_increment = (float)blue / steps;

    float current_red = 0.0;
    float current_green = 0.0;
    float current_blue = 0.0;

    for (int i = 0; i < steps; i++) {
        current_red += red_increment;
        current_green += green_increment;
        current_blue += blue_increment;

        int r = (int)current_red;
        int g = (int)current_green;
        int b = (int)current_blue;

