        gpioDelay(delay_ms * 1000); // Convert ms to microseconds
    }
}

// Convert HSV color space to RGB color space
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    if (s == 0.0) {
        *r = *g = *b = (int)(v * 255);
        return;
    }

    h = fmod(h, 360.0);
    h /= 60.0;
    int i = (int)h;
    float f = h - i;
    float p = v * (1 - s);
    float q = v * (1 - s * f);
    float t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        default: // case 5:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

