unsigned char read_light_level() {
    unsigned char data[2];
    int lux;

    // Send power on and start measurement command (high resolution mode)
    unsigned char config[1] = {0x10}; // Continuous high resolution mode
    if (write(i2c_fd, config, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return 0; // Return 0 lux on error
    }

    // Wait for measurement to complete (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return 0; // Return 0 lux on error
    }

    // Combine the two bytes to get the lux value
    lux = (data[0] << 8) | data[1];

    return (unsigned char)lux;
}

// Seed the random number generator with entropy from /dev/urandom
void seed_random() {
    int fd;
    unsigned char buf[4];

    fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        return;
    }

    if (read(fd, buf, 4) != 4) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        close(fd);
        return;
    }

    close(fd);
    srand(buf[0] * 256 + buf[1] * 256 + buf[2] * 256 + buf[3]);
}

