        // Convert hue to RGB
        int red, green, blue;
        hsv_to_rgb(hue, 1.0, 1.0, &red, &green, &blue);

        // Read light level
        unsigned char light_level = read_light_level();

        // Adjust brightness based on light level
        float brightness_factor = (float)light_level / 1000.0; // Assuming max lux is 1000
        if (brightness_factor > 1.0) brightness_factor = 1.0;

        red   = (int)(red   * brightness_factor);
        green = (int)(green * brightness_factor);
        blue  = (int)(blue  * brightness_factor);

        // Fade to the new color
        fade_to_color(red, green, blue, FADE_DURATION);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

