#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_ID 0x12
#define TCS34725_PON 0x00
#define TCS34725_AEN 0x01
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define LED_GPIO 17
#define RED_THRESHOLD 200

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
volatile sig_atomic_t running = 1;

// Calibration parameters (example values, adjust as needed)
float clear_gain = 1.0;
float red_gain = 1.0;
float green_gain = 1.0;
float blue_gain = 1.0;
float clear_offset = 0.0;
float red_offset = 0.0;
float green_offset = 0.0;
float blue_offset = 0.0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_word(int fd, uint8_t reg);
int tcs34725_init(int fd);
int read_color_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
void control_led(int gpio, float calibrated_red);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[1] << 8) | buf[0]; // Combine bytes into a 16-bit value
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Verify sensor ID
        int sensor_id = i2c_read_word(fd, TCS34725_ID);
        if (sensor_id < 0) {
            fprintf(stderr, "Error reading sensor ID, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        if (sensor_id != 0x44) {
            fprintf(stderr, "Incorrect sensor ID: 0x%02X, expected 0x44, retrying...\n", sensor_id);
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Power on the sensor
        if (i2c_write_byte(fd, TCS34725_PON, 0x01) < 0) {
            fprintf(stderr, "Error powering on sensor, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        usleep(3000); // Wait for PON to stabilize

        // Enable RGBC
        if (i2c_write_byte(fd, TCS34725_AEN, 0x03) < 0) {
            fprintf(stderr, "Error enabling RGBC, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Set integration time
        if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) < 0) {
            fprintf(stderr, "Error setting integration time, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Set gain
        if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) < 0) {
            fprintf(stderr, "Error setting gain, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        printf("TCS34725 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "TCS34725 initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read color data function
int read_color_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    *clear = i2c_read_word(fd, TCS34725_CDATA);
    *red = i2c_read_word(fd, TCS34725_RDATA);
    *green = i2c_read_word(fd, TCS34725_GDATA);
    *blue = i2c_read_word(fd, TCS34725_BDATA);

    if (*clear < 0 || *red < 0 || *green < 0 || *blue < 0) {
        fprintf(stderr, "Error reading color data.\n");
        return -1;
    }

    return 0;
}

// Calibrate color data function
void calibrate_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    *calibrated_clear = (float)clear * clear_gain + clear_offset;
    *calibrated_red = (float)red * red_gain + red_offset;
    *calibrated_green = (float)green * green_gain + green_offset;
    *calibrated_blue = (float)blue * blue_gain + blue_offset;
}

// Control LED function
void control_led(int gpio, float calibrated_red) {
    if (calibrated_red > RED_THRESHOLD) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get LED GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request LED GPIO line for output
    if (gpiod_line_request_output(led_line, "tcs34725_led", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t clear, red, green, blue;
    float calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;
    while (running) {
        // Read color data
        if (read_color_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate color data
            calibrate_color_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Display calibrated RGB and clear values
            printf("C: %.2f, R: %.2f, G: %.2f, B: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED
            control_led(LED_GPIO, calibrated_red);
        } else {
            fprintf(stderr, "Failed to read color data, attempting re-initialization...\n");
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                running = 0; // Exit loop if I2C fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                running = 0;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                close(i2c_fd);
                running = 0;
                continue;
            }
        }

        usleep(200000); // Poll every 200 ms
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

