#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define NUM_LEDS 10
#define GPIO_PIN 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void set_led_brightness(int brightness);
int map_lux_to_brightness(float lux);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    int retries = 0;
    int msb, lsb;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Failed to set BH1750 mode, retry %d\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(180000); // Wait 180ms

        msb = i2cReadByteData(i2c_handle, 0x00);
        lsb = i2cReadByteData(i2c_handle, 0x01);

        if (msb >= 0 && lsb >= 0) {
            *lux = (float)((msb << 8) | lsb) / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read BH1750 data, retry %d\n", retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return 1; // Failure
}

// Set LED brightness using pigpio's hardware PWM
void set_led_brightness(int brightness) {
    // Create a wave with the specified brightness
    gpioWaveClear();

    for (int i = 0; i < NUM_LEDS; i++) {
        // Generate a wave for a single LED
        gpioPulse_t pulse[24]; // 24 pulses per LED (8 bits * 3 levels)
        for (int j = 0; j < 24; j++) {
            if (j % 3 == 0) {
                // Green
                pulse[j].gpioOn = (1 << GPIO_PIN);
                pulse[j].gpioOff = 0;
                pulse[j].usDelay = (int)(2500 * brightness / 100.0); // Adjust delay based on brightness
            } else if (j % 3 == 1) {
                // Red
                pulse[j].gpioOn = (1 << GPIO_PIN);
                pulse[j].gpioOff = 0;
                pulse[j].usDelay = (int)(2500 * brightness / 100.0); // Adjust delay based on brightness
            } else {
                // Blue
                pulse[j].gpioOn = (1 << GPIO_PIN);
                pulse[j].gpioOff = 0;
                pulse[j].usDelay = (int)(2500 * brightness / 100.0); // Adjust delay based on brightness
            }
        }

        gpioWaveAddGeneric(24, pulse);

        // Add a small delay between LEDs
        gpioPulse_t led_delay;
        led_delay.gpioOn = 0;
        led_delay.gpioOff = 0;
        led_delay.usDelay = 10; // Small delay between LEDs
        gpioWaveAddGeneric(1, &led_delay);
    }

    // Create the wave
    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        // Transmit the wave
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Repeat indefinitely
    } else {
        fprintf(stderr, "Failed to create wave: %d\n", wave_id);
    }

    gpioWaveDelete(wave_id);
}

// Map lux value to brightness using a logarithmic scale
int map_lux_to_brightness(float lux) {
    // Clamp lux value to a reasonable range
    if (lux < 0) lux = 0;
    if (lux > 1000) lux = 1000;

    // Logarithmic mapping
    float brightness = 100.0 * (log10(lux + 1) / log10(1001)); // Map 0-1000 lux to 0-100 brightness

    return (int)brightness;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveTxStop(); // Stop any running waves
    gpioWaveClear();   // Clear any pending waves
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read light level\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

