#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define START_FRAME 0x00000000
#define END_FRAME 0xFFFFFFFF

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int bh1750_init(int fd);
int bh1750_read_lux(int fd);
float lux_to_brightness(float lux);
int apa102_set_brightness(int fd, int brightness);
int apa102_send_frame(int fd, uint32_t frame);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize BH1750 sensor
int bh1750_init(int fd) {
    uint8_t init_cmd = 0x20; // One-Time High-Resolution Mode
    if (write(fd, &init_cmd, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int bh1750_read_lux(int fd) {
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    uint16_t raw = (data[0] << 8) | data[1];
    return raw;
}

// Convert lux to APA102 brightness (0-31)
float lux_to_brightness(float lux) {
    if (lux < 10) {
        return 0.0;
    } else if (lux > 300) {
        return 31.0;
    } else {
        return (lux - 10) * (31.0 / 290.0);
    }
}

// Set APA102 brightness for all LEDs
int apa102_set_brightness(int fd, int brightness) {
    uint8_t buffer[4 * (NUM_LEDS + 2)];
    memset(buffer, 0, sizeof(buffer));

    // Start frame
    for (int i = 0; i < 4; i++) {
        buffer[i] = (START_FRAME >> (8 * i)) & 0xFF;
    }

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        uint8_t frame = 0xE0 | (brightness & 0x1F);
        for (int j = 0; j < 4; j++) {
            buffer[4 + i * 4 + j] = (frame >> (8 * j)) & 0xFF;
        }
    }

    // End frame
    for (int i = 0; i < 4; i++) {
        buffer[4 + NUM_LEDS * 4 + i] = (END_FRAME >> (8 * i)) & 0xFF;
    }

    if (write(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to write to SPI device");
        return -1;
    }
    return 0;
}

// Send a single APA102 frame
int apa102_send_frame(int fd, uint32_t frame) {
    uint8_t buffer[4];
    for (int i = 0; i < 4; i++) {
        buffer[i] = (frame >> (8 * i)) & 0xFF;
    }
    if (write(fd, buffer, 4) != 4) {
        perror("Failed to write to SPI device");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
