#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define I2C bus and sensor addresses
#define I2C_BUS 1
#define SENSOR_ADDR_LOW 0x23
#define SENSOR_ADDR_HIGH 0x5C

// Define APA102 start frame and end frame
#define APA102_START_FRAME 0x00
#define APA102_END_FRAME 0xFF

// Define APA102 brightness level (0-31)
#define APA102_BRIGHTNESS 0x00

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_lux(float lux1, float lux2);
int map_lux_to_brightness(float average_lux);
int set_apa102_brightness(int brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x21, 0x00) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(180); // Wait for conversion (at least 180ms)

    int lux = i2cReadWordData(i2c_handle, 0x00);
    if (lux < 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return lux;
}

// Function to average lux readings
float average_lux(float lux1, float lux2) {
    int count = 0;
    float sum = 0.0;

    if (lux1 >= 0) {
        sum += lux1;
        count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        count++;
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

// Function to map lux value to APA102 brightness level
int map_lux_to_brightness(float average_lux) {
    // Inverse mapping: lower lux -> higher brightness
    int brightness = 31 - (int)(average_lux / 100.0); // Example mapping
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

// Function to set APA102 strip brightness
int set_apa102_brightness(int brightness) {
    char buffer[4];
    buffer[0] = APA102_START_FRAME;
    buffer[1] = 0x00; // Global brightness (0-31)
    buffer[2] = brightness;
    buffer[3] = APA102_END_FRAME;

    if (spiWrite(spi_handle, buffer, 4) != 4) {
        fprintf(stderr, "Error writing to SPI device.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle_low = i2cOpen(I2C_BUS, SENSOR_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X\n", SENSOR_ADDR_LOW);
        i2c_handle_low = -1; // Mark as invalid
    }

    i2c_handle_high = i2cOpen(I2C_BUS, SENSOR_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X\n", SENSOR_ADDR_HIGH);
        i2c_handle_high = -1; // Mark as invalid
    }

    // Open SPI handle
    spi_handle = spiOpen(0, 500000, 0); // SPI channel 0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float lux_low = -1.0, lux_high = -1.0;

        // Read lux values from sensors
        if (i2c_handle_low >= 0) {
            lux_low = read_bh1750(i2c_handle_low);
        }
        if (i2c_handle_high >= 0) {
            lux_high = read_bh1750(i2c_handle_high);
        }

        // Calculate average lux
        float average_lux = average_lux(lux_low, lux_high);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux);

        // Fade to target brightness
        int current_brightness = 0; // Initialize current brightness
        int steps = 50; // Number of steps for fading
        float increment = (float)(target_brightness - current_brightness) / steps;

        for (int i = 0; i < steps; i++) {
            current_brightness = (int)(current_brightness + increment);
            if (set_apa102_brightness(current_brightness) != 0) {
                fprintf(stderr, "Error setting APA102 brightness\n");
                break;
            }
            gpioDelay(1000); // 1ms delay
        }

        gpioDelay(100); // 100ms delay
    }

    // Clean up and exit
    set_apa102_brightness(0); // Turn off LEDs
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

