#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 1 // Single LED for simplicity
#define LUX_MAX 120000.0
#define LUX_MIN 0.0
#define BRIGHTNESS_MAX 255.0
#define BRIGHTNESS_MIN 0.0
#define BIT_BANG_FREQUENCY 800000 // 800 kHz
#define BIT_BANG_THRESHOLD 100000 // 100 ms
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init();
int veml7700_read_als(uint16_t *als);
float veml7700_convert_to_lux(uint16_t als);
uint8_t map_lux_to_brightness(float lux);
void ws2812b_bitbang(uint8_t brightness);
void signal_handler(int signal);
void cleanup();

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    struct timeval tv;
    struct tm *tm_info;
    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init() != 0)
    {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return 1;
    }

    uint16_t als_value;
    float lux;
    uint8_t brightness;
    char timestamp[26];

    // Main loop
    while (!terminate)
    {
        // Read ALS data
        if (veml7700_read_als(&als_value) != 0)
        {
            fprintf(stderr, "Failed to read ALS data\n");
            continue; // Continue to the next iteration
        }

        // Convert to lux
        lux = veml7700_convert_to_lux(als_value);

        // Map lux to brightness
        brightness = map_lux_to_brightness(lux);

        // Drive WS2812B LED
        ws2812b_bitbang(brightness);

        // Print data
        get_timestamp(timestamp);
        printf("%s - ALS: %u, Lux: %.2f, Brightness: %d\n", timestamp, als_value, lux, brightness);

        // Delay
        gpioDelay(LOOP_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize VEML7700 sensor
int veml7700_init()
{
    int retries = I2C_RETRY_COUNT;
    int status;

    while (retries > 0)
    {
        status = i2cWriteWordData(i2c_handle, VEML7700_CONFIG, 0x0000); // Integration time 100ms, Gain 1/8
        if (status == 0)
        {
            return 0; // Success
        }
        else
        {
            fprintf(stderr, "VEML7700 init failed (attempt %d): %d\n", I2C_RETRY_COUNT - retries + 1, status);
            retries--;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    return -1; // Failure after retries
}

// Read ALS data from VEML7700
int veml7700_read_als(uint16_t *als)
{
    int retries = I2C_RETRY_COUNT;
    int status;

    while (retries > 0)
    {
        status = i2cReadWordData(i2c_handle, VEML7700_ALS_DATA);
        if (status >= 0)
        {
            *als = (uint16_t)status;
            return 0; // Success
        }
        else
        {
            fprintf(stderr, "VEML7700 read failed (attempt %d): %d\n", I2C_RETRY_COUNT - retries + 1, status);
            retries--;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    return -1; // Failure after retries
}

// Convert raw ALS value to lux
float veml7700_convert_to_lux(uint16_t als)
{
    return (float)als * 0.0288; // Default settings: gain 1/8, integration time 100ms
}

// Map lux value to brightness (0-255) with gamma correction
uint8_t map_lux_to_brightness(float lux)
{
    if (lux < LUX_MIN)
    {
