#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define error codes
#define ERROR_NONE 0
#define ERROR_GPIOD 1
#define ERROR_SENSOR 2

// Define self-test parameters
#define SELF_TEST_READS 5
#define SELF_TEST_INTERVAL_MS 100

// Define error signal parameters
#define ERROR_BLINK_COUNT 5
#define ERROR_BLINK_INTERVAL_MS 100
#define ERROR_BUZZER_PATTERN_COUNT 3
#define ERROR_BUZZER_PATTERN_MS {200, 200, 600, 200}

// Define flame detection parameters
#define FLAME_DETECTED 0 // Active-low sensor
#define FLAME_GONE 1

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int self_test(void);
int read_flame_sensor(void);
void activate_buzzer(void);
void deactivate_buzzer(void);
void activate_led(void);
void deactivate_led(void);
void log_event(const char *event);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return ERROR_GPIOD;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error: Could not get flame sensor line %d\n", FLAME_SENSOR_PIN);
        goto cleanup_chip;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error: Could not get buzzer line %d\n", BUZZER_PIN);
        goto cleanup_flame_line;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get LED line %d\n", LED_PIN);
        goto cleanup_buzzer_line;
    }

    // Request flame sensor line for input
    ret = gpiod_line_request_input(flame_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request flame sensor line for input\n");
        goto cleanup_led_line;
    }

    // Request buzzer line for output
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request buzzer line for output\n");
        goto cleanup_flame_line;
    }

    // Request LED line for output
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request LED line for output\n");
        goto cleanup_buzzer_line;
    }

    return ERROR_NONE;

cleanup_led_line:
    gpiod_line_release(led_line);
cleanup_buzzer_line:
    gpiod_line_release(buzzer_line);
cleanup_flame_line:
    gpiod_line_release(flame_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return ERROR_GPIOD;
}

// Function to perform self-test
int self_test(void) {
    int i;
    int flame_detected_count = 0;

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        activate_led();
        usleep(500000); // 500 ms
        deactivate_led();
        usleep(500000); // 500 ms
    }

    // Read flame sensor 5 times
    for (i = 0; i < SELF_TEST_READS; i++) {
        int value = gpiod_line_get_value(flame_line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read flame sensor value\n");
            return ERROR_GPIOD;
        }
        if (value == FLAME_DETECTED) {
            flame_detected_count++;
        }
        usleep(SELF_TEST_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Check if flame detected consistently
    if (flame_detected_count == SELF_TEST_READS) {
        fprintf(stderr, "Error: Flame sensor fault detected during self-test\n");
        return ERROR_SENSOR;
    }

    return ERROR_NONE;
}

// Function to read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read flame sensor value\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to activate buzzer
void activate_buzzer(void) {
    gpiod_line_set_value(buzzer_line, 1);
}

// Function to deactivate buzzer
void deactivate_buzzer(void) {
    gpiod_line_set_value(buzzer_line, 0);
}

// Function to activate LED
void activate_led(void) {
    gpiod_line_set_value(led_line, 1);
}

// Function to deactivate LED
void deactivate_led(void) {
    gpiod_line_set_value(led_line, 0);
}

// Function to log events
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup function to release GPIO resources
void cleanup(void) {
    printf("Cleaning up GPIO resources...\n");

    // Deactivate buzzer and LED
    deactivate_buzzer();
    deactivate_led();

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    int flame_status = FLAME_GONE; // Initial flame status

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    ret = gpio_init();
    if (ret != ERROR_NONE) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Perform self-test
    ret = self_test();
    if (ret != ERROR_NONE) {
        fprintf(stderr, "Error: Self-test failed\n");
        log_event("Self-test failed");
        // Signal error with distinct pattern
        int i;
        for (i = 0; i < ERROR_BLINK_COUNT; i++) {
            activate_led();
            usleep(ERROR_BLINK_INTERVAL_MS * 1000);
            deactivate_led();
            usleep(ERROR_BLINK_INTERVAL_MS * 1000);
        }

        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }
        usleep(600000); // Wait 600 ms
        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }
        usleep(600000); // Wait 600 ms
        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }
        usleep(600000); // Wait 600 ms
        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }

        log_event("Error signal sent");
        cleanup();
        return 1;
    }
    log_event("Self-test passed");

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor, exiting\n");
            log_event("Failed to read flame sensor");
            break; // Exit loop on error
        }

        if (flame_detected == FLAME_DETECTED && flame_status == FLAME_GONE) {
            // Flame detected
            activate_buzzer();
            activate_led();
            log_event("Flame detected");
            flame_status = FLAME_DETECTED;
        } else if (flame_detected == FLAME_GONE && flame_status == FLAME_DETECTED) {
            // Flame gone
            deactivate_buzzer();
            deactivate_led();
            log_event("Flame gone");
            flame_status = FLAME_GONE;
        }

        usleep(50000); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

