    printf("Cleaning up GPIO resources...\n");

    // Deactivate buzzer and LED
    deactivate_buzzer();
    deactivate_led();

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
