        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }
        usleep(600000); // Wait 600 ms
        for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_PATTERN_MS[i] * 1000);
        }

        log_event("Error signal sent");
        cleanup();
        return 1;
    }
    log_event("Self-test passed");

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor, exiting\n");
            log_event("Failed to read flame sensor");
            break; // Exit loop on error
        }

        if (flame_detected == FLAME_DETECTED && flame_status == FLAME_GONE) {
            // Flame detected
            activate_buzzer();
            activate_led();
            log_event("Flame detected");
            flame_status = FLAME_DETECTED;
        } else if (flame_detected == FLAME_GONE && flame_status == FLAME_DETECTED) {
            // Flame gone
            deactivate_buzzer();
            deactivate_led();
            log_event("Flame gone");
            flame_status = FLAME_GONE;
        }

        usleep(50000); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

