#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define BLINK_ON_TIME_US 500000 // 0.5 seconds
#define BLINK_OFF_TIME_US 500000 // 0.5 seconds

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_init(int address, uint8_t mode);
int i2c_read(int fd, uint8_t reg, uint16_t *data);
float convert_to_lux(uint16_t raw_value);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
void blink_led(int pin, float average_lux);
void signal_handler(int signal);

// I2C initialization function
int i2c_init(int address, uint8_t mode) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    uint8_t buf[1];
    buf[0] = mode;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint16_t *data) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Circular buffer functions
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// GPIO functions
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Blink LED function
void blink_led(int pin, float average_lux) {
    float rate = 0.5 + (average_lux / 1000.0) * 4.5;
    if (rate < 0.5) rate = 0.5;
    if (rate > 5.0) rate = 5.0;

    float period = 1.0 / rate;
    float on_time = period / 2.0;
    float off_time = period / 2.0;

    struct timespec on_ts, off_ts;
    on_ts.tv_sec = 0;
    on_ts.tv_nsec = (long)(on_time * 1000000000.0);
    off_ts.tv_sec = 0;
    off_ts.tv_nsec = (long)(off_time * 1000000000.0);

    gpio_set_value(pin, 1);
    nanosleep(&on_ts, NULL);
    gpio_set_value(pin, 0);
    nanosleep(&off_ts, NULL);
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize I2C
    i2c_fd = i2c_init(BH1750_ADDR, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "GPIO direction setting failed. Exiting.\n");
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    circular_buffer_init(&lux_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint16_t raw_value;
    float lux;
    float average_lux;

    printf("Starting light sensor and LED control...\n");

    while (program_running) {
        // Read light sensor
        if (i2c_read(i2c_fd, 0x00, &raw_value) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_value);

            // Add to circular buffer
            circular_buffer_add(&lux_buffer, lux);

            // Calculate average lux
            average_lux = circular_buffer_average(&lux_buffer);

            // Blink LED
            blink_led(GPIO_PIN, average_lux);

            printf("Raw: %u, Lux: %.2f, Avg Lux: %.2f\n", raw_value, lux, average_lux);
        } else {
            fprintf(stderr, "I2C read failed. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_set_value(GPIO_PIN, 0); // Turn off LED
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

