#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the 74HC595 chip
#define CHIP_NAME "gpiochip0"

// Define the segment pattern for the digit '5'
const unsigned char digit_5 = 0x7E; // a, f, g, e, d, c are on

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line, *clock_line, *latch_line;

// Function prototypes
int setup_gpio(void);
void shift_out(unsigned char data);
void display_digit(unsigned char digit);
void blink_digit(void);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Cleaning up and exiting.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int setup_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        if(data_line) gpiod_line_release(data_line);
        if(clock_line) gpiod_line_release(clock_line);
        if(latch_line) gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO lines as outputs
    if (gpiod_line_request_output(data_line, "74HC595", 0) < 0 ||
        gpiod_line_request_output(clock_line, "74HC595", 0) < 0 ||
        gpiod_line_request_output(latch_line, "74HC595", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set the data line based on the current bit
        if ((data >> i) & 0x01) {
            gpiod_line_set_value(data_line, 1);
        } else {
            gpiod_line_set_value(data_line, 0);
        }

        // Pulse the clock line
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
    }
}

