#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip number
#define GPIO_CHIP 0

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_request_lines(void);
int gpio_configure_led(void);
int gpio_configure_button(void);
void blink_led(void);
void button_interrupt_handler(void);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// GPIO initialization function
int gpio_init(void) {
    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return 0;
}

// GPIO line request function
int gpio_request_lines(void) {
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        return -1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        return -1;
    }

    return 0;
}

// GPIO configuration function for LED
int gpio_configure_led(void) {
    if (gpiod_line_request_output(led_line, "blink_led", 0) < 0) {
        perror("Error requesting LED line as output");
        return -1;
    }
    return 0;
}

// GPIO configuration function for button
int gpio_configure_button(void) {
    if (gpiod_line_request_input(button_line, "button_input") < 0) {
        perror("Error requesting button line as input");
        return -1;
    }

    if (gpiod_line_set_pull_config(button_line, GPIOD_LINE_REQUEST_PULL_UP) < 0) {
        perror("Error setting button line pull-up");
        return -1;
    }

    return 0;
}

// LED blinking function
void blink_led(void) {
    struct timespec on_time = {0, 500000000}; // 0.5 seconds
    struct timespec off_time = {0, 500000000}; // 0.5 seconds

    while (!terminate) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Error setting LED value");
            break;
        }
        nanosleep(&on_time, NULL);

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Error setting LED value");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Button interrupt handler function
void button_interrupt_handler(void) {
    struct timespec timeout = {1, 0}; // 1 second
    int ret;

    // Wait for a falling edge event with a timeout
    ret = gpiod_line_event_wait(button_line, GPIOD_LINE_EVENT_FALLING_EDGE, &timeout);
    if (ret < 0) {
        perror("Error waiting for button event");
        return;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for button event.\n");
        return;
    }

    // Debounce delay
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY * 1000000}; // Convert milliseconds to nanoseconds
    nanosleep(&debounce_delay, NULL);

    // Stop blinking, turn off LED, and print message
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED value");
    }
    printf("Button pressed! LED turned off.\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpio_request_lines() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure LED
    if (gpio_configure_led() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure button
    if (gpio_configure_button() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        button_interrupt_handler();
        if (!terminate) {
            blink_led();
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

