#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(0.75); // Wait 750ms

        gpioWrite(LED_GPIO, 0); // Turn LED off
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(0.75); // Wait 750ms
    }

    gpioWrite(LED_GPIO, 0); // Ensure LED is off on exit
    gpioTerminate(); // Terminate pigpio

    return 0;
}

