#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define GPIO chip
#define GPIOCHIP "gpiochip0"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_config_led_output(void);
int gpio_config_button_input(void);
int gpio_read_button(void);
int gpio_write_led(int value);
void blink_led(void);
void cleanup(void);
void signal_handler(int sig);

// Function to initialize GPIO
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to configure LED pin as output
int gpio_config_led_output(void) {
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request_output(led_line, "led", 0); // Initial value low
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line %d as output: %s\n", LED_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to configure button pin as input with pull-down
int gpio_config_button_input(void) {
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line %d: %s\n", BUTTON_PIN, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request_input(button_line, "button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line %d as input: %s\n", BUTTON_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read button state
int gpio_read_button(void) {
    int value = gpiod_line_get_value(button_line);
    if (value < 0) {
        fprintf(stderr, "Error reading button line %d: %s\n", BUTTON_PIN, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write LED state
int gpio_write_led(int value) {
    int ret = gpiod_line_set_value(led_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing LED line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to blink the LED
void blink_led(void) {
    gpio_write_led(1); // Turn LED on
    usleep(500000);    // Wait 500ms
    gpio_write_led(0); // Turn LED off
    usleep(500000);    // Wait 500ms
}

// Function to handle signals (Ctrl+C, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "Signal %d received, terminating...\n", sig);
    terminate = 1;
}

// Function to cleanup GPIO resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    // Configure LED and button pins
    if (gpio_config_led_output() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpio_config_button_input() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    int button_state = 0;
    int last_button_state = 0;
    struct timeval last_debounce_time;
    gettimeofday(&last_debounce_time, NULL);

    while (!terminate) {
        int current_button_state = gpio_read_button();
        if (current_button_state < 0) {
            break; // Exit loop on error
        }

        struct timeval now;
        gettimeofday(&now, NULL);
        long time_diff = (now.tv_sec - last_debounce_time.tv_sec) * 1000000L + (now.tv_usec - last_debounce_time.tv_usec);

        if (current_button_state != last_button_state) {
            if (time_diff > DEBOUNCE_TIME * 1000) {
                button_state = current_button_state;
                last_button_state = current_button_state;
                gettimeofday(&last_debounce_time, NULL);
            }
        }

        if (button_state == 1) {
            blink_led();
        } else {
            gpio_write_led(0); // Turn LED off
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

