#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM period (ms)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int initialize_gpio();

// Function to set PWM duty cycle for a given GPIO line
void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle);

// Function to generate random RGB values
void generate_random_rgb(int *red, int *green, int *blue);

// Function to cleanup GPIO lines
void cleanup_gpio();

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines. Exiting.\n");
        return 1;
    }

    int red, green, blue;

    // Main loop
    while (1) {
        // Generate random RGB values
        generate_random_rgb(&red, &green, &blue);

        // Set PWM duty cycles
        set_pwm_duty_cycle(red_line, red);
        set_pwm_duty_cycle(green_line, green);
        set_pwm_duty_cycle(blue_line, blue);

        // Wait for 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up GPIO lines...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0); // GPIO chip 0
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return -1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        if (red_line) gpiod_line_release(red_line);
        if (green_line) gpiod_line_release(green_line);
        if (blue_line) gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb-led", 0) != 0) {
        perror("gpiod_line_request_output (red)");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, "rgb-led", 0) != 0) {
        perror("gpiod_line_request_output (green)");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(blue_line, "rgb-led", 0) != 0) {
        perror("gpiod_line_request_output (blue)");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set PWM duty cycle for a given GPIO line
void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    // Calculate the on and off times based on the duty cycle
    int on_time = (PWM_PERIOD * duty_cycle) / 100; // microseconds
    int off_time = PWM_PERIOD - on_time; // microseconds

    // Set the line high for the on time
    if (gpiod_line_set_value(line, 1) != 0) {
        perror("gpiod_line_set_value (high)");
    }
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = on_time * 1000; // Convert microseconds to nanoseconds
    if (nanosleep(&sleep_time, NULL) != 0) {
        perror("nanosleep (on)");
    }

    // Set the line low for the off time
    if (gpiod_line_set_value(line, 0) != 0) {
        perror("gpiod_line_set_value (low)");
    }
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = off_time * 1000; // Convert microseconds to nanoseconds
    if (nanosleep(&sleep_time, NULL) != 0) {
        perror("nanosleep (off)");
    }
}

// Function to generate random RGB values
void generate_random_rgb(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    // Release GPIO lines
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);
}

