    double magnitude;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate G-force magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > impact_threshold) {
                // Log impact
                log_impact(x, y, z);

                // Trigger GPIO pulse
                gpioWrite(GPIO_PIN, 1);
                gpioDelay(50000); // 50 ms
                gpioWrite(GPIO_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Delay for the specified sample rate
        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

