#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define MODE_VALUE 0x01
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define RED_MSB_REG 0x68
#define GREEN_LSB_REG 0x6A
#define GREEN_MSB_REG 0x6C
#define BLUE_LSB_REG 0x6E
#define BLUE_MSB_REG 0x70
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als(uint16_t *als);
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void map_als_to_pwm(uint16_t als, int *pwm_duty_cycle);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the ADPD188BI sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MODE_REG, MODE_VALUE) == 0) {
            printf("Sensor initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing sensor (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read ALS data from the sensor
int read_als(uint16_t *als) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        char buffer[2];
        if (i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buffer, 2) == 2) {
            *als = (buffer[1] << 8) | buffer[0];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading ALS data (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to read ALS data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read RGB data from the sensor
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        char buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buffer, 6) == 6) {
            *red = (buffer[1] << 8) | buffer[0];
            *green = (buffer[3] << 8) | buffer[2];
            *blue = (buffer[5] << 8) | buffer[4];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading RGB data (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to read RGB data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to map ALS value to PWM duty cycle
void map_als_to_pwm(uint16_t als, int *pwm_duty_cycle) {
    *pwm_duty_cycle = (int)(((float)als / 65535.0) * PWM_RANGE);
}

// Function to log data to a CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function to close I2C, turn off LED, and close file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 to hardware PWM mode
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, 1000); // Set PWM frequency to 1 kHz

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als, red, green, blue;
    int pwm_duty_cycle;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_als(&als) == 0 && read_rgb(&red, &green, &blue) == 0) {
            // Map ALS to PWM duty cycle
            map_als_to_pwm(als, &pwm_duty_cycle);

            // Set LED brightness
            gpioPWM(LED_GPIO, pwm_duty_cycle);

            // Log data
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the specified interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

