        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read accelerometer data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    // Read 6 bytes of accelerometer data
    status = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    // Combine MSB and LSB, and shift right by 2 bits
    raw_x = ((int16_t)buffer[0] << 8 | (int16_t)buffer[1]) >> 2;
    raw_y = ((int16_t)buffer[2] << 8 | (int16_t)buffer[3]) >> 2;
    raw_z = ((int16_t)buffer[4] << 8 | (int16_t)buffer[5]) >> 2;

    // Convert to g-force units
    data->x = (float)raw_x / 4096.0 * 9.81;
    data->y = (float)raw_y / 4096.0 * 9.81;
    data->z = (float)raw_z / 4096.0 * 9.81;

    // Calculate magnitude
    data->magnitude = calculate_magnitude(data->x, data->y, data->z);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log impact data to a file
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Check for impact
            if (sensor_data.magnitude > 19.62) {
                log_impact(sensor_data.x, sensor_data.y, sensor_data.z, sensor_data.magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", sensor_data.magnitude);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

