#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SAMPLE_RATE_HZ 20
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0f
#define SENSITIVITY 0.00875f

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold calibration offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} calibration_offsets_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
int configure_gyro(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
gyro_data_t calibrate_gyro(int fd, calibration_offsets_t *offsets);
void log_data(gyro_data_t data);
void signal_handler(int sig);
int check_who_am_i(int fd);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Configure the gyroscope
int configure_gyro(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error configuring CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error configuring CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_regs(fd, OUT_X_L, data, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calibrate the gyroscope
gyro_data_t calibrate_gyro(int fd, calibration_offsets_t *offsets) {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            data.x = 0.0f; data.y = 0.0f; data.z = 0.0f; // Return 0s on error
            return data;
        }
        x_sum += (float)raw_x * SENSITIVITY;
        y_sum += (float)raw_y * SENSITIVITY;
        z_sum += (float)raw_z * SENSITIVITY;
        usleep(10000); // 10 ms delay
    }

    offsets->x_offset = x_sum / CALIBRATION_SAMPLES;
    offsets->y_offset = y_sum / CALIBRATION_SAMPLES;
    offsets->z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n", offsets->x_offset, offsets->y_offset, offsets->z_offset);

    data.x = 0.0f;
    data.y = 0.0f;
    data.z = 0.0f;
    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file);
}

// Signal handler
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Check WHO_AM_I register
int check_who_am_i(int fd) {
    uint8_t who_am_i;
    if (i2c_read_regs(fd, WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%X, got 0x%X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Check WHO_AM_I register
    if (check_who_am_i(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Configure the gyroscope
    if (configure_gyro(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Calibrate the gyroscope
    calibration_offsets_t offsets;
    if (calibrate_gyro(i2c_fd, &offsets) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    gyro_data_t data;
    while (!terminate) {
        if (read_gyro_data(i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading gyro data in main loop\n");
            continue; // Continue to the next iteration
        }

        data.x = (float)raw_x * SENSITIVITY - offsets.x_offset;
        data.y = (float)raw_y * SENSITIVITY - offsets.y_offset;
        data.z = (float)raw_z * SENSITIVITY - offsets.z_offset;

        log_data(data);

        // Check for alert condition
        if (fabs(data.x) > ALERT_THRESHOLD || fabs(data.y) > ALERT_THRESHOLD || fabs(data.z) > ALERT_THRESHOLD) {
            fprintf(stderr, "Alert: Gyroscope reading exceeds threshold. X=%.3f, Y=%.3f, Z=%.3f\n", data.x, data.y, data.z);
            fprintf(log_file, "Alert: Gyroscope reading exceeds threshold. X=%.3f, Y=%.3f, Z=%.3f\n", data.x, data.y, data.z);
            fflush(log_file);
        }

        usleep(50000); // 50 ms delay (20 Hz)
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

