#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// LED GPIO pin
#define LED_PIN 17

// Full-resolution, ±2g range
#define RANGE 2.0
#define SCALE_FACTOR (RANGE / 256.0)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 sensor
int adxl345_init() {
    int status;

    // Verify DEVID
    status = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (status < 0) {
        fprintf(stderr, "Error reading DEVID: %d\n", status);
        return -1;
    }
    if (status != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", status);
        return -1;
    }

    // Set data format to full resolution, ±2g range
    status = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08); // Set POWER_CTL register to measure mode
    if (status < 0) {
        fprintf(stderr, "Error writing to POWER_CTL: %d\n", status);
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units
    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;

    return 0;
}

// Log acceleration data to a file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
