#include <math.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Y_H_M 0x05
#define OUT_Y_L_M 0x06
#define OUT_Z_H_M 0x07
#define OUT_Z_L_M 0x08

// Global variables
int i2c_handle_accel;
int i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_accel();
int init_mag();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
int read_mag_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accel() != 0 || init_mag() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Check if the log file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading(degrees),Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(gauss),Mag_Y(gauss),Mag_Z(gauss)\n");
    }
    rewind(log_file);

    // Main loop
    sensor_data_t accel_data, mag_data;
    while (!terminate) {
        // Read sensor data
        if (read_accel_data(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }
        if (read_mag_data(&mag_data.x, &mag_data.y, &mag_data.z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Calculate heading
        float heading = calculate_heading(accel_data.x, accel_data.y, accel_data.z, mag_data.x, mag_data.y, mag_data.z);

        // Log data
        log_data(heading, accel_data.x, accel_data.y, accel_data.z, mag_data.x, mag_data.y, mag_data.z);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0); // Bus 1, accelerometer address
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0); // Bus 1, magnetometer address
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return 1;
    }

    return 0;
}

// Initialize accelerometer
int init_accel() {
    // Set accelerometer to 50 Hz, all axes enabled
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        return 1;
    }

    // Set accelerometer to +/- 2g range
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG4_A\n");
        return 1;
    }

    return 0;
}

// Initialize magnetometer
int init_mag() {
    // Set magnetometer to continuous-conversion mode
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_mag_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return 1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float cos_roll = cos(roll);
    float sin_roll = sin(roll);
    float cos_pitch = cos(pitch);
    float sin_pitch = sin(pitch);

    float mag_x_comp = mag_x * cos_pitch + mag_z * sin_pitch;
    float mag_y_comp = mag_x * sin_roll * sin_pitch + mag_y * cos_roll - mag_z * sin_roll * cos_pitch;

    float heading = atan2(mag_y_comp, mag_x_comp);

    // Convert to degrees
    heading = heading * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

