#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses and registers
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define CONTROL_VALUE 0x80

// Define sampling interval
#define SAMPLING_INTERVAL_MS 10

// Define log file name
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    long long timestamp_sec;
    long long timestamp_nsec;
    int16_t tdoa;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int addr);
int configure_sensor(int handle);
int16_t read_sensor_data(int handle);
long long get_timestamp();
int calculate_tdoa(int16_t sensor1, int16_t sensor2);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Configure the sensor
int configure_sensor(int handle) {
    int result = i2cWriteByteData(handle, CONTROL_REG, CONTROL_VALUE);
    if (result < 0) {
        fprintf(stderr, "Failed to write to control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read 16-bit audio data from the sensor
int16_t read_sensor_data(int handle) {
    char buffer[2];
    int result = i2cReadI2CBlockData(handle, DATA_REG, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }
    return (int16_t)((buffer[1] << 8) | buffer[0]);
}

// Get current timestamp
long long get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

// Calculate Time Difference of Arrival (TDOA)
int calculate_tdoa(int16_t sensor1, int16_t sensor2) {
    return sensor1 - sensor2;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
    fprintf(log_file, "%lld,%lld,%d,%d,%d\n", data.timestamp_sec, data.timestamp_nsec, data.sensor1, data.sensor2, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    // Main loop
    while (!terminate) {
        // Read data from sensors
        int16_t sensor1_data = read_sensor_data(i2c_handle1);
        int16_t sensor2_data = read_sensor_data(i2c_handle2);

        // Get timestamp
        long long timestamp = get_timestamp();

        // Calculate TDOA
        int16_t tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Create sensor data struct
        sensor_data_t data = {
            .sensor1 = sensor1_data,
            .sensor2 = sensor2_data,
            .timestamp_sec = timestamp / 1000000000LL,
            .timestamp_nsec = timestamp % 1000000000LL,
            .tdoa = tdoa
        };

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C handles
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

