#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// Sensitivities
#define GYRO_SENSITIVITY 0.005  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000 // CPHA=1, CPOL=1, aux SPI off

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int read_imu_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void convert_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signal);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the transmit buffer: MSB = 0, followed by the register address
    tx_buf[0] = 0x00; // MSB = 0
    tx_buf[1] = reg_addr;

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error: spiXfer failed (register read): %d\n", result);
        return -1;
    }

    // Delay for at least 40 microseconds
    gpioDelay(40);

    // Read the data from the receive buffer
    tx_buf[0] = 0x00; // Dummy byte for reading data
    tx_buf[1] = 0x00; // Dummy byte for reading data

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error: spiXfer failed (data read): %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Read IMU Data Function
int read_imu_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    if (spi_read_register(spi_handle, X_GYRO, gyro_x) != 0) return -1;
    if (spi_read_register(spi_handle, Y_GYRO, gyro_y) != 0) return -1;
    if (spi_read_register(spi_handle, Z_GYRO, gyro_z) != 0) return -1;
    if (spi_read_register(spi_handle, X_ACCEL, accel_x) != 0) return -1;
    if (spi_read_register(spi_handle, Y_ACCEL, accel_y) != 0) return -1;
    if (spi_read_register(spi_handle, Z_ACCEL, accel_z) != 0) return -1;

    return 0;
}

// Convert Data Function
void convert_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    *gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
    *accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;
}

// Log Data Function
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp_ms, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup Function
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Signal Handler Function
void signal_handler(int signal) {
    terminate = 1;
}

int main() {
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_imu_data(&gyro_x_raw, &gyro_y_raw, &gyro_z_raw, &accel_x_raw, &accel_y_raw, &accel_z_raw) == 0) {
            convert_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);
            log_data(fp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error: Failed to read IMU data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup(0);

    return 0;
}

