#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02f  // dps/LSB
#define ACCL_SCALE 0.00025f // g/LSB

// SPI device and GPIO pin definitions
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int spi_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int spi_init(int bus, int cs_pin, int mode, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int adis16448_read_register(int fd, uint8_t reg_addr, int16_t *data);
void adis16448_convert_data(int16_t raw_data, float scale, float *converted_data);
void signal_handler(int sig);

// SPI initialization function
int spi_init(int bus, int cs_pin, int mode, int speed) {
    int fd;
    char spi_device[20];

    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, cs_pin);

    fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_flags = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_hz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADIS16448 register read function
int adis16448_read_register(int fd, uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set register address with read bit (MSB = 1)
    tx_buf[0] = 0x80 | reg_addr;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(fd, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer error for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two received bytes into a 16-bit value
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Data conversion function
void adis16448_convert_data(int16_t raw_data, float scale, float *converted_data) {
    *converted_data = (float)raw_data * scale;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accl_x, raw_accl_y, raw_accl_z;
    float gyro_x, gyro_y, gyro_z;
    float accl_x, accl_y, accl_z;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(0, 0, 3, 1000000); // SPI bus 0, CS0, mode 3, 1 MHz
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO for chip select
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adis16448_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (adis16448_read_register(spi_fd, XGYRO_OUT, &raw_gyro_x) != 0) {
            fprintf(stderr, "Error reading XGYRO_OUT\n");
        } else {
            adis16448_convert_data(raw_gyro_x, GYRO_SCALE, &gyro_x);
        }

        if (adis16448_read_register(spi_fd, YGYRO_OUT, &raw_gyro_y) != 0) {
            fprintf(stderr, "Error reading YGYRO_OUT\n");
        } else {
            adis16448_convert_data(raw_gyro_y, GYRO_SCALE, &gyro_y);
        }

        if (adis16448_read_register(spi_fd, ZGYRO_OUT, &raw_gyro_z) != 0) {
            fprintf(stderr, "Error reading ZGYRO_OUT\n");
        } else {
            adis16448_convert_data(raw_gyro_z, GYRO_SCALE, &gyro_z);
        }

        // Read accelerometer data
        if (adis16448_read_register(spi_fd, XACCL_OUT, &raw_accl_x) != 0) {
            fprintf(stderr, "Error reading XACCL_OUT\n");
        } else {
            adis16448_convert_data(raw_accl_x, ACCL_SCALE, &accl_x);
        }

        if (adis16448_read_register(spi_fd, YACCL_OUT, &raw_accl_y) != 0) {
            fprintf(stderr, "Error reading YACCL_OUT\n");
        } else {
            adis16448_convert_data(raw_accl_y, ACCL_SCALE, &accl_y);
        }

        if (adis16448_read_register(spi_fd, ZACCL_OUT, &raw_accl_z) != 0) {
            fprintf(stderr, "Error reading ZACCL_OUT\n");
        } else {
            adis16448_convert_data(raw_accl_z, ACCL_SCALE, &accl_z);
        }

        // Print the data
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f dps, Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
               gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

