#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from ADIS16448 register
int16_t read_adis16448_register(int reg_addr)
{
    char tx_buffer[2];
    char rx_buffer[2];
    int result;

    // Set register address with read bit (bit 15)
    tx_buffer[0] = (reg_addr << 1) | 0x80; // MSB = 1 for read
    tx_buffer[1] = 0x00; // Dummy data for reading

    gpioDelay(40); // Stall time of at least 40 microseconds

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (reg 0x%02X): %d\n", reg_addr, result);
        return 0; // Return 0 on error
    }

    // Combine the two bytes to form the 16-bit data
    return (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);
}

int main()
{
