#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48
#define WHO_AM_I     0x75

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_mpu6886(int fd);
int read_mpu6886_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s, retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, &data, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X): %s, retrying...\n", reg, data, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%02X)\n", reg, data);
    return -1; // Failure
}

// Initialize MPU-6886
int init_mpu6886(int fd) {
    uint8_t who_am_i;

    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        return -1;
    }

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x86\n", who_am_i);
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, 0x1C, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to +-250 dps
    if (i2c_write_reg(fd, 0x1B, 0x00) != 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read MPU-6886 data
int read_mpu6886_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t raw_data[14];

    if (i2c_read_reg(fd, ACCEL_XOUT_H, raw_data, 14) != 0) {
        fprintf(stderr, "Failed to read MPU-6886 data\n");
        return -1;
    }

    *accel_x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    *accel_y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    *accel_z = (int16_t)((raw_data[4] << 8) | raw_data[5]);
    *gyro_x  = (int16_t)((raw_data[8] << 8) | raw_data[9]);
    *gyro_y  = (int16_t)((raw_data[10] << 8) | raw_data[11]);
    *gyro_z  = (int16_t)((raw_data[12] << 8) | raw_data[13]);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6886\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read MPU-6886 data
        if (read_mpu6886_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print raw data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU-6886 data in main loop\n");
        }

        usleep(50000); // 50ms delay
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

