#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define POLL_INTERVAL_MS 10
#define LED_ON_TIME_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize ADXL345
int adxl345_init() {
    // Verify device ID
    char buf[1];
    buf[0] = 0x00; // Register address
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    if (buf[0] != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X). Expected 0xE5.\n", buf[0]);
        return -1;
    }

    // Set data format register (full resolution, +-2g range)
    buf[0] = DATA_FORMAT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (DATA_FORMAT).\n");
        return -1;
    }
    buf[0] = 0x0B; // Full resolution, +-2g range
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (DATA_FORMAT value).\n");
        return -1;
    }

    // Set power control register (measure mode)
    buf[0] = POWER_CTL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (POWER_CTL).\n");
        return -1;
    }
    buf[0] = 0x08; // Measure mode
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (POWER_CTL value).\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char buf[7];
    char reg = DATAX0;

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (DATAX0).\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 7) != 7) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buf[2] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[4] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[6] << 8) | buf[5]);

    // Convert to g-force units (256 LSB/g)
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact to file
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                log_impact(x, y, z, magnitude);

                // Turn on LED
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to microseconds
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
