#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define LED_GPIO_CHIP "gpiochip0"
#define LED_GPIO_NUM 17
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define ACCEL_REG_X_MSB 0x01
#define ACCEL_REG_X_LSB 0x02
#define ACCEL_REG_Y_MSB 0x03
#define ACCEL_REG_Y_LSB 0x04
#define ACCEL_REG_Z_MSB 0x05
#define ACCEL_REG_Z_LSB 0x06
#define ACCEL_RANGE_2G 0x01
#define ACCEL_CONFIG_REG 0x29
#define ACCEL_CTRL_REG1 0x2A
#define ACCEL_CTRL_REG2 0x2B
#define ACCEL_CTRL_REG3 0x2C
#define ACCEL_STATUS_REG 0x00
#define ACCEL_DATA_RATE 0x01 // 100 Hz

// Global variables
int i2c_fd = -1;
struct gpiod_chip *led_chip = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mma8451q_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void log_impact(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register and value");
        return -1;
    }
    return 0;
}

// MMA8451Q initialization function
int mma8451q_init(int fd) {
    int retries = 3;
    while (retries > 0) {
        int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
        if (who_am_i == WHO_AM_I_VALUE) {
            // Configure accelerometer for +-2g range and 100 Hz data rate
            if (i2c_write_reg(fd, ACCEL_CONFIG_REG, ACCEL_RANGE_2G) != 0) {
                fprintf(stderr, "Error writing to ACCEL_CONFIG_REG\n");
                return -1;
            }
