int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_msb = i2c_read_reg(fd, ACCEL_REG_X_MSB);
    int x_lsb = i2c_read_reg(fd, ACCEL_REG_X_LSB);
    int y_msb = i2c_read_reg(fd, ACCEL_REG_Y_MSB);
