int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register and value");
        return -1;
    }
    return 0;
}

// Read sensor data function
int16_t read_sensor_data(int fd, uint8_t reg) {
    int16_t value = i2c_read_register(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor data from register 0x%02X\n", reg);
        return 0; // Return 0 on error
    }
    return value;
}

