#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20

// Freefall thresholds
#define FREEFALL_THRESHOLD 300  // mg
#define FREEFALL_TIME 100      // ms

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int adxl345_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int detect_freefall(int fd);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    unsigned char devid;

    // Verify device ID
    if (i2c_read_bytes(fd, ADXL345_REG_DEVID, &devid, 1) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set freefall threshold
    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD) != 0) {
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Set freefall time
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, FREEFALL_TIME) != 0) {
        fprintf(stderr, "Error setting freefall time\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x04) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_write_byte(fd, ADXL345_REG_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Error mapping freefall interrupt to INT1\n");
        return -1;
    }

    // Put the sensor in measurement mode
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error putting sensor in measurement mode\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char buf[6];

    if (i2c_read_bytes(fd, ADXL345_REG_DATAX0, buf, 6) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Detect freefall function
int detect_freefall(int fd) {
    unsigned char int_source;

    if (i2c_read_bytes(fd, ADXL345_REG_INT_SOURCE, &int_source, 1) != 0) {
        fprintf(stderr, "Error reading interrupt source\n");
        return -1;
    }

    // Check if freefall interrupt is set (bit 2)
    if (int_source & 0x04) {
        return 1; // Freefall detected
    }

    return 0; // No freefall detected
}

// Log data function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", timestamp, milliseconds, x, y, z);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    int16_t x, y, z;
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure interrupt GPIO
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (program_running) {
        if (detect_freefall(i2c_fd)) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                log_data(log_file, x, y, z);
            }
        }
        gpioDelay(10); // Check every 10ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

