// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Fall detection state machine
enum { IDLE, FREEFALL, IMPACT } state = IDLE;
double freefall_start_time = 0.0;
double impact_time = 0.0;

// Function prototypes
int init_lsm6dsr();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z);
void log_data(double timestamp, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void signal_handler(int signal);
void cleanup();

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calculate acceleration magnitude
double calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to g (assuming +-2g range)
    double accel_x = (double)x / 16384.0; // 2^14 = 16384
    double accel_y = (double)y / 16384.0;
    double accel_z = (double)z / 16384.0;

    return sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
}

// Function to log data to a file
void log_data(double timestamp, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    fprintf(log_file, "%.6f,%d,%d,%d,%d,%d,%d\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec ts;
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    double accel_magnitude;

    while (!terminate) {
        // Read sensor data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL); // 100ms
            continue;
        }
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL); // 100ms
            continue;
        }

        // Calculate acceleration magnitude
        accel_magnitude = calculate_acceleration_magnitude(accel_x, accel_y, accel_z);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        // Log data
        log_data(timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Fall detection state machine
        switch (state) {
            case IDLE:
                if (accel_magnitude < 0.2) {
                    state = FREEFALL;
                    freefall_start_time = timestamp;
                    printf("Freefall detected at timestamp: %.6f\n", timestamp);
                }
                break;
            case FREEFALL:
                if (timestamp - freefall_start_time > 1.0) {
                    state = IDLE;
                    printf("Freefall ended at timestamp: %.6f\n", timestamp);
                } else if (accel_magnitude > 2.5) {
                    state = IMPACT;
                    impact_time = timestamp;
                    printf("Impact detected at timestamp: %.6f\n", timestamp);
                    state = IDLE; // Reset state after impact
                }
                break;
            case IMPACT:
                state = IDLE; // Reset state after impact
                break;
        }

        // Delay for 10ms (100Hz)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

