#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_X_GYRO_OUT 0x14
#define ADIS16266_Y_GYRO_OUT 0x16
#define ADIS16266_Z_GYRO_OUT 0x18
#define ADIS16266_WHO_AM_I   0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling Factor
#define SCALE_FACTOR 0.0305

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int16_t read_gyro_data(int handle, uint8_t reg_addr);
double scale_gyro_data(int16_t raw_data);
void log_data(FILE *fp, double x_rate, double y_rate, double z_rate);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = 0x80 | reg_addr; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: spiXfer (read) failed with code %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a 16-bit register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit
    tx_buf[1] = data & 0xFF; //LSB

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: spiXfer (write) failed with code %d\n", result);
        return -1;
    }

    tx_buf[0] = (reg_addr + 1) & 0x7F; // Clear read bit
    tx_buf[1] = (data >> 8) & 0xFF; //MSB

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: spiXfer (write MSB) failed with code %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from a specific register
int16_t read_gyro_data(int handle, uint8_t reg_addr) {
    int16_t raw_data;
    if (spi_read_register(handle, reg_addr, &raw_data) != 0) {
        fprintf(stderr, "Error: Failed to read gyro data from register 0x%02X\n", reg_addr);
        return 0; // Return 0 on error
    }
    return raw_data;
}

// Function to scale the raw gyroscope data
double scale_gyro_data(int16_t raw_data) {
    return (double)raw_data * SCALE_FACTOR;
}

// Function to log the gyroscope data to a CSV file
void log_data(FILE *fp, double x_rate, double y_rate, double z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int16_t who_am_i;
    if (spi_read_register(spi_handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "Error: WHO_AM_I register value 0x%04X does not match expected value 0x3F5A\n", who_am_i);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Rate,Y_Rate,Z_Rate\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t raw_x = read_gyro_data(spi_handle, ADIS16266_X_GYRO_OUT);
        int16_t raw_y = read_gyro_data(spi_handle, ADIS16266_Y_GYRO_OUT);
        int16_t raw_z = read_gyro_data(spi_handle, ADIS16266_Z_GYRO_OUT);

        // Scale gyroscope data
        double x_rate = scale_gyro_data(raw_x);
        double y_rate = scale_gyro_data(raw_y);
        double z_rate = scale_gyro_data(raw_z);

        // Log data
        log_data(log_file, x_rate, y_rate, z_rate);

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Close SPI handle and log file
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

