#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Full-scale range and sensitivity
#define FULL_SCALE_RANGE 250.0f // dps
#define SENSITIVITY (FULL_SCALE_RANGE / 32768.0f) // mdps/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
void log_data(long long timestamp, float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Configure CTRL_REG1 for normal mode and all axes enabled
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1: %s. Retrying...\n", strerror(errno));
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 for +-250 dps full-scale range
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG4: %s. Retrying...\n", strerror(errno));
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);

    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
