    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Configure CTRL_REG1 for normal mode and all axes enabled
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1: %s. Retrying...\n", strerror(errno));
        gpioDelay(1000); // Wait 1ms before retrying
