#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log events to the log file
void log_event(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", get_timestamp(), message);
        fflush(log_file); // Ensure immediate write to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0; // Indicate success
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO
    if (initialize()) {
        return 1; // Exit if initialization fails
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            log_event("Error reading sensor value");
        } else {
            char flame_status[5];
            if (sensor_value == 0) {
                strcpy(flame_status, "YES");
                printf("FLAME DETECTED!\n");
            } else {
                strcpy(flame_status, "NO");
            }

            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Flame detected: %s", flame_status);
            log_event(log_message);
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

