#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D
#define SAMPLE_RATE_MS 100
#define CSV_FILE "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_acceleration(int fd, int *x, int *y, int *z);
char* get_iso8601_timestamp();
int log_data(FILE *fp, char *timestamp, int x, int y, int z);
void signal_handler(int sig);

// I2C read register function
int i2c_read_register(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    unsigned char data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return (int)data;
}

// I2C write register function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int *x, int *y, int *z) {
    int x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    x_lsb = i2c_read_register(fd, REG_X_LSB);
    x_msb = i2c_read_register(fd, REG_X_MSB);
    y_lsb = i2c_read_register(fd, REG_Y_LSB);
    y_msb = i2c_read_register(fd, REG_Y_MSB);
    z_lsb = i2c_read_register(fd, REG_Z_LSB);
    z_msb = i2c_read_register(fd, REG_Z_MSB);

    if (x_lsb == -1 || x_msb == -1 || y_lsb == -1 || y_msb == -1 || z_lsb == -1 || z_msb == -1) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (x_msb << 8) | x_lsb;
    *y = (y_msb << 8) | y_lsb;
    *z = (z_msb << 8) | z_lsb;

    return 0;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Log data to CSV file function
int log_data(FILE *fp, char *timestamp, int x, int y, int z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        perror("Failed to write to CSV file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    int x, y, z;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data to CSV file
                if (log_data(csv_file, timestamp, x, y, z) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        // Sleep for 100 ms
        usleep(SAMPLE_RATE_MS * 1000);
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

