#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to log the sensor data to a file
void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s.%03ld,%d,%d\n", timestamp, (long)(timeinfo->tm_sec * 1000), sensor1_value, sensor2_value);
    fclose(fp);
}

// Function to halt the conveyor belt (simulated)
void halt_conveyor() {
    printf("Conveyor belt halted!\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt safety system monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
        } else {
            // Log the data
            log_data(sensor1_value, sensor2_value);

            // Check for both sensors being triggered
            if (sensor1_value == 1 && sensor2_value == 1) {
                halt_conveyor();
            }
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

