// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x2A
#define DATA_RATE_100HZ 0x02 // Bits 3-5 = 0b010
#define ACTIVE_MODE 0x01
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_sensor(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the MMA8452Q sensor
int init_sensor(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Set data rate to 100 Hz and standby mode
    uint8_t ctrl_reg1_value = DATA_RATE_100HZ;
    if (i2c_write_reg(fd, CTRL_REG1, ctrl_reg1_value) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    // Set active mode
    ctrl_reg1_value |= ACTIVE_MODE;
    if (i2c_write_reg(fd, CTRL_REG1, ctrl_reg1_value) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = ((int16_t)data[0] << 8) | data[1];
    *x = *x >> 4;

    *y = ((int16_t)data[2] << 8) | data[3];
    *y = *y >> 4;

    *z = ((int16_t)data[4] << 8) | data[5];
    *z = *z >> 4;

    return 0;
}

// Calculate tilt angle
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    return atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    double tilt_angle;

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angle(x, y, z);
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, skipping iteration\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

