#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_WHO_AM_I 0x0F
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE 1.0

// Metal detector threshold (mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_lis3mdl(int fd);
int read_magnetic_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *gx, float *gy, float *gz);
float calculate_magnitude(float x, float y, float z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            result = 0;
            break;
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    return result;
}

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (read(fd, value, 1) == 1) {
