int init_lis3mdl(int fd) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        // Check WHO_AM_I register
        uint8_t who_am_i;
        if (i2c_read_reg(fd, LIS3MDL_WHO_AM_I, &who_am_i) == 0) {
