#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Registers
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_PARTID 0x00

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_data);
void log_data(FILE *fp, double x, double y, double z);
void signal_handler(int signal);

// SPI Read Function with Retry
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len + 1];
    int retries = 3;
    int result;

    tx_buf[0] = reg | 0x80 | 0x40; // Read bit (MSB) and Multi-byte bit (bit 6)

    while (retries > 0) {
        result = spiXfer(handle, tx_buf, rx_buf, len + 1);
        if (result == len + 1) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI Read Error: %d, Retries remaining: %d\n", result, retries);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI Read Failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Function with Retry
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    int retries = 3;
    int result;

    tx_buf[0] = reg | 0x80; // Write bit (MSB)
    tx_buf[1] = data;

    while (retries > 0) {
        result = spiWrite(handle, tx_buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI Write Error: %d, Retries remaining: %d\n", result, retries);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI Write Failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Error resetting ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t part_id;

    // Check PARTID
    if (spi_read_register(handle, ADXL354B_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Error reading PARTID.\n");
        return -1;
    }

    if (part_id != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the device
    if (adxl354b_reset(handle) != 0) {
        fprintf(stderr, "Error resetting ADXL354B.\n");
        return -1;
    }

    // Set measurement mode
    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x00) != 0) { // Clear RUN bit
        fprintf(stderr, "Error clearing RUN bit.\n");
        return -1;
    }
    gpioDelay(1000); // Wait for STABLE bit to set

    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x01) != 0) { // Set RUN bit
        fprintf(stderr, "Error setting RUN bit.\n");
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_data[3], y_data[3], z_data[3];

    if (spi_read_register(handle, ADXL354B_XDATA, x_data, 3) != 0) {
        fprintf(stderr, "Error reading XDATA.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_YDATA, y_data, 3) != 0) {
        fprintf(stderr, "Error reading YDATA.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_ZDATA, z_data, 3) != 0) {
        fprintf(stderr, "Error reading ZDATA.\n");
        return -1;
    }

    // Combine the 3 bytes into a 20-bit signed integer
    *x = ((int32_t)((uint32_t)x_data[2] << 12) | ((uint32_t)x_data[1] << 4) | ((uint32_t)x_data[0] >> 4)) >> 4;
    *y = ((int32_t)((uint32_t)y_data[2] << 12) | ((uint32_t)y_data[1] << 4) | ((uint32_t)y_data[0] >> 4)) >> 4;
    *z = ((int32_t)((uint32_t)z_data[2] << 12) | ((uint32_t)z_data[1] << 4) | ((uint32_t)z_data[0] >> 4)) >> 4;

    return 0;
}

// Convert Raw Data to g-force
double convert_to_g(int16_t raw_data) {
    return (double)raw_data * 0.0000039; // 3.9 microg/LSB
}

// Log Data to File
void log_data(FILE *fp, double x, double y, double z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler for Graceful Shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t x_raw, y_raw, z_raw;
    double x_g, y_g, z_g;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x_raw, &y_raw, &z_raw) == 0) {
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);
            log_data(log_file, x_g, y_g, z_g);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

