void log_imu_data(double timestamp, double gyro_x_rate, double gyro_y_rate, double gyro_z_rate, double accel_x_g, double accel_y_g, double accel_z_g);
void signal_handler(int signal);

// SPI read function with retry and stall handling
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Set MSB to indicate read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    // Retry loop with exponential backoff
    for (int i = 0; i < 5; i++) {
        result = spiXfer(handle, tx_buf, rx_buf, 2);
        if (result == 2) {
            *data = (rx_buf[0] << 8) | rx_buf[1];
            return 0; // Success
        } else {
