    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    double gyro_x_rate, gyro_y_rate, gyro_z_rate, accel_x_g, accel_y_g, accel_z_g;
    struct timespec ts;
