        read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

        // Process IMU data
        process_imu_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z,
                         &gyro_x_rate, &gyro_y_rate, &gyro_z_rate, &accel_x_g, &accel_y_g, &accel_z_g);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
        } else {
            fprintf(stderr, "Failed to get timestamp\n");
            continue; // Skip logging this iteration
        }

        // Log IMU data
        log_imu_data(timestamp, gyro_x_rate, gyro_y_rate, gyro_z_rate, accel_x_g, accel_y_g, accel_z_g);

        // Delay for approximately 100 Hz sampling rate
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

