#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int obstacle_detected;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the sensor value
        obstacle_detected = gpioRead(GPIO_PIN);

        // Check for obstacle detection (LOW signal)
        if (obstacle_detected == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event with timestamp
            printf("[%s] Obstacle detected! Self-parking sequence started.\n", timestamp);

            // Simulate self-parking sequence (print messages every 0.5 seconds for 5 seconds)
            for (int i = 0; i < 10; i++) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] Self-parking step %d\n", timestamp, i + 1);
                gpioDelay(500); // 0.5 seconds
            }

            // Log the completion of the self-parking sequence
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Self-parking sequence completed.\n", timestamp);
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

