            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event with timestamp
            printf("[%s] Obstacle detected! Self-parking sequence started.\n", timestamp);

            // Simulate self-parking sequence (print messages every 0.5 seconds for 5 seconds)
            for (int i = 0; i < 10; i++) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
