            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Self-parking sequence completed.\n", timestamp);
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
