// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int gpio1, int gpio2) {
    int sensor1_value = gpioRead(gpio1);
    int sensor2_value = gpioRead(gpio2);
    return (sensor1_value << 1) | sensor2_value; // Combine sensor values
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_status, int sensor2_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_status == 0 ? "Obstacle Detected" : "Clear",
           sensor2_status == 0 ? "Obstacle Detected" : "Clear");
}

