    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor_data = read_sensors(SENSOR1_GPIO, SENSOR2_GPIO);

        // Extract sensor statuses
        int sensor1_status = (sensor_data >> 1) & 1;
        int sensor2_status = sensor_data & 1;

        // Log the data
        log_data(sensor1_status, sensor2_status);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

