#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// ADIS16266 Register Addresses
#define ADIS16266_MSC_CTRL 0x24
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_SPEED 1000000 // 1 MHz

// CS GPIO Pin
#define CS_GPIO_PIN 8

// Scale Factor
#define SCALE_FACTOR 0.02

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(int bus, int chip_select, int mode, int bits_per_word, int clock_speed);
int cs_init(int gpio_pin);
int cs_set_low(void);
int cs_set_high(void);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int adis16266_write_register(int fd, uint8_t reg_addr, uint16_t value);
int adis16266_read_register(int fd, uint8_t reg_addr, int16_t *value);
int16_t adis16266_read_gyro_data(int fd, uint8_t reg_addr);
double convert_to_degrees_per_second(int16_t raw_data);
void signal_handler(int sig);

// SPI Initialization
int spi_init(int bus, int chip_select, int mode, int bits_per_word, int clock_speed) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, chip_select);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", spi_device);
        return -1;
    }

    // Set SPI mode
    int mode_flags = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed Hz
    int speed = clock_speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed Hz: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// CS GPIO Initialization
int cs_init(int gpio_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "cs_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    cs_line = gpiod_chip_get_line(chip, gpio_pin);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set CS Line Low
int cs_set_low(void) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS line low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set CS Line High
int cs_set_high(void) {
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS line high: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_CLOCK_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// ADIS16266 Write Register
int adis16266_write_register(int fd, uint8_t reg_addr, uint16_t value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for write
    tx_buf[1] = (value >> 8) & 0xFF;
    tx_buf[2] = value & 0xFF;

    if (cs_set_low() < 0) return -1;
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        cs_set_high();
        return -1;
    }
    if (cs_set_high() < 0) return -1;

    return 0;
}

// ADIS16266 Read Register
int adis16266_read_register(int fd, uint8_t reg_addr, int16_t *value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (cs_set_low() < 0) return -1;
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        cs_set_high();
        return -1;
    }
    if (cs_set_high() < 0) return -1;

    *value = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// ADIS16266 Read Gyro Data
int16_t adis16266_read_gyro_data(int fd, uint8_t reg_addr) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int16_t value;

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (cs_set_low() < 0) return -1;
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        cs_set_high();
        return -1;
    }
    if (cs_set_high() < 0) return -1;

    value = (rx_buf[1] << 8) | rx_buf[2];
    return value;
}

// Convert to Degrees per Second
double convert_to_degrees_per_second(int16_t raw_data) {
    return (double)raw_data * SCALE_FACTOR;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT, SPI_MODE, SPI_BITS_PER_WORD, SPI_CLOCK_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize CS GPIO
    if (cs_init(CS_GPIO_PIN) < 0) {
        fprintf(stderr, "CS GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Enable Data Ready Mode
    if (adis16266_write_register(spi_fd, ADIS16266_MSC_CTRL, 0x0001) < 0) {
        fprintf(stderr, "Failed to enable data ready mode\n");
        close(spi_fd);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 ms

        // Read Gyro Data
        int16_t x_raw = adis16266_read_gyro_data(spi_fd, ADIS16266_XGYRO_OUT);
        int16_t y_raw = adis16266_read_gyro_data(spi_fd, ADIS16266_YGYRO_OUT);
        int16_t z_raw = adis16266_read_gyro_data(spi_fd, ADIS16266_ZGYRO_OUT);

        // Convert to Degrees per Second
        double x_rate = convert_to_degrees_per_second(x_raw);
        double y_rate = convert_to_degrees_per_second(y_raw);
        double z_rate = convert_to_degrees_per_second(z_raw);

        // Log Data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Wait 100 ms
        nanosleep(&ts, NULL);
    }

    // Cleanup
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_line_release(cs_line);
    gpiod_chip_close(cs_line->chip);

    return 0;
}

