#include <stdint.h>
#include <signal.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22

// Sensitivity values
#define GYRO_SENSITIVITY 8.75  // mdps/LSB
#define ACCEL_SENSITIVITY 0.061 // mg/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus()
{
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a single byte from an I2C register
int read_register(int reg)
{
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0)
    {
        fprintf(stderr, "Failed to read register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int reg, int value)
{
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0)
    {
        fprintf(stderr, "Failed to write register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to configure the LSM6DSR
int configure_lsm6dsr()
{
    // Configure accelerometer: +-2g, 104 Hz
    if (write_register(CTRL1_XL, 0x42) < 0)
    {
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (write_register(CTRL2_G, 0x42) < 0)
    {
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z)
{
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (result < 0)
    {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

// Function to convert raw data to physical units
void convert_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw,
                  float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z)
{
    *gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY / 1000.0f; // dps
    *gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY / 1000.0f; // dps
    *gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY / 1000.0f; // dps
    *accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY / 1000.0f; // g
    *accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY / 1000.0f; // g
    *accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY / 1000.0f; // g
}

// Function to print the sensor data
void print_data(float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z)
{
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps, Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
           gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
}

int main()
{
    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (initialize_pigpio() < 0)
    {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() < 0)
    {
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(0x0F);
    if (who_am_i != 0x6B)
    {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x6B\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LSM6DSR
    if (configure_lsm6dsr() < 0)
    {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    while (!terminate)
    {
        // Read sensor data
        if (read_sensor_data(&gyro_x_raw, &gyro_y_raw, &gyro_z_raw, &accel_x_raw, &accel_y_raw, &accel_z_raw) < 0)
        {
            break; // Exit loop on error
        }

        // Convert data to physical units
        convert_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw,
                     &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

        // Print the data
        print_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

