#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 Registers
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_WHO_AM_I_VALUE 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    int retries = 3;
    int status;

    // Check WHO_AM_I register
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
        if (status >= 0 && status == FXOS8700_WHO_AM_I_VALUE) {
            break;
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Hybrid mode, active)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01); // Active mode, 100 Hz
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG2 (High resolution)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x02); // High resolution
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG2: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG2 after multiple retries.\n");
        return -1;
    }

    // Configure M_CTRL_REG1 (Hybrid mode, active)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x1F); // Active mode, hybrid
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to M_CTRL_REG1: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to M_CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure M_CTRL_REG2 (High resolution)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x20); // High resolution
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to M_CTRL_REG2: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to M_CTRL_REG2 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
        if (status == 12) {
            break;
        } else {
            fprintf(stderr, "Error reading sensor data: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1;
    }

    // Process accelerometer data (14-bit, left-aligned)
    *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    // Process magnetometer data (16-bit, signed)
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize FXOS8700 sensor
    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Print sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

