        status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x20); // High resolution
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to M_CTRL_REG2: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to M_CTRL_REG2 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
        if (status == 12) {
            break;
        } else {
            fprintf(stderr, "Error reading sensor data: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1;
    }

    // Process accelerometer data (14-bit, left-aligned)
    *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    // Process magnetometer data (16-bit, signed)
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize FXOS8700 sensor
    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Print sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

