#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle_x(int16_t x, int16_t z);
double calculate_tilt_angle_y(int16_t y, int16_t z);
void log_tilt_event(double angle_x, double angle_y);
void signal_handler(int signal);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Set data format: +/- 2g range, full resolution
    if (i2c_write_byte(fd, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error setting data format\n");
        return -1;
    }

    // Enable measurement mode
    if (i2c_write_byte(fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_bytes(fd, DATAX0, buf, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate tilt angle around X axis
double calculate_tilt_angle_x(int16_t x, int16_t z) {
    return atan2(x, z) * 180.0 / M_PI;
}

// Calculate tilt angle around Y axis
double calculate_tilt_angle_y(int16_t y, int16_t z) {
    return atan2(y, z) * 180.0 / M_PI;
}

// Log tilt event function
void log_tilt_event(double angle_x, double angle_y) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Tilt: X=%.2f, Y=%.2f\n", timestamp, angle_x, angle_y);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting...\n", signal);
}

int main() {
    int16_t x, y, z;
    double angle_x, angle_y;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt angles
            angle_x = calculate_tilt_angle_x(x, z);
            angle_y = calculate_tilt_angle_y(y, z);

            // Log tilt event if threshold is exceeded
            if (fabs(angle_x) > TILT_THRESHOLD || fabs(angle_y) > TILT_THRESHOLD) {
                log_tilt_event(angle_x, angle_y);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

