#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_RATE_MS 1
#define WINDOW_SIZE_S 5
#define PAUSE_SIZE_S 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    int i;

    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Command-line argument parsing
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // pigpio initialization
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // GPIO mode setup
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring noise levels on GPIO%d...\n", GPIO_PIN);

    while (program_running) {
        high_count = 0;

        // Sampling loop
        for (i = 0; i < WINDOW_SIZE_S * 1000 / SAMPLE_RATE_MS; ++i) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_RATE_MS * 1000); // Delay in microseconds
        }

        // Timestamping
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Alert condition check
        if (high_count > threshold) {
            printf("%s ALERT: High noise level detected (%d readings)\n", timestamp, high_count);
        } else {
            printf("%s: Noise level normal (%d readings)\n", timestamp, high_count);
        }

        // Pause
        gpioDelay(PAUSE_SIZE_S * 1000000); // Delay in microseconds
    }

    // pigpio termination
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

