#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define lock/unlock duration (seconds)
#define LOCK_DURATION 5

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int generate_random_code(int *code);
int prompt_user_for_code(int *code);
int validate_code(int user_code, int generated_code);
int unlock_door(int door_pin);
int lock_door(int door_pin);
int log_access(int generated_code);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Get GPIO lines
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line for door A: %d\n", DOOR_A_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line for door B: %d\n", DOOR_B_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        return -1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(door_a_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for door A as output: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for door B as output: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    return 0;
}

// Generate a random 6-digit code
int generate_random_code(int *code) {
    *code = (rand() % 900000) + 100000;
    return 0;
}

// Prompt the user to enter the code
int prompt_user_for_code(int *code) {
    char input[7]; // Buffer to store the input string
    int ret;

    while (1) {
        printf("Enter the 6-digit code: ");
        if (fgets(input, sizeof(input), stdin) != NULL) {
            // Remove trailing newline character
            input[strcspn(input, "\n")] = 0;

            // Check if the input is a valid 6-digit number
            if (strlen(input) == 6 && atoi(input) > 0) {
                *code = atoi(input);
                return 0; // Success
            } else {
