#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE2 0x21
#define LUX_LOG_FILE "light_log.txt"
#define SLEEP_DURATION_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write(int fd, unsigned char reg, unsigned char value);
int i2c_read(int fd, unsigned char reg, unsigned char *buf, int len);
float calculate_lux(unsigned short raw_value);
int log_data(float lux_value);
void signal_handler(int signal);

// I2C write function
int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Calculate lux from raw value
float calculate_lux(unsigned short raw_value) {
    return (float)raw_value * 5.0 / 6.0;
}

// Log data to file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LUX_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        unsigned char data[2];
        unsigned short raw_value;
        float lux_value;

        // Send measurement command
        if (i2c_write(i2c_fd, 0x00, ONE_TIME_HIGH_RES_MODE2) < 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying in %d seconds.\n", SLEEP_DURATION_SEC);
            fclose(log_file);
            close(i2c_fd);
            sleep(SLEEP_DURATION_SEC);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                return 1;
            }
            log_file = fopen(LUX_LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                close(i2c_fd);
                return 1;
            }
            continue;
        }

        // Wait for measurement (180ms)
        usleep(180000); // 180ms

        // Read data
        if (i2c_read(i2c_fd, 0x00, data, 2) < 0) {
            fprintf(stderr, "Failed to read data. Retrying in %d seconds.\n", SLEEP_DURATION_SEC);
            fclose(log_file);
            close(i2c_fd);
            sleep(SLEEP_DURATION_SEC);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                return 1;
            }
            log_file = fopen(LUX_LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                close(i2c_fd);
                return 1;
            }
            continue;
        }

        // Combine bytes
        raw_value = (data[0] << 8) | data[1];

        // Calculate lux
        lux_value = calculate_lux(raw_value);

        // Log data
        if (log_data(lux_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Sleep
        sleep(SLEEP_DURATION_SEC);
    }

    // Cleanup
    printf("Closing resources...\n");
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

