#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PWM_RANGE 1000000
#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_mpr121();
int read_mpr121_data(unsigned char *data);
float map_touch_to_frequency(unsigned short touch_data);
void set_pwm_frequency(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

// Initialize MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms

    // Configure electrode sensitivity (example values)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Electrode 0-11 touch threshold
        fprintf(stderr, "Error: MPR121 touch threshold config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x0C) < 0) { // Electrode 0-11 release threshold
        fprintf(stderr, "Error: MPR121 release threshold config failed\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) { // Enable electrode 0-3
        fprintf(stderr, "Error: MPR121 electrode enable failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0F) < 0) { // Enable electrode 4-7
        fprintf(stderr, "Error: MPR121 electrode enable failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0F) < 0) { // Enable electrode 8-11
        fprintf(stderr, "Error: MPR121 electrode enable failed\n");
        return -1;
    }

    return 0;
}

// Read MPR121 data
int read_mpr121_data(unsigned char *data) {
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2) < 0) {
        fprintf(stderr, "Error: MPR121 data read failed\n");
        return -1;
    }
    return 0;
}

// Map touch data to frequency (logarithmic scale)
float map_touch_to_frequency(unsigned short touch_data) {
    float max_touch = 0.0;
    for (int i = 0; i < 12; i++) {
        if (touch_data & (1 << i)) {
            max_touch = (float)i; // Use electrode index as touch value
        }
    }

    if (max_touch == 0.0) {
        return 220.0; // Default frequency if no electrode is touched
    }

    float frequency = 220.0 * pow(2.0, (max_touch / 11.0) * 3.0); // Logarithmic mapping

    // Clamp frequency to 220-880 Hz
    if (frequency < 220.0) frequency = 220.0;
    if (frequency > 880.0) frequency = 880.0;

    return frequency;
}

// Set PWM frequency
void set_pwm_frequency(float frequency) {
    int period = (int)(1000000.0 / frequency); // Calculate period in microseconds
    gpioPWM(GPIO_PWM, 128); // 50% duty cycle
    gpioSetPWMfrequency(GPIO_PWM, (int)(1000000.0 / period)); // Set frequency
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }

    // Check for motion detected message with secret key
    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        char *token = strtok(buffer + 16, ":");
        if (token != NULL && strcmp(token, SECRET_KEY) == 0) {
            printf("Motion detected and secret key verified!\n");

            // Play theremin tones for 5 seconds
            for (int i = 0; i < 250; i++) { // 5 seconds * 20ms sampling rate
                unsigned char data[2];
                if (read_mpr121_data(data) == 0) {
                    unsigned short touch_data = (data[1] << 8) | data[0];
                    float frequency = map_touch_to_frequency(touch_data);
                    set_pwm_frequency(frequency);
                    log_frequency(frequency);
                    gpioDelay(20000); // 20ms delay
                } else {
                    fprintf(stderr, "Error reading MPR121 data during playback\n");
                    break;
                }
            }

            // Stop PWM
            gpioPWM(GPIO_PWM, 0);
        } else {
            printf("Invalid secret key\n");
        }
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_PWM, 0); // Initialize to 0 frequency

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections and handle them
    while (program_running) {
        int addrlen = sizeof(address);
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        handle_client(new_socket);
    }

    // Clean up
    printf("Cleaning up...\n");
    gpioPWM(GPIO_PWM, 0); // Stop PWM
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

