#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD 1000000 // 1ms period (1000 Hz)
#define SAMPLE_RATE_MS 100
#define MAGNITUDE_SCALE_FACTOR 0.1 // Adjust as needed
#define MAGNITUDE_OFFSET 100.0 // Adjust as needed

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *led_line;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Magnetometer initialization function
int init_magnetometer(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        return -1;
    }
    return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_regs(fd, OUT_X_L_M, data, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Magnitude calculation function
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// LED brightness control function
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;

    int duty_cycle = (int)((double)brightness / 100.0 * PWM_PERIOD);
    if (gpiod_line_set_value(led_line, duty_cycle) < 0) {
        perror("Failed to set LED brightness");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get LED GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request LED GPIO line for output
    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    double magnitude;
    int brightness;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_RATE_MS * 1000000; // 100ms

    while (!terminate) {
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            brightness = (int)(magnitude * MAGNITUDE_SCALE_FACTOR + MAGNITUDE_OFFSET);
            if (brightness < 0) brightness = 0;
            if (brightness > 100) brightness = 100;
            if (set_led_brightness(brightness) < 0) {
                fprintf(stderr, "Failed to set LED brightness, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read magnetometer data, but continuing...\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

