#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define CONFIG_A 0x70  // 8-sample averaging, 15 Hz output rate
#define CONFIG_B 0x20  // Gain = 1.3 Gauss
#define MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer for hard-iron offset calculation
#define OFFSET_BUFFER_SIZE 100
int16_t x_offset_buffer[OFFSET_BUFFER_SIZE];
int16_t y_offset_buffer[OFFSET_BUFFER_SIZE];
int16_t z_offset_buffer[OFFSET_BUFFER_SIZE];
int offset_index = 0;

// Function prototypes
int hmc5883l_init();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void update_offset_buffers(int16_t x, int16_t y, int16_t z);
void calculate_hard_iron_offsets(int16_t *x_offset, int16_t *y_offset, int16_t *z_offset);
void print_offset_corrected_data(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset, int16_t z_offset);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the HMC5883L magnetometer
int hmc5883l_init() {
    // Configure the magnetometer
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, CONFIG_A) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, CONFIG_B) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update the circular buffers with new raw data
void update_offset_buffers(int16_t x, int16_t y, int16_t z) {
    x_offset_buffer[offset_index] = x;
    y_offset_buffer[offset_index] = y;
    z_offset_buffer[offset_index] = z;

    offset_index = (offset_index + 1) % OFFSET_BUFFER_SIZE;
}

// Calculate the hard-iron offsets as the running average of the circular buffer
void calculate_hard_iron_offsets(int16_t *x_offset, int16_t *y_offset, int16_t *z_offset) {
    int sum_x = 0, sum_y = 0, sum_z = 0;

    for (int i = 0; i < OFFSET_BUFFER_SIZE; i++) {
        sum_x += x_offset_buffer[i];
        sum_y += y_offset_buffer[i];
        sum_z += z_offset_buffer[i];
    }

    *x_offset = (int16_t)(sum_x / OFFSET_BUFFER_SIZE);
    *y_offset = (int16_t)(sum_y / OFFSET_BUFFER_SIZE);
    *z_offset = (int16_t)(sum_z / OFFSET_BUFFER_SIZE);
}

// Print the offset-corrected magnetometer data
void print_offset_corrected_data(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset, int16_t z_offset) {
    printf("%d,%d,%d\n", x - x_offset, y - y_offset, z - z_offset);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the magnetometer
    if (hmc5883l_init() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize offset buffers
    for (int i = 0; i < OFFSET_BUFFER_SIZE; i++) {
        x_offset_buffer[i] = 0;
        y_offset_buffer[i] = 0;
        z_offset_buffer[i] = 0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    int16_t x_offset, y_offset, z_offset;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Update offset buffers
            update_offset_buffers(x, y, z);

            // Calculate hard-iron offsets
            calculate_hard_iron_offsets(&x_offset, &y_offset, &z_offset);

            // Print offset-corrected data every 500 ms
            print_offset_corrected_data(x, y, z, x_offset, y_offset, z_offset);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

