#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D Registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x31
#define INT1_DURATION 0x32
#define OUT_X_L_A 0x28

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
int16_t accel_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int configure_lsm303d(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void interrupt_handler(int gpio, int level, void *user_data);
void signal_handler(int sig);
void print_buffer(int16_t *buffer, int size);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D configuration function
int configure_lsm303d(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_register(fd, 0x0F);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 50 Hz ODR, all axes enabled
    if (i2c_write_register(fd, CTRL_REG1_A, 0x57) < 0) return -1;

    // Configure accelerometer: +-2g full-scale
    if (i2c_write_register(fd, CTRL_REG4_A, 0x00) < 0) return -1;

    // Configure interrupt: any-axis-high event
    if (i2c_write_register(fd, INT1_CFG, 0x2A) < 0) return -1;

    // Configure interrupt: threshold 2000 mg (2000 / 16 = 125)
    if (i2c_write_register(fd, INT1_THS, 0x7D) < 0) return -1;

    // Configure interrupt: duration 0 (immediate)
    if (i2c_write_register(fd, INT1_DURATION, 0x00) < 0) return -1;

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int result = i2c_smbus_read_i2c_block_data(fd, OUT_X_L_A | 0x80, 6, (char *)data);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, void *user_data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s: Interrupt triggered\n", buf);
    print_buffer(accel_buffer, 10);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);

    // Disable accelerometer
    i2c_write_register(i2c_fd, CTRL_REG1_A, 0x00);

    // Close I2C file descriptor
    close(i2c_fd);

    // Close GPIO line
    gpiod_line_release(gpio_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    exit(0);
}

// Print buffer function
void print_buffer(int16_t *buffer, int size) {
    printf("Last 10 samples:\n");
    for (int i = 0; i < size; i++) {
        int index = (buffer_index - size + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  %d: %d\n", i, buffer[index]);
    }
}

int main() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure LSM303D
    if (configure_lsm303d(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, INT1_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
