// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define nanosleep parameters
#define SLEEP_TIME_SEC 0
#define SLEEP_TIME_NSEC 500000000 // 500 milliseconds

// Global variables for GPIO lines
struct gpiod_line *solenoid1_line = NULL;
struct gpiod_line *solenoid2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int setup_gpio(void);
void energize_solenoid(int solenoid_number);
void de_energize_solenoid(int solenoid_number);
void cleanup_gpio(void);
void signal_handler(int signal);

// Function to set up GPIO lines
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line for solenoid 1
    solenoid1_line = gpiod_chip_get_line(gpio_chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get GPIO line for solenoid 2
    solenoid2_line = gpiod_chip_get_line(gpio_chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(solenoid1_line);
        return -1;
    }

    // Request GPIO line for solenoid 1 as output
    ret = gpiod_line_request_output(solenoid1_line, "solenoid1", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        return -1;
    }

    // Request GPIO line for solenoid 2 as output
    ret = gpiod_line_request_output(solenoid2_line, "solenoid2", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        return -1;
    }

    return 0;
}

// Function to energize a solenoid
void energize_solenoid(int solenoid_number) {
    struct gpiod_line *line;

    if (solenoid_number == 1) {
        line = solenoid1_line;
    } else if (solenoid_number == 2) {
        line = solenoid2_line;
    } else {
        fprintf(stderr, "Invalid solenoid number: %d\n", solenoid_number);
        return;
    }

    int ret = gpiod_line_set_value(line, 1); // Set value HIGH
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", solenoid_number, strerror(errno));
    }
}

// Function to de-energize a solenoid
void de_energize_solenoid(int solenoid_number) {
    struct gpiod_line *line;

    if (solenoid_number == 1) {
        line = solenoid1_line;
    } else if (solenoid_number == 2) {
        line = solenoid2_line;
    } else {
        fprintf(stderr, "Invalid solenoid number: %d\n", solenoid_number);
        return;
    }

    int ret = gpiod_line_set_value(line, 0); // Set value LOW
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", solenoid_number, strerror(errno));
    }
}

// Function to clean up GPIO resources
void cleanup_gpio(void) {
    // De-energize both solenoids
    de_energize_solenoid(1);
    de_energize_solenoid(2);

    // Release GPIO lines
    if (solenoid1_line) {
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_release(solenoid2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Energize solenoid 1
        energize_solenoid(1);
        nanosleep((const struct timespec[]){{SLEEP_TIME_SEC, SLEEP_TIME_NSEC}}, NULL);

        // De-energize solenoid 1, energize solenoid 2
        de_energize_solenoid(1);
        energize_solenoid(2);
        nanosleep((const struct timespec[]){{SLEEP_TIME_SEC, SLEEP_TIME_NSEC}}, NULL);

        // De-energize solenoid 2
        de_energize_solenoid(2);
    }

    return 0;
}

