#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout in seconds
#define TIMEOUT_SECONDS 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables
int uart1_fd = -1;
int uart2_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *port);
int read_code(int fd, char *code);
int compare_codes(const char *code1, const char *code2, const char *expected_code);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Ensure locks are initially locked
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Initialize UART port
int initialize_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios options;
    tcgetattr(fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &options);

    return fd;
}

// Read code from UART port
int read_code(int fd, char *code) {
    int i = 0;
    int c;

    while (i < 6 && !terminate) {
        c = getchar(fd);
        if (c == EOF) {
            fprintf(stderr, "UART read timeout\n");
            return -1; // Timeout
        }

        if (c >= '0' && c <= '9') {
            code[i++] = c;
        } else {
            // Reset buffer on non-digit character
            fprintf(stderr, "Invalid character received, resetting buffer\n");
            tcflush(fd, TCIFLUSH);
            i = 0; // Reset the code buffer
        }
    }

    if (i == 6) {
        code[i] = '\0'; // Null-terminate the string
        return 0;       // Success
    } else {
        return -1; // Incomplete code
    }
}

// Compare codes using constant-time comparison
int compare_codes(const char *code1, const char *code2, const char *expected_code) {
    if (code1 == NULL || code2 == NULL || expected_code == NULL) {
        return 0; // Consider as not matching if any is NULL
    }

    if (strlen(code1) != 6 || strlen(code2) != 6 || strlen(expected_code) != 6) {
        return 0; // Length mismatch
    }

    int result = 1; // Assume match initially
    for (int i = 0; i < 6; i++) {
        if (code1[i] != code2[i] || code1[i] != expected_code[i]) {
            result = 0; // Mismatch found
            break;
        }
    }
    return result;
}

