#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip
#define GPIOCHIP "gpiochip0"

// Define relay strike duration (seconds)
#define RELAY_DURATION 1

// Define failsafe timeout (seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int motion_detected(void);
int relay_on(void);
int relay_off(void);
int failsafe_check(void);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", GPIOCHIP);
        return -1;
    }

    // Request PIR line as input
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line: %d", PIR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(pir_line, "motion_sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %d", ret);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request Relay line as output
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get Relay line: %d", RELAY_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    ret = gpiod_line_request_output(relay_line, "relay_control", 0); // Initial state LOW
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request Relay line as output: %d", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    return 0;
}

// Function to detect motion
int motion_detected(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR line value: %d", value);
        return 0; // Return 0 to avoid triggering relay on error
    }
    return value;
}

// Function to turn the relay ON
int relay_on(void) {
    int ret = gpiod_line_set_value(relay_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set Relay line value to 1: %d", ret);
        return -1;
    }
    syslog(LOG_INFO, "Relay ON");
    return 0;
}

// Function to turn the relay OFF
int relay_off(void) {
    int ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set Relay line value to 0: %d", ret);
        return -1;
    }
    syslog(LOG_INFO, "Relay OFF");
    return 0;
}

// Function to implement the failsafe check
int failsafe_check(void) {
    static time_t last_motion_time = 0;
    time_t current_time = time(NULL);

    if (motion_detected()) {
        last_motion_time = current_time;
    }

    if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT) {
        syslog(LOG_WARNING, "Failsafe triggered: PIR sensor HIGH for %d seconds. De-energizing relay.", FAILSAFE_TIMEOUT);
        relay_off();
        return 1; // Failsafe triggered
    }

    return 0; // No failsafe triggered
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (relay_line) {
        relay_off(); // Ensure relay is off before releasing
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(0);
}

int main(void) {
    // Open system log
    openlog("motion_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Motion sensor application started.");

    // Main loop
    while (!terminate) {
        if (motion_detected()) {
            syslog(LOG_INFO, "Motion detected!");
            relay_on();
            sleep(RELAY_DURATION);
            relay_off();
        }

        if (failsafe_check()) {
            // Failsafe already triggered in failsafe_check()
            // No need to do anything here, just continue the loop
        }

        usleep(50000); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

