#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define relay activation time (seconds)
#define RELAY_ON_TIME 300

// Define pause time between relays (seconds)
#define PAUSE_TIME 60

// Define the timer interval (seconds)
#define TIMER_INTERVAL 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the relay sequence
const int relay_sequence[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

// Define the relay sequence index
int current_relay_index = 0;

// Define the current relay state
int current_relay_state = 0; // 0 = OFF, 1 = ON

// Define the timer state
int timer_state = 0; // 0 = OFF, 1 = ON

// Define the timer count
int timer_count = 0;

// Define the timer duration
int timer_duration = 0;

// Define the timer type
int timer_type = 0; // 0 = Activation, 1 = Pause

// Define a flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void relay_control(int relay_pin, int state);
void timer_callback();
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;

    // Deactivate all relays
    relay_control(RELAY1_PIN, 0);
    relay_control(RELAY2_PIN, 0);
    relay_control(RELAY3_PIN, 0);
    relay_control(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

// Relay control function
void relay_control(int relay_pin, int state) {
    int result = gpioWrite(relay_pin, state);
    if (result != 0) {
        char message[100];
        snprintf(message, sizeof(message), "Error writing to GPIO %d: %d", relay_pin, result);
        log_message(LOG_ERR, message);
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Relay on GPIO %d set to %d", relay_pin, state);
        log_message(LOG_INFO, message);
    }
}

// Timer callback function
void timer_callback() {
    if (timer_state == 1) {
        timer_count++;

        if (timer_count >= timer_duration) {
            // Timer duration reached
            timer_state = 0;
            timer_count = 0;

            if (timer_type == 0) {
                // Relay activation time reached
                relay_control(relay_sequence[current_relay_index], 0); // Deactivate relay
                current_relay_state = 0;
                log_message(LOG_INFO, "Relay activation time reached, deactivating relay.");
            } else {
                // Pause time reached
                current_relay_index = (current_relay_index + 1) % NUM_RELAYS; // Move to the next relay
                log_message(LOG_INFO, "Pause time reached, moving to the next relay.");
            }
        }
    }
}

// Log message function
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to OFF (HIGH)
    relay_control(RELAY1_PIN, 1);
    relay_control(RELAY2_PIN, 1);
    relay_control(RELAY3_PIN, 1);
    relay_control(RELAY4_PIN, 1);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback function
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Activate the current relay
        if (current_relay_state == 0) {
            relay_control(relay_sequence[current_relay_index], 1); // Activate relay
            current_relay_state = 1;
            log_message(LOG_INFO, "Relay activated.");
            timer_state = 1;
            timer_count = 0;
            timer_duration = RELAY_ON_TIME;
            timer_type = 0; // Activation
        }

        // Sleep for a short time to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Cleanup (should not reach here if signal handler is working correctly)
    relay_control(RELAY1_PIN, 0);
    relay_control(RELAY2_PIN, 0);
    relay_control(RELAY3_PIN, 0);
    relay_control(RELAY4_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}

