#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Sysfs Paths
#define SYSFS_PATH "/sys/kernel/mpu6050_accel"
#define LATEST_DATA_PATH SYSFS_PATH "/latest"
#define BUFFER_SIZE 100

// Data Structure
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Global Variables
int i2c_fd = -1;
volatile sig_atomic_t running = 1;

// Circular Buffer
AccelData accel_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int init_mpu6050(int fd);
int read_accel_data(int fd, AccelData *data);
void update_circular_buffer(AccelData data);
int write_latest_data_to_sysfs(const AccelData *data);
void timer_handler(int signum);
void signal_handler(int signum);
int create_sysfs_directory(const char *path);

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// MPU6050 Initialization Function
int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }
    return 0;
}

// Read Acceleration Data Function
int read_accel_data(int fd, AccelData *data) {
    uint8_t raw_data[6];
    if (i2c_read_reg(fd, ACCEL_XOUT_H, &raw_data[0]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H\n");
        return -1;
    }
    if (i2c_read_reg(fd, ACCEL_XOUT_H + 1, &raw_data[1]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 1\n");
        return -1;
    }
    if (i2c_read_reg(fd, ACCEL_XOUT_H + 2, &raw_data[2]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 2\n");
        return -1;
    }
    if (i2c_read_reg(fd, ACCEL_XOUT_H + 3, &raw_data[3]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 3\n");
        return -1;
    }
    if (i2c_read_reg(fd, ACCEL_XOUT_H + 4, &raw_data[4]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 4\n");
        return -1;
    }
    if (i2c_read_reg(fd, ACCEL_XOUT_H + 5, &raw_data[5]) < 0) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 5\n");
        return -1;
    }

    int16_t x = (raw_data[0] << 8) | raw_data[1];
    int16_t y = (raw_data[2] << 8) | raw_data[3];
    int16_t z = (raw_data[4] << 8) | raw_data[5];

    data->x = (float)x / 16384.0f;
    data->y = (float)y / 16384.0f;
    data->z = (float)z / 16384.0f;

    return 0;
}

// Circular Buffer Update Function
void update_circular_buffer(AccelData data) {
    accel_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Write Latest Data to Sysfs Function
int write_latest_data_to_sysfs(const AccelData *data) {
    FILE *fp = fopen(LATEST_DATA_PATH, "w");
    if (fp == NULL) {
        perror("Failed to open sysfs file for writing");
        return -1;
    }

    fprintf(fp, "%.6f %.6f %.6f", data->x, data->y, data->z);
    fclose(fp);
    return 0;
}

// Timer Handler Function
void timer_handler(int signum) {
    AccelData data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        update_circular_buffer(data);
        write_latest_data_to_sysfs(&data);
    } else {
        fprintf(stderr, "Failed to read acceleration data in timer handler\n");
    }
}

// Signal Handler Function
void signal_handler(int signum) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

// Create Sysfs Directory Function
int create_sysfs_directory(const char *path) {
    if (mkdir(path, 0777) == -1) {
        if (errno != EEXIST) {
            perror("Failed to create sysfs directory");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Create sysfs directory
    if (create_sysfs_directory(SYSFS_PATH) < 0) {
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer
    struct sigevent sev;
    struct itimerspec its;
    timer_t timerid;

    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timerid;

    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        perror("Failed to create timer");
        close(i2c_fd);
        return 1;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 100 Hz (10ms)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 100 Hz (10ms)

    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("Failed to set timer");
        close(i2c_fd);
        timer_delete(timerid);
        return 1;
    }

    // Main loop
    while (running) {
        pause(); // Wait for signal
    }

    // Clean up
    timer_delete(timerid);
    close(i2c_fd);
    unlink(LATEST_DATA_PATH);
    rmdir(SYSFS_PATH);

    return 0;
}

