#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins (BCM numbering)
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals (seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int gpio_init(void);
void relay_on(int gpio_pin);
void relay_off(int gpio_pin);
void toggle_relay(int gpio_pin, int interval);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    relay_off(RELAY1_PIN);
    relay_off(RELAY2_PIN);
    relay_off(RELAY3_PIN);
    relay_off(RELAY4_PIN);

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    exit(0);
}

// Initialize GPIO pins
int gpio_init(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        if (chip) gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "relay_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay1_line, &config, 0) < 0) {
        perror("Error requesting GPIO line 18");
        cleanup(0);
        return -1;
    }
    if (gpiod_line_request(relay2_line, &config, 0) < 0) {
        perror("Error requesting GPIO line 23");
        cleanup(0);
        return -1;
    }
    if (gpiod_line_request(relay3_line, &config, 0) < 0) {
        perror("Error requesting GPIO line 24");
        cleanup(0);
        return -1;
    }
    if (gpiod_line_request(relay4_line, &config, 0) < 0) {
        perror("Error requesting GPIO line 25");
        cleanup(0);
        return -1;
    }

    return 0;
}

// Turn on a relay
void relay_on(int gpio_pin) {
    struct gpiod_line *line;
    switch (gpio_pin) {
        case RELAY1_PIN: line = relay1_line; break;
        case RELAY2_PIN: line = relay2_line; break;
        case RELAY3_PIN: line = relay3_line; break;
        case RELAY4_PIN: line = relay4_line; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO value");
    }
}

// Turn off a relay
void relay_off(int gpio_pin) {
    struct gpiod_line *line;
    switch (gpio_pin) {
        case RELAY1_PIN: line = relay1_line; break;
        case RELAY2_PIN: line = relay2_line; break;
        case RELAY3_PIN: line = relay3_line; break;
        case RELAY4_PIN: line = relay4_line; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO value");
    }
}

// Toggle a relay with a specified interval
void toggle_relay(int gpio_pin, int interval) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        relay_on(gpio_pin);
        clock_gettime(CLOCK_MONOTONIC, &now);
