void relay_on(int gpio_pin) {
    struct gpiod_line *line;
    switch (gpio_pin) {
        case RELAY1_PIN: line = relay1_line; break;
        case RELAY2_PIN: line = relay2_line; break;
        case RELAY3_PIN: line = relay3_line; break;
        case RELAY4_PIN: line = relay4_line; break;
