#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define cooldown period (in seconds)
#define COOLDOWN_PERIOD 5

// Global variables
static volatile int running = 1;
static volatile int alarm_active = 0;
static volatile time_t last_alarm_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_alarm();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int sound_sensor_pin;
    int relay_pin;
    int cooldown_period;
    char log_file_path[64];
} Config;

Config config = {SOUND_SENSOR_PIN, RELAY_PIN, COOLDOWN_PERIOD, "alarm_log.txt"};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Sound-activated relay system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Check if sound is detected and cooldown period has passed
        if (sound_detected && !alarm_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_alarm_time) >= config.cooldown_period) {
                // Activate relay
                activate_relay();

                // Log alarm
                log_alarm();

                // Update last alarm time
                last_alarm_time = current_time;

                // Set alarm_active flag
                alarm_active = 1;
            }
        } else if (sound_detected && alarm_active) {
            // Sound detected while alarm is active, do nothing
        } else {
            // No sound detected, check if alarm should be deactivated
            if (alarm_active) {
                deactivate_relay();
                alarm_active = 0;
            }
        }

        // Poll every 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(config.sound_sensor_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", config.sound_sensor_pin);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(config.relay_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", config.relay_pin);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    deactivate_relay();

    return 0;
}

// Read sound sensor
int read_sound_sensor() {
    return gpioRead(config.sound_sensor_pin);
}

// Activate relay
void activate_relay() {
    gpioWrite(config.relay_pin, 1); // Set GPIO HIGH
    printf("Relay activated!\n");
}

// Deactivate relay
void deactivate_relay() {
    gpioWrite(config.relay_pin, 0); // Set GPIO LOW
    printf("Relay deactivated!\n");
}

// Log alarm to file
void log_alarm() {
    FILE *fp = fopen(config.log_file_path, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_relay(); // Ensure relay is off
    gpioTerminate();    // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

