volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int init_mpu6050(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the sensor
    if (i2c_write_byte(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_read_bytes(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set gyroscope full-scale range to +-250 degrees/second
    if (i2c_write_byte(fd, GYRO_CONFIG, 0) != 0) {
        fprintf(stderr, "Error: Could not set gyroscope configuration\n");
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, GYRO_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t gyro_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t gyro_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t gyro_z = (int16_t)((data[4] << 8) | data[5]);

    *x = (float)gyro_x / GYRO_SENSITIVITY;
    *y = (float)gyro_y / GYRO_SENSITIVITY;
    *z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the angular velocity threshold
void check_threshold(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > 50.0f) {
        printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
        // Call the user-defined callback function here
        // user_callback(x, y, z);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Exiting program...\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    float x, y, z;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Check threshold
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        // Delay
        usleep(10000); // 10ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

