#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_INTERVAL_USEC (READ_INTERVAL_SEC * 1000000)
#define MAX_RETRIES 3
#define TIMEOUT_SEC 1

// Global variables
int uart_handle;
FILE *co2_log_file;
FILE *co2_error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_co2(int *co2_ppm, int *error_flag);
int log_data(int co2_ppm, int error_flag);
void signal_handler(int signal);
void log_error(const char *message);

// Structure for grouping sensor data
typedef struct {
    long timestamp_us;
    int co2_ppm;
    int error_flag;
} sensor_data_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", UART_DEVICE);
        gpioTerminate();
        return 1;
    }

    // Open log files
    co2_log_file = fopen(CO2_LOG_FILE, "a");
    if (co2_log_file == NULL) {
        fprintf(stderr, "Failed to open co2_log_file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    co2_error_log_file = fopen(CO2_ERROR_LOG_FILE, "a");
    if (co2_error_log_file == NULL) {
        fprintf(stderr, "Failed to open co2_error_log_file\n");
        fclose(co2_log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read CO2 concentration from the MH-Z19B sensor
int read_co2(int *co2_ppm, int *error_flag) {
    unsigned char read_command[9] = CO2_READ_COMMAND;
    unsigned char response[9];
    int retries = 0;
    int bytes_read = 0;
    int i;

    // Send read command
    if (serWrite(uart_handle, (char *)read_command, 9) != 9) {
        log_error("Failed to send read command");
        *error_flag = 1;
        return 1;
    }

    // Wait for response
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Check for available data
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            // Read data
            if (bytes_read == 0) {
                // Read the first byte to determine the number of bytes to read
                if (serRead(uart_handle, (char *)response + bytes_read, 1) != 1) {
                    log_error("Failed to read first byte");
                    *error_flag = 1;
                    return 1;
                }
                bytes_read = 1;
            } else if (bytes_read < 8) {
                // Read the remaining bytes
                if (serRead(uart_handle, (char *)response + bytes_read, 1) != 1) {
                    log_error("Failed to read remaining bytes");
                    *error_flag = 1;
                    return 1;
                }
                bytes_read++;
            } else {
                // Read the last byte
                if (serRead(uart_handle, (char *)response + bytes_read, 1) != 1) {
                    log_error("Failed to read last byte");
                    *error_flag = 1;
                    return 1;
                }
                bytes_read++;
                break; // Exit the loop after reading all 9 bytes
            }

            // Check for timeout
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
            if (elapsed_time > TIMEOUT_SEC) {
                log_error("Timeout waiting for response");
                *error_flag = 1;
                return 1;
            }
        } else {
            // No data available, check for timeout
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
            if (elapsed_time > TIMEOUT_SEC) {
                log_error("Timeout waiting for response");
                *error_flag = 1;
                return 1;
            }
        }

        if (bytes_read == 9) {
            break;
        }
    }

    // Validate checksum
    unsigned char checksum = 0;
    for (i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = ~checksum + 1;

    if (checksum != response[8]) {
        log_error("Checksum mismatch");
        *error_flag = 1;
        return 1;
    }

    // Extract CO2 concentration
    *co2_ppm = (response[2] << 8) | response[3];
    *error_flag = 0;

    return 0;
}

// Function to log data to a JSON file
int log_data(int co2_ppm, int error_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    // Create JSON object
    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": %ld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_us, co2_ppm, error_flag);

    // Append to log file
    if (fprintf(co2_log_file, "%s", json_string) < 0) {
        log_error("Failed to write to co2_log_file");
        return 1;
    }

    // Print to stdout
    printf("%s", json_string);

    // Flush the file
    fflush(co2_log_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to log errors to a file
void log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    fprintf(co2_error_log_file, "%ld: %s\n", timestamp_us, message);
    fflush(co2_error_log_file);
    fprintf(stderr, "%ld: %s\n", timestamp_us, message);
}

int main() {
    int co2_ppm, error_flag;
    struct timespec sleep_time;
    sleep_time.tv_sec = READ_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    if (initialize()) {
        return 1;
    }

    printf("CO2 Monitor started. Press Ctrl+C to terminate.\n");

    while (!terminate) {
        if (read_co2(&co2_ppm, &error_flag) == 0) {
            if (log_data(co2_ppm, error_flag) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read CO2");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Closing UART...\n");
    serClose(uart_handle);

    printf("Closing log files...\n");
    fclose(co2_log_file);
    fclose(co2_error_log_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("CO2 Monitor terminated.\n");

    return 0;
}

