#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L Registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_START 0x03

// GPIO pin for heading deviation alert
#define ALERT_GPIO 17

// Target heading
#define TARGET_HEADING 90.0

// Hard-iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int hmc5883l_init();
int hmc5883l_read_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float compensate_heading(float heading);
void control_gpio(float heading);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// HMC5883L initialization function
int hmc5883l_init() {
    // Configure CONFIG_A register
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        log_error("Failed to write to CONFIG_A register");
        return -1;
    }

    // Configure CONFIG_B register
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        log_error("Failed to write to CONFIG_B register");
        return -1;
    }

    // Configure MODE register
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        log_error("Failed to write to MODE register");
        return -1;
    }

    return 0;
}

// HMC5883L data reading function
int hmc5883l_read_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_START, data, 6) == 6) {
            *x = (int16_t)((data[0] << 8) | data[1]);
            *z = (int16_t)((data[2] << 8) | data[3]);
            *y = (int16_t)((data[4] << 8) | data[5]);
            return 0; // Success
        } else {
            log_error("Failed to read data, retrying...");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    log_error("Failed to read data after multiple retries");
    return -1; // Failure
}

// Heading calculation function
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Heading compensation function
float compensate_heading(float heading) {
