// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L Registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_START 0x03

// GPIO pin for heading deviation alert
#define ALERT_GPIO 17

// Target heading
#define TARGET_HEADING 90.0

// Hard-iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
