#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address for BH1750 sensor
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50.0
#define LUX_THRESHOLD_GREEN 150.0
#define LUX_THRESHOLD_BLUE 300.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int init_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux, int red_relay_state, int green_relay_state, int blue_relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    // Initialize relays to OFF state
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    return 0;
}

// Initialize I2C communication
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    unsigned char config_mode = 0x10; // Continuous high-resolution mode
    unsigned char buffer[2];
    int result;

    // Send configuration mode command
    result = write(i2c_fd, &config_mode, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1.0;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read 2 bytes of lux data
    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    // Convert raw data to lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_relay_state = 0;
    int green_relay_state = 0;
    int blue_relay_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_relay_state = 1;
    } else if (lux < LUX_THRESHOLD_GREEN) {
        green_relay_state = 1;
    } else if (lux < LUX_THRESHOLD_BLUE) {
        blue_relay_state = 1;
    } else {
        red_relay_state = 1;
        green_relay_state = 1;
        blue_relay_state = 1;
    }

    gpioWrite(RED_RELAY_PIN, red_relay_state);
    gpioWrite(GREEN_RELAY_PIN, green_relay_state);
    gpioWrite(BLUE_RELAY_PIN, blue_relay_state);

    log_data(lux, red_relay_state, green_relay_state, blue_relay_state);
}

// Log data to file
void log_data(float lux, int red_relay_state, int green_relay_state, int blue_relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_relay_state, green_relay_state, blue_relay_state);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float lux = read_lux();
        if (lux >= 0) {
            control_relays(lux);
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Smart Lighting System stopped.\n");
    return 0;
}

