// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, stopping motors and exiting...\n");
}

// Function to set motor direction and speed
void set_motor_speed(int motor_a_distance, int motor_b_distance) {
    // Motor A
    if (motor_a_distance < 50) {
        // Forward
        gpioWrite(MOTOR_A_IN1, 1);
        gpioWrite(MOTOR_A_IN2, 0);
        int duty_cycle = 255 - (int)(((float)(motor_a_distance - 10) / 90.0) * 255.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 1);
        int duty_cycle = (int)(((float)(motor_a_distance - 10) / 90.0) * 255.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    }

    // Motor B
    if (motor_b_distance < 50) {
        // Forward
        gpioWrite(MOTOR_B_IN3, 1);
        gpioWrite(MOTOR_B_IN4, 0);
        int duty_cycle = 255 - (int)(((float)(motor_b_distance - 10) / 90.0) * 255.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 1);
        int duty_cycle = (int)(((float)(motor_b_distance - 10) / 90.0) * 255.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Simulated sensor readings (replace with actual sensor readings)
    int motor_a_distance = 30; // Example distance for Motor A
    int motor_b_distance = 60; // Example distance for Motor B

    // Main control loop
    while (program_running) {
        set_motor_speed(motor_a_distance, motor_b_distance);
        gpioDelay(100); // 100 ms delay
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

