#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define SERVO_PIN 18
#define PWM_PERIOD 20000 // 50Hz
#define PWM_FILE "/sys/class/pwm/pwmchip2/pwm0"
#define LOG_FILE "solar_tracker.log"
#define RETRY_DELAY_BASE_MS 10
#define RETRY_DELAY_MAX_MS 100
#define MAX_RETRIES 5

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, unsigned char reg);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int sig);

// I2C read function with retry and exponential backoff
int i2c_read_word(int fd, unsigned char reg) {
    int retries = 0;
    int result;
    unsigned char buf[2];

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries++;
            usleep(RETRY_DELAY_BASE_MS * (1 << retries) * 1000); // Exponential backoff
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            perror("Failed to read data");
            retries++;
            usleep(RETRY_DELAY_BASE_MS * (1 << retries) * 1000); // Exponential backoff
            continue;
        }

        result = (buf[0] << 8) | buf[1];
        return result;
    }

    fprintf(stderr, "I2C read failed after %d retries. Register: 0x%02X\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// I2C write function with retry and exponential backoff
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    int retries = 0;
    unsigned char buf[2];

    while (retries < MAX_RETRIES) {
        buf[0] = reg;
        buf[1] = value;

        if (write(fd, buf, 2) != 2) {
            perror("Failed to write data");
            retries++;
            usleep(RETRY_DELAY_BASE_MS * (1 << retries) * 1000); // Exponential backoff
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "I2C write failed after %d retries. Register: 0x%02X, Value: 0x%02X\n", MAX_RETRIES, reg, value);
    return -1; // Indicate failure
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (set power management register to 0)
    if (i2c_write_byte(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read accelerometer and gyroscope data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    *accel_x = i2c_read_word(fd, ACCEL_XOUT_H);
    *accel_y = i2c_read_word(fd, ACCEL_XOUT_H + 2);
    *accel_z = i2c_read_word(fd, ACCEL_XOUT_H + 4);
    *gyro_x = i2c_read_word(fd, GYRO_XOUT_H);
    *gyro_y = i2c_read_word(fd, GYRO_XOUT_H + 2);
    *gyro_z = i2c_read_word(fd, GYRO_XOUT_H + 4);

    if (*accel_x == -1 || *accel_y == -1 || *accel_z == -1 || *gyro_x == -1 || *gyro_y == -1 || *gyro_z == -1) {
        fprintf(stderr, "Failed to read MPU-6050 data\n");
        return -1;
    }

    return 0;
}

// Calculate pitch angle
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
}

// Calculate roll angle
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(int angle) {
    int duty_cycle = (int)(((float)angle / 180.0) * PWM_PERIOD + 1000); // Map 0-180 to 1000-2000
    char buf[20];

    snprintf(buf, sizeof(buf), "duty_cycle=%d\n", duty_cycle);
    int fd = open(PWM_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM file");
        return -1;
    }

    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write to PWM file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle = 90; // Initial servo angle

    while (!terminate) {
        // Read MPU-6050 data
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

            // Set servo angle (example: proportional control)
            servo_angle = (int)(pitch + 90); // Adjust gain and offset as needed
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > 180) servo_angle = 180;

            // Set servo angle
            if (set_servo_angle(servo_angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            // Log data
            log_data(pitch, roll, servo_angle);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

