    }
    return 0;
}

// Read accelerometer and gyroscope data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    *accel_x = i2c_read_word(fd, ACCEL_XOUT_H);
    *accel_y = i2c_read_word(fd, ACCEL_XOUT_H + 2);
    *accel_z = i2c_read_word(fd, ACCEL_XOUT_H + 4);
    *gyro_x = i2c_read_word(fd, GYRO_XOUT_H);
    *gyro_y = i2c_read_word(fd, GYRO_XOUT_H + 2);
    *gyro_z = i2c_read_word(fd, GYRO_XOUT_H + 4);

    if (*accel_x == -1 || *accel_y == -1 || *accel_z == -1 || *gyro_x == -1 || *gyro_y == -1 || *gyro_z == -1) {
        fprintf(stderr, "Failed to read MPU-6050 data\n");
        return -1;
    }

    return 0;
}

// Calculate pitch angle
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
}

// Calculate roll angle
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    return atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(int angle) {
    int duty_cycle = (int)(((float)angle / 180.0) * PWM_PERIOD + 1000); // Map 0-180 to 1000-2000
    char buf[20];

    snprintf(buf, sizeof(buf), "duty_cycle=%d\n", duty_cycle);
    int fd = open(PWM_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM file");
        return -1;
    }

    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write to PWM file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle = 90; // Initial servo angle

    while (!terminate) {
        // Read MPU-6050 data
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

            // Set servo angle (example: proportional control)
            servo_angle = (int)(pitch + 90); // Adjust gain and offset as needed
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > 180) servo_angle = 180;

            // Set servo angle
            if (set_servo_angle(servo_angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            // Log data
            log_data(pitch, roll, servo_angle);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

