#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 100

// Define transition time (seconds)
#define TRANSITION_TIME 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} ScheduleEntry;

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_schedule(ScheduleEntry *schedule, int *schedule_size);
int parse_schedule_line(char *line, ScheduleEntry *entry);
int set_relay_state(int relay_number, int state);
int fade_relay_brightness(int relay_number, int target_brightness);
int apply_schedule(ScheduleEntry *schedule, int schedule_size);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    gpioSetPWMrange(RELAY1_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY2_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY3_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY4_GPIO, PWM_RANGE);

    return 0;
}

// Function to read the schedule from a file
int read_schedule(ScheduleEntry *schedule, int *schedule_size) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    char line[256];
    *schedule_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_line(line, &schedule[*schedule_size]) == 0) {
            (*schedule_size)++;
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule line
int parse_schedule_line(char *line, ScheduleEntry *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->on_off) == 5) {
        return 0;
    } else {
        fprintf(stderr, "Invalid schedule line: %s", line);
        return 1;
    }
}

// Function to set the state of a relay (on/off)
int set_relay_state(int relay_number, int state) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to fade the brightness of a relay using PWM
int fade_relay_brightness(int relay_number, int target_brightness) {
    int gpio_pin;
    int current_brightness;
    int step;
    int i;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    current_brightness = gpioGetPWMdutycycle(gpio_pin) / 1000; // Get current brightness (0-100)
    step = (target_brightness - current_brightness) / 100; // Calculate step size for 100 steps

    for (i = 0; i < 100; i++) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 100) current_brightness = 100;
        gpioPWM(gpio_pin, current_brightness * 1000); // Set PWM duty cycle
        gpioDelay(18000); // Delay for 18 seconds (18000 microseconds)
    }

    return 0;
}

// Function to apply the schedule
int apply_schedule(ScheduleEntry *schedule, int schedule_size) {
    time_t current_time;
    struct tm *time_info;
    int i;

    time(&current_time);
    time_info = localtime(&current_time);

    for (i = 0; i < schedule_size; i++) {
        if (schedule[i].hour == time_info->tm_hour &&
            schedule[i].minute == time_info->tm_min &&
            schedule[i].second == time_info->tm_sec) {

            if (schedule[i].on_off == 1) {
                // Turn on the relay and fade in
                set_relay_state(schedule[i].relay_number, 1);
                fade_relay_brightness(schedule[i].relay_number, 100);
            } else {
                // Turn off the relay and fade out
                fade_relay_brightness(schedule[i].relay_number, 0);
                set_relay_state(schedule[i].relay_number, 0);
            }
            return 0; // Exit after handling one event
        }
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to turn off relays and release GPIO resources
void cleanup() {
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    ScheduleEntry *schedule = NULL;
    int schedule_size = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read the schedule
    if (read_schedule(schedule, &schedule_size) != 0) {
        cleanup();
        return 1;
    }

    // Allocate memory for the schedule
    schedule = (ScheduleEntry *)malloc(schedule_size * sizeof(ScheduleEntry));
    if (schedule == NULL) {
        perror("Failed to allocate memory for schedule");
        cleanup();
        return 1;
    }

    if (read_schedule(schedule, &schedule_size) != 0) {
        free(schedule);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        free(schedule);
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        apply_schedule(schedule, schedule_size);
        gpioDelay(1000000); // Check every second (1000000 microseconds)
    }

    // Cleanup and exit
    free(schedule);
    cleanup();

    return 0;
}

