// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to calculate RGB values based on proximity value
void calculate_rgb(float proximity, int *red, int *green, int *blue) {
    // Map proximity value (0.0 to 1.0) to RGB values
    *red   = (int)(proximity * 255.0);
    *green = (int)((1.0 - proximity) * 255.0);
    *blue  = 0; // Keep blue at 0 for simplicity
}

// Function to set the RGB LED color
int set_rgb_led(int red, int green, int blue) {
    if (set_pwm_duty_cycle(RED_PIN, red) != 0) return -1;
    if (set_pwm_duty_cycle(GREEN_PIN, green) != 0) return -1;
    if (set_pwm_duty_cycle(BLUE_PIN, blue) != 0) return -1;
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    if (gpioSetPWMrange(RED_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    float proximity = 0.0;
    int red, green, blue;

    // Main loop
    while (program_running) {
        // Calculate RGB values based on proximity
        calculate_rgb(proximity, &red, &green, &blue);

        // Set RGB LED color
        if (set_rgb_led(red, green, blue) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Increment proximity value (simulating a sine wave)
        proximity += 0.01;
        if (proximity > 1.0) {
            proximity = 0.0;
        }

        // Delay for a short period
        gpioDelay(10000); // 10ms delay
    }

    // Turn off the LED
    set_rgb_led(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

