#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for ±250 deg/s
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_i2c(int address);
int wake_sensor(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
double convert_to_dps(int16_t raw_data);
void log_data(gyro_data_t data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C interface
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Wake up the MPU-6050 sensor
int wake_sensor(int fd) {
    uint8_t data = 0x00;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw gyroscope data to degrees per second
double convert_to_dps(int16_t raw_data) {
    return (double)raw_data / GYRO_SENSITIVITY;
}

// Log gyroscope data to a file
void log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    double x_dps = convert_to_dps(data.x);
    double y_dps = convert_to_dps(data.y);
    double z_dps = convert_to_dps(data.z);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Wake up the sensor
    if (wake_sensor(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

