#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody (frequency, duration in ms)
const int melody[][2] = {
    {440, 250},   // A4
    {494, 250},   // B4
    {523, 250},   // C5
    {587, 250},   // D5
    {659, 250},   // E5
    {698, 250},   // F5
    {784, 250},   // G5
    {880, 250}    // A5
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int playing = 0; // Flag to indicate if the melody is playing
volatile int button_pressed = 0; // Flag to indicate if the button is pressed
volatile unsigned long last_interrupt_time = 0; // Last time the button was pressed

// Function prototypes
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void play_melody();
void stop_melody();
void cleanup(int signal);

// Interrupt handler function
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_interrupt_time > 50000) { // Debounce (50ms)
        button_pressed = 1;
        last_interrupt_time = current_time;
    }
}

// Function to play the melody
void play_melody() {
    playing = 1;
    int i = 0;
    while (playing && i < melody_length) {
        int frequency = melody[i][0];
        int duration = melody[i][1];

        if (gpioHardwarePWM(BUZZER_PIN, frequency, 500000) < 0) { // 50% duty cycle
            fprintf(stderr, "Error setting PWM frequency: %d\n", frequency);
            stop_melody();
            return;
        }

        gpioDelay(duration * 1000); // Delay for the duration

        if (!playing) break; // Stop if the button is pressed again

        i++;
    }
    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    playing = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
}

// Cleanup function to handle signals
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set BUTTON_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for the button
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
