#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEFAULT_POLL_TIMEOUT 1000
#define WINDOW_SIZE 5

// Structure to hold the last WINDOW_SIZE events
typedef struct {
    int events[WINDOW_SIZE];
    int count;
} EventWindow;

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;
static EventWindow event_window = {{0}, 0};
static int poll_timeout_ms = DEFAULT_POLL_TIMEOUT;
static struct timespec last_event_time;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
int read_sensor(void);
void log_event(int value);
void update_event_window(int value);
void check_earthquake_alert(void);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, exiting...\n");
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_input(gpio_line, "vibration_sensor", NULL);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %d\n", ret);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value;
    int ret;

    ret = gpiod_line_get_value(gpio_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line value: %d\n", ret);
        return -1;
    }

    value = ret;
    return value;
}

// Log event to file
void log_event(int value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[32];

    time(&now);
    timeinfo = gmtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Update event window
void update_event_window(int value) {
    event_window.events[event_window.count % WINDOW_SIZE] = value;
    event_window.count++;
    if (event_window.count >= WINDOW_SIZE) {
        // Full window, check for earthquake alert
        check_earthquake_alert();
    }
}

// Check for earthquake alert
void check_earthquake_alert(void) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (event_window.events[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        time_t now;
        struct tm *timeinfo;
        char timestamp[32];

        time(&now);
        timeinfo = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        printf("EARTHQUAKE ALERT: %s\n", timestamp);
    }
}

// Cleanup resources
void cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    int sensor_value;

    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default: %d ms\n", DEFAULT_POLL_TIMEOUT);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        log_event(sensor_value);
        update_event_window(sensor_value);

        // Poll for events
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = poll_timeout_ms * 1000000; // Convert milliseconds to nanoseconds

        ret = gpiod_line_event_wait(gpio_line, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %d\n", ret);
            break; // Exit loop on error
        }
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

