    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, short *x, short *y, short *z) {
    unsigned char x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    if (i2c_read_reg(fd, OUT_X_H_M, &x_msb) == -1 ||
        i2c_read_reg(fd, OUT_X_L_M, &x_lsb) == -1 ||
        i2c_read_reg(fd, OUT_Z_H_M, &z_msb) == -1 ||
        i2c_read_reg(fd, OUT_Z_L_M, &z_lsb) == -1 ||
        i2c_read_reg(fd, OUT_Y_H_M, &y_msb) == -1 ||
        i2c_read_reg(fd, OUT_Y_L_M, &y_lsb) == -1) {
        return -1;
    }

    *x = (short)((x_msb << 8) | x_lsb);
    *z = (short)((z_msb << 8) | z_lsb);
    *y = (short)((y_msb << 8) | y_lsb);

    return 0;
}

// Calibrate data
void calibrate_data(short x, short y, short z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x + X_OFFSET;
    *calibrated_y = (float)y + Y_OFFSET;
    *calibrated_z = (float)z + Z_OFFSET;
}

// Calculate heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x);
    heading = heading * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to CSV file
void log_data(FILE *fp, float x, float y, float z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, heading);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure magnetometer
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) == -1) { // 15 Hz
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) == -1) { // Continuous-conversion mode
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    short x_raw, y_raw, z_raw;
    float x_calibrated, y_calibrated, z_calibrated;
    float heading;
    char direction[10];

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x_raw, &y_raw, &z_raw) == -1) {
            fprintf(stderr, "Failed to read magnetometer data. Skipping.\n");
            sleep(1);
            continue;
        }

        // Calibrate data
        calibrate_data(x_raw, y_raw, z_raw, &x_calibrated, &y_calibrated, &z_calibrated);

        // Calculate heading
        heading = calculate_heading(x_calibrated, y_calibrated);

        // Determine compass direction
        if (heading >= 337.5 || heading < 22.5) {
            strcpy(direction, "N");
        } else if (heading < 67.5) {
            strcpy(direction, "NE");
        } else if (heading < 112.5) {
            strcpy(direction, "E");
        } else if (heading < 157.5) {
            strcpy(direction, "SE");
        } else if (heading < 202.5) {
            strcpy(direction, "S");
        } else if (heading < 247.5) {
            strcpy(direction, "SW");
        } else if (heading < 292.5) {
            strcpy(direction, "W");
        } else {
            strcpy(direction, "NW");
        }

        // Log data
        log_data(log_file, x_calibrated, y_calibrated, z_calibrated, heading);

        // Print data to console
        printf("Direction: %s, Heading: %.2f\n", direction, heading);

        sleep(1);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

