#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static volatile int running = 1;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user);
void log_relay_state(const char *state);
void signal_handler(int signal);

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log relay state to a JSON file
void log_relay_state(const char *state) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        perror("Error opening relay_log.json");
        return;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
    free(timestamp); // Free the allocated memory
    fclose(fp);
}

// Callback function for touch sensor interrupt
void touch_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        // Toggle the relay state
        relay_state = !relay_state;
        gpioWrite(RELAY_PIN, relay_state);

        // Log the relay state
        log_relay_state(relay_state ? "ON" : "OFF");

        // Update the last touch time
        last_touch_time = current_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    log_relay_state("OFF"); // Log the final state
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set up interrupt service routine (ISR) for the touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

