#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define activation duration (seconds)
#define ACTIVATION_DURATION 5

// Define relay activation delay (seconds)
#define RELAY_DELAY 1

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int read_soil_moisture(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Setup GPIO pins
int setup_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request lines for relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        fprintf(stderr, "Error getting line %d: %s\n", RELAY1_PIN, strerror(errno));
        goto cleanup_chip;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        fprintf(stderr, "Error getting line %d: %s\n", RELAY2_PIN, strerror(errno));
        goto cleanup_line1;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        fprintf(stderr, "Error getting line %d: %s\n", RELAY3_PIN, strerror(errno));
        goto cleanup_line2;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        fprintf(stderr, "Error getting line %d: %s\n", RELAY4_PIN, strerror(errno));
        goto cleanup_line3;
    }

    // Request lines as outputs with initial value 1 (inactive)
    if (gpiod_line_request_output(relay1_line, "irrigation", 1) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", RELAY1_PIN, strerror(errno));
        goto cleanup_line4;
    }

    if (gpiod_line_request_output(relay2_line, "irrigation", 1) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", RELAY2_PIN, strerror(errno));
        goto cleanup_line4;
    }

    if (gpiod_line_request_output(relay3_line, "irrigation", 1) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", RELAY3_PIN, strerror(errno));
        goto cleanup_line4;
    }

    if (gpiod_line_request_output(relay4_line, "irrigation", 1) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", RELAY4_PIN, strerror(errno));
        goto cleanup_line4;
    }

    return 0;

cleanup_line4:
    gpiod_line_release(relay4_line);
cleanup_line3:
    gpiod_line_release(relay3_line);
cleanup_line2:
    gpiod_line_release(relay2_line);
cleanup_line1:
    gpiod_line_release(relay1_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Simulate reading soil moisture
int read_soil_moisture(void) {
    return rand() % 101; // Returns a value between 0 and 100
}

// Activate a relay
void activate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting line %d to 0: %s\n", gpiod_line_get_offset(line), strerror(errno));
    }
    printf("Relay %d activated\n", relay_number);
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting line %d to 1: %s\n", gpiod_line_get_offset(line), strerror(errno));
    }
    printf("Relay %d deactivated\n", relay_number);
}

// Log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    // Close log file
    if (log_file) fclose(log_file);

    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int moisture_level = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture_level);

        // Activate relays if moisture is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            activate_relay(1);
            log_event(1, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(1);

            sleep(RELAY_DELAY);

            activate_relay(2);
            log_event(2, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(2);

            sleep(RELAY_DELAY);

            activate_relay(3);
            log_event(3, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(3);

            sleep(RELAY_DELAY);

            activate_relay(4);
            log_event(4, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(4);
        }

        // Wait 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

