    gpiod_line_release(relay4_line);
cleanup_line3:
    gpiod_line_release(relay3_line);
cleanup_line2:
    gpiod_line_release(relay2_line);
cleanup_line1:
    gpiod_line_release(relay1_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Simulate reading soil moisture
int read_soil_moisture(void) {
    return rand() % 101; // Returns a value between 0 and 100
}

// Activate a relay
void activate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting line %d to 0: %s\n", gpiod_line_get_offset(line), strerror(errno));
    }
    printf("Relay %d activated\n", relay_number);
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting line %d to 1: %s\n", gpiod_line_get_offset(line), strerror(errno));
    }
    printf("Relay %d deactivated\n", relay_number);
}

// Log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    // Close log file
    if (log_file) fclose(log_file);

    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int moisture_level = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture_level);

        // Activate relays if moisture is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
