            sleep(RELAY_DELAY);

            activate_relay(3);
            log_event(3, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(3);

            sleep(RELAY_DELAY);

            activate_relay(4);
            log_event(4, moisture_level);
            sleep(ACTIVATION_DURATION);
            deactivate_relay(4);
        }

        // Wait 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

