#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define VALVE_PIN 17
#define NOZZLE_PIN 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 100

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define watering parameters
#define VALVE_OPEN_PULSE_WIDTH 1500
#define VALVE_CLOSED_PULSE_WIDTH 500
#define NOZZLE_ANGLE_COUNT 5
#define NOZZLE_ANGLE_INCREMENT 45
#define NOZZLE_DELAY_SECONDS 2
#define VALVE_HOLD_SECONDS 5

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_valve_state(int open);
int set_nozzle_angle(int angle);
int water_plant();
int check_moisture();
void signal_handler(int signal);
void cleanup();

// Moisture readings (simulated)
int moisture_readings[] = {20, 40, 60, 80, 100};
int moisture_index = 0;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Check moisture level
        int moisture_level = check_moisture();

        // Water plant if moisture is low
        if (moisture_level < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level: %d. Watering plant.\n", moisture_level);
            if (water_plant() != 0) {
                fprintf(stderr, "Failed to water plant. Continuing.\n");
            }
        } else {
            printf("Moisture level: %d. Skipping watering.\n", moisture_level);
        }

        // Wait before next cycle
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    return 0;
}

// Set valve state
int set_valve_state(int open) {
    int pulse_width = open ? VALVE_OPEN_PULSE_WIDTH : VALVE_CLOSED_PULSE_WIDTH;
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = gpioServo(VALVE_PIN, pulse_width);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error setting valve state (attempt %d): %d\n", 3 - retries + 1, result);
            gpioDelay(100); // Backoff
            retries--;
        }
    }

    if (result != 0) {
        fprintf(stderr, "Critical error: Failed to set valve state after multiple retries.\n");
        program_running = 0; // Stop the program
        return 1;
    }

    return 0;
}

// Set nozzle angle
int set_nozzle_angle(int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = gpioServo(NOZZLE_PIN, pulse_width);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error setting nozzle angle (attempt %d): %d\n", 3 - retries + 1, result);
            gpioDelay(100); // Backoff
            retries--;
        }
    }

    if (result != 0) {
        fprintf(stderr, "Error: Failed to set nozzle angle after multiple retries.\n");
        return 1; // Indicate failure
    }

    return 0;
}

// Water plant
int water_plant() {
    // Open the valve
    if (set_valve_state(1) != 0) {
        return 1;
    }

    // Sweep the nozzle through all five angles
    for (int i = 0; i < NOZZLE_ANGLE_COUNT; i++) {
        if (set_nozzle_angle(i * NOZZLE_ANGLE_INCREMENT) != 0) {
            fprintf(stderr, "Error: Failed to set nozzle angle %d. Continuing to next angle.\n", i * NOZZLE_ANGLE_INCREMENT);
        }
        sleep(NOZZLE_DELAY_SECONDS);
    }

    // Hold for 5 seconds
    sleep(VALVE_HOLD_SECONDS);

    // Close the valve
    if (set_valve_state(0) != 0) {
        return 1;
    }

    return 0;
}

// Check moisture level
int check_moisture() {
    // Increment the moisture index (cycling through the readings)
    moisture_index = (moisture_index + 1) % (sizeof(moisture_readings) / sizeof(moisture_readings[0]));
    return moisture_readings[moisture_index];
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up and exiting.\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    // Stop servos
    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

