#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43

// Sensitivity factor for ±250 deg/sec
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
gyro_data_t read_gyro_data(int fd);
void log_data(FILE *fp, gyro_data_t data);
void signal_handler(int sig);
int init_i2c(void);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    uint8_t data[6];
    gyro_data_t gyro_data;

    if (i2c_read_regs(fd, GYRO_XOUT_H, data, 6) != 0) {
        gyro_data.x = 0.0;
        gyro_data.y = 0.0;
        gyro_data.z = 0.0;
        return gyro_data;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t gyro_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t gyro_z = (int16_t)((data[4] << 8) | data[5]);

    // Convert to degrees/second
    gyro_data.x = (float)gyro_x / GYRO_SENSITIVITY;
    gyro_data.y = (float)gyro_y / GYRO_SENSITIVITY;
    gyro_data.z = (float)gyro_z / GYRO_SENSITIVITY;

    return gyro_data;
}

// Function to log data to file
void log_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data(i2c_fd);
        log_data(log_file, gyro_data);
        sleep(1); // Sample at 10 Hz
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

