#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_PULSE_WIDTH 60000 // microseconds (60ms)
#define TIMEOUT_US 50000       // microseconds (50ms)

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int trigger_pulse(void);
int read_echo_pulse_width(unsigned int *pulse_width);
float calculate_distance(unsigned int pulse_width);
int log_distance(float distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// GPIO initialization function
int gpio_init(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    // Request trigger line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting trigger line: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    // Request echo line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "echo";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting echo line: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    return 0;
}

// Trigger pulse function
int trigger_pulse(void) {
    // Set trigger high
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10); // 10 microseconds

    // Set trigger low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read echo pulse width function
int read_echo_pulse_width(unsigned int *pulse_width) {
    struct timespec start, end;
    unsigned int duration;

    // Wait for rising edge with timeout
    int count = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(errno));
            return -1;
        }
        if (value == 1) {
            break;
        }
        if (count++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        usleep(1); // Check every microsecond
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for falling edge with timeout
    count = 0;
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(errno));
            return -1;
        }
        if (value == 0) {
            break;
        }
        if (count++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        usleep(1); // Check every microsecond
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    *pulse_width = duration;
    return 0;
}

// Calculate distance function
float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Convert us to cm
}

// Log distance function
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(log_file, "%s, -1\n", timestamp);
        fflush(log_file);
        return -1;
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int pulse_width;
    float distance;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000; // 1 second

    // Main loop
    while (!terminate) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Trigger pulse failed\n");
            continue; // Continue to the next iteration
        }

        // Read echo pulse width
        if (read_echo_pulse_width(&pulse_width) < 0) {
            fprintf(stderr, "Echo pulse width read failed\n");
            continue; // Continue to the next iteration
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Log distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Distance logging failed\n");
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

