// Log distance function
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(log_file, "%s, -1\n", timestamp);
        fflush(log_file);
        return -1;
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int pulse_width;
    float distance;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000; // 1 second

    // Main loop
    while (!terminate) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Trigger pulse failed\n");
            continue; // Continue to the next iteration
        }

        // Read echo pulse width
        if (read_echo_pulse_width(&pulse_width) < 0) {
            fprintf(stderr, "Echo pulse width read failed\n");
            continue; // Continue to the next iteration
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Log distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Distance logging failed\n");
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

