#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define DOOR_GPIO 18
#define DISTANCE_THRESHOLD 500 // 50 cm in mm
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_door(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int i2c_handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int i2c_handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read (0x%04X): %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *value = buf[0];
    return 0;
}

// Function to read a 16-bit word from a VL53L1X register
int vl53l1x_read_word(int i2c_handle, uint16_t reg, uint16_t *value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read (0x%04X): %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Software reset
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Check device ID
    uint8_t device_id;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &device_id) != 0) {
        fprintf(stderr, "Error: Could not read device ID.\n");
        return -1;
    }

    if (device_id != 0xEACC) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set ranging mode (example: short distance mode)
    if (vl53l1x_write_byte(i2c_handle, 0x0080, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode.\n");
        return -1;
    }

    // Start continuous ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    uint16_t range_status;
    uint16_t distance;

    // Check for data ready
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if (!(range_status & 0x01)) {
        fprintf(stderr, "Error: Data not ready.\n");
        return -1;
    }

    // Read distance
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    return (int)distance;
}

// Door control function
void control_door(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(DOOR_GPIO, 1); // Open door
    } else {
        gpioWrite(DOOR_GPIO, 0); // Close door
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(DOOR_GPIO, PI_OUTPUT);
    gpioWrite(DOOR_GPIO, 0); // Ensure door is initially closed

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_door(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    gpioWrite(DOOR_GPIO, 0); // Close door
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

