#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity factor for ±250 dps range
#define GYRO_SENSITIVITY 131.0

// I2C Bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
void init_mpu6050(int fd);
void read_gyro_data(int fd, float *x, float *y, float *z);
void signal_handler(int signal);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for reading");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
void init_mpu6050(int fd) {
    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        exit(EXIT_FAILURE);
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        exit(EXIT_FAILURE);
    }
}

// Read gyroscope data
void read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_regs(fd, GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return;
    }

    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

int main() {
    float x, y, z;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    init_mpu6050(i2c_fd);

    // Main loop
    while (program_running) {
        read_gyro_data(i2c_fd, &x, &y, &z);
        printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x, y, z);
        usleep(100000); // 100ms delay
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

