#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define GPIO chip
#define GPIOCHIP "gpiochip0"

// Define watering duration
#define WATERING_DURATION 5 // seconds

// Define polling interval
#define POLLING_INTERVAL 60 // seconds

// Define log file name
#define LOG_FILE "watering_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
void activate_relay(int relay_num);
void deactivate_relay(int relay_num);
void log_watering_cycle(int relay_num);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Setup GPIO pins
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        perror("Error getting GPIO line for relay 1");
        goto cleanup_chip;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        perror("Error getting GPIO line for relay 2");
        goto cleanup_line1;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        perror("Error getting GPIO line for relay 3");
        goto cleanup_line2;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        perror("Error getting GPIO line for relay 4");
        goto cleanup_line3;
    }

    ret = gpiod_line_request_output(relay1_line, "watering_system", 1); // Active-low
    if (ret < 0) {
        perror("Error requesting GPIO line for relay 1 as output");
        goto cleanup_line4;
    }

    ret = gpiod_line_request_output(relay2_line, "watering_system", 1); // Active-low
    if (ret < 0) {
        perror("Error requesting GPIO line for relay 2 as output");
        goto cleanup_line1;
    }

    ret = gpiod_line_request_output(relay3_line, "watering_system", 1); // Active-low
    if (ret < 0) {
        perror("Error requesting GPIO line for relay 3 as output");
        goto cleanup_line2;
    }

    ret = gpiod_line_request_output(relay4_line, "watering_system", 1); // Active-low
    if (ret < 0) {
        perror("Error requesting GPIO line for relay 4 as output");
        goto cleanup_line3;
    }

    return 0;

cleanup_line4:
    gpiod_line_release(relay4_line);
cleanup_line3:
    gpiod_line_release(relay3_line);
cleanup_line2:
    gpiod_line_release(relay2_line);
cleanup_line1:
    gpiod_line_release(relay1_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Activate relay
void activate_relay(int relay_num) {
    struct gpiod_line *line;

    switch (relay_num) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_num);
            return;
    }

    int ret = gpiod_line_set_value(line, 0); // Active-low
    if (ret < 0) {
        perror("Error setting relay value");
    }
}

// Deactivate relay
void deactivate_relay(int relay_num) {
    struct gpiod_line *line;

    switch (relay_num) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_num);
            return;
    }

    int ret = gpiod_line_set_value(line, 1); // Active-low
    if (ret < 0) {
        perror("Error setting relay value");
    }
}

// Log watering cycle
void log_watering_cycle(int relay_num) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s - Relay %d activated\n", timestamp, relay_num);
    fclose(fp);
}

// Cleanup GPIO resources
void cleanup(void) {
    printf("Cleaning up GPIO resources...\n");

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    printf("Cleanup complete.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Activate relays sequentially
        activate_relay(1);
        log_watering_cycle(1);
        sleep(WATERING_DURATION);
        deactivate_relay(1);

        activate_relay(2);
        log_watering_cycle(2);
        sleep(WATERING_DURATION);
        deactivate_relay(2);

        activate_relay(3);
        log_watering_cycle(3);
        sleep(WATERING_DURATION);
        deactivate_relay(3);

        activate_relay(4);
        log_watering_cycle(4);
        sleep(WATERING_DURATION);
        deactivate_relay(4);

        // Wait for the next polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

