#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int pin, int mode);
int set_pwm_frequency(int pin, int frequency);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received termination signal. Shutting down...");
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1; // Indicate failure
    }
    log_event("pigpio initialisation successful");
    return 0; // Indicate success
}

// Function to set GPIO mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d", pin, mode);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "GPIO %d mode set to %d", pin, mode);
    log_event(message);
    return 0; // Indicate success
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO %d to %d", pin, frequency);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "PWM frequency for GPIO %d set to %d", pin, frequency);
    log_event(message);
    return 0; // Indicate success
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle for GPIO %d to %d", pin, duty_cycle);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "PWM duty cycle for GPIO %d set to %d", pin, duty_cycle);
    log_event(message);
    return 0; // Indicate success
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set GPIO modes to output
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1; // Exit if mode setting fails
    }

    // Set PWM frequency for all relays
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1; // Exit if frequency setting fails
    }

    // Sunrise simulation
    for (int duty_cycle = 0; duty_cycle <= 255 && program_running; ++duty_cycle) {
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if PWM setting fails
            break;
        }
        gpioDelay(1000); // Wait for 1 second
    }

    // Turn off all relays
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
    log_event("Program terminated successfully");

    return 0;
}

