// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

// LED GPIO pin
#define LED_PIN      17

// Circular buffer size
#define BUFFER_SIZE  100

// Full-scale range: ±250 deg/s
#define GYRO_SENSITIVITY 131.0f

// Threshold for LED activation
#define THRESHOLD 250.0f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void update_led(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set sample rate divider
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set gyroscope full-scale range
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        if (who_am_i != 0x68) {
            fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", i2c_handle);
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t raw_x = (data[0] << 8) | data[1];
    int16_t raw_y = (data[2] << 8) | data[3];
    int16_t raw_z = (data[4] << 8) | data[5];

    // Convert to degrees/second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

