    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Store data in circular buffer
            gyro_buffer[buffer_index].timestamp = ts;
            gyro_buffer[buffer_index].x = x;
            gyro_buffer[buffer_index].y = y;
            gyro_buffer[buffer_index].z = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Update LED
            update_led(x, y, z);

            // Print data (optional)
            // printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_mpu6050() != 0) {
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        // Delay for 50ms (20Hz)
        gpioDelay(50000);
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

