static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z);
int log_data(float x, float y, float z);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mpu9250";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
        gpiod_line = NULL;
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[GYRO_REG_COUNT];
    uint8_t rx_buf[GYRO_REG_COUNT];
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = GYRO_REG_COUNT,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    // Build the transmit buffer with register addresses
    for (int i = 0; i < GYRO_REG_COUNT; i++) {
        tx_buf[i] = GYRO_REG_START + i;
    }

    // Assert chip select
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error performing SPI transfer: %s\n", strerror(errno));
        // De-assert chip select
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        }
        return -1;
    }

    // De-assert chip select
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    // Extract raw data
    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z) {
    *dps_x = (float)raw_x / GYRO_SCALE_FACTOR;
    *dps_y = (float)raw_y / GYRO_SCALE_FACTOR;
    *dps_z = (float)raw_z / GYRO_SCALE_FACTOR;
}

// Function to log data to file
int log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float dps_x, dps_y, dps_z;
    int retries;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
                convert_to_dps(raw_x, raw_y, raw_z, &dps_x, &dps_y, &dps_z);
                if (log_data(dps_x, dps_y, dps_z) == 0) {
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Log data failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "SPI read failed, retrying...\n");
            }
            retries++;
            usleep(10000); // Wait 10 ms before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping data point.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait for the next sample
    }

    fprintf(stderr, "Data acquisition stopped.\n");

    cleanup();

    return 0;
}

