int spi_init(int bus, int chip_select, int speed, int mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_circular_buffer(float x, float y, float z);
void check_stability(float x, float y, float z);
void blink_led(int gpio_pin, int duration_ms);
void signal_handler(int signum);
void cleanup();

// SPI initialization function
int spi_init(int bus, int chip_select, int speed, int mode) {
    char spi_device_path[20];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", bus, chip_select);

    int fd = open(spi_device_path, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_flags = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_flags = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_flags) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];

    // Read X axis
    tx_buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read command for X axis
    memset(rx_buf, 0, sizeof(rx_buf));
    if (spi_transfer(fd, tx_buf, rx_buf, 1) < 0) return -1;
    int16_t raw_x = (rx_buf[0] << 8) | rx_buf[1];
    *x = (float)raw_x / GYRO_SENSITIVITY;

    // Read Y axis
    tx_buf[0] = MPU6050_GYRO_YOUT_H | 0x80; // Read command for Y axis
    memset(rx_buf, 0, sizeof(rx_buf));
    if (spi_transfer(fd, tx_buf, rx_buf, 1) < 0) return -1;
    int16_t raw_y = (rx_buf[0] << 8) | rx_buf[1];
    *y = (float)raw_y / GYRO_SENSITIVITY;

    // Read Z axis
    tx_buf[0] = MPU6050_GYRO_ZOUT_H | 0x80; // Read command for Z axis
    memset(rx_buf, 0, sizeof(rx_buf));
    if (spi_transfer(fd, tx_buf, rx_buf, 1) < 0) return -1;
    int16_t raw_z = (rx_buf[0] << 8) | rx_buf[1];
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

