void add_to_circular_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to check for stability issues
void check_stability(float x, float y, float z) {
    if (fabs(x) > STABILITY_THRESHOLD || fabs(y) > STABILITY_THRESHOLD || fabs(z) > STABILITY_THRESHOLD) {
        blink_led(LED_GPIO, 500);
