    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO for LED control
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "stability_monitor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    float x, y, z;

    // Main loop
    while (1) {
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
