#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity);
void log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity);
void control_led(unsigned short proximity);
void signal_handler(int signal);

// I2C read register function with retries
int i2c_read_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    int retries = RETRY_COUNT;
    int result;

    buf[0] = reg;

    while (retries > 0) {
        if (write(fd, buf, 1) != 1) {
            perror("I2C write (register address) failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to us
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return buf[0];
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write register function with retries
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    int retries = RETRY_COUNT;
    int result;

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to us
            continue;
        }
        return 0; // Indicate success
    }

    fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Read sensor data function
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity) {
    int ambient_light_low, ambient_light_high, proximity_low, proximity_high;

    ambient_light_low = i2c_read_register(fd, AMBIENT_LIGHT_REG);
    ambient_light_high = i2c_read_register(fd, AMBIENT_LIGHT_REG + 1);
    proximity_low = i2c_read_register(fd, PROXIMITY_REG);
    proximity_high = i2c_read_register(fd, PROXIMITY_REG + 1);

    if (ambient_light_low == -1 || ambient_light_high == -1 || proximity_low == -1 || proximity_high == -1) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *ambient_light = (unsigned short)((ambient_light_high << 8) | ambient_light_low);
    *proximity = (unsigned short)((proximity_high << 8) | proximity_low);

    return 0;
}

// Log data function
void log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Control LED function
void control_led(unsigned short proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        gpiod_line_set_value(gpio_line, 1); // Set GPIO high
    } else {
        gpiod_line_set_value(gpio_line, 0); // Set GPIO low
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

int main() {
    unsigned short ambient_light, proximity;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (gpio_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "biometric_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            control_led(proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

