#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define X_REG 0x02
#define Y_REG 0x04
#define SENSITIVITY 200.0 // LSB/deg/s
#define SAMPLE_RATE 100.0 // Hz
#define SAMPLE_PERIOD (1.0 / SAMPLE_RATE) * 1000000.0 // microseconds
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
int read_register(int reg_addr, uint8_t *data);
int read_gyro_data(gyro_data_t *data);
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADXRS290
int read_register(int reg_addr, uint8_t *data) {
    char tx[2];
    char rx[2];

    tx[0] = reg_addr | 0x80; // Set read bit
    tx[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg_addr, result);
        return -1;
    }

    *data = rx[1];
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb;

    if (read_register(X_REG, &x_msb) != 0) return -1;
    if (read_register(X_REG + 1, &x_lsb) != 0) return -1;
    if (read_register(Y_REG, &y_msb) != 0) return -1;
    if (read_register(Y_REG + 1, &y_lsb) != 0) return -1;

    data->x_rate = (int16_t)((x_msb << 8) | x_lsb);
    data->y_rate = (int16_t)((y_msb << 8) | y_lsb);

    return 0;
}

// Function to log data to a file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    fprintf(fp, "%ld,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI with retry
    int reinit_attempts = 0;
    while (init_spi() != 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "SPI initialisation failed, retrying... (%d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
        gpioDelay(1000); // Wait 1 second before retrying
        reinit_attempts++;
    }

    if (spi_handle < 0) {
        fprintf(stderr, "Failed to initialise SPI after %d attempts. Exiting.\n", MAX_REINIT_ATTEMPTS);
        cleanup();
        return 1;
    }

    // Open data file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        cleanup();
        return 1;
    }
    fprintf(fp, "timestamp,X_rate,Y_rate\n"); // Write header

    // Set up signal handler
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }

        gpioDelay(SAMPLE_PERIOD); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

