#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION 2000 // milliseconds
#define SEISMIC_EVENT_DURATION 500 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int setup_callbacks();
int log_event();
void trigger_alert();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long last_event_time;
} SensorData;

SensorData sensor_data = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is initially LOW

    return 0;
}

// Function to set up callbacks for GPIO pins
int setup_callbacks() {
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 1\n");
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 2\n");
        return 1;
    }

    return 0;
}

// Function to log seismic events to a file
int log_event() {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
        free(timestamp);
        return 1;
    }
    free(timestamp);
    return 0;
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION); // Wait for alert duration
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio

    exit(0);
}

// Function to get the current time in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up callbacks
    if (setup_callbacks() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_value = gpioRead(SENSOR_1_PIN);
        int sensor2_value = gpioRead(SENSOR_2_PIN);

        if (sensor1_value == 1 && sensor2_value == 1) {
            unsigned long current_time = gpioTick();

            if (sensor_data.sensor1_state == 1 && sensor_data.sensor2_state == 1) {
                if (current_time - sensor_data.last_event_time >= SEISMIC_EVENT_DURATION * 1000) {
                    log_event();
                    trigger_alert();
                    sensor_data.last_event_time = current_time;
                }
            } else {
                sensor_data.sensor1_state = sensor1_value;
                sensor_data.sensor2_state = sensor2_value;
                sensor_data.last_event_time = current_time;
            }
        } else {
            sensor_data.sensor1_state = sensor1_value;
            sensor_data.sensor2_state = sensor2_value;
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

