#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define ANGULAR_VELOCITY_THRESHOLD 20.0
#define CIRCULAR_BUFFER_SIZE 100

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

gyro_data_t circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
int spi_read_register(int reg_addr, char *data);
int16_t combine_bytes(char low_byte, char high_byte);
float convert_to_dps(int16_t raw_data);
void add_to_circular_buffer(float angular_velocity);
float get_latest_angular_velocity();
void control_led(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// SPI Read Function
int spi_read_register(int reg_addr, char *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = (reg_addr << 1) | 0x01; // Read command
    tx_buf[1] = 0x00; // Dummy byte for reading

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Combine Bytes Function
int16_t combine_bytes(char low_byte, char high_byte) {
    return (int16_t)((high_byte << 8) | low_byte);
}

// Convert to DPS Function
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / 200.0;
}

// Circular Buffer Functions
void add_to_circular_buffer(float angular_velocity) {
    pthread_mutex_lock(&buffer_mutex);
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    circular_buffer[buffer_index].timestamp = ts;
    circular_buffer[buffer_index].angular_velocity = angular_velocity;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

float get_latest_angular_velocity() {
    pthread_mutex_lock(&buffer_mutex);
    int latest_index = (buffer_index - 1 + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE;
    float latest_velocity = circular_buffer[latest_index].angular_velocity;
    pthread_mutex_unlock(&buffer_mutex);
    return latest_velocity;
}

// LED Control Function
void control_led(float angular_velocity) {
    if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "ADXRS290 Gyroscope Data Acquisition Started\n");

    // Main loop
    while (!terminate) {
        char rate_xl_data, rate_xh_data;
        int16_t raw_rate_x;
