#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define the PWM frequency
#define PWM_FREQUENCY 100

// Define the PWM range
#define PWM_RANGE 255

// Global variable to store the fade duration
int fade_duration = 0;

// Function prototypes
int initialize_gpio();
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set the GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set the PWM frequency for each GPIO pin
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set the PWM range for each GPIO pin
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    return 0; // Indicate success
}

// Function to set the brightness of a lamp using PWM
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off over a specified duration
void fade_lamp(int gpio, int duration) {
    int steps = duration * 10; // Number of steps for the fade
    int delay_ms = duration * 1000 / steps; // Delay between steps in milliseconds

    for (int i = PWM_RANGE; i >= 0; i--) {
        set_lamp_brightness(gpio, i);
        gpioDelay(delay_ms);
    }
}

int main(int argc, char *argv[]) {
    // Check if the correct number of command-line arguments is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1; // Indicate an error
    }

    // Parse the fade duration from the command-line argument
    fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds.\n");
        return 1; // Indicate an error
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Indicate an error
    }

    printf("Smart Sunset Simulator started. Fade duration: %d seconds\n", fade_duration);

    // Fade the lamps sequentially
    printf("Fading Lamp 1...\n");
    fade_lamp(LAMP1_GPIO, fade_duration);

    printf("Fading Lamp 2...\n");
    fade_lamp(LAMP2_GPIO, fade_duration);

    printf("Fading Lamp 3...\n");
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Smart Sunset Simulator finished.\n");

    // Terminate the pigpio library
    gpioTerminate();

    return 0; // Indicate success
}

