#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define YELLOW2_PIN 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define state durations (in seconds)
#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variables for GPIO lines
struct gpiod_line *red_line = NULL;
struct gpiod_line *yellow_line = NULL;
struct gpiod_line *green_line = NULL;
struct gpiod_line *yellow2_line = NULL;

// Function prototypes
int initialize_gpio(void);
void set_gpio_state(int pin, int state);
void red_light(void);
void red_yellow_light(void);
void green_light(void);
void yellow_light(void);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up GPIO lines...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    struct gpiod_chip *chip;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    yellow2_line = gpiod_chip_get_line(chip, YELLOW2_PIN);

    if (!red_line || !yellow_line || !green_line || !yellow2_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(red_line, "traffic_light", 1); // Initial state: OFF (HIGH)
    if (ret < 0) {
        perror("Error requesting red GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(yellow_line, "traffic_light", 1); // Initial state: OFF (HIGH)
    if (ret < 0) {
        perror("Error requesting yellow GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(green_line, "traffic_light", 1); // Initial state: OFF (HIGH)
    if (ret < 0) {
        perror("Error requesting green GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(yellow2_line, "traffic_light", 1); // Initial state: OFF (HIGH)
    if (ret < 0) {
        perror("Error requesting yellow2 GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set GPIO state
void set_gpio_state(int pin, int state) {
    struct gpiod_line *line;
    int ret;

    switch (pin) {
        case RED_PIN:
            line = red_line;
            break;
        case YELLOW_PIN:
            line = yellow_line;
            break;
        case GREEN_PIN:
            line = green_line;
            break;
        case YELLOW2_PIN:
            line = yellow2_line;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", pin);
            return;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Error setting GPIO value");
    }
}

// Function to turn on red light
void red_light(void) {
    printf("Red light ON\n");
    set_gpio_state(RED_PIN, 0); // LOW
    set_gpio_state(YELLOW_PIN, 1); // HIGH
    set_gpio_state(GREEN_PIN, 1); // HIGH
    set_gpio_state(YELLOW2_PIN, 1); // HIGH
    sleep(RED_DURATION);
}

// Function to turn on red and yellow lights
void red_yellow_light(void) {
    printf("Red + Yellow light ON\n");
    set_gpio_state(RED_PIN, 0); // LOW
    set_gpio_state(YELLOW_PIN, 0); // LOW
    set_gpio_state(GREEN_PIN, 1); // HIGH
    set_gpio_state(YELLOW2_PIN, 1); // HIGH
    sleep(RED_YELLOW_DURATION);
}

// Function to turn on green light
void green_light(void) {
    printf("Green light ON\n");
    set_gpio_state(RED_PIN, 1); // HIGH
    set_gpio_state(YELLOW_PIN, 1); // HIGH
    set_gpio_state(GREEN_PIN, 0); // LOW
    set_gpio_state(YELLOW2_PIN, 1); // HIGH
    sleep(GREEN_DURATION);
}

// Function to turn on yellow light
void yellow_light(void) {
    printf("Yellow light ON\n");
    set_gpio_state(RED_PIN, 1); // HIGH
    set_gpio_state(YELLOW_PIN, 1); // HIGH
    set_gpio_state(GREEN_PIN, 1); // HIGH
    set_gpio_state(YELLOW2_PIN, 0); // LOW
    sleep(YELLOW_DURATION);
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    set_gpio_state(RED_PIN, 1); // Turn off all relays
    set_gpio_state(YELLOW_PIN, 1);
    set_gpio_state(GREEN_PIN, 1);
    set_gpio_state(YELLOW2_PIN, 1);

    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (yellow_line) {
        gpiod_line_release(yellow_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (yellow2_line) {
        gpiod_line_release(yellow2_line);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        red_light();
        red_yellow_light();
        green_light();
        yellow_light();
    }

    return 0;
}

