#include <string.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY 100 // milliseconds
#define TOUCH_STATUS_REG 0x00
#define TOUCH_STATUS_REG_MSB 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status(int *touch_status);
void toggle_relay(int touch_status);
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    log_message("GPIO initialized");
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("I2C open failed");
        return -1;
    }
    log_message("I2C initialized");
    return 0;
}

// Function to configure MPR121
int configure_mpr121() {
    char buf[2];
    int result;

    // Reset MPR121
    buf[0] = 0x80; // Reset register
    buf[1] = 0x63;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Stop mode
    buf[0] = 0x5E; // Stop mode register
    buf[1] = 0x00;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    buf[0] = 0x5D; // Electrode enable register
    buf[1] = 0x01;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 electrode enable failed");
        return -1;
    }

    // Touch threshold
    buf[0] = 0x41; // Touch threshold register
    buf[1] = TOUCH_THRESHOLD;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 touch threshold failed");
        return -1;
    }

    // Release threshold
    buf[0] = 0x42; // Release threshold register
    buf[1] = RELEASE_THRESHOLD;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 release threshold failed");
        return -1;
    }

    // Debounce
    buf[0] = 0x5B; // Debounce register
    buf[1] = 0x21;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 debounce failed");
        return -1;
    }

    // Charge time
    buf[0] = 0x5C; // Charge time register
    buf[1] = 0x0D;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 charge time failed");
        return -1;
    }

    // Run mode
    buf[0] = 0x5E; // Run mode register
    buf[1] = 0x0D;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_message("MPR121 run mode failed");
        return -1;
    }

    log_message("MPR121 configured");
    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int *touch_status) {
    char buf[1];
    char data[2];
    int result;

    buf[0] = TOUCH_STATUS_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        log_message("MPR121 touch status read failed");
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        log_message("MPR121 touch status read failed");
        return -1;
    }

    *touch_status = (data[1] << 8) | data[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay(int touch_status) {
    static int relay_state = 0; // 0 = OFF, 1 = ON

    if (touch_status & 0x01) { // Electrode 0 is touched
        gpioDelay(DEBOUNCE_DELAY); // Debounce delay
        relay_state = !relay_state; // Toggle relay state
        gpioWrite(RELAY_GPIO, relay_state);
        char message[100];
        snprintf(message, sizeof(message), "Relay toggled to %s", relay_state ? "ON" : "OFF");
        log_message(message);
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

int main() {
    int touch_status;

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            toggle_relay(touch_status);
        } else {
            log_message("Error reading touch status, retrying...");
        }
        gpioDelay(10); // Check every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
    fclose(log_file);

    log_message("Program terminated");

    return 0;
}

