int read_flame_sensor(int gpio_pin);
void activate_alarm(int buzzer_gpio, int led_gpio);
void deactivate_alarm(int buzzer_gpio, int led_gpio);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int gpio_pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpioRead(gpio_pin) == 0) {
            low_count++;
        }
        gpioDelay(50); // 50 ms delay
    }
    return (low_count == DEBOUNCE_COUNT) ? 0 : 1; // Return 0 if consistently low, 1 otherwise
}

// Function to activate the alarm (buzzer and LED)
void activate_alarm(int buzzer_gpio, int led_gpio) {
    gpioWrite(buzzer_gpio, 1); // Turn on buzzer
    gpioWrite(led_gpio, 1);    // Turn on LED
}

