    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame1_detected = read_flame_sensor(FLAME_SENSOR_1);
        int flame2_detected = read_flame_sensor(FLAME_SENSOR_2);

        if (flame1_detected == 0 || flame2_detected == 0) {
            activate_alarm(BUZZER, LED);
            log_event("Flame Detected");
        } else {
            deactivate_alarm(BUZZER, LED);
        }

        gpioDelay(100); // Check every 100 ms
    }

    // Cleanup
    deactivate_alarm(BUZZER, LED);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

