#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255

#define OBSTACLE_DISTANCE 20.0 // cm
#define OBSTACLE_SPEED 127.5 // 50% of PWM_RANGE

#define LOG_FILE "balance_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// PID parameters
double Kp = 1.0;
double Ki = 0.01;
double Kd = 0.1;

// Global variables for PID
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
double simulate_tilt_error();
double simulate_distance();
void stop_motors();

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <motor_command_file>\n", argv[0]);
        return 1;
    }

    const char *motor_command_file = argv[1];

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    FILE *fp = fopen(motor_command_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening motor command file: %s\n", motor_command_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    char motor_command;
    while (program_running && (motor_command = fgetc(fp)) != EOF) {
        if (motor_command == 'A') {
            // Simulate tilt error and distance
            double tilt_error = simulate_tilt_error();
            double distance = simulate_distance();

            // Obstacle avoidance
            if (distance < OBSTACLE_DISTANCE) {
                set_motor_speed(-OBSTACLE_SPEED, -OBSTACLE_SPEED);
            } else {
                // PID control
                double error = tilt_error;
                integral += error;
                double derivative = error - previous_error;
                double output = Kp * error + Ki * integral + Kd * derivative;

                // Clamp output to motor speed range
                int motor_a_speed = (int)output;
                int motor_b_speed = (int)output;

                if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
                if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
                if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
                if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

                set_motor_speed(motor_a_speed, motor_b_speed);
            }

            // Log data
            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        } else if (motor_command == 'B') {
            // Simulate tilt error and distance
            double tilt_error = simulate_tilt_error();
            double distance = simulate_distance();

            // Obstacle avoidance
            if (distance < OBSTACLE_DISTANCE) {
                set_motor_speed(-OBSTACLE_SPEED, -OBSTACLE_SPEED);
            } else {
                // PID control
                double error = tilt_error;
                integral += error;
                double derivative = error - previous_error;
                double output = Kp * error + Ki * integral + Kd * derivative;

                // Clamp output to motor speed range
                int motor_a_speed = (int)output;
                int motor_b_speed = (int)output;

                if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
                if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
                if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
                if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

                set_motor_speed(motor_a_speed, motor_b_speed);
            }

            // Log data
            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        } else {
            fprintf(stderr, "Invalid motor command: %c\n", motor_command);
            log_data(0.0, 0.0, 0, 0); // Log error
        }

        gpioDelay(50); // 50 ms delay
        previous_error = tilt_error;
    }

    fclose(fp);
    fclose(log_file);
    stop_motors();
    gpioTerminate();

    return 0;
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Stopping motors and exiting.\n");
        program_running = 0;
    }
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENB, PWM_FREQUENCY);
    gpioSetPWMrange(ENA, PWM_RANGE);
    gpioSetPWMrange(ENB, PWM_RANGE);

    // Enable motors (set ENA and ENB HIGH)
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    return 0;
}

void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, abs(motor_a_speed));
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA, abs(motor_a_speed));
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, abs(motor_b_speed));
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB, abs(motor_b_speed));
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, 0);
    }
}

void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

double simulate_tilt_error() {
    // Simulate tilt error between -10.0 and 10.0 degrees
    return ((double)rand() / RAND_MAX) * 20.0 - 10.0;
}

double simulate_distance() {
    // Simulate distance between 2.0 and 400.0 cm
    return ((double)rand() / RAND_MAX) * 398.0 + 2.0;
}

void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENA, 0);
    gpioPWM(ENB, 0);
}

