#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = 1.0;

// Function prototypes
void signal_handler(int signal);
int init_alsa(snd_pcm_t **pcm_handle);
int read_audio_data(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(const short *buffer, int buffer_size);
void map_rms_to_rgb(double rms, double sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    int rc;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    rc = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(rc));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    rc = snd_pcm_hw_params_any(*pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    rc = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format
    rc = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT);
    if (rc < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    rc = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &SAMPLE_RATE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set number of channels
    rc = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "Error setting number of channels: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set period size
    rc = snd_pcm_hw_params_set_period_size_near(*pcm_handle, hw_params, &PERIOD_SIZE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    rc = snd_pcm_hw_params(*pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Read audio data from ALSA
int read_audio_data(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int rc = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (rc == -EPIPE) {
        // Overrun occurred
        fprintf(stderr, "Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
        return -1;
    } else if (rc < 0) {
        fprintf(stderr, "Error reading audio data: %s\n", snd_strerror(rc));
        return -1;
    } else if (rc != buffer_size) {
        fprintf(stderr, "Short read, read %d frames\n", rc);
        return -1;
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Map RMS amplitude to RGB values
void map_rms_to_rgb(double rms, double sensitivity, int *red, int *green, int *blue) {
    // Normalize RMS to a range of 0.0 to 1.0
    double normalized_rms = rms / (double)32768.0; // Assuming 16-bit audio
    if (normalized_rms > 1.0) normalized_rms = 1.0;

    // Apply sensitivity scaling
    normalized_rms *= sensitivity;

    // Non-linear mapping (example: logarithmic)
    double log_rms = log10(normalized_rms + 1.0); // Avoid log(0)
    log_rms = log_rms / log10(2.0); // Scale to 0-1 range

    // Map to RGB (example: cool to warm transition)
    if (log_rms < 0.5) {
        // Cool colors (blue to green)
        *red   = (int)(255 * (1 - log_rms * 2));
        *green = (int)(255 * (log_rms * 2));
        *blue  = 0;
    } else {
        // Warm colors (green to red)
        *red   = (int)(255 * log_rms * 2);
        *green = (int)(255 * (1 - (log_rms - 0.5) * 2));
        *blue  = 0;
    }
}

// Set LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    short *audio_buffer = NULL;
    int red, green, blue;
    double rms;
    struct timeval start, end;
    double elapsed_time;
    int i;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0) {
                    fprintf(stderr, "Error: Sensitivity must be a positive value.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed. Using simulated audio.\n");
        // Allocate audio buffer for simulation
        audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
        if (audio_buffer == NULL) {
            fprintf(stderr, "Failed to allocate audio buffer.\n");
            cleanup();
            return 1;
        }
    } else {
        // Allocate audio buffer for ALSA
        audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
        if (audio_buffer == NULL) {
            fprintf(stderr, "Failed to allocate audio buffer.\n");
            cleanup();
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (pcm_handle != NULL) {
            // Read audio data
            if (read_audio_data(pcm_handle, audio_buffer, PERIOD_SIZE) != 0) {
                fprintf(stderr, "Error reading audio data, continuing...\n");
                continue;
            }
        } else {
            // Simulate audio data (sine wave)
            for (i = 0; i < PERIOD_SIZE; i++) {
                audio_buffer[i] = (short)(10000 * sin(2 * M_PI * i / PERIOD_SIZE));
            }
        }

        // Calculate RMS amplitude
        rms = calculate_rms(audio_buffer, PERIOD_SIZE);

        // Map RMS to RGB values
        map_rms_to_rgb(rms, sensitivity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay
        gettimeofday(&start, NULL);
        while (1) {
            gettimeofday(&end, NULL);
            elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;
            if (elapsed_time >= 0.01) break;
        }
    }

    // Cleanup
    free(audio_buffer);
    cleanup();

    return 0;
}

