#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define GPIO23 23

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define PWM period (in seconds)
#define PWM_PERIOD 1

// Define sunrise/sunset duration (in seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime and nighttime durations (in seconds)
#define DAYTIME_DURATION 21600
#define NIGHTTIME_DURATION 48960

// Define the number of relays
#define NUM_RELAYS 4

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_pin;
} gpio_line_t;

// Global variables
static volatile int running = 1;
static gpio_line_t relays[NUM_RELAYS];

// Function prototypes
int initialize_gpio(gpio_line_t *relays);
int set_relay_state(gpio_line_t *relay, int state);
int sunrise(gpio_line_t *relays);
int daytime(gpio_line_t *relays);
int sunset(gpio_line_t *relays);
int nighttime(gpio_line_t *relays);
void cleanup_gpio(gpio_line_t *relays);
void signal_handler(int sig);

// Function to initialize GPIO lines
int initialize_gpio(gpio_line_t *relays) {
    int gpio_pins[] = {GPIO17, GPIO27, GPIO22, GPIO23};
    int i;

    for (i = 0; i < NUM_RELAYS; i++) {
        relays[i].gpio_pin = gpio_pins[i];

        relays[i].chip = gpiod_chip_open_by_name(GPIOCHIP);
        if (!relays[i].chip) {
            fprintf(stderr, "Error opening GPIO chip for pin %d: %s\n", gpio_pins[i], strerror(errno));
            return -1;
        }

        relays[i].line = gpiod_chip_get_line(relays[i].chip, gpio_pins[i]);
        if (!relays[i].line) {
            fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", gpio_pins[i], strerror(errno));
            gpiod_chip_close(relays[i].chip);
            return -1;
        }

        if (gpiod_line_request_output(relays[i].line, "sunlight_simulator", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line for output for pin %d: %s\n", gpio_pins[i], strerror(errno));
            gpiod_chip_close(relays[i].chip);
            return -1;
        }
    }
    return 0;
}

// Function to set the state of a relay
int set_relay_state(gpio_line_t *relay, int state) {
    if (gpiod_line_set_value(relay->line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line value for pin %d: %s\n", relay->gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to simulate sunrise
int sunrise(gpio_line_t *relays) {
    int i, duty_cycle;
    time_t start_time = time(NULL);
    time_t current_time;

    printf("Starting sunrise...\n");

    while (time(NULL) - start_time < SUNRISE_DURATION && running) {
        current_time = time(NULL);
        duty_cycle = (int)(((float)(current_time - start_time) / SUNRISE_DURATION) * 100);

        for (i = 0; i < NUM_RELAYS; i++) {
            if (duty_cycle > 0) {
                if (set_relay_state(&relays[i], 0) < 0) return -1; // Active low
            } else {
                if (set_relay_state(&relays[i], 1) < 0) return -1; // Active low
            }
        }

        sleep(PWM_PERIOD);
    }

    printf("Sunrise complete.\n");
    return 0;
}

// Function to simulate daytime
int daytime(gpio_line_t *relays) {
    int i;
    printf("Starting daytime...\n");

    for (i = 0; i < NUM_RELAYS; i++) {
        if (set_relay_state(&relays[i], 0) < 0) return -1; // Active low
    }

    sleep(DAYTIME_DURATION);

    printf("Daytime complete.\n");
    return 0;
}

// Function to simulate sunset
int sunset(gpio_line_t *relays) {
    int i, duty_cycle;
    time_t start_time = time(NULL);
    time_t current_time;

    printf("Starting sunset...\n");

    while (time(NULL) - start_time < SUNSET_DURATION && running) {
        current_time = time(NULL);
        duty_cycle = 100 - (int)(((float)(current_time - start_time) / SUNSET_DURATION) * 100);

        for (i = 0; i < NUM_RELAYS; i++) {
            if (duty_cycle > 0) {
                if (set_relay_state(&relays[i], 0) < 0) return -1; // Active low
            } else {
                if (set_relay_state(&relays[i], 1) < 0) return -1; // Active low
            }
        }

        sleep(PWM_PERIOD);
    }

    printf("Sunset complete.\n");
    return 0;
}

// Function to simulate nighttime
int nighttime(gpio_line_t *relays) {
    int i;
    printf("Starting nighttime...\n");

    for (i = 0; i < NUM_RELAYS; i++) {
        if (set_relay_state(&relays[i], 1) < 0) return -1; // Active low
    }

    sleep(NIGHTTIME_DURATION);

    printf("Nighttime complete.\n");
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(gpio_line_t *relays) {
    int i;

    printf("Cleaning up GPIO resources...\n");

    for (i = 0; i < NUM_RELAYS; i++) {
        if (relays[i].line) {
            gpiod_line_release(relays[i].line);
        }
        if (relays[i].chip) {
            gpiod_chip_close(relays[i].chip);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Shutting down...\n", sig);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(relays) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (running) {
        if (sunrise(relays) < 0) break;
        if (daytime(relays) < 0) break;
        if (sunset(relays) < 0) break;
        if (nighttime(relays) < 0) break;
    }

    // Cleanup GPIO resources
    cleanup_gpio(relays);

    printf("Exiting.\n");
    return 0;
}

