#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to generate a timestamped filename for the video
int generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, "%Y%m%d_%H%M%S.h264", timeinfo);
    return 0;
}

// Function to execute the raspivid command
int execute_raspivid(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_SEC * 1000);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    return 0;
}

// Function to log the event to a file
int log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp, size_t timestamp_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, timestamp_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return 0;
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Create the video directory if it doesn't exist
    struct stat st = {0};
    if (stat(VIDEO_DIR, &st) == -1) {
        if (mkdir(VIDEO_DIR, 0777) == -1) {
            perror("mkdir");
            gpioTerminate();
            return 1;
        }
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    int last_trigger_time = 0; // Debouncing

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (active-low)
            int current_time = gpioTick();

            // Debouncing
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) {
                char filename[64];
                generate_filename(filename, sizeof(filename));

                char timestamp[32];
                get_iso8601_timestamp(timestamp, sizeof(timestamp));

                printf("Motion detected! Recording video: %s\n", filename);

                if (execute_raspivid(filename) == 0) {
                    printf("Video recorded successfully.\n");
                    if (log_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log event\n");
                    }
                } else {
                    fprintf(stderr, "Failed to execute raspivid\n");
                }

                last_trigger_time = current_time;
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

