#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_XOUT_H 0x43

// Sensitivity scale factor for ±250°/s range
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_degps(int16_t raw_value);
void log_data(double timestamp, double x, double y, double z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int result;

    while (retries > 0) {
        // Wake up the sensor
        result = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set sample rate divider to 125 Hz
        result = i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07);
        if (result != 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        result = i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw value to degrees per second
double convert_to_degps(int16_t raw_value) {
    return (double)raw_value / GYRO_SENSITIVITY;
}

// Log data to CSV file
void log_data(double timestamp, double x, double y, double z) {
    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    double x_degps, y_degps, z_degps;
    struct timespec ts;
    double timestamp;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            x_degps = convert_to_degps(x_raw);
            y_degps = convert_to_degps(y_raw);
            z_degps = convert_to_degps(z_raw);

            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

            // Log data
            log_data(timestamp, x_degps, y_degps, z_degps);
        } else {
            fprintf(stderr, "Failed to read gyro data. Attempting re-initialization...\n");
            init_mpu6050(); // Attempt to re-initialize the sensor
        }

        // Delay for 10 ms
        gpioDelay(10000);
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

