#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY_ZONE1 4
#define RELAY_ZONE2 17
#define RELAY_ZONE3 27
#define RELAY_ZONE4 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor(int zone);
void control_relay(int zone, int state);
void log_data(int zone, int moisture, int relay_state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(RELAY_ZONE1, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE2, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE3, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE4, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY_ZONE1, 1);
    gpioWrite(RELAY_ZONE2, 1);
    gpioWrite(RELAY_ZONE3, 1);
    gpioWrite(RELAY_ZONE4, 1);

    return 0; // Indicate success
}

// Function to read moisture sensor data (simulated)
int read_moisture_sensor(int zone) {
    // Seed the random number generator with the current time
    static int seeded = 0;
    if (!seeded) {
        srand(time(NULL));
        seeded = 1;
    }

    // Simulate moisture reading between 0 and 100
    return rand() % 101;
}

// Function to control the relay state
void control_relay(int zone, int state) {
    int gpio_pin;

    switch (zone) {
        case 1:
            gpio_pin = RELAY_ZONE1;
            break;
        case 2:
            gpio_pin = RELAY_ZONE2;
            break;
        case 3:
            gpio_pin = RELAY_ZONE3;
            break;
        case 4:
            gpio_pin = RELAY_ZONE4;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

    gpioWrite(gpio_pin, state);
}

// Function to log data to a file
void log_data(int zone, int moisture, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Zone: %d, Moisture: %d, Relay State: %d\n", timestamp, zone, moisture, relay_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Deactivate all relays (set to HIGH)
    gpioWrite(RELAY_ZONE1, 1);
    gpioWrite(RELAY_ZONE2, 1);
    gpioWrite(RELAY_ZONE3, 1);
    gpioWrite(RELAY_ZONE4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        for (int zone = 1; zone <= 4; zone++) {
            // Read moisture sensor
            int moisture = read_moisture_sensor(zone);

            // Determine relay state based on moisture level
            int relay_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1; // 0 = ON, 1 = OFF

            // Control the relay
            control_relay(zone, relay_state);

            // Log the data
            log_data(zone, moisture, relay_state);

            printf("Zone %d: Moisture = %d, Relay State = %d\n", zone, moisture, relay_state);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The signal handler will take care of cleanup
    return 0;
}

