#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm (4 meters)
#define MAX_PULSE_WIDTH (MAX_DISTANCE * 1000000.0 / SPEED_OF_SOUND) // us
#define TIMEOUT_US 100000      // 100 ms
#define TRIGGER_INTERVAL_US 200000 // 200 ms

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_valid = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge_callback(int gpio, int level, uint32_t tick);
void echo_falling_edge_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of the ECHO signal
void echo_rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    pulse_start = tick;
    pulse_valid = 1; // Indicate that a rising edge has been received
    pthread_mutex_unlock(&mutex);
}

// Callback function for falling edge of the ECHO signal
void echo_falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    pulse_end = tick;
    pulse_valid = 2; // Indicate that a falling edge has been received
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate an invalid pulse width
    }
    return (double)pulse_width * SPEED_OF_SOUND / 20000.0; // cm
}

// Function to log the distance to a file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%lf\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register callback functions
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(TRIGGER_INTERVAL_US);

        int pulse_width = 0;
        int timeout_count = 0;

        // Wait for a valid pulse
        while (pulse_valid != 2 && running) {
            gpioDelay(1000); // Check every 1 ms
            timeout_count++;
            if (timeout_count > TIMEOUT_US / 1000) {
                // Timeout: No echo received within the timeout period
                fprintf(stderr, "Timeout: No echo received\n");
                pulse_valid = 0; // Reset pulse_valid to avoid infinite loop
                break;
            }
        }

        if (pulse_valid == 2) {
            // Calculate pulse width, handling wrap-around
            if (pulse_end >= pulse_start) {
                pulse_width = pulse_end - pulse_start;
            } else {
                pulse_width = (0xFFFFFFFF - pulse_start) + pulse_end + 1; // Handle wrap-around
            }

            // Validate pulse width
            if (pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
                pulse_valid = 0; // Reset pulse_valid
            } else {
                // Calculate distance
                double distance = calculate_distance(pulse_width);

                if (distance > 0) {
                    // Log the distance
                    log_distance(distance);
                    printf("Distance: %.2f cm\n", distance);
                } else {
                    fprintf(stderr, "Invalid distance calculation\n");
                }
            }
            pulse_valid = 0; // Reset pulse_valid for next measurement
        }
    }

    // Cleanup
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    return 0;
}

