#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define SENSITIVITY 16384.0 // LSB/g for ±2g full scale

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure LIS3DH accelerometer
int config_lis3dh() {
    // 100 Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // ±2g full scale, high-resolution disabled
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (result == 6) {
            // Combine high and low bytes, convert to signed 16-bit integer
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert to g
            *x = (float)x_raw / SENSITIVITY;
            *y = (float)y_raw / SENSITIVITY;
            *z = (float)z_raw / SENSITIVITY;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate the buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    printf("Freefall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude < freefall_threshold) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                gpioDelay(500000); // Debounce delay (0.5 seconds)
            }

            if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(10000); // 10ms delay (100 Hz data rate)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

