#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f

// Global variables
int i2c_handle;
