    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG4: High-resolution mode, 12-bit left-justified
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
