// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Define alert duration
#define ALERT_DURATION 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int sensor_readings[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void update_circular_buffer(int new_reading);
int check_center_sensor();
void alert();
void move_forward();
void turn_left();
void turn_right();
void stop_robot();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to update the circular buffer
void update_circular_buffer(int new_reading) {
    sensor_readings[buffer_index] = new_reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the center sensor for consecutive readings
int check_center_sensor() {
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_readings[i] == 1) { // No line detected
            count++;
        }
    }
    return (count == BUFFER_SIZE);
}

// Function to trigger the alert
void alert() {
    gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Wait for ALERT_DURATION seconds
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
}

// Placeholder functions for motor control
void move_forward() {
    printf("Moving forward\n");
}

void turn_left() {
    printf("Turning left\n");
}

void turn_right() {
    printf("Turning right\n");
}

void stop_robot() {
    printf("Stopping robot\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize sensor readings buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sensor_readings[i] = 0; // Initialize to no line detected
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int center = read_sensor(CENTER_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        // Update circular buffer
        update_circular_buffer(left);
        update_circular_buffer(center);
        update_circular_buffer(right);

        // Line-following logic
        if (center == 0) { // Center sensor detects line
            move_forward();
        } else if (left == 0) { // Left sensor detects line
            turn_left();
        } else if (right == 0) { // Right sensor detects line
            turn_right();
        } else { // No sensor detects line
            stop_robot();
        }

        // Check for alert condition
        if (check_center_sensor()) {
            alert();
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

