#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *field_raw);
float convert_to_mT(int field_raw);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7210_address;
    int relay_gpio;
    float threshold_mt;
    int sample_interval_ms;
} Config;

Config config = {I2C_BUS, SI7210_ADDR, RELAY_GPIO, THRESHOLD_MT, SAMPLE_INTERVAL_MS};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int field_raw;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    while (!terminate) {
        if (read_sensor_data(&field_raw) == 0) {
            field_mT = convert_to_mT(field_raw);

            if (field_mT * 100 > config.threshold_mt * 100) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }

            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Field strength: %.2f mT, Relay state: %s", field_mT, relay_state ? "ON" : "OFF");
            log_event(log_message);
        } else {
            log_event("Failed to read sensor data");
        }

        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config.i2c_bus, config.si7210_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(config.relay_gpio, PI_OUTPUT);
    gpioWrite(config.relay_gpio, 0); // Initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor_data(int *field_raw) {
    int retries = 0;
    int field_raw_val = 0;
    int lsb, msb;

    // Start conversion
    if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
        log_event("Failed to start conversion");
        return 1;
    }

    // Wait for conversion to complete
    int poll_count = 0;
    while (i2cReadByteData(i2c_handle, 0xC1) != 0x00) {
        gpioDelay(1000); // 1 ms delay
        poll_count++;
        if (poll_count > MAX_POLL_ATTEMPTS) {
            log_event("Conversion timeout");
            return 1;
        }
    }

    // Read sensor data with retries
    for (retries = 0; retries < MAX_RETRIES; retries++) {
        lsb = i2cReadByteData(i2c_handle, 0xC0);
        if (lsb >= 0) break; // Success
        gpioDelay(1000); // 1 ms delay
    }

    if (lsb < 0) {
        log_event("Failed to read LSB");
        return 1;
    }

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        msb = i2cReadByteData(i2c_handle, 0xC1);
        if (msb >= 0) break; // Success
        gpioDelay(1000); // 1 ms delay
    }

    if (msb < 0) {
        log_event("Failed to read MSB");
        return 1;
    }

    field_raw_val = (msb << 8) | lsb;

    *field_raw = field_raw_val;
    return 0;
}

float convert_to_mT(int field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    printf("%s: %s\n", timestamp, message); // Also print to console
}

void signal_handler(int signal) {
    terminate = 1;
    log_event("Received SIGINT. Shutting down...");
}

void cleanup() {
    log_event("Cleaning up...");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
}

