#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
void log_event(const char *message);
void handle_client(int client_socket);
void relay_on();
void relay_off();
void signal_handler(int signum);

// Function to log events with timestamps
void log_event(const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        char command[100];
        strncpy(command, buffer, sizeof(command) - 1);
        command[bytes_received] = '\0'; // Ensure null termination

        // Normalize command (case-insensitive, trim whitespace)
        char normalized_command[100];
        strncpy(normalized_command, command, sizeof(normalized_command) - 1);
        for (int i = 0; normalized_command[i]; i++) {
            normalized_command[i] = tolower(normalized_command[i]);
        }
        for (int i = 0; i < strlen(normalized_command); i++) {
            if (normalized_command[i] == ' ') {
                normalized_command[i] = '\0';
                break;
            }
        }

        if (strcmp(normalized_command, "on") == 0) {
            relay_on();
            log_event("Relay ON");
        } else if (strcmp(normalized_command, "off") == 0) {
            relay_off();
            log_event("Relay OFF");
        } else {
            log_event("Invalid command");
            char error_message[] = "Invalid command\n";
            send(client_socket, error_message, strlen(error_message), 0);
        }
    } else if (bytes_received == 0) {
        log_event("Client disconnected");
    } else {
        perror("recv failed");
        log_event("Error receiving data");
    }

    close(client_socket);
}

// Function to turn the relay ON
void relay_on() {
    gpioWrite(RELAY_GPIO, 1); // Assuming HIGH activates the relay
    log_event("Relay ON");
}

// Function to turn the relay OFF
void relay_off() {
    gpioWrite(RELAY_GPIO, 0); // Assuming LOW deactivates the relay
    log_event("Relay OFF");
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");

        // Close server socket
        if (server_fd != -1) {
            close(server_fd);
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Turn off relay
        relay_off();

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

int main() {
    int client_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    relay_off(); // Ensure relay is off on startup

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        log_event("Socket listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_event("Server listening on port 5000");

    // Main loop to accept connections
    while (program_running) {
        if ((client_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            log_event("Socket accept failed");
            continue; // Continue listening for new connections
        }

        log_event("Client connected");
        handle_client(client_socket);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(server_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

