#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1500.0
#define POLLING_INTERVAL_MS 100

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int send_start_measurement(int handle);
int read_sensor_data(int handle, int16_t *raw_flow);
int validate_crc(int16_t raw_flow, uint8_t crc);
float convert_to_ml_min(int16_t raw_flow);
void control_relay(float flow1, float flow2);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Send start measurement command
    if (send_start_measurement(i2c_handle1) != 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    if (send_start_measurement(i2c_handle2) != 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure relay GPIO
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode. Exiting.\n");
        cleanup();
        return 1;
    }

    gpioWrite(RELAY_GPIO, 0); // Initialize relay to de-energized state

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Continuing without logging.\n");
    }

    // Main loop
    while (!terminate) {
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Read sensor data
        if (read_sensor_data(i2c_handle1, &raw_flow1) != 0) {
            fprintf(stderr, "Failed to read data from sensor 1. Skipping cycle.\n");
            flow1 = -1.0; // Indicate error
        } else {
            if (validate_crc(raw_flow1, crc8((uint8_t*)&raw_flow1, 2)) != 0) {
                fprintf(stderr, "CRC mismatch for sensor 1. Skipping cycle.\n");
                flow1 = -1.0; // Indicate error
            } else {
                flow1 = convert_to_ml_min(raw_flow1);
            }
        }

        if (read_sensor_data(i2c_handle2, &raw_flow2) != 0) {
            fprintf(stderr, "Failed to read data from sensor 2. Skipping cycle.\n");
            flow2 = -1.0; // Indicate error
        } else {
            if (validate_crc(raw_flow2, crc8((uint8_t*)&raw_flow2, 2)) != 0) {
                fprintf(stderr, "CRC mismatch for sensor 2. Skipping cycle.\n");
                flow2 = -1.0; // Indicate error
            } else {
                flow2 = convert_to_ml_min(raw_flow2);
            }
        }

        // Control relay
        control_relay(flow1, flow2);

        // Log data
        if (log_file != NULL) {
            log_flow_data(flow1, flow2);
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpio's delay function uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Send start measurement command
int send_start_measurement(int handle) {
    char cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, int16_t *raw_flow) {
    char buffer[3];
    int result = i2cReadDevice(handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Validate CRC
int validate_crc(int16_t raw_flow, uint8_t crc) {
    uint8_t crc_calculated = crc8((uint8_t*)&raw_flow, 2);
    if (crc_calculated != crc) {
        return -1;
    }
    return 0;
}

// Convert to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / SCALE_FACTOR;
}

// Control relay
void control_relay(float flow1, float flow2) {
    if (flow1 >= 0 && flow2 >= 0) { // Only control if both readings are valid
        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1); // Energize relay
        } else {
            gpioWrite(RELAY_GPIO, 0); // De-energize relay
        }
    }
}

// Log flow data
void log_flow_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

