#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define RAIN_DETECTED 0  // Rain sensor output is LOW when rain is detected
#define DRY 1            // Rain sensor output is HIGH when dry
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5
#define DRY_THRESHOLD_COUNT 3
#define DRY_THRESHOLD_MS (DRY_THRESHOLD_COUNT * POLL_INTERVAL_MS)

// Global variables
static volatile int running = 1;
static volatile int rain_detected = 0;
static volatile int dry_poll_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int enable, int in1, int in2);
int shutdown_gpio();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Ensure motor is initially stopped
    control_motor(0, 0, 0);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message(LOG_ERR, "Failed to read rain sensor");
        return -1;
    }
    return (sensor_value == RAIN_DETECTED) ? 1 : 0; // 1 for rain, 0 for dry
}

// Function to control the motor
int control_motor(int enable, int in1, int in2) {
    int result = gpioWrite(MOTOR_ENA_PIN, enable);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_ENA_PIN");
        return -1;
    }

    result = gpioWrite(MOTOR_IN1_PIN, in1);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_IN1_PIN");
        return -1;
    }

    result = gpioWrite(MOTOR_IN2_PIN, in2);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_IN2_PIN");
        return -1;
    }

    return 0;
}

// Function to shutdown GPIO pins
int shutdown_gpio() {
    log_message(LOG_INFO, "Shutting down GPIO");
    control_motor(0, 0, 0); // Stop the motor
    gpioTerminate();
    log_message(LOG_INFO, "GPIO terminated");
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    shutdown_gpio();
    closelog();
    exit(0);
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    // Main loop
    while (running) {
        int current_rain_status = read_rain_sensor();
        if (current_rain_status < 0) {
            log_message(LOG_ERR, "Error reading rain sensor, exiting");
            running = 0;
            continue;
        }

        if (current_rain_status && !rain_detected) {
            // Rising edge: rain detected
            log_message(LOG_INFO, "Rain detected!");
            rain_detected = 1;
            dry_poll_count = 0; // Reset dry poll count

            // Close the window
            if (control_motor(1, 1, 0) == 0) {
                log_message(LOG_INFO, "Motor started");
                gpioDelay(MOTOR_RUN_TIME_S * 1000000); // 5 seconds
                if (control_motor(0, 0, 0) == 0) {
                    log_message(LOG_INFO, "Motor stopped");
                } else {
                    log_message(LOG_ERR, "Failed to stop motor");
                }
            } else {
                log_message(LOG_ERR, "Failed to start motor");
            }
        } else if (!current_rain_status && rain_detected) {
            // Falling edge: rain stopped
            dry_poll_count++;
            if (dry_poll_count >= DRY_THRESHOLD_COUNT) {
                log_message(LOG_INFO, "Rain stopped, window closed");
                rain_detected = 0;
                dry_poll_count = 0; // Reset dry poll count
            }
        } else if (!current_rain_status && !rain_detected) {
            // No rain and not in the process of closing the window
            dry_poll_count++;
            if (dry_poll_count >= DRY_THRESHOLD_COUNT) {
                log_message(LOG_INFO, "Rain stopped, window closed");
                rain_detected = 0;
                dry_poll_count = 0; // Reset dry poll count
            }
        } else {
            // Still raining
            dry_poll_count = 0;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // 200 ms delay
    }

    // Shutdown GPIO
    shutdown_gpio();

    // Close syslog
    closelog();

    return 0;
}

