#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define BUTTON_LOCK_PIN 21
#define BUTTON_UNLOCK_PIN 22

// Define servo pulse widths
#define SERVO_UNLOCKED 1000
#define SERVO_LOCKED 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_pulse_width(int pulse_width);
int read_button(int button_pin);
void debounce(int button_pin);
void handle_signal(int signal);
void cleanup();

// Signal handler function
void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal, shutting down...\n");
        program_running = 0;
        cleanup();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_LOCK_PIN, PI_INPUT);
    gpioSetMode(BUTTON_UNLOCK_PIN, PI_INPUT);

    gpioSetPullUpDown(BUTTON_LOCK_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK_PIN, PI_PUD_UP);

    return 0;
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width to %d\n", pulse_width);
        return 1;
    }
    return 0;
}

// Read button state
int read_button(int button_pin) {
    return gpioRead(button_pin);
}

// Debounce button press
void debounce(int button_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

// Cleanup function to stop servo and terminate pigpio
void cleanup() {
    set_servo_pulse_width(0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (read_button(BUTTON_LOCK_PIN) == 0) {
            printf("Lock button pressed\n");
            if (set_servo_pulse_width(SERVO_LOCKED) != 0) {
                fprintf(stderr, "Error setting servo to locked position\n");
            }
            debounce(BUTTON_LOCK_PIN);
            while (read_button(BUTTON_LOCK_PIN) == 0 && program_running) {
                gpioDelay(1000); // Wait for button release
            }
        }

        // Check for unlock button press
        if (read_button(BUTTON_UNLOCK_PIN) == 0) {
            printf("Unlock button pressed\n");
            if (set_servo_pulse_width(SERVO_UNLOCKED) != 0) {
                fprintf(stderr, "Error setting servo to unlocked position\n");
            }
            debounce(BUTTON_UNLOCK_PIN);
            while (read_button(BUTTON_UNLOCK_PIN) == 0 && program_running) {
                gpioDelay(1000); // Wait for button release
            }
        }

        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0;
}

