#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void toggle_relay(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x80, 0x63);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (%d)\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure baseline filtering
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x05); // MHD = 0x05
    if (status < 0) {
        fprintf(stderr, "Error: MHD configuration failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5C, 0x05); // NHD = 0x05
    if (status < 0) {
        fprintf(stderr, "Error: NHD configuration failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5D, 0x01); // NCL = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: NCL configuration failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x0C); // FDL = 0x0C
    if (status < 0) {
        fprintf(stderr, "Error: FDL configuration failed (%d)\n", status);
        return -1;
    }

    // Set debounce
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x01); // Debounce = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: Debounce configuration failed (%d)\n", status);
        return -1;
    }

    // Set FFI/SFI/CDT
    status = i2cWriteByteData(i2c_handle, 0x2C, 0x01); // FFI = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: FFI configuration failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x2D, 0x01); // SFI = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: SFI configuration failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x2E, 0x01); // CDT = 0x01
    if (status < 0) {
        fprintf(stderr, "Error: CDT configuration failed (%d)\n", status);
        return -1;
    }

    // Set auto-config
    status = i2cWriteByteData(i2c_handle, 0x7B, 0x01); // Enable auto-config
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config enable failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x7C, 0x01); // Enable auto-config
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config enable failed (%d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x7D, 0x01); // Enable auto-config
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config enable failed (%d)\n", status);
        return -1;
    }

    // Enable electrodes
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x0C); // Enable exactly 12 electrodes
    if (status < 0) {
        fprintf(stderr, "Error: Electrode enable failed (%d)\n", status);
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    int status = i2cReadWordData(i2c_handle, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status (%d)\n", status);
        return -1;
    }
    *touch_status = (uint16_t)status;
    return 0;
}

// Function to toggle the relay
void toggle_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

int main() {
    uint16_t touch_status;
    int last_touch_state = 0; // 0 = no touch, 1 = touch
    int current_touch_state;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    toggle_relay(0); // Ensure relay is OFF on startup

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPR121 and relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            current_touch_state = (touch_status & 0x01) ? 1 : 0; // Check electrode 0

            if (current_touch_state && !last_touch_state) {
                // Rising edge detected on electrode 0
                toggle_relay(1); // Turn relay ON
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
                toggle_relay(0); // Turn relay OFF
            }

            last_touch_state = current_touch_state;
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50000); // Check every 50ms
    }

    // Cleanup
    toggle_relay(0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

