#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <stdarg.h>
#include <errno.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define SERVO_MIN_PULSE_WIDTH 1000 // microseconds
#define SERVO_MAX_PULSE_WIDTH 2000 // microseconds
#define SERVO_PERIOD 20000         // microseconds (50Hz)

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static int socket_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
void signal_handler(int sig);
int setup_gpio(void);
int setup_socket(void);
void *servo_thread(void *arg);
int parse_command(const char *command, int *angle);
int read_pir_sensor(void);
void send_response(int client_fd, const char *response);
void cleanup(void);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    syslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// GPIO setup function
int setup_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", GPIO_CHIP);
        return -1;
    }

    servo_line = gpiod_chip_get_line(gpio_chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line: %d", SERVO_PIN);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

