#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL_SEC 2
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void control_relay(float lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GROW_LIGHT_GPIO);
        return 1;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    int retries = 0;
    int raw_value;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, 0x20); // One-Time High-Resolution Mode
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d, retry %d\n", result, retries + 1);
            gpioDelay(100); // Wait before retrying
            retries++;
            continue;
        }

        gpioDelay(120); // Wait for conversion (at least 120ms)

        char buffer[2];
        result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device: %d, retry %d\n", result, retries + 1);
            gpioDelay(100); // Wait before retrying
            retries++;
            continue;
        }

        raw_value = (buffer[0] << 8) | buffer[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return 1; // Failure
}

// Control the grow light relay
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(GROW_LIGHT_GPIO, 1); // Activate relay
        printf("Lux: %.2f, Activating grow light\n", lux);
    } else {
        gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate relay
        printf("Lux: %.2f, Deactivating grow light\n", lux);
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_relay(lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

