#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <getopt.h>
#include <gpiod.h>
#include <math.h>

// Define GPIO pins
#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1000.0
#define DEFAULT_DURATION 200
#define DEFAULT_TARE_READINGS 10
#define DEFAULT_READINGS_PER_CYCLE 5

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *solenoid_line;
static double tare_offset = 0.0;
static double scale = DEFAULT_SCALE;
static double threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int readings_per_cycle = DEFAULT_READINGS_PER_CYCLE;
static int tare_readings = DEFAULT_TARE_READINGS;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hx711();
double average_readings(int num_readings, int (*read_func)());
void tare_load_cell();
double calculate_weight(double average_raw);
void activate_solenoid();
void signal_handler(int sig);
void cleanup();

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    // Wait for DOUT to go LOW
    int retries = 0;
    while (gpiod_line_get_value(dout_line) == 1 && retries < 3) {
        syslog(LOG_ERR, "DOUT pin is HIGH, waiting for data...");
        usleep(100000); // Wait 100ms
        retries++;
    }

    if (retries >= 3) {
        syslog(LOG_ERR, "Timeout waiting for DOUT to go LOW");
        return -1; // Indicate error
    }

    // Read 24 bits
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1); // Small delay
        data = data << 1;
        if (gpiod_line_get_value(dout_line)) {
            data++;
        }
        gpiod_line_set_value(sck_line, 0);
        usleep(1); // Small delay
    }

    // Send one additional clock pulse for Channel A / Gain 128
    gpiod_line_set_value(sck_line, 1);
    usleep(1);
    gpiod_line_set_value(sck_line, 0);
    usleep(1);

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to average readings
double average_readings(int num_readings, int (*read_func)()) {
    double sum = 0.0;
    for (int i = 0; i < num_readings; i++) {
        int raw = read_func();
        if (raw == -1) {
            syslog(LOG_ERR, "Error reading HX711, skipping this reading");
            return -1.0; // Indicate error
        }
        sum += raw;
        usleep(1000); // Small delay between readings
    }
    return sum / num_readings;
}

// Function to perform tare
void tare_load_cell() {
    double sum = 0.0;
    for (int i = 0; i < tare_readings; i++) {
        int raw = read_hx711();
        if (raw == -1) {
            syslog(LOG_ERR, "Error reading HX711 during tare, skipping this reading");
            return; // Indicate error
        }
        sum += raw;
        usleep(1000); // Small delay between readings
    }
    tare_offset = sum / tare_readings;
    syslog(LOG_INFO, "Tare offset: %lf", tare_offset);
}

// Function to calculate weight
double calculate_weight(double average_raw) {
    return (average_raw - tare_offset) / scale;
}

// Function to activate solenoid
void activate_solenoid() {
    syslog(LOG_INFO, "Activating solenoid for %d ms", duration);
    gpiod_line_set_value(solenoid_line, 1);
    usleep(duration * 1000); // Convert ms to microseconds
    gpiod_line_set_value(solenoid_line, 0);
    syslog(LOG_INFO, "Solenoid deactivated");
}

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0); // Ensure solenoid is off
        gpiod_line_release(solenoid_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:r:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'r':
                readings_per_cycle = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-r readings_per_cycle]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Error getting GPIO lines");
        cleanup();
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(dout_line, "weight_monitor", 0) < 0 ||
        gpiod_line_request_output(sck_line, "weight_monitor", 0) < 0 ||
        gpiod_line_request_output(solenoid_line, "weight_monitor", 0) < 0) {
        syslog(LOG_ERR, "Error requesting GPIO lines");
        cleanup();
        return 1;
    }

    // Set solenoid pin as output
    gpiod_line_set_direction(solenoid_line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);

    // Tare the load cell
    tare_load_cell();

    // Main loop
    while (!terminate) {
        double average_raw = average_readings(readings_per_cycle, read_hx711);
        if (average_raw == -1.0) {
            syslog(LOG_ERR, "Error reading HX711, skipping weight calculation");
            usleep(500000); // Wait 500ms
            continue;
        }

        double weight = calculate_weight(average_raw);
        syslog(LOG_INFO, "Weight: %lf grams", weight);

        if (weight > threshold) {
            activate_solenoid();
        }

        usleep(500000); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

