#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, exiting gracefully...");
    running = 0;
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    if (result == MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    }
    else
    {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// Callback function for when the MQTT client receives a message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message)
{
    if (message->payloadlen > 0)
    {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0)
        {
            gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            syslog(LOG_INFO, "Relay turned ON");
        }
        else if (strcmp(payload, "OFF") == 0)
        {
            gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            syslog(LOG_INFO, "Relay turned OFF");
        }
        else
        {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    }
    else
    {
        syslog(LOG_ERR, "Empty payload received on topic %s", message->topic);
    }
}

// Function to initialize the pigpio library and set the GPIO pin as output
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set initial state to LOW
    syslog(LOG_INFO, "GPIO %d initialized as output, initial state LOW", GPIO_PIN);
    return 0;
}

// Function to cleanup resources before exiting
void cleanup()
{
    syslog(LOG_INFO, "Cleaning up resources...");

    if (mosq)
    {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    closelog();
}

int main()
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0)
    {
        closelog();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq)
    {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    // Main loop to handle MQTT messages
    while (running)
    {
        rc = mosquitto_loop(mosq, -1, 1); // Blocking loop with a timeout
        if (rc != MOSQ_ERR_SUCCESS)
        {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            sleep(5);
            mosquitto_lib_init();
            mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
            if (!mosq)
            {
                syslog(LOG_ERR, "Failed to recreate mosquitto client instance");
                cleanup();
                return 1;
            }
            mosquitto_connect_callback_set(mosq, on_connect);
            mosquitto_message_callback_set(mosq, on_message);
            rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
            if (rc != MOSQ_ERR_SUCCESS)
            {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker: %s", mosquitto_strerror(rc));
                cleanup();
                return 1;
            }
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

