// Define the PWM range (20 ms = 20000 microseconds)
#define PWM_RANGE 20000

// Function to set the pulse width for a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (gpioServo(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error setting pulse width for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

