    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the PWM frequency for all servos
    if (gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Set the PWM range for all servos
    if (gpioSetPWMrange(SERVO1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(SERVO2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(SERVO3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(SERVO4_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(SERVO5_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    // Move each servo to its predefined position
    if (set_servo_pulse_width(SERVO1_PIN, SERVO1_PULSE_WIDTH) != 0 ||
        set_servo_pulse_width(SERVO2_PIN, SERVO2_PULSE_WIDTH) != 0 ||
        set_servo_pulse_width(SERVO3_PIN, SERVO3_PULSE_WIDTH) != 0 ||
        set_servo_pulse_width(SERVO4_PIN, SERVO4_PULSE_WIDTH) != 0 ||
        set_servo_pulse_width(SERVO5_PIN, SERVO5_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }

    // Wait for 3 seconds to allow the servos to reach their positions
    sleep(3);

    // Stop the PWM signals on all servos
    gpioServo(SERVO1_PIN, 0);
    gpioServo(SERVO2_PIN, 0);
    gpioServo(SERVO3_PIN, 0);
    gpioServo(SERVO4_PIN, 0);
    gpioServo(SERVO5_PIN, 0);

    // Release the pigpio library resources
    gpioTerminate();

    printf("Servo control complete\n");
    return 0;
}

