#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5

// Encoder B
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

#define TARGET_SPEED 50.0 // RPM
#define Kp 0.5
#define Ki 0.05
#define PWM_FREQUENCY 10000 // 10 kHz
#define SAMPLE_PERIOD 100 // ms
#define STALL_TIME 2000 // ms
#define MAX_PWM 255

volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;

// Function prototypes
void motor_a_forward(int pwm);
void motor_a_stop();
void motor_b_forward(int pwm);
void motor_b_stop();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count, double time_elapsed);
double calculate_error(double target_rpm, double actual_rpm);
double calculate_integral(double error, double *integral, double dt);
double calculate_derivative(double error, double previous_error, double dt);
double calculate_pwm(double error, double integral, double derivative, double kp, double ki, double dt);
void clamp_pwm(double *pwm);
void anti_windup(double *integral, double pwm);
void signal_handler(int signal);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);

    gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT);
    gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_UP);

    // Register interrupts for encoders
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A Phase A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A Phase B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B Phase A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B Phase B\n");
        gpioTerminate();
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);

    double integral_a = 0.0;
    double integral_b = 0.0;
    double previous_error_a = 0.0;
    double previous_error_b = 0.0;
    double pwm_a = 0.0;
    double pwm_b = 0.0;
    double rpm_a, rpm_b;
    time_t start_time, current_time;
    int stall_count_a = 0;
    int stall_count_b = 0;

    while (1) {
        time(&start_time);
        gpioDelay(SAMPLE_PERIOD * 1000); // Delay for 100ms
        time(&current_time);
        double time_elapsed = difftime(current_time, start_time);

        // Stall detection
        if (time_elapsed > 0.1) {
            rpm_a = calculate_rpm(encoder_a_count, time_elapsed);
            rpm_b = calculate_rpm(encoder_b_count, time_elapsed);

            if (fabs(rpm_a) < 0.1) {
                stall_count_a++;
                if (stall_count_a > STALL_TIME / 100) {
                    fprintf(stderr, "Warning: Motor A stalled!\n");
                    stall_count_a = 0; // Reset stall count
                }
            } else {
                stall_count_a = 0; // Reset stall count
            }

            if (fabs(rpm_b) < 0.1) {
                stall_count_b++;
                if (stall_count_b > STALL_TIME / 100) {
                    fprintf(stderr, "Warning: Motor B stalled!\n");
                    stall_count_b = 0; // Reset stall count
                }
            } else {
                stall_count_b = 0; // Reset stall count
            }
        }

        // PI controller for Motor A
        double error_a = calculate_error(TARGET_SPEED, calculate_rpm(encoder_a_count, time_elapsed));
        integral_a = calculate_integral(error_a, &integral_a, time_elapsed);
        anti_windup(&integral_a, pwm_a);
        double derivative_a = calculate_derivative(error_a, previous_error_a, time_elapsed);
        pwm_a = calculate_pwm(error_a, integral_a, derivative_a, Kp, Ki, time_elapsed);
        clamp_pwm(&pwm_a);
        motor_a_forward((int)pwm_a);
        previous_error_a = error_a;

        // PI controller for Motor B
        double error_b = calculate_error(TARGET_SPEED, calculate_rpm(encoder_b_count, time_elapsed));
        integral_b = calculate_integral(error_b, &integral_b, time_elapsed);
        anti_windup(&integral_b, pwm_b);
        double derivative_b = calculate_derivative(error_b, previous_error_b, time_elapsed);
        pwm_b = calculate_pwm(error_b, integral_b, derivative_b, Kp, Ki, time_elapsed);
        clamp_pwm(&pwm_b);
        motor_b_forward((int)pwm_b);
        previous_error_b = error_b;

        // Print RPM and PWM values
        printf("Motor A: RPM = %.2f, PWM = %.2f\n", calculate_rpm(encoder_a_count, time_elapsed), pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %.2f\n", calculate_rpm(encoder_b_count, time_elapsed), pwm_b);

        // Reset encoder counts
        encoder_a_count = 0;
        encoder_b_count = 0;
    }

    return 0;
}

void motor_a_forward(int pwm) {
    gpioWrite(MOTOR_A_DIR, 1); // Set direction to forward
    gpioPWM(MOTOR_A_PWM, pwm);
}

void motor_a_stop() {
    gpioWrite(MOTOR_A_DIR, 0); // Set direction to stop
    gpioPWM(MOTOR_A_PWM, 0);
}

void motor_b_forward(int pwm) {
    gpioWrite(MOTOR_B_DIR, 1); // Set direction to forward
    gpioPWM(MOTOR_B_PWM, pwm);
}

void motor_b_stop() {
    gpioWrite(MOTOR_B_DIR, 0); // Set direction to stop
    gpioPWM(MOTOR_B_PWM, 0);
}

void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_a = 0;
    static int last_b = 0;

    int a = gpioRead(ENCODER_A_PHASE_A);
    int b = gpioRead(ENCODER_A_PHASE_B);

    if (a != last_a || b != last_b) {
        if (a == b) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
        last_a = a;
        last_b = b;
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_a = 0;
    static int last_b = 0;

    int a = gpioRead(ENCODER_B_PHASE_A);
    int b = gpioRead(ENCODER_B_PHASE_B);

    if (a != last_a || b != last_b) {
        if (a == b) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
        last_a = a;
        last_b = b;
    }
}

double calculate_rpm(int encoder_count, double time_elapsed) {
    double revolutions = (double)encoder_count / 64.0; // 64 ticks per revolution
    double rpm = (revolutions / time_elapsed) * 60.0;
    return rpm;
}

double calculate_error(double target_rpm, double actual_rpm) {
    return target_rpm - actual_rpm;
}

double calculate_integral(double error, double *integral, double dt) {
    *integral += error * dt;
    return *integral;
}

double calculate_derivative(double error, double previous_error, double dt) {
    return (error - previous_error) / dt;
}

double calculate_pwm(double error, double integral, double derivative, double kp, double ki, double dt) {
    return kp * error + ki * integral + derivative;
}

void clamp_pwm(double *pwm) {
    if (*pwm < 0.0) {
        *pwm = 0.0;
    } else if (*pwm > MAX_PWM) {
        *pwm = MAX_PWM;
    }
}

void anti_windup(double *integral, double pwm) {
    if (pwm == 0.0) {
        *integral = 0.0;
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();
    exit(0);
}

