            rpm_b = calculate_rpm(encoder_b_count, time_elapsed);

            if (fabs(rpm_a) < 0.1) {
                stall_count_a++;
                if (stall_count_a > STALL_TIME / 100) {
                    fprintf(stderr, "Warning: Motor A stalled!\n");
                    stall_count_a = 0; // Reset stall count
                }
            } else {
                stall_count_a = 0; // Reset stall count
            }

            if (fabs(rpm_b) < 0.1) {
                stall_count_b++;
                if (stall_count_b > STALL_TIME / 100) {
                    fprintf(stderr, "Warning: Motor B stalled!\n");
                    stall_count_b = 0; // Reset stall count
                }
            } else {
                stall_count_b = 0; // Reset stall count
            }
        }

        // PI controller for Motor A
        double error_a = calculate_error(TARGET_SPEED, calculate_rpm(encoder_a_count, time_elapsed));
        integral_a = calculate_integral(error_a, &integral_a, time_elapsed);
        anti_windup(&integral_a, pwm_a);
        double derivative_a = calculate_derivative(error_a, previous_error_a, time_elapsed);
        pwm_a = calculate_pwm(error_a, integral_a, derivative_a, Kp, Ki, time_elapsed);
        clamp_pwm(&pwm_a);
        motor_a_forward((int)pwm_a);
        previous_error_a = error_a;

        // PI controller for Motor B
        double error_b = calculate_error(TARGET_SPEED, calculate_rpm(encoder_b_count, time_elapsed));
        integral_b = calculate_integral(error_b, &integral_b, time_elapsed);
        anti_windup(&integral_b, pwm_b);
        double derivative_b = calculate_derivative(error_b, previous_error_b, time_elapsed);
        pwm_b = calculate_pwm(error_b, integral_b, derivative_b, Kp, Ki, time_elapsed);
        clamp_pwm(&pwm_b);
        motor_b_forward((int)pwm_b);
        previous_error_b = error_b;

        // Print RPM and PWM values
        printf("Motor A: RPM = %.2f, PWM = %.2f\n", calculate_rpm(encoder_a_count, time_elapsed), pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %.2f\n", calculate_rpm(encoder_b_count, time_elapsed), pwm_b);

        // Reset encoder counts
        encoder_a_count = 0;
        encoder_b_count = 0;
    }

    return 0;
}

void motor_a_forward(int pwm) {
    gpioWrite(MOTOR_A_DIR, 1); // Set direction to forward
    gpioPWM(MOTOR_A_PWM, pwm);
}

void motor_a_stop() {
    gpioWrite(MOTOR_A_DIR, 0); // Set direction to stop
    gpioPWM(MOTOR_A_PWM, 0);
}

void motor_b_forward(int pwm) {
    gpioWrite(MOTOR_B_DIR, 1); // Set direction to forward
    gpioPWM(MOTOR_B_PWM, pwm);
}

void motor_b_stop() {
    gpioWrite(MOTOR_B_DIR, 0); // Set direction to stop
    gpioPWM(MOTOR_B_PWM, 0);
}

void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_a = 0;
    static int last_b = 0;

    int a = gpioRead(ENCODER_A_PHASE_A);
    int b = gpioRead(ENCODER_A_PHASE_B);

    if (a != last_a || b != last_b) {
        if (a == b) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
        last_a = a;
        last_b = b;
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_a = 0;
    static int last_b = 0;

    int a = gpioRead(ENCODER_B_PHASE_A);
    int b = gpioRead(ENCODER_B_PHASE_B);

    if (a != last_a || b != last_b) {
        if (a == b) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
        last_a = a;
        last_b = b;
    }
}

double calculate_rpm(int encoder_count, double time_elapsed) {
    double revolutions = (double)encoder_count / 64.0; // 64 ticks per revolution
    double rpm = (revolutions / time_elapsed) * 60.0;
    return rpm;
}

double calculate_error(double target_rpm, double actual_rpm) {
    return target_rpm - actual_rpm;
}

double calculate_integral(double error, double *integral, double dt) {
    *integral += error * dt;
    return *integral;
}

double calculate_derivative(double error, double previous_error, double dt) {
    return (error - previous_error) / dt;
}

double calculate_pwm(double error, double integral, double derivative, double kp, double ki, double dt) {
    return kp * error + ki * integral + derivative;
}

void clamp_pwm(double *pwm) {
    if (*pwm < 0.0) {
        *pwm = 0.0;
    } else if (*pwm > MAX_PWM) {
        *pwm = MAX_PWM;
    }
}

void anti_windup(double *integral, double pwm) {
    if (pwm == 0.0) {
        *integral = 0.0;
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();
    exit(0);
}

