#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_DUSK 50
#define LUX_DAWN 200
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_bh1750(int i2c_handle, float *lux);
void control_relay(int gpio_pin, int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(180); // Wait for measurement

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the relay (LED strip)
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    float lux;

    while (!terminate) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            log_data(lux, relay_state);

            if (lux < LUX_DUSK && relay_state == 0) {
                control_relay(GPIO_RELAY, 1);
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux > LUX_DAWN && relay_state == 1) {
                control_relay(GPIO_RELAY, 0);
                relay_state = 0;
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Error reading sensor, turning off relay\n");
            control_relay(GPIO_RELAY, 0);
            relay_state = 0;
            log_data(-1.0, relay_state); // Log error
        }

        gpioDelay(5000); // Poll every 5 seconds
    }

    // Cleanup
    control_relay(GPIO_RELAY, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

