#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int configure_gpio();
int read_touch_sensor();
int debounce_touch_sensor();
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to configure GPIO pins
int configure_gpio() {
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        return 1;
    }
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch_sensor() {
    int stable_high = 0;
    int stable_low = 0;
    int i;

    // Check for stable HIGH reading
    for (i = 0; i < DEBOUNCE_DELAY; i++) {
        if (read_touch_sensor() == 1) {
            stable_high++;
        }
        gpioDelay(1); // 1 ms delay
    }

    if (stable_high == DEBOUNCE_DELAY) {
        // Wait for the sensor to return LOW
        while (read_touch_sensor() == 1) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Check for stable LOW reading
        for (i = 0; i < DEBOUNCE_DELAY; i++) {
            if (read_touch_sensor() == 0) {
                stable_low++;
            }
            gpioDelay(1); // 1 ms delay
        }

        if (stable_low == DEBOUNCE_DELAY) {
            return 1; // Valid touch detected
        }
    }

    return 0; // No valid touch detected
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Function to log the relay state with an ISO-8601 timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Relay: %s\n", buffer, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Configure GPIO pins
    if (configure_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (debounce_touch_sensor()) {
            int new_state = toggle_relay();
            log_relay_state(new_state);
        }
        gpioDelay(10); // 10 ms delay to reduce CPU usage
    }

    return 0; // This line will never be reached due to the infinite loop
}

