#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FACTOR 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_TIME 1.0 // seconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
double calculate_lpm();
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
int setup();
void cleanup();

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Calculate LPM function
double calculate_lpm() {
    pthread_mutex_lock(&pulse_mutex);
    int current_pulse_count = pulse_count;
    pulse_count = 0; // Reset pulse count
    pthread_mutex_unlock(&pulse_mutex);

    return ((double)current_pulse_count / CALIBRATION_FACTOR) * 60.0;
}

// Control solenoid function
void control_solenoid(double lpm) {
    static int solenoid_state = 1; // 1 = open, 0 = closed

    if (lpm > LPM_THRESHOLD && solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Log data function
void log_data(double lpm, int solenoid_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    program_running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
