#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_DATA_PIN 23
#define DEFAULT_SCK_PIN 24
#define DEFAULT_TIMEOUT_MS 1000
#define DEFAULT_STABILIZATION_TIME_SEC 1

// Global variables
static int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int servo_pin = DEFAULT_SERVO_PIN;
static int data_pin = DEFAULT_DATA_PIN;
static int sck_pin = DEFAULT_SCK_PIN;
static int timeout_ms = DEFAULT_TIMEOUT_MS;
static int stabilization_time_sec = DEFAULT_STABILIZATION_TIME_SEC;
static int socket_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config();
int hx711_read();
double hx711_calibrate(double known_weight);
int servo_open();
int servo_close();
int servo_set_pulse_width(int pulse_width);
double weight_to_pulse_width(double weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int setup_socket();
void handle_client(int client_fd);
void cleanup();

// HX711 read function with timeout
int hx711_read() {
    int data = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout_count = 0;
    while (gpioRead(data_pin) == 1 && timeout_count < timeout_ms) {
        gpioDelay(1); // 1 ms delay
        timeout_count++;
    }

    if (timeout_count >= timeout_ms) {
        fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1 us pulse
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1 us pulse
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // 1 us pulse
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // 1 us pulse

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// HX711 calibration function
double hx711_calibrate(double known_weight) {
    double raw_value = hx711_read();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed during calibration\n");
        return -1.0; // Indicate error
    }
    calibration_factor = known_weight / raw_value;
    printf("Calibration factor: %f\n", calibration_factor);
    return calibration_factor;
}

// Servo open function
int servo_open() {
    if (gpioServo(servo_pin, 1500) != 0) { // Initial position
        fprintf(stderr, "Error: Failed to initialize servo\n");
        return -1;
    }
    return 0;
}

// Servo close function
int servo_close() {
    if (gpioServo(servo_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to disable servo\n");
        return -1;
    }
    return 0;
}

// Servo set pulse width function
int servo_set_pulse_width(int pulse_width) {
    if (gpioServo(servo_pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width\n");
        return -1;
    }
    return 0;
}

// Weight to pulse width mapping function
double weight_to_pulse_width(double weight) {
    // Assuming a linear relationship between weight and pulse width
    // You'll need to adjust these values based on your specific setup
    double min_weight = 0.0;  // Minimum weight to dispense
    double max_weight = 100.0; // Maximum weight to dispense
    double min_pulse_width = 1000; // Minimum pulse width
    double max_pulse_width = 2000; // Maximum pulse width

    double pulse_width = min_pulse_width + (weight - min_weight) * (max_pulse_width - min_pulse_width) / (max_weight - min_weight);
    return pulse_width;
}

// Log event function
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_t *timestamp = json_string(time_string());
    json_t *target = json_real(target_weight);
    json_t *actual = json_real(actual_weight);
    json_t *error = json_string(error_message);

    json_object_set_new(root, "timestamp", timestamp);
    json_object_set_new(root, "target_weight", target);
    json_object_set_new(root, "actual_weight", actual);
    json_object_set_new(root, "error", error);

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(2));

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", json_str);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
        json_decref(root);
        free(json_str);
        return -1;
    }

    json_decref(root);
    free(json_str);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Setup socket function
int setup_socket() {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(server_ip);
    address.sin_port = htons(server_port);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        close(socket_fd);
        return -1;
    }

    if (listen(socket_fd, 3) < 0) {
        perror("Error listening on socket");
        close(socket_fd);
        return -1;
    }

    printf("Listening on %s:%d\n", server_ip, server_port);
    return socket_fd;
}

// Handle client function
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_fd);
        return;
    }

    double target_weight;
    if (sscanf(buffer, "%lf", &target_weight) != 1) {
        fprintf(stderr, "Error: Invalid weight received\n");
        log_event(target_weight, -1.0, "Invalid weight received");
        close(client_fd);
        return;
    }

    printf("Received target weight: %f\n", target_weight);

    // Open servo
    if (servo_open() != 0) {
        log_event(target_weight, -1.0, "Failed to open servo");
        close(client_fd);
        return;
    }

    // Wait for stabilization
    sleep(stabilization_time_sec);

    // Read weight
    int raw_value = hx711_read();
    if (raw_value == -1) {
        log_event(target_weight, -1.0, "HX711 read failed");
        servo_close();
        close(client_fd);
        return;
    }

    double actual_weight = raw_value * calibration_factor;
    printf("Actual weight: %f\n", actual_weight);

    // Log event
    log_event(target_weight, actual_weight, NULL);

    // Send actual weight back to client
    char weight_str[20];
    snprintf(weight_str, sizeof(weight_str), "%f", actual_weight);
    if (send(client_fd, weight_str, strlen(weight_str), 0) < 0) {
        perror("Error sending data");
    }

    // Close servo
    if (servo_close() != 0) {
        fprintf(stderr, "Error: Failed to close servo\n");
    }

    close(client_fd);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Disable servo
    gpioServo(servo_pin, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file. Using defaults.");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            // Remove leading/trailing whitespace
            while (*key == ' ') key++;
            while (*value == ' ') value++;
            char *end = value + strlen(value) - 1;
            while (end > value && *end == ' ') end--;
            *(end + 1) = 0;

            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            } else if (strcmp(key, "data_pin") == 0) {
                data_pin = atoi(value);
            } else if (strcmp(key, "sck_pin") == 0) {
                sck_pin = atoi(value);
            } else if (strcmp(key, "timeout_ms") == 0) {
                timeout_ms = atoi(value);
            } else if (strcmp(key, "stabilization_time_sec") == 0) {
                stabilization_time_sec = atoi(value);
            }
        }
    }

    fclose(fp);
    printf("Configuration loaded:\n");
    printf("  Calibration Factor: %f\n", calibration_factor);
    printf("  Server IP: %s\n", server_ip);
    printf("  Server Port: %d\n", server_port);
    printf("  Servo Pin: %d\n", servo_pin);
    printf("  Data Pin: %d\n", data_pin);
    printf("  SCK Pin: %d\n", sck_pin);
    printf("  Timeout (ms): %d\n", timeout_ms);
    printf("  Stabilization Time (s): %d\n", stabilization_time_sec);
    return 0;
}

// Get current timestamp as a string
char* time_string() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Error: Failed to read configuration. Using defaults.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Setup socket
    socket_fd = setup_socket();
    if (socket_fd == -1) {
        fprintf(stderr, "Error: Socket setup failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Calibrate HX711
    printf("Calibrating HX711...\n");
    if (hx711_calibrate(100.0) == -1.0) {
        fprintf(stderr, "Error: HX711 calibration failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    struct sockaddr_in client_address;
    socklen_t client_address_len = sizeof(client_address);
    int client_fd;

    while (!terminate) {
        client_fd = accept(socket_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_fd < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_fd);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

