#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int debounce_time_ms = DEFAULT_DEBOUNCE_TIME;
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce(int touch_state);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, exiting gracefully...\n");
        running = 0;
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state
    return 0; // Indicate success
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce the touch sensor input
int debounce(int touch_state) {
    int stable_count = 0;
    int current_state = touch_state;

    for (int i = 0; i < 5; i++) {
        gpioDelay(debounce_time_ms * 1000); // Delay for debounce time
        if (gpioRead(TOUCH_SENSOR_PIN) == current_state) {
            stable_count++;
        } else {
            return 0; // Not stable yet
        }
    }

    return stable_count == 5; // Return 1 if stable for all 5 readings
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_time_ms = atoi(argv[2]);
            if (debounce_time_ms <= 0) {
                fprintf(stderr, "Invalid debounce time. Using default value.\n");
                debounce_time_ms = DEFAULT_DEBOUNCE_TIME;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch-controlled relay control started. Debounce time: %d ms\n", debounce_time_ms);

    int last_touch_state = 0; // Store the last known touch state

    // Main loop
    while (running) {
        int current_touch_state = read_touch_sensor();

        if (current_touch_state != last_touch_state) {
            if (debounce(current_touch_state)) {
                // Valid rising edge detected
                toggle_relay();
                log_relay_state(relay_state);
                last_touch_state = current_touch_state;
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

