#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INITIAL_ANGLE 90

volatile sig_atomic_t program_running = 1;
struct termios original_termios;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int angle = INITIAL_ANGLE;
    int pulse_width;
    struct termios new_termios;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Configure terminal for raw input
    new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0; // Read at least 0 characters
    new_termios.c_cc[VTIME] = 0; // Wait indefinitely

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    printf("Servo control. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");
    printf("Initial angle: %d\n", angle);

    while (program_running) {
        char input;
        if (read(STDIN_FILENO, &input, 1) > 0) {
            switch (input) {
                case '+':
                    angle += 10;
                    if (angle > MAX_ANGLE) {
                        angle = MAX_ANGLE;
                    }
                    break;
                case '-':
                    angle -= 10;
                    if (angle < MIN_ANGLE) {
                        angle = MIN_ANGLE;
                    }
                    break;
                case 'q':
                    program_running = 0;
                    break;
                default:
                    // Ignore other inputs
                    break;
            }

            // Calculate pulse width
            pulse_width = MIN_PULSE_WIDTH + (int)((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

            // Set servo pulse width
            gpioServo(SERVO_PIN, pulse_width);

            printf("Angle: %d, Pulse Width: %d\n", angle, pulse_width);
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }

    // Stop PWM
    gpioServo(SERVO_PIN, 0);

    // Restore terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &original_termios) != 0) {
        perror("tcsetattr");
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

