    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }
    return value;
}

// Function to count pulses with debouncing
void count_pulses() {
    static int last_value = 0;
    static struct timespec last_time;
    struct timespec current_time;
    int value = read_gpio();

    if (value < 0) {
        return; // Error already reported
    }

    if (value != last_value) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long time_diff_ns = (current_time.tv_sec - last_time.tv_sec) * 1000000000L + (current_time.tv_nsec - last_time.tv_nsec);

