    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = SAMPLE_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        count_pulses();

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        long elapsed_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000L + (end_time.tv_nsec - start_time.tv_nsec);

        if (elapsed_ns >= SAMPLE_INTERVAL_SEC * 1000000000) {
            double rpm = calculate_rpm();
            log_rpm(rpm);
            print_rpm(rpm);

            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

