#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define MAX_TOUCH_DURATION_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
int last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void failsafe();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        return 1;
    }

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading TOUCH_SENSOR_PIN\n");
        return -1; // Indicate an error
    }
    return value;
}

// Control the relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return 1;
    }
    return 0;
}

// Failsafe mechanism
void failsafe() {
    time_t current_time = time(NULL);
    if (last_touch_time != 0 && difftime(current_time, last_touch_time) > MAX_TOUCH_DURATION_S) {
        printf("Failsafe triggered: Touch sensor HIGH for more than %d seconds. Turning relay OFF.\n", MAX_TOUCH_DURATION_S);
        control_relay(0); // Turn relay OFF
        relay_state = 0; // Update relay state
        last_touch_time = 0; // Reset last touch time
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up and exiting...\n");
    control_relay(0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor and relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            break;
        }

        if (touch_state == 1) {
            // Touch detected
            if (last_touch_time == 0) {
                // First touch
                last_touch_time = time(NULL);
            }

            if (relay_state == 0) {
                // Toggle relay state
                relay_state = 1;
                if (control_relay(1) != 0) {
                    fprintf(stderr, "Error controlling relay, exiting.\n");
                    break;
                }
                printf("Relay toggled ON\n");
            }
        } else {
            // Touch released
            last_touch_time = 0; // Reset last touch time
            if (relay_state == 1) {
                // Turn relay OFF
                relay_state = 0;
                if (control_relay(0) != 0) {
                    fprintf(stderr, "Error controlling relay, exiting.\n");
                    break;
                }
                printf("Relay toggled OFF\n");
            }
        }

        failsafe(); // Check for failsafe condition

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for POLL_INTERVAL_MS milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

