#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PWM_FREQUENCY 1000  // Hz
#define PULSES_PER_LITER 450.0
#define Kp 1.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
double calculate_flow_rate(int pulse_count, double time_interval_s);
int calculate_pwm_duty_cycle(double error, double kp);
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
void log_data(double timestamp_ms, double flow_rate, int valve_position);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to calculate flow rate (L/min)
double calculate_flow_rate(int pulse_count, double time_interval_s) {
    return (double)pulse_count / PULSES_PER_LITER / time_interval_s * 60.0;
}

// Function to calculate PWM duty cycle
int calculate_pwm_duty_cycle(double error, double kp) {
    double pwm_value = kp * error;
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 255) {
        pwm_value = 255;
    }
    return (int)pwm_value;
}

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to log data to file
void log_data(double timestamp_ms, double flow_rate, int valve_position) {
    if (log_file != NULL) {
        fprintf(log_file, "%lf,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Setup function to initialize pigpio and GPIO pins
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strncmp(argv[1], "-t", 2) != 0) {
        fprintf(stderr, "Invalid argument format. Use -t <target_flow_rate>\n");
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1] + 2, &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running) {
        // Sample flow rate
        pulse_count = 0; // Reset pulse count
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
        int pulse_count_sampled = pulse_count;

        double flow_rate = calculate_flow_rate(pulse_count_sampled, (double)SAMPLE_INTERVAL_MS / 1000.0);

        // Calculate error
        double error = target_flow_rate - flow_rate;

        // Calculate PWM duty cycle
        int pwm_duty_cycle = calculate_pwm_duty_cycle(error, Kp);

        // Set PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, pwm_duty_cycle);

        // Log data
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        double timestamp_ms = (double)time(NULL) * 1000.0;

        log_data(timestamp_ms, flow_rate, pwm_duty_cycle);

        printf("Timestamp: %.0f ms, Flow Rate: %.2f L/min, Valve Position: %d\n", timestamp_ms, flow_rate, pwm_duty_cycle);

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Flow control system stopped.\n");
    return 0;
}

