    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strncmp(argv[1], "-t", 2) != 0) {
        fprintf(stderr, "Invalid argument format. Use -t <target_flow_rate>\n");
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1] + 2, &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running) {
        // Sample flow rate
        pulse_count = 0; // Reset pulse count
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
        int pulse_count_sampled = pulse_count;

        double flow_rate = calculate_flow_rate(pulse_count_sampled, (double)SAMPLE_INTERVAL_MS / 1000.0);

        // Calculate error
        double error = target_flow_rate - flow_rate;

        // Calculate PWM duty cycle
        int pwm_duty_cycle = calculate_pwm_duty_cycle(error, Kp);

        // Set PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, pwm_duty_cycle);

        // Log data
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        double timestamp_ms = (double)time(NULL) * 1000.0;

        log_data(timestamp_ms, flow_rate, pwm_duty_cycle);

        printf("Timestamp: %.0f ms, Flow Rate: %.2f L/min, Valve Position: %d\n", timestamp_ms, flow_rate, pwm_duty_cycle);

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Flow control system stopped.\n");
    return 0;
}

