#include <unistd.h>

// Define GPIO pins
#define RFID_PIN 8
#define BUTTON_PIN 22
#define LOCK1_PIN 17
#define LOCK2_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define RFID tag
const unsigned char valid_tag[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid(unsigned char *data);
int validate_tag(const unsigned char *tag);
int read_button();
void log_event(const char *event_type, const char *message);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid(unsigned char *data) {
    char tx_buf[10] = {0}; // Dummy data for reading
    char rx_buf[10];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 0) {
        log_event("RFID Read Failure", "SPI transfer failed");
        return -1; // SPI transfer failed
    }

    memcpy(data, rx_buf, 10);
    return 0; // Success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    for (int i = 0; i < 10; i++) {
        if (tag[i] != valid_tag[i]) {
            return 0; // Invalid tag
        }
    }
    return 1; // Valid tag
}

// Function to read button press
int read_button() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(50); // Debounce
    return (button_state == 0); // Active low
}

// Function to log events
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s: %s\n", timestamp, event_type, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s, Message: %s\n", event_type, message);
    }
}

// Function to unlock doors
void unlock_doors() {
    gpioWrite(LOCK1_PIN, 0); // LOW to unlock
    gpioWrite(LOCK2_PIN, 0);
    gpioDelay(5000); // 5 seconds
    lock_doors();
}

// Function to lock doors
void lock_doors() {
    gpioWrite(LOCK1_PIN, 1); // HIGH to lock
    gpioWrite(LOCK2_PIN, 1);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_event("System Shutdown", "Received signal, shutting down");
    lock_doors(); // Ensure doors are locked on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(RFID_PIN, PI_OUTPUT); // SPI CS
    gpioSetMode(BUTTON_PIN, PI_INPUT); // Button
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Internal pull-up
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        log_event("SPI Initialization Failure", "Failed to open SPI channel");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char rfid_data[10];
    int button_pressed = 0;

    printf("Two-Factor Authentication System Started\n");

    while (program_running) {
        // Read RFID tag
        if (read_rfid(rfid_data) == 0) {
            // Check for valid tag
            if (validate_tag(rfid_data)) {
                log_event("RFID Read", "Valid tag read");

                // Wait for button press
                while (!button_pressed && program_running) {
                    button_pressed = read_button();
                    gpioDelay(100); // Check every 100ms
                }

                if (button_pressed) {
                    log_event("Button Press", "Button pressed");
                    unlock_doors();
                    button_pressed = 0; // Reset button state
                } else {
                    log_event("Button Press", "Button press timeout");
                }
            } else {
                log_event("Invalid Tag", "Invalid RFID tag");
            }
        } else {
            log_event("RFID Read Failure", "Failed to read RFID tag");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up (should not reach here if signal handler works)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

