#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>
#include <errno.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1 // seconds

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// Encoder pulses per revolution
#define PULSES_PER_REV 600.0

// PWM frequency
#define PWM_FREQUENCY 100.0 // Hz

// Global variables (protected by mutexes)
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// GPIO chip
struct gpiod_chip *chip;

// GPIO lines
struct gpiod_line *motor1_ena_line;
struct gpiod_line *motor1_in1_line;
struct gpiod_line *motor1_in2_line;
struct gpiod_line *motor2_enb_line;
struct gpiod_line *motor2_in3_line;
struct gpiod_line *motor2_in4_line;
struct gpiod_line *encoder1_a_line;
struct gpiod_line *encoder1_b_line;
struct gpiod_line *encoder2_a_line;
struct gpiod_line *encoder2_b_line;

// Log file
FILE *log_file;

// Function prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
double calculate_rpm(int encoder_count);
double pid_control(double target_rpm, double current_rpm);
void set_motor_speed(int motor, double speed);
void log_data(double rpm1, double rpm2, double pid_output1, double p1, double i1, double d1, double pid_output2, double p2, double i2, double d2);
void signal_handler(int signal);
void cleanup();

// Encoder 1 interrupt handler
static void encoder1_interrupt_handler(struct gpiod_line *line, unsigned int event, void *user_data)
{
    (void)line; (void)event; (void)user_data; // unused parameters
    int b_value;
    int current_count;

    pthread_mutex_lock(&encoder1_mutex);
    current_count = encoder1_count;
    pthread_mutex_unlock(&encoder1_mutex);

    b_value = gpiod_line_get_value(encoder1_b_line);
    if (b_value < 0) {
        fprintf(stderr, "Error reading encoder1_b_line: %s\n", strerror(errno));
        return;
    }

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (b_value == 1) {
            current_count++;
        } else {
            current_count--;
        }
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (b_value == 0) {
            current_count++;
        } else {
            current_count--;
        }
    }

    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count = current_count;
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder 2 interrupt handler
static void encoder2_interrupt_handler(struct gpiod_line *line, unsigned int event, void *user_data)
{
    (void)line; (void)event; (void)user_data; // unused parameters
    int b_value;
    int current_count;

    pthread_mutex_lock(&encoder2_mutex);
    current_count = encoder2_count;
    pthread_mutex_unlock(&encoder2_mutex);

    b_value = gpiod_line_get_value(encoder2_b_line);
    if (b_value < 0) {
        fprintf(stderr, "Error reading encoder2_b_line: %s\n", strerror(errno));
        return;
    }

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (b_value == 1) {
            current_count++;
        } else {
            current_count--;
        }
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (b_value == 0) {
            current_count++;
        } else {
            current_count--;
        }
    }

    pthread_mutex_lock(&encoder2_mutex);
    encoder2_count = current_count;
    pthread_mutex_unlock(&encoder2_mutex);
}

int main()
{
    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines for motors
    motor1_ena_line = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1_line = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2_line = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb_line = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3_line = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4_line = gpiod_chip_get_line(chip, MOTOR2_IN4);

    if (!motor1_ena_line || !motor1_in1_line || !motor1_in2_line || !motor2_enb_line || !motor2_in3_line || !motor2_in4_line) {
        fprintf(stderr, "Error getting motor GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO lines for encoders
    encoder1_a_line = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b_line = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a_line = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b_line = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!encoder1_a_line || !encoder1_b_line || !encoder2_a_line || !encoder2_b_line) {
        fprintf(stderr, "Error getting encoder GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor1 ENA as output
    if (gpiod_line_request_output(motor1_ena_line, "motor1_ena", 0) < 0) {
        fprintf(stderr, "Error requesting motor1_ena as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor1 IN1 as output
    if (gpiod_line_request_output(motor1_in1_line, "motor1_in1", 0) < 0) {
        fprintf(stderr, "Error requesting motor1_in1 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor1 IN2 as output
    if (gpiod_line_request_output(motor1_in2_line, "motor1_in2", 0) < 0) {
        fprintf(stderr, "Error requesting motor1_in2 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor2 ENB as output
    if (gpiod_line_request_output(motor2_enb_line, "motor2_enb", 0) < 0) {
        fprintf(stderr, "Error requesting motor2_enb as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor2 IN3 as output
    if (gpiod_line_request_output(motor2_in3_line, "motor2_in3", 0) < 0) {
        fprintf(stderr, "Error requesting motor2_in3 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for motor2 IN4 as output
    if (gpiod_line_request_output(motor2_in4_line, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Error requesting motor2_in4 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for encoder1 A as input with edge events
    if (gpiod_line_request_input(encoder1_a_line, "encoder1_a") < 0) {
        fprintf(stderr, "Error requesting encoder1_a as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(encoder1_a_line, 0) < 0) {
        fprintf(stderr, "Error requesting rising edge events for encoder1_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(encoder1_a_line, 0) < 0) {
        fprintf(stderr, "Error requesting falling edge events for encoder1_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for encoder1 B as input
    if (gpiod_line_request_input(encoder1_b_line, "encoder1_b") < 0) {
        fprintf(stderr, "Error requesting encoder1_b as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for encoder2 A as input with edge events
    if (gpiod_line_request_input(encoder2_a_line, "encoder2_a") < 0) {
        fprintf(stderr, "Error requesting encoder2_a as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(encoder2_a_line, 0) < 0) {
        fprintf(stderr, "Error requesting rising edge events for encoder2_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(encoder2_a_line, 0) < 0) {
        fprintf(stderr, "Error requesting falling edge events for encoder2_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO line for encoder2 B as input
    if (gpiod_line_request_input(encoder2_b_line, "encoder2_b") < 0) {
        fprintf(stderr, "Error requesting encoder2_b as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up interrupt handlers for encoders
    if (gpiod_line_set_event_callback(encoder1_a_line, encoder1_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error setting event callback for encoder1_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_set_event_callback(encoder2_a_line, encoder2_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Error setting event callback for encoder2_a: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Create threads for encoder event monitoring
    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder1 thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder2 thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

