    // Determine direction and duty cycle
    int direction = (speed > 0) ? 1 : -1;
    speed = fabs(speed);

    // Calculate PWM period and duty cycle
    double period = 1.0 / PWM_FREQUENCY;
    double duty_cycle = speed / 100.0; // Assuming speed is a percentage

    // Set PWM
    if (gpiod_line_set_value(*ena_line_ptr, 1) < 0) {
        fprintf(stderr, "Error setting motor %d ENA high: %s\n", motor, strerror(errno));
        return;
