    } else if (motor == 2) {
        ena_line = motor2_enb_line;
        in1_line = motor2_in3_line;
        in2_line = motor2_in4_line;
        ena_line_ptr = &ena_line;
        in1_line_ptr = &in1_line;
        in2_line_ptr = &in2_line;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    // Determine direction and duty cycle
    int direction = (speed > 0) ? 1 : -1;
    speed = fabs(speed);

    // Calculate PWM period and duty cycle
    double period = 1.0 / PWM_FREQUENCY;
    double duty_cycle = speed / 100.0; // Assuming speed is a percentage

    // Set PWM
    if (gpiod_line_set_value(*ena_line_ptr, 1) < 0) {
        fprintf(stderr, "Error setting motor %d ENA high: %s\n", motor, strerror(errno));
        return;
    }

    if (direction > 0) {
        if (gpiod_line_set_value(*in1_line_ptr, 1) < 0) {
            fprintf(stderr, "Error setting motor %d IN1 high: %s\n", motor, strerror(errno));
            return;
        }
        if (gpiod_line_set_value(*in2_line_ptr, 0) < 0) {
            fprintf(stderr, "Error setting motor %d IN2 low: %s\n", motor, strerror(errno));
            return;
        }
    } else {
        if (gpiod_line_set_value(*in1_line_ptr, 0) < 0) {
            fprintf(stderr, "Error setting motor %d IN1 low: %s\n", motor, strerror(errno));
            return;
        }
        if (gpiod_line_set_value(*in2_line_ptr, 1) < 0) {
            fprintf(stderr, "Error setting motor %d IN2 high: %s\n", motor, strerror(errno));
            return;
        }
    }

    // Wait for the period
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = (long)(period * 1000000000 * (1 - duty_cycle));
    nanosleep(&sleep_time, NULL);

    // Set the line low for the remaining time
    if (gpiod_line_set_value(*ena_line_ptr, 0) < 0) {
        fprintf(stderr, "Error setting motor %d ENA low: %s\n", motor, strerror(errno));
        return;
    }

    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = (long)(period * 1000000000 * duty_cycle);
    nanosleep(&sleep_time, NULL);

    if (gpiod_line_set_value(*ena_line_ptr, 1) < 0) {
        fprintf(stderr, "Error setting motor %d ENA high: %s\n", motor, strerror(errno));
        return;
    }
}

// Log data to file
void log_data(double rpm1, double rpm2, double pid_output1, double p1, double i1, double d1, double pid_output2, double p2, double i2, double d2)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, rpm1, rpm2, p1, i1, d1, pid_output1, p2, i2, d2);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup()
{
    // Stop motors
    gpiod_line_set_value(motor1_ena_line, 0);
    gpiod_line_set_value(motor1_in1_line, 0);
    gpiod_line_set_value(motor1_in2_line, 0);
    gpiod_line_set_value(motor2_enb_line, 0);
    gpiod_line_set_value(motor2_in3_line, 0);
    gpiod_line_set_value(motor2_in4_line, 0);

    // Release GPIO lines
    gpiod_line_release(motor1_ena_line);
    gpiod_line_release(motor1_in1_line);
    gpiod_line_release(motor1_in2_line);
    gpiod_line_release(motor2_enb_line);
    gpiod_line_release(motor2_in3_line);
    gpiod_line_release(motor2_in4_line);
    gpiod_line_release(encoder1_a_line);
    gpiod_line_release(encoder1_b_line);
    gpiod_line_release(encoder2_a_line);
    gpiod_line_release(encoder2_b_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Destroy mutexes
    pthread_mutex_destroy(&encoder1_mutex);
    pthread_mutex_destroy(&encoder2_mutex);
}

