    }

    return 0;
}

// Activate a valve
int activate_valve(int gpio_pin, int duration_ms) {
    struct gpiod_line *line;
    if (gpio_pin == VALVE1_GPIO) {
        line = valve1_line;
    } else if (gpio_pin == VALVE2_GPIO) {
        line = valve2_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    log_event("Valve activated");

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    log_event("Valve deactivated");

    return 0;
}

// Deactivate a valve
int deactivate_valve(int gpio_pin) {
    struct gpiod_line *line;
    if (gpio_pin == VALVE1_GPIO) {
        line = valve1_line;
    } else if (gpio_pin == VALVE2_GPIO) {
        line = valve2_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    log_event("Valve deactivated");

    return 0;
}

// Log an event to the log file
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", buf, event);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Cleanup function to release GPIO lines and close the log file
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Deactivate valves
    deactivate_valve(VALVE1_GPIO);
    deactivate_valve(VALVE2_GPIO);

    // Release GPIO lines
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (!terminate) {
        // Activate Valve 1
        if (activate_valve(VALVE1_GPIO, VALVE1_DURATION) < 0) {
            fprintf(stderr, "Error activating Valve 1. Exiting.\n");
            break;
        }

        // Pause
        struct timespec ts;
        ts.tv_sec = VALVE1_PAUSE;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);

        // Activate Valve 2
        if (activate_valve(VALVE2_GPIO, VALVE2_DURATION) < 0) {
            fprintf(stderr, "Error activating Valve 2. Exiting.\n");
            break;
        }

        // Pause
        ts.tv_sec = VALVE2_PAUSE;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Cleanup and exit
    cleanup();
    log_event("Program terminated");
    return 0;
}

