#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELE_CURRENT 0x01
#define ELE_EN 0x20

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Set touch and release thresholds
    for (int i = 0x41; i <= 0x52; i += 2) {
        if (i2cWriteByteData(i2c_handle, i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold\n");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, i + 1, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold\n");
            return -1;
        }
    }

    // Set filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x5E, FILTER_CHARGE_TIME) < 0) {
        fprintf(stderr, "Error: Failed to set filter/charge time\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, ELE_CURRENT) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Run mode with ELE_EN=1
    if (i2cWriteByteData(i2c_handle, 0x2B, ELE_EN) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_level);
    printf("Relay toggled to %d\n", !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

