#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION 500 // milliseconds
#define RATE_LIMIT_DURATION 2000 // milliseconds
#define POLLING_INTERVAL 50 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *event_type, const char *message);
void motion_detected_callback(int gpio, int level, unsigned int tick, void *user_data);
void unlock_door();
void rate_limit();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log events with timestamps
void log_event(const char *event_type, const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    fprintf(log_file, "%s: %s\n", buf, message);
    fflush(log_file); // Ensure immediate write to file
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) { // Rising edge detected
        unsigned long current_time = gpioTick();

        if (current_time - last_unlock_time > RATE_LIMIT_DURATION) {
            char message[100];
            snprintf(message, sizeof(message), "Motion detected on GPIO %d", gpio);
            log_event("Motion Detected", message);
            unlock_door();
            last_unlock_time = current_time;
        } else {
            char message[100];
            snprintf(message, sizeof(message), "Rate limited on GPIO %d", gpio);
            log_event("Rate Limited", message);
        }
    }
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    log_event("Door Unlocked", "Door unlocked for 500ms");
    gpioDelay(UNLOCK_DURATION * 1000); // Delay for 500ms
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door Locked", "Door locked");
}

// Function to implement rate limiting (not strictly needed with the callback)
void rate_limit() {
    // This function is not strictly needed because the callback already handles rate limiting.
    // It's included for completeness in case the callback is removed.
    gpioDelay(RATE_LIMIT_DURATION * 1000); // Delay for 2 seconds
}

