    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback functions for motion detection
    gpioSetAlertFuncEx(PIR_SENSOR_1, motion_detected_callback, NULL);
    gpioSetAlertFuncEx(PIR_SENSOR_2, motion_detected_callback, NULL);

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Polling loop (can be removed if callbacks are sufficient)
        gpioDelay(POLLING_INTERVAL * 1000); // Poll every 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

