#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define minimum and maximum durations for motor steps (ms)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Global variable to signal program termination
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to generate a random integer within a given range
int generate_random(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to create a haptic pattern
void create_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        motor1_duties[i] = generate_random(0, PWM_RANGE);
        motor2_duties[i] = generate_random(0, PWM_RANGE);
        durations[i] = generate_random(MIN_DURATION, MAX_DURATION);
    }
}

// Function to play a haptic pattern
void play_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps && !shutdown_flag; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duties[i]);
        gpioPWM(MOTOR2_PIN, motor2_duties[i]);
        gpioDelay(durations[i] * 1000); // Convert ms to microseconds
    }
    // Stop the motors after the pattern is complete
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("GPIO resources released.\n");
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO pin modes to output
    if (set_gpio_mode(MOTOR1_PIN, PI_OUTPUT) != 0 || set_gpio_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Set PWM frequency
