    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO pin modes to output
    if (set_gpio_mode(MOTOR1_PIN, PI_OUTPUT) != 0 || set_gpio_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Allocate memory for the pattern data
    int *motor1_duties = NULL;
    int *motor2_duties = NULL;
    int *durations = NULL;
    int num_steps;

    while (!shutdown_flag) {
        // Generate a random number of steps for the pattern
        num_steps = generate_random(MIN_STEPS, MAX_STEPS);

        // Allocate memory for the pattern data
        motor1_duties = (int *)malloc(num_steps * sizeof(int));
        motor2_duties = (int *)malloc(num_steps * sizeof(int));
        durations = (int *)malloc(num_steps * sizeof(int));

        if (motor1_duties == NULL || motor2_duties == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup_gpio();
            return 1;
        }

        // Create the haptic pattern
        create_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Play the haptic pattern
        play_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Free the allocated memory
        free(motor1_duties);
        free(motor2_duties);
        free(durations);
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

