#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

// Threshold for weight to engage solenoid (in kg)
#define WEIGHT_THRESHOLD 10.0

// Number of readings for startup calibration
#define CALIBRATION_READINGS 100

// Timeout for HX711 read (in seconds)
#define HX711_TIMEOUT 0.5

// Global variables
double scale_factor = DEFAULT_SCALE;
double offset = DEFAULT_OFFSET;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_data(double weight);
void load_calibration_data();
void save_calibration_data();
void startup_calibration();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < (int)(HX711_TIMEOUT * 1000)) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }

    if (timeout >= (int)(HX711_TIMEOUT * 1000)) {
        fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return ((double)raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage the lock
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release the lock
    }
}

// Function to log data to a file
void log_data(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt. Using default values.\n");
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data in calibration.txt. Using default values.\n");
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for writing.\n");
        return;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Function to perform startup calibration
void startup_calibration() {
    int raw_value;
    double sum = 0.0;
    int i;

    printf("Starting startup calibration. Please ensure no weight is applied.\n");
    for (i = 0; i < CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed during calibration. Using previous offset.\n");
            return; // Exit calibration if read fails
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / CALIBRATION_READINGS;
    printf("Startup calibration complete. Offset: %.2f\n", offset);
    save_calibration_data();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Perform startup calibration if calibration.txt doesn't exist or is invalid
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL || fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        startup_calibration();
    }
    fclose(fp);

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open weight_log.txt\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);
            log_data(weight);
            printf("Weight: %.2f kg\n", weight);
        } else {
            fprintf(stderr, "Error: HX711 read failed. Skipping iteration.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Release the lock
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

