#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define MOTOR_SPEED 150
#define MOTOR_DURATION 5 // seconds

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_THRESHOLD 3
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void close_window();
void stop_window();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (low_count >= DEBOUNCE_THRESHOLD) ? 1 : 0; // 1 for rain, 0 for no rain
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, MOTOR_SPEED);
    gpioDelay(MOTOR_DURATION * 1000000); // Convert seconds to microseconds
    stop_window();
}

// Function to stop the window motor
void stop_window() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Window closed.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    stop_window();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Initialize PWM
    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000); // 1000 Hz
    gpioSetPWMrange(MOTOR_PWM_PIN, 255); // PWM range

    // Open log file
    log_file = fopen("/var/log/window_control.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started.");

    // Main loop
    while (running) {
        if (debounce_rain_sensor()) {
            log_event("Rain detected!");
            close_window();
        }
        gpioDelay(60 * 1000000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    stop_window();
    gpioTerminate();
    fclose(log_file);
    closelog();
    return 0;
}

