#define CALIBRATION_FACTOR 100.0

// Threshold weight in grams
#define WEIGHT_THRESHOLD 100.0

// Solenoid activation duration in seconds
#define SOLENOID_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold GPIO pin configurations
typedef struct {
    int dt_pin;
    int sck_pin;
    int solenoid_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(HX711_DT, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting HX711_DT as input\n");
        return 1;
    }
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting HX711_SCK as output\n");
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting SOLENOID_PIN as output\n");
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off
    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioWrite(HX711_SCK, 0);
    while (gpioRead(HX711_DT) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1);
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

