    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring stock level... Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        float weight = (float)raw_value / CALIBRATION_FACTOR;

        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold! Activating solenoid.\n");
            activate_solenoid();
            log_event("Solenoid activated due to low stock.");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

