#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file and log file
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 5.0

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Global variables
double calibration_factor = 1.0; // Default calibration factor
FILE *log_file = NULL;
FILE *calibration_file = NULL;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void calibrate_load_cell();
void control_solenoid(int state);
void log_event(double weight);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 100000) {
        gpioDelay(1); // 1 ms delay
        timeout++;
        if (timeout > 100000) {
            fprintf(stderr, "Error: HX711 data line timeout.\n");
            return -1; // Indicate error
        }
    }

    if (timeout >= 100000) return -1; // Timeout occurred

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Pulse the clock pin 1 more time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return;
    }

    printf("Reading raw value... Please wait.\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    // Save calibration factor to file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }

    fprintf(calibration_file, "%lf", calibration_factor);
    fclose(calibration_file);
}

// Function to control the solenoid
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log events to file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
        return;
    }

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fclose(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate(); // Terminate pigpio
    if (calibration_file != NULL) fclose(calibration_file);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration factor from file
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        printf("Calibration file not found. Starting calibration.\n");
        calibrate_load_cell();
        if (calibration_factor == 1.0) {
            fprintf(stderr, "Error: Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
    } else {
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error: Could not read calibration factor from file. Starting calibration.\n");
            fclose(calibration_file);
            calibrate_load_cell();
            if (calibration_factor == 1.0) {
                fprintf(stderr, "Error: Calibration failed. Exiting.\n");
                gpioTerminate();
                return 1;
            }
        } else {
            printf("Calibration factor loaded: %lf\n", calibration_factor);
            fclose(calibration_file);
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read from HX711. Retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight exceeds threshold. Activating solenoid.\n");
            log_event(weight);
            control_solenoid(1); // Activate solenoid
            gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Wait for activation time
            control_solenoid(0); // Deactivate solenoid
            printf("Solenoid deactivated.\n");
        }

        gpioDelay(1000); // Delay between readings
    }

    return 0;
}

