// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
int control_relay(int state);
int log_event(int relay_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
}

// Cleanup function
void cleanup(void) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request sensor line as input
    if (gpiod_line_request_input(sensor_line, "sensor") < 0) {
        perror("Error requesting sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    // Request relay line as output
    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Error requesting relay line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Error setting relay value");
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(int relay_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s Relay: %s\n", buf, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int relay_state = 0; // Initial relay state: OFF
    int last_sensor_value = 1; // Initialize to a non-activated state

    printf("Monitoring sensor and controlling relay. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        // Debounce and toggle relay on obstacle detection
        if (sensor_value == 0 && last_sensor_value == 1) {
            relay_state = !relay_state; // Toggle relay state
            if (control_relay(relay_state) < 0) {
                fprintf(stderr, "Error controlling relay, exiting.\n");
                break;
            }
            if (log_event(relay_state) < 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_sensor_value = sensor_value;
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        if (initialize_gpio() < 0) {
            fprintf(stderr, "GPIO re-initialization failed. Exiting.\n");
            break;
        }

        // Small delay to avoid busy-waiting
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

