#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define buzzer activation time (in milliseconds)
#define BUZZER_DURATION 2000

// Global variables for GPIO lines and chip
struct gpiod_chip *gpio_chip;
struct gpiod_line *pir_line_1, *pir_line_2, *buzzer_line;
FILE *log_file;

// Function prototypes
int setup_gpio();
int read_pir_sensor(int gpio_pin);
int activate_buzzer(int gpio_pin, int duration_ms);
int log_motion_event(int gpio_pin);
void signal_handler(int signal);

// Function to format timestamp
char* format_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%d %H:%M:%S", tm_info);
    return timestamp_str;
}

// Function to setup GPIO lines
int setup_gpio() {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get PIR sensor lines
    pir_line_1 = gpiod_chip_get_line(gpio_chip, PIR_SENSOR_1);
    if (!pir_line_1) {
        perror("Error getting PIR sensor 1 line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    pir_line_2 = gpiod_chip_get_line(gpio_chip, PIR_SENSOR_2);
    if (!pir_line_2) {
        perror("Error getting PIR sensor 2 line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line_1);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line_1);
        gpiod_line_release(pir_line_2);
        return -1;
    }

    // Request PIR sensor lines as input
    if (gpiod_line_request_input(pir_line_1, "motion_detector") < 0) {
        perror("Error requesting PIR sensor 1 line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line_1);
        gpiod_line_release(pir_line_2);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    if (gpiod_line_request_input(pir_line_2, "motion_detector") < 0) {
        perror("Error requesting PIR sensor 2 line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line_1);
        gpiod_line_release(pir_line_2);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    // Request buzzer line as output
    if (gpiod_line_request_output(buzzer_line, "motion_detector", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line_1);
        gpiod_line_release(pir_line_2);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Function to read PIR sensor value
int read_pir_sensor(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == PIR_SENSOR_1) {
        line = pir_line_1;
    } else if (gpio_pin == PIR_SENSOR_2) {
        line = pir_line_2;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading PIR sensor value");
        return -1;
    }

    return value;
}

// Function to activate buzzer
int activate_buzzer(int gpio_pin, int duration_ms) {
    struct gpiod_line *line;

    line = buzzer_line;

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting buzzer value");
        return -1;
    }

    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error clearing buzzer value");
        return -1;
    }

    return 0;
}

// Function to log motion event
int log_motion_event(int gpio_pin) {
    char timestamp_str[20];
    char log_message[100];

    format_timestamp(timestamp_str, sizeof(timestamp_str));

    snprintf(log_message, sizeof(log_message), "%s - Motion detected on GPIO %d\n", timestamp_str, gpio_pin);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s", log_message) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Release GPIO resources
    if (pir_line_1) {
        gpiod_line_release(pir_line_1);
    }
    if (pir_line_2) {
        gpiod_line_release(pir_line_2);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed.\n");
        fclose(log_file);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int pir1_value = read_pir_sensor(PIR_SENSOR_1);
        int pir2_value = read_pir_sensor(PIR_SENSOR_2);

        if (pir1_value < 0 || pir2_value < 0) {
            fprintf(stderr, "Error reading PIR sensors.\n");
            break; // Exit loop on error
        }

        if (pir1_value == 1) {
            printf("Motion detected on PIR sensor 1\n");
            if (activate_buzzer(BUZZER_PIN, BUZZER_DURATION) < 0) {
                fprintf(stderr, "Error activating buzzer.\n");
                break; // Exit loop on error
            }
            if (log_motion_event(PIR_SENSOR_1) < 0) {
                fprintf(stderr, "Error logging motion event.\n");
                break; // Exit loop on error
            }
        }

        if (pir2_value == 1) {
            printf("Motion detected on PIR sensor 2\n");
            if (activate_buzzer(BUZZER_PIN, BUZZER_DURATION) < 0) {
                fprintf(stderr, "Error activating buzzer.\n");
                break; // Exit loop on error
            }
            if (log_motion_event(PIR_SENSOR_2) < 0) {
                fprintf(stderr, "Error logging motion event.\n");
                break; // Exit loop on error
            }
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup (in case the loop breaks due to an error)
    signal_handler(SIGTERM); // Call the signal handler to clean up

    return 0;
}

