#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO chip and line names
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE "gpio18"

// Default duration (seconds)
#define DEFAULT_DURATION 60

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int duration = DEFAULT_DURATION;

// Function prototypes
int read_config_file(const char *filename);
int validate_duration(int duration);
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int activate_valve(struct gpiod_line *line);
int deactivate_valve(struct gpiod_line *line);
void signal_handler(int sig);
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
}

// Function to read the configuration file
int read_config_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line_buf[256];
    if (fgets(line_buf, sizeof(line_buf), fp) == NULL) {
        fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the line
    char *key = strtok(line_buf, "=");
    char *value = strtok(NULL, "\n");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Error parsing config file: Invalid format\n");
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error parsing config file: Invalid key\n");
        return -1;
    }

    char *endptr;
    duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' || errno == ERANGE) {
        fprintf(stderr, "Error parsing config file: Invalid duration value\n");
        return -1;
    }

    if (!validate_duration(duration)) {
        fprintf(stderr, "Error: Duration out of range (1-3600 seconds)\n");
        return -1;
    }

    return 0;
}

// Function to validate the duration
int validate_duration(int duration) {
    return (duration >= 1 && duration <= 3600);
}

// Function to setup GPIO
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, 18); // GPIO18 (BCM)
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", GPIO_LINE);
        gpiod_chip_close(*chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to activate the valve
int activate_valve(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line high: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve activated for %d seconds\n", duration);
    return 0;
}

// Function to deactivate the valve
int deactivate_valve(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve deactivated\n");
    return 0;
}

// Function to cleanup GPIO resources
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration file
    if (read_config_file(CONFIG_FILE) < 0) {
        fprintf(stderr, "Using default duration: %d seconds\n", DEFAULT_DURATION);
        duration = DEFAULT_DURATION;
    }

    // Setup GPIO
    if (setup_gpio(&chip, &line) < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Activate valve
    if (activate_valve(line) < 0) {
        fprintf(stderr, "Valve activation failed. Exiting.\n");
        cleanup(chip, line);
        return 1;
    }

    // Wait for the specified duration
    struct timespec sleep_time;
    sleep_time.tv_sec = duration;
    sleep_time.tv_nsec = 0;
    int ret = nanosleep(&sleep_time, NULL);
    if (ret < 0) {
        fprintf(stderr, "nanosleep interrupted by signal\n");
    }

    // Deactivate valve
    if (deactivate_valve(line) < 0) {
        fprintf(stderr, "Valve deactivation failed. Exiting.\n");
        cleanup(chip, line);
        return 1;
    }

    // Cleanup and exit
    cleanup(chip, line);
    printf("Watering system finished.\n");
    return 0;
}

