#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_PWM 22
#define RIGHT_MOTOR_PWM 23
#define LEFT_MOTOR_DIR 24
#define RIGHT_MOTOR_DIR 25

// Define constants
#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio);
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    gpioPWM(LEFT_MOTOR_PWM, left_speed);
    gpioPWM(RIGHT_MOTOR_PWM, right_speed);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    set_motor_speed(0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR);
        int middle_sensor = read_sensor(MIDDLE_SENSOR);
        int right_sensor = read_sensor(RIGHT_SENSOR);

        // Apply control law
        if (middle_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 0) {
            set_motor_speed(BASE_SPEED / 2, BASE_SPEED);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED / 2, BASE_SPEED);
        } else if (right_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED / 2);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED, BASE_SPEED / 2);
        } else {
            set_motor_speed(0, 0);
            log_data(left_sensor, middle_sensor, right_sensor, 0, 0);
        }

        gpioDelay(10); // Delay for 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(0, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

