#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 mode. Error code: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read lux data. Error code: %d\n", result);
        return -1.0;
    }

    uint16_t raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
