#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define SERVO_LOCKED 1000
#define SERVO_UNLOCKED 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set servo pulse width
void set_servo_pulse(int pulse_width) {
    // Constrain pulse width to safe range
    if (pulse_width < 500) {
        pulse_width = 500;
    } else if (pulse_width > 2500) {
        pulse_width = 2500;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to handle button press
void handle_button_press(int button_pin, int pulse_width) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (active-low)
        set_servo_pulse(pulse_width);
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        handle_button_press(LOCK_BUTTON_PIN, SERVO_LOCKED);
        handle_button_press(UNLOCK_BUTTON_PIN, SERVO_UNLOCKED);
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    return 0;
}

