#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations (in milliseconds)
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Function prototypes
int initialize_gpio();
void pulse_motor(int gpio_pin, int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to control the motors
    while (program_running) {
        // Pulse motor 1
        pulse_motor(MOTOR1_GPIO, MOTOR1_PULSE_DURATION);

        // Pulse motor 2
        pulse_motor(MOTOR2_GPIO, MOTOR2_PULSE_DURATION);
    }

    // Cleanup GPIO and terminate pigpio before exiting
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    return 0;
}

// Function to pulse a motor by setting the GPIO pin HIGH for a specified duration
void pulse_motor(int gpio_pin, int duration_ms) {
    // Set the GPIO pin HIGH
    gpioWrite(gpio_pin, 1);

    // Wait for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Set the GPIO pin LOW
    gpioWrite(gpio_pin, 0);
}

// Function to cleanup GPIO and terminate pigpio
void cleanup_gpio() {
    // Set GPIO pins to LOW before releasing
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);

    // Release GPIO pins
    gpioSetMode(MOTOR1_GPIO, PI_INPUT); // Set to input to release
    gpioSetMode(MOTOR2_GPIO, PI_INPUT); // Set to input to release

    // Terminate pigpio
    gpioTerminate();
}

// Signal handler function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    program_running = 0; // Set the flag to exit the main loop
}

