    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(publisher, ZMQ_ADDRESS);
    if (rc != 0) {
        perror("zmq_bind failed");
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Sound sensor mode: Listening on %s\n", ZMQ_ADDRESS);
    return 0;
}

// Initialize ZeroMQ subscriber
int initialize_zmq_subscriber() {
    context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_connect(subscriber, ZMQ_ADDRESS);
    if (rc != 0) {
        perror("zmq_connect failed");
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));
    if (rc != 0) {
        perror("zmq_setsockopt failed");
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Alarm node mode: Connected to %s\n", ZMQ_ADDRESS);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // GPIO cleanup
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
    gpioTerminate();

    // ZeroMQ cleanup
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    printf("Cleanup complete.\n");
}

// Sound sensor mode
void sound_sensor_mode() {
    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);

        if (sound_detected == 0) { // Sound detected (active-low)
            publish_alert();
        }

        gpioDelay(10); // Poll every 10 ms
    }
}

// Alarm node mode
void alarm_node_mode() {
    while (running) {
        zmq_msg_t message;
        zmq_msg_init(&message);

        int rc = zmq_msg_recv(&message, subscriber, 0);
        if (rc == -1) {
            if (running) {
                perror("zmq_msg_recv failed");
            }
            zmq_msg_close(&message);
            continue; // Non-fatal error, continue listening
        }

        char *topic = (char *)zmq_msg_data(&message);
        int topic_len = zmq_msg_size(&message);

        if (strncmp(topic, "SOUND_ALERTS", topic_len) == 0) {
            activate_alarm();
        }

        zmq_msg_close(&message);
    }
}

// Publish alert
void publish_alert() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    char message[256];
    snprintf(message, sizeof(message), "SOUND_ALERTS:%s", buf);

    zmq_msg_t msg;
    zmq_msg_init_size(&msg, strlen(message));
    memcpy(zmq_msg_data(&msg), message, strlen(message));

    int rc = zmq_sendmsg(publisher, &msg, 0);
    zmq_msg_close(&msg);

    if (rc == -1) {
        perror("zmq_sendmsg failed");
    }
}

// Activate alarm
void activate_alarm() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
    gpioDelay(ALARM_DURATION * 1000); // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  <mode> can be 'sound_sensor' or 'alarm_node'\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        mode = 1;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (mode == 0) {
        if (initialize_zmq_publisher() != 0) {
            cleanup();
            return 1;
        }
    } else {
        if (initialize_zmq_subscriber() != 0) {
            cleanup();
            return 1;
        }
    }

    // Main loop
    if (mode == 0) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    // Cleanup
    cleanup();

    return 0;
}

