            // Logic 0
        } else {
            return 0; // Invalid space length
        }
    }

    // Decode Command (8 bits)
    for (i = 0; i < 8; i++) {
        if (pulse_buffer[18 + (i * 2)] < NEC_BIT_MARK * 0.8 || pulse_buffer[18 + (i * 2)] > NEC_BIT_MARK * 1.2) return 0;
        if (pulse_buffer[19 + (i * 2)] > NEC_ONE_SPACE * 0.8) {
            command |= (1 << i);
        } else if (pulse_buffer[19 + (i * 2)] > NEC_ZERO_SPACE * 0.8) {
            // Logic 0
        } else {
            return 0; // Invalid space length
        }
    }

    // Decode Checksum (8 bits)
    for (i = 0; i < 8; i++) {
        if (pulse_buffer[34 + (i * 2)] < NEC_BIT_MARK * 0.8 || pulse_buffer[34 + (i * 2)] > NEC_BIT_MARK * 1.2) return 0;
        if (pulse_buffer[35 + (i * 2)] > NEC_ONE_SPACE * 0.8) {
            checksum |= (1 << i);
        } else if (pulse_buffer[35 + (i * 2)] > NEC_ZERO_SPACE * 0.8) {
            // Logic 0
        } else {
            return 0; // Invalid space length
        }
    }

