        int checksum_inv = 0;

        for (i = 0; i < 8; i++) {
            if (pulse_buffer[68 + (i * 2)] < NEC_BIT_MARK * 0.8 || pulse_buffer[68 + (i * 2)] > NEC_BIT_MARK * 1.2) return 0;
            if (pulse_buffer[69 + (i * 2)] > NEC_ONE_SPACE * 0.8) {
                address_inv |= (1 << i);
            } else if (pulse_buffer[69 + (i * 2)] > NEC_ZERO_SPACE * 0.8) {
                // Logic 0
            } else {
