            if (pulse_buffer[88 + (i * 2)] < NEC_BIT_MARK * 0.8 || pulse_buffer[88 + (i * 2)] > NEC_BIT_MARK * 1.2) return 0;
            if (pulse_buffer[89 + (i * 2)] > NEC_ONE_SPACE * 0.8) {
