            } else {
                return 0; // Invalid space length
            }
        }

        if ((address_inv + command_inv) != checksum_inv) {
            return 0; // Checksum mismatch
        }

        nec_address_inv = address_inv;
        nec_command_inv = command_inv;
        nec_checksum_inv = checksum_inv;
        nec_command_inv_valid = 1;
        nec_checksum_inv_valid = 1;
        nec_address_inv_valid = 1;
    }

    nec_address = address;
    nec_command = command;
    nec_checksum = checksum;
    nec_valid = 1;

    return 1; // Valid NEC frame
}

