void publish_mqtt(int address, int command) {
    char payload[128];
    snprintf(payload, sizeof(payload), "{\"address\": %d, \"command\": %d}", address, command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }
}

// Signal Handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup Function
void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    closelog();
}

// IR Callback Function
void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < 68) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            // Buffer overflow, reset
            syslog(LOG_WARNING, "IR buffer overflow, resetting");
            pulse_count = 0;
        }
    }

    if (pulse_count >= 68) {
        if (decode_nec_frame()) {
            syslog(LOG_INFO, "Decoded NEC frame: Address = 0x%02X, Command = 0x%02X", nec_address, nec_command);
            publish_mqtt(nec_address, nec_command);
        } else {
            syslog(LOG_WARNING, "Invalid NEC frame received");
        }
        pulse_count = 0; // Reset buffer after decoding
    }
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode and pull-up/down resistor
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        cleanup();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register IR callback
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        sleep(1); // Keep the program running
    }

    return 0;
}

