    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Function to read sensor data
int read_sensor(int fd, int address) {
    unsigned char data[2];
    int result;

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02x: %s\n", address, strerror(errno));
        return -1;
    }

    // Write the high-resolution mode command
    unsigned char cmd = BH1750_CMD_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Could not write to I2C device at address 0x%02x: %s\n", address, strerror(errno));
        return -1;
    }

    // Wait for conversion (at least 180ms)
    usleep(180000); // 180ms

    // Read 2 bytes of data
    if (read(fd, data, 2) != 2) {
