#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fflush(log_file);
            fclose(log_file);
        }
        exit(0);
    }
}

// Function to initialize the I2C device
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read airflow data from the sensor
int read_airflow_data(int *raw_value) {
    unsigned char buffer[2];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write(i2c_fd, buffer, 0) != 0) {
            fprintf(stderr, "Error sending I2C start condition: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Error reading I2C data: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *raw_value = ((buffer[0] << 8) | buffer[1]) & 0x3FFF; // Mask to 14 bits
        return 0; // Success
    }

    fprintf(stderr, "Failed to read airflow data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to convert raw value to SLPM
float convert_to_slpm(int raw_value) {
    return (raw_value - 3277) * 0.1;
}

// Function to log the airflow data to a file
int log_airflow_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    int raw_value;
    float flow_rate;

    while (1) {
        // Read airflow data
        if (read_airflow_data(&raw_value) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_value);

            // Log the data
            if (log_airflow_data(flow_rate) != 0) {
                fprintf(stderr, "Error logging airflow data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }

        sleep(1); // Sample once per second
    }

    return 0;
}

