#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_SP_EN 0x81

#define AS7341_F1_LSB 0x60
#define AS7341_F1_MSB 0x61
#define AS7341_F2_LSB 0x62
#define AS7341_F2_MSB 0x63
#define AS7341_F3_LSB 0x64
#define AS7341_F3_MSB 0x65
#define AS7341_F4_LSB 0x66
#define AS7341_F4_MSB 0x67
#define AS7341_F5_LSB 0x68
#define AS7341_F5_MSB 0x69
#define AS7341_F6_LSB 0x6A
#define AS7341_F6_MSB 0x6B
#define AS7341_F7_LSB 0x6C
#define AS7341_F7_MSB 0x6D
#define AS7341_F8_LSB 0x6E
#define AS7341_F8_MSB 0x6F
#define AS7341_CLEAR_LSB 0x70
#define AS7341_CLEAR_MSB 0x71
#define AS7341_NIR_LSB 0x72
#define AS7341_NIR_MSB 0x73

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_lux(const sensor_data_t *data);
int log_data(const sensor_data_t *data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the AS7341 sensor
int initialize_sensor() {
    int status;

    // Verify WHO_AM_I register
    status = i2cWriteByteData(i2c_handle, AS7341_WHO_AM_I, 0x00); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    int who_am_i = i2cReadByteData(i2c_handle, AS7341_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x19, got 0x%x\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed (0x%x)\n", who_am_i);

    // Power on the sensor
    status = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x01); // Set PON bit
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for power-on

    // Configure SMUX for spectral readings
    status = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03); // Enable all channels
    if (status < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %s\n", strerror(errno));
        return -1;
    }

    // Enable spectral measurement
    status = i2cWriteByteData(i2c_handle, AS7341_SP_EN, 0x01); // Set SP_EN bit
    if (status < 0) {
        fprintf(stderr, "Error writing to SP_EN register: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read spectral data from the AS7341
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[20];
    int status;

    // Read all 10 spectral channels in one go
    status = i2cReadI2CBlockData(i2c_handle, AS7341_F1_LSB, (char *)buffer, 20);
    if (status < 0) {
        fprintf(stderr, "Error reading spectral data: %s\n", strerror(errno));
        return -1;
    }

    // Combine LSB and MSB for each channel
    data->f1 = (buffer[1] << 8) | buffer[0];
    data->f2 = (buffer[3] << 8) | buffer[2];
    data->f3 = (buffer[5] << 8) | buffer[4];
    data->f4 = (buffer[7] << 8) | buffer[6];
