// Function to initialize the AS7341 sensor
int initialize_sensor() {
    int status;

    // Verify WHO_AM_I register
    status = i2cWriteByteData(i2c_handle, AS7341_WHO_AM_I, 0x00); // Dummy write to set register pointer
    if (status < 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    int who_am_i = i2cReadByteData(i2c_handle, AS7341_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x19, got 0x%x\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed (0x%x)\n", who_am_i);

