    status = i2cWriteByteData(i2c_handle, AS7341_SP_EN, 0x01); // Set SP_EN bit
    if (status < 0) {
        fprintf(stderr, "Error writing to SP_EN register: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
