// Constants
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;
FILE *data_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int handle, int address, char *buffer);
int convert_to_g(const char *buffer, float *x_g, float *y_g, float *z_g);
int log_data(FILE *fp, float x_g, float y_g, float z_g);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Read sensor data
int read_sensor_data(int handle, int address, char *buffer) {
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(handle, 0x28, buffer, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C read failed (attempt %d): %d", i + 1, result);
            log_error(error_file, error_message);
            gpioDelay(BACKOFF_DELAY_MS * (1 << i)); // Exponential backoff
        }
    }
    return -1; // Failure after retries
}

// Convert raw data to g
int convert_to_g(const char *buffer, float *x_g, float *y_g, float *z_g) {
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x_g = x_raw * 0.000244;
    *y_g = y_raw * 0.000244;
    *z_g = z_raw * 0.000244;

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, float x_g, float y_g, float z_g) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Log error to error log file
int log_error(FILE *fp, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval. Using default value.\n");
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILENAME, "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        log_error(error_file, "I2C initialization failed");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        log_error(error_file, "Failed to open data file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(data_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[6];
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, i2c_address, buffer) == 0) {
            if (convert_to_g(buffer, &x_g, &y_g, &z_g) == 0) {
                log_data(data_file, x_g, y_g, z_g);
            } else {
                log_error(error_file, "Failed to convert data to g");
            }
        } else {
            log_error(error_file, "Failed to read sensor data");
        }

        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

