// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define POWER_ON_CMD 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 1

// Global variables
int i2c_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *device, int addr);
int i2c_write(int fd, int addr, unsigned char *data, int len);
int i2c_read(int fd, int addr, unsigned char *data, int len);
float read_bh1750(int fd);
char *format_lux(float lux);
int udp_init(const char *addr, int port);
int udp_send(int socket, const char *message, const char *addr, int port);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, int addr, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, int addr, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from BH1750 sensor
float read_bh1750(int fd) {
    unsigned char data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send power-on command
        if (i2c_write(fd, BH1750_ADDR, &POWER_ON_CMD, 1) < 0) {
            fprintf(stderr, "Error sending power-on command, retry %d\n", retries + 1);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Send continuous high-resolution mode command
        if (i2c_write(fd, BH1750_ADDR, &CONTINUOUS_HIGH_RES_MODE, 1) < 0) {
            fprintf(stderr, "Error sending continuous mode command, retry %d\n", retries + 1);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Wait for measurement (at least 180ms)
        usleep(200000); // 200ms

        // Read 2 bytes of data
        if (i2c_read(fd, BH1750_ADDR, data, 2) < 0) {
            fprintf(stderr, "Error reading data, retry %d\n", retries + 1);
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Combine the two bytes into a 16-bit value
        unsigned int raw_value = (data[0] << 8) | data[1];

        // Convert to lux
        float lux = (float)raw_value / 1.2;

        return lux;
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return -1.0; // Indicate error
}

// Function to format lux value as a string
char *format_lux(float lux) {
    char *buffer = (char *)malloc(20 * sizeof(char)); // Allocate memory for the string
    if (buffer == NULL) {
        perror("Failed to allocate memory for lux string");
        return NULL;
    }
    snprintf(buffer, 20, "%.2f", lux);
    return buffer;
}

// UDP initialization function
int udp_init(const char *addr, int port) {
    int socket_desc;
    struct sockaddr_in server_addr;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_desc < 0) {
        perror("Could not create socket");
        return -1;
    }

    // Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(addr);
    server_addr.sin_port = htons(port);

    // Set TTL
    int ttl = TTL;
    if (setsockopt(socket_desc, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Setting TTL failed");
        close(socket_desc);
        return -1;
    }

    return socket_desc;
}

// UDP send function
int udp_send(int socket, const char *message, const char *addr, int port) {
    struct sockaddr_in server_addr;

    // Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(addr);
    server_addr.sin_port = htons(port);

    // Send the message
    if (sendto(socket, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Send failed");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize UDP
    udp_socket = udp_init(MULTICAST_ADDR, MULTICAST_PORT);
    if (udp_socket < 0) {
        fprintf(stderr, "UDP initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Format lux value as a string
        char *lux_str = format_lux(lux);
        if (lux_str == NULL) {
            fprintf(stderr, "Failed to format lux string\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Send lux value over UDP
        if (udp_send(udp_socket, lux_str, MULTICAST_ADDR, MULTICAST_PORT) < 0) {
            fprintf(stderr, "Failed to send UDP message\n");
        }

        free(lux_str); // Free allocated memory

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated\n");
    return 0;
}

