#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the UART
int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 10; // Timeout of 1 second (in deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART with timeout
int read_uart(int fd, char *buffer, size_t max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, max_len - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

// Function to parse the range data
int parse_range_data(const char *line, long *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        fprintf(stderr, "Error duplicating line for parsing: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid timestamp format\n");
        free(line_copy);
        return -1;
    }
    *timestamp = strtol(token, NULL, 10);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid range format\n");
        free(line_copy);
        return -1;
    }
    *range = strtof(token, NULL);

    free(line_copy);
    return 0;
}

// Function to log the range data
void log_range_data(long timestamp, float range) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    char line_buffer[MAX_LINE_LENGTH];
    int line_buffer_index = 0;
    long timestamp;
    float range;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    fprintf(stderr, "UART initialized successfully.\n");

    // Main loop
    while (program_running) {
        int bytes_read = read_uart(uart_fd, line_buffer + line_buffer_index, MAX_LINE_LENGTH - line_buffer_index - 1);

        if (bytes_read > 0) {
            line_buffer_index += bytes_read;

            // Check for newline character
            if (line_buffer_index > 0 && line_buffer[line_buffer_index - 1] == '\n') {
                // Null-terminate the line
                line_buffer[line_buffer_index] = '\0';

                // Parse the data
                if (parse_range_data(line_buffer, &timestamp, &range) == 0) {
                    // Log the data
                    log_range_data(timestamp, range);
                } else {
                    fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                }

                // Reset the buffer index
                line_buffer_index = 0;
            }
        } else if (bytes_read == 0) {
            // Timeout occurred, no data available
            //fprintf(stderr, "Timeout waiting for data.\n");
        } else {
            // Error occurred during read
            fprintf(stderr, "Error reading from UART, attempting to re-initialize.\n");
            close(uart_fd);
            uart_fd = init_uart(UART_DEVICE);
            if (uart_fd == -1) {
                fprintf(stderr, "Failed to re-initialize UART, exiting.\n");
                program_running = 0; // Exit if re-initialization fails
            }
        }
    }

    // Close the UART port
    if (uart_fd != -1) {
        close(uart_fd);
        fprintf(stderr, "UART port closed.\n");
    }

    return EXIT_SUCCESS;
}

