#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port and baud rate
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
static volatile int running = 1;
static int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop();
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
    }
    return value;
}

// Function to log sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send an emergency stop message over the serial port
void emergency_stop() {
    if (serial_fd != -1) {
        if (write(serial_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
            perror("Error writing to serial port");
        }
    } else {
        fprintf(stderr, "Serial port not initialized, cannot send emergency stop.\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Setup function to initialize pigpio and serial port
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the serial port
    serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for 8N1
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening serial port: %s\n", SERIAL_PORT);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to close the serial port and terminate pigpio
void cleanup() {
    if (serial_fd != -1) {
        serClose(serial_fd);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and serial port
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left, middle, right);

        // Check for emergency stop condition
        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

